-- ==========================================================================
__UAI_MODULES["agent/pricing"] = (function()
-- Model pricing directory for in/out tokens per 1,000,000 tokens.
-- Format: { promptCostPer1M, completionCostPer1M }
-- Generated by tools/sync_pricing.js from OpenRouter & LiteLLM datasets.
return function(env)
	local M = {}

	local PRICES = {
		["@cf/aisingapore/gemma-sea-lion-v4-27b-it"] = { 0.351, 0.555 },
		["@cf/deepseek-ai/deepseek-r1-distill-qwen-32b"] = { 0.497, 4.881 },
		["@cf/google/gemma-2b-it-lora"] = { 0, 0 },
		["@cf/google/gemma-4-26b-a4b-it"] = { 0.1, 0.3 },
		["@cf/google/gemma-7b-it-lora"] = { 0, 0 },
