			state.clearTodos(session)
			session.emit("cleared", {})
			session.emit("status", { text = "Ready" })
			M.persist(session)
		end

		-- A title the user typed wins over the one derived from the first message, and
		-- keeps winning: the derivation only ever fires while the title is still the
		-- placeholder.
		function session.rename(title)
			local clean = util.ellipsis(util.trim(title), 60)
			if clean == "" then return false, "a conversation needs a title" end
			session.title = clean
			session.named = true
			M.listChanged:fire()
			M.persist(session)
			return true
		end

		-- Nothing about this conversation is written to disk. The composer's isolation
		-- toggle is what turns it on, for the same reason a worktree exists: somewhere
		-- to try something without it becoming part of the history.
		function session.setEphemeral(value)
			session.ephemeral = value == true
			if session.ephemeral and fsx.enabled then
				fsx.delete(THREAD_DIR .. "/" .. session.id .. ".json")
			else
				M.persist(session)
			end
			M.listChanged:fire()
			return session.ephemeral
		end

		function session.stats()
			local stats = session.ctx.stats()
			stats.busy = session.busy
			stats.turns = session.turns
			stats.todos = state.todoCounts(session)
			return stats
		end

		return session
	end

	-- Threads ---------------------------------------------------------------

	function M.current()
		if M.activeId and M.threads[M.activeId] then return M.threads[M.activeId] end
		return M.newThread()
	end

	function M.newThread(opts)
		local session = M.create(opts)
		M.threads[session.id] = session
		M.activeId = session.id
		M.trimThreads()
		M.listChanged:fire()
		return session
	end

	function M.switch(id)
		if not M.threads[id] then return false end
		M.activeId = id
		M.listChanged:fire()
		return true
	end

	function M.list()
		local out = {}
		for _, session in pairs(M.threads) do out[#out + 1] = session end
		table.sort(out, function(a, b) return (a.updatedAt or 0) > (b.updatedAt or 0) end)
		return out
	end

	-- The conversations currently running a turn, newest activity first.
	--
	-- Switching conversation does not stop the one you left -- its loop is on its own
	-- thread and keeps going -- so more than one can be working at a time, and the
	-- interface needs to be able to say which. Anything that reads "is the agent
	-- busy" from the active session alone is asking the wrong question.
	function M.busy()
		local out = {}
		for _, session in ipairs(M.list()) do
			if session.busy then out[#out + 1] = session end
		end
		return out
	end

	function M.busyCount()
		return #M.busy()
	end

	-- Conversations grouped by the place they happened in, most recently used group
	-- first, with the place the client is in now always at the top -- that is the one
	-- a new conversation would join.
	function M.groups()
		local place = env.require("runtime/place")
		local byPlace, order = {}, {}
		for _, session in ipairs(M.list()) do
			local key = tostring(session.placeId or 0)
			local group = byPlace[key]
			if not group then
				local label = session.placeName
				if label == nil or util.trim(tostring(label)) == "" then
					-- A transcript from before the place was recorded, or from a host that
					-- could not read it. "Place 0" would read as a place.
					label = (session.placeId and session.placeId > 0)
						and ("Place " .. key) or "Unknown place"
				end
				group = {
					placeId = session.placeId or 0,
					-- The name recorded when the conversation started, except for the
					-- current place, where the live label is better: it may have resolved
					-- since, and a place can be renamed.
					label = label,
					sessions = {},
					updatedAt = 0,
					current = (session.placeId or 0) == place.id,
				}
				if group.current then group.label = place.label() end
				byPlace[key] = group
				order[#order + 1] = group
			end
			group.sessions[#group.sessions + 1] = session
			if (session.updatedAt or 0) > group.updatedAt then group.updatedAt = session.updatedAt or 0 end
		end
		table.sort(order, function(a, b)
			if a.current ~= b.current then return a.current end
			if a.updatedAt ~= b.updatedAt then return a.updatedAt > b.updatedAt end
			return tostring(a.label) < tostring(b.label)
		end)
		return order
	end

	-- Title, then the transcript. A search that only matched titles would miss the
	-- conversation you remember by something that was said in it.
	function M.search(query)
		local needle = util.trim(tostring(query or "")):lower()
		if needle == "" then return {} end
		local out = {}
		for _, session in ipairs(M.list()) do
			local where, snippet = nil, nil
			if tostring(session.title):lower():find(needle, 1, true) then
				where = "title"
			end
			if not where then
				for _, message in ipairs(session.ctx.messages or {}) do
					local body = tostring(message.content or "")
					local at = body:lower():find(needle, 1, true)
					if at then
						where = message.role == "user" and "message" or "reply"
						snippet = util.ellipsis(body:sub(math.max(at - 40, 1)), 120)
						break
					end
				end
			end
			if where then
				out[#out + 1] = { session = session, where = where, snippet = snippet }
			end
		end
		return out
	end

	function M.remove(id)
		local session = M.threads[id]
		if not session then return false end
		session.preparing, session.removed = nil, true
		attachments.clearUploads(id)
		if session.busy then session.abort() end
		M.threads[id] = nil
		if fsx.enabled then fsx.delete(THREAD_DIR .. "/" .. id .. ".json") end
		if M.activeId == id then
			local remaining = M.list()
			M.activeId = remaining[1] and remaining[1].id or nil
			if not M.activeId then M.newThread() end
		end
		M.listChanged:fire()
		return true
	end

	function M.trimThreads()
		-- Keep all sessions: no limit is enforced, preserving all history indefinitely.
		if THREAD_LIMIT == math.huge then return end
		local ordered = M.list()
		for index = THREAD_LIMIT + 1, #ordered do
			local victim = ordered[index]
			if not victim.busy and victim.id ~= M.activeId then M.remove(victim.id) end
		end
	end

	-- Persistence is best-effort by design: a host with no filesystem simply keeps
	-- everything in memory for the session, and nothing above here cares.
	--
	-- The transcript goes in the file as well as the context. It did not, and the
	-- consequence was the one thing about restored conversations anybody would notice:
	-- the sidebar listed them, switching to one worked, and the panel showed the
	-- greeting card -- because the transcript is a pure function of `session.log` and
	-- `log` was the one field restore left empty. `ctx.serialise` is not a substitute:
	-- it keeps what the *model* needs to continue, which has no reasoning, no timings,
	-- no risk levels and no tool arguments.
	function M.persist(session)
		if not fsx.enabled or session.headless then return false end
		if session.depth and session.depth > 0 then return false end
		if session.ephemeral then return false end
		return fsx.writeJson(THREAD_DIR .. "/" .. session.id .. ".json", {
			id = session.id,
			title = session.title,
			named = session.named == true,
			placeId = session.placeId,
			placeName = session.placeName,
			updatedAt = session.updatedAt,
			createdAt = session.createdAt,
			turns = session.turns, opencodeSession = session.opencodeSession,
			context = session.ctx.serialise(),
			transcript = transcriptOf(session),
		})
	end

	function M.restore()
		if not fsx.enabled then return 0 end
		local restored = 0
		for _, entry in ipairs(fsx.list(THREAD_DIR)) do
			if entry.name:match("%.json$") then
				local data = fsx.readJson(entry.path, nil)
				if type(data) == "table" and data.id then
					local session = M.create({
						id = data.id,
						title = data.title,
						placeId = tonumber(data.placeId),
						placeName = data.placeName,
					})
					session.named = data.named == true
					session.createdAt = data.createdAt or session.createdAt
					session.updatedAt = data.updatedAt or session.updatedAt
					session.turns = data.turns or 0; session.opencodeSession = data.opencodeSession
					session.ctx.restore(data.context)
					-- Replayed by the view in the order it happened. A file written before
					-- transcripts were stored simply has none, and that conversation opens on
					-- the greeting exactly as it used to.
					if type(data.transcript) == "table" then
						for _, event in ipairs(data.transcript) do
							if type(event) == "table" and event.kind then
								session.log[#session.log + 1] = event
							end
						end
					end
					M.threads[session.id] = session
					restored = restored + 1
				end
			end
		end
		if restored > 0 then
			local ordered = M.list()
			M.activeId = ordered[1] and ordered[1].id or nil
			log.info("session", util.pluralise(restored, "conversation") .. " restored")
			M.listChanged:fire()
		end
		return restored
	end

	return M
end
end)()

-- ==========================================================================
-- agent/state
-- ==========================================================================
__UAI_MODULES["agent/state"] = (function()
-- Agent-owned state that outlives a single turn: the task list the model keeps,
-- and the memory it writes to.
--
-- Both are model-writable, which is the point -- a long task survives context
-- compaction because the plan is not in the transcript -- and both are bounded,
-- because a model given an unbounded store will fill it.
--
-- Memory is the client's, deliberately: a fact about the person using it is not a
-- fact about one conversation. A task list is the opposite -- it is the plan for
-- the job in front of it -- so it lives on the session, which is what lets two
-- conversations work at once. It did not, and one global list was the whole bug:
-- starting a second conversation replaced the first one's plan in the strip *and*
-- in the system prompt it was about to be sent, so a running turn resumed against
-- somebody else's steps.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")

	local TODO_LIMIT = 24
	local MEMORY_LIMIT = 60
	local MEMORY_VALUE_CAP = 600

	local M = {
		todosChanged = signal.new("todos"),
		memoryChanged = signal.new("memory"),
	}

	-- Todos -----------------------------------------------------------------

	local STATUS = { pending = true, active = true, done = true, dropped = true }

	-- Where a list lives when there is no session in scope. Nothing in the client
	-- reaches this any more; it exists so a caller that loses its session writes
	-- somewhere harmless rather than raising, and so a test can drive the store
	-- without building a session.
	local orphan = { todos = {} }

	local function holderFor(session)
		if type(session) ~= "table" then return orphan end
		session.todos = session.todos or {}
		return session
	end

	function M.todoList(session)
		return holderFor(session).todos
	end

	-- The whole list is replaced rather than patched. A model that edits one item
	-- at a time drifts out of sync with its own plan; handing back the full list
	-- every time keeps the transcript and the panel identical.
	function M.setTodos(items, session)
		local out = {}
		for index, item in ipairs(items or {}) do
			if index > TODO_LIMIT then break end
			local text = util.trim(type(item) == "table" and (item.text or item.title) or item)
			if text ~= "" then
				local status = type(item) == "table" and tostring(item.status or "pending"):lower() or "pending"
				if not STATUS[status] then status = "pending" end
				out[#out + 1] = {
					id = index,
					text = util.ellipsis(text, 160),
					status = status,
					note = type(item) == "table" and item.note or nil,
				}
			end
		end
		local holder = holderFor(session)
		holder.todos = out
		-- The session goes with the list, so a strip showing one conversation can
		-- ignore another conversation's plan instead of painting it.
		M.todosChanged:fire(out, holder ~= orphan and holder or nil)
		return out
	end

	function M.todoCounts(session)
		local list = M.todoList(session)
		local counts = { pending = 0, active = 0, done = 0, dropped = 0, total = #list }
		for _, item in ipairs(list) do
			counts[item.status] = (counts[item.status] or 0) + 1
		end
		return counts
	end

	function M.clearTodos(session)
		local holder = holderFor(session)
		holder.todos = {}
		M.todosChanged:fire({}, holder ~= orphan and holder or nil)
	end

	-- Rendered into the system prompt each turn so the plan cannot be forgotten,
	-- and into the transcript panel for the user.
	function M.todoBlock(session)
		local list = M.todoList(session)
		if #list == 0 then return nil end
		local marks = { pending = "[ ]", active = "[>]", done = "[x]", dropped = "[-]" }
		local lines = {}
		for _, item in ipairs(list) do
			lines[#lines + 1] = string.format("%s %s", marks[item.status] or "[ ]", item.text)
		end
		return table.concat(lines, "\n")
	end

	-- Memory ----------------------------------------------------------------

	local function entries()
		local stored = config.get("memory.entries", {})
		if type(stored) ~= "table" then return {} end
		return stored
	end

	function M.memoryEnabled()
		return config.get("memory.enabled", true) ~= false
	end

	function M.remember(key, value)
		local cleanKey = util.trim(key):gsub("%s+", "_")
		if cleanKey == "" then return false, "a memory needs a key" end
		if not M.memoryEnabled() then return false, "memory is disabled in settings" end
		local list = entries()
		local text = util.ellipsis(util.trim(value), MEMORY_VALUE_CAP)
		if text == "" then return false, "a memory needs a value" end

		local replaced = false
		for _, entry in ipairs(list) do
			if entry.key == cleanKey then
				entry.value = text
				entry.at = clock.ms()
				replaced = true
			end
		end
		if not replaced then
			if #list >= MEMORY_LIMIT then
				-- Oldest out. A model that keeps writing should lose its earliest
				-- notes rather than start failing.
				table.sort(list, function(a, b) return (a.at or 0) < (b.at or 0) end)
				table.remove(list, 1)
			end
			list[#list + 1] = { key = cleanKey, value = text, at = clock.ms() }
		end
		config.set("memory.entries", list)
		M.memoryChanged:fire(list)
		return true, (replaced and "updated " or "saved ") .. cleanKey
	end

	function M.recall(key)
		for _, entry in ipairs(entries()) do
			if entry.key == util.trim(key) then return entry.value end
		end
		return nil
	end

	function M.forget(key)
		local list = entries()
		local kept = {}
		local removed = 0
		for _, entry in ipairs(list) do
			if entry.key == util.trim(key) then
				removed = removed + 1
			else
				kept[#kept + 1] = entry
			end
		end
		config.set("memory.entries", kept)
		M.memoryChanged:fire(kept)
		return removed > 0
	end

	function M.memoryList()
		local list = entries()
		table.sort(list, function(a, b) return tostring(a.key) < tostring(b.key) end)
		return list
	end

	function M.clearMemory()
		config.set("memory.entries", {})
		M.memoryChanged:fire({})
	end

	function M.memoryBlock()
		if not M.memoryEnabled() then return nil end
		local list = M.memoryList()
		if #list == 0 then return nil end
		local lines = {}
		for _, entry in ipairs(list) do
			lines[#lines + 1] = "- " .. entry.key .. ": " .. entry.value
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/stats
-- ==========================================================================
__UAI_MODULES["agent/stats"] = (function()
-- Activity history.
--
-- Everything the home card and the Usage panel show is counted here, from events
-- the client genuinely observed, and nothing is modelled or interpolated: a figure
-- either has a record behind it or it is absent. That is the whole contract of this
-- module, and it is why the counters are so plain.
--
-- Two things follow from it. Tokens are only ever counted from the moment this file
-- first exists -- `agent/usage` has always been in-memory, so there is no history to
-- recover and inventing one would be worse than a zero. Messages and conversations
-- *can* be recovered, because every persisted transcript carries the real timestamp
-- of every message in it, so the first run seeds those from disk and says so.
--
-- Buckets are local days and local hours, because "yesterday" and "11 AM" are the
-- user's, not UTC's. runtime/clock owns that conversion.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local dispose = env.require("runtime/dispose")

	local FILE = "stats.json"
	-- Thirteen months of days. Past that the oldest is dropped, which is also the
	-- ceiling on how far back any window can reach -- stated here because the panel
	-- says "all" and that is what all means.
	local DAY_LIMIT = 400
	-- Ids of conversations already counted, so resuming one after a restart does not
	-- count it twice. Only twenty transcripts are ever kept on disk, so a window of
	-- sixty-four covers every conversation that could still be resumed.
	local SEEN_LIMIT = 64
	local TOOL_LIMIT = 120
	local SAVE_SECONDS = 2

	-- The comparison Claude Code's home card makes. 76,944 words in the first
	-- edition; at the four-characters-per-token estimate this client uses everywhere
	-- else that is a little under 100,000 tokens, which is the divisor. It is an
	-- estimate of the book, not of the count -- the token figure itself is measured.
	local BOOK = { title = "Harry Potter and the Philosopher's Stone", tokens = 100000 }

	local M = {
		changed = signal.new("stats"),
		loaded = false,
		observing = false,
		BOOK = BOOK,
		DAY_LIMIT = DAY_LIMIT,
	}

	local function blankTotals()
		return {
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, cached = 0, reasoning = 0,
			cost = 0, requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
		}
	end

	local function blank()
		return {
			version = 1,
			startedAt = clock.ms(),
			-- Nil until the first request is recorded, and the Usage panel prints it
			-- rather than implying the token columns cover the whole history.
			tokensFrom = nil,
			seededAt = nil,
			days = {},
			hours = {},
			models = {},
			tools = {},
			seen = {},
			totals = blankTotals(),
		}
	end

	M.data = blank()

	local seenSet = {}

	local function rebuildSeen()
		seenSet = {}
		for _, id in ipairs(M.data.seen or {}) do seenSet[tostring(id)] = true end
	end

	-- Numbers come back from JSON as numbers, but a hand-edited or half-written file
	-- can hold anything, and one string in a counter would poison every sum.
	local function number(value)
		return tonumber(value) or 0
	end

	local function sanitiseCounters(source, template)
		local out = {}
		for key, fallback in pairs(template) do
			out[key] = number(util.get(source or {}, key, fallback))
		end
		return out
	end

	local DAY_TEMPLATE = {
		sessions = 0, messages = 0, userMessages = 0, replies = 0,
		tokensIn = 0, tokensOut = 0, cost = 0, requests = 0,
		toolCalls = 0, toolErrors = 0, errors = 0,
	}

	local function blankDay()
		return sanitiseCounters({}, DAY_TEMPLATE)
	end

	function M.load()
		local stored = fsx.readJson(FILE, nil)
		M.data = blank()
		if type(stored) == "table" then
			M.data.startedAt = number(stored.startedAt) > 0 and number(stored.startedAt) or M.data.startedAt
			M.data.tokensFrom = tonumber(stored.tokensFrom)
			M.data.seededAt = tonumber(stored.seededAt)
			M.data.totals = sanitiseCounters(stored.totals, blankTotals())
			M.data.estimated = stored.estimated == true
			if type(stored.days) == "table" then
				for key, record in pairs(stored.days) do
					if clock.dayNumberOfKey(key) and type(record) == "table" then
						local day = sanitiseCounters(record, DAY_TEMPLATE)
						day.hours = {}
						for hour, count in pairs(type(record.hours) == "table" and record.hours or {}) do
							local index = tonumber(hour)
							if index and index >= 0 and index <= 23 then
								day.hours[tostring(math.floor(index))] = number(count)
							end
						end
						day.models = {}
						for id, entry in pairs(type(record.models) == "table" and record.models or {}) do
							if type(id) == "string" and type(entry) == "table" then
								day.models[id] = {
									requests = number(entry.requests),
									tokensIn = number(entry.tokensIn),
									tokensOut = number(entry.tokensOut),
									cost = number(entry.cost),
								}
							end
						end
						M.data.days[key] = day
					end
				end
			end
			if type(stored.tools) == "table" then
				for name, count in pairs(stored.tools) do
					if type(name) == "string" then M.data.tools[name] = number(count) end
				end
			end
			if type(stored.seen) == "table" then
				for _, id in ipairs(stored.seen) do
					if type(id) == "string" then M.data.seen[#M.data.seen + 1] = id end
				end
			end
		end
		rebuildSeen()
		M.loaded = true
		return M.data
	end

	function M.saveNow()
		if not fsx.enabled then return false, "no filesystem" end
		local ok, err = fsx.writeJson(FILE, M.data)
		if not ok then log.warn("stats", "could not persist activity history", err) end
		return ok, err
	end

	local flush = clock.debounce(function() M.saveNow() end, SAVE_SECONDS)

	function M.save()
		flush()
	end

	-- Recording ---------------------------------------------------------------

	-- Get-or-create for one local day, trimming the oldest when the window is full.
	-- The trim is by day number rather than by string order so a key from a future
	-- year cannot sort itself into the middle of the set.
	local function dayFor(ms)
		local key = clock.dayKey(ms)
		local record = M.data.days[key]
		if record then return record, key end
		record = blankDay()
		record.hours = {}
		record.models = {}
		M.data.days[key] = record

		local keys = {}
		for existing in pairs(M.data.days) do keys[#keys + 1] = existing end
		if #keys > DAY_LIMIT then
			table.sort(keys, function(a, b)
				return (clock.dayNumberOfKey(a) or 0) < (clock.dayNumberOfKey(b) or 0)
			end)
			for index = 1, #keys - DAY_LIMIT do M.data.days[keys[index]] = nil end
		end
		return record, key
	end

	local function bump(record, key, amount)
		record[key] = number(record[key]) + (amount or 1)
	end

	local function touchHour(day, ms)
		local hour = tostring(clock.hourOf(ms))
		day.hours[hour] = number(day.hours[hour]) + 1
		M.data.hours[hour] = number(M.data.hours[hour]) + 1
	end

	-- `quiet` seeds from disk without republishing per row: the first run would
	-- otherwise fire the signal a few thousand times before the interface exists.
	function M.recordMessage(role, at, quiet)
		local day = dayFor(at)
		bump(day, "messages")
		bump(M.data.totals, "messages")
		if role == "user" then
			bump(day, "userMessages")
			bump(M.data.totals, "userMessages")
		else
			bump(day, "replies")
			bump(M.data.totals, "replies")
		end
		touchHour(day, at)
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
	end

	-- A conversation counts once, the first time something is actually said in it: a
	-- thread object exists from the moment a panel opens and counting those would
	-- report a session for every time the window was looked at.
	function M.recordSession(id, at, quiet)
		local key = tostring(id or "")
		if key ~= "" then
			if seenSet[key] then return false end
			seenSet[key] = true
			M.data.seen[#M.data.seen + 1] = key
			while #M.data.seen > SEEN_LIMIT do table.remove(M.data.seen, 1) end
		end
		local day = dayFor(at)
		bump(day, "sessions")
		bump(M.data.totals, "sessions")
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
		return true
	end

	function M.counted(id)
		return seenSet[tostring(id or "")] == true
	end

	-- One inference request, after the fact, with whatever the provider reported.
	-- `delta` is what agent/usage measured for this request alone.
	function M.recordRequest(delta)
		delta = delta or {}
		local at = delta.at or clock.ms()
		local day = dayFor(at)
		local tokensIn = number(delta.prompt)
		local tokensOut = number(delta.completion)
		local cost = number(delta.cost)

		bump(day, "requests")
		bump(day, "tokensIn", tokensIn)
		bump(day, "tokensOut", tokensOut)
		bump(day, "cost", cost)
		bump(M.data.totals, "requests")
		bump(M.data.totals, "tokensIn", tokensIn)
		bump(M.data.totals, "tokensOut", tokensOut)
		bump(M.data.totals, "cached", number(delta.cached))
		bump(M.data.totals, "reasoning", number(delta.reasoning))
		bump(M.data.totals, "cost", cost)
		if delta.estimated then M.data.estimated = true end
		if not M.data.tokensFrom then M.data.tokensFrom = at end

		local model = util.trim(tostring(delta.model or ""))
		if model ~= "" then
			local perDay = day.models[model]
			if not perDay then
				perDay = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0 }
				day.models[model] = perDay
			end
			bump(perDay, "requests")
			bump(perDay, "tokensIn", tokensIn)
			bump(perDay, "tokensOut", tokensOut)
			bump(perDay, "cost", cost)

			local lifetime = M.data.models[model]
			if not lifetime then
				lifetime = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0, firstAt = at }
				M.data.models[model] = lifetime
			end
			bump(lifetime, "requests")
			bump(lifetime, "tokensIn", tokensIn)
			bump(lifetime, "tokensOut", tokensOut)
			bump(lifetime, "cost", cost)
			lifetime.lastAt = at
		end

		M.save()
		M.changed:fire(M.data)
	end

	function M.recordTool(name, ok, at)
		local day = dayFor(at)
		bump(day, "toolCalls")
		bump(M.data.totals, "toolCalls")
		if not ok then
			bump(day, "toolErrors")
			bump(M.data.totals, "toolErrors")
		end
		local key = util.trim(tostring(name or ""))
		if key ~= "" then
			if M.data.tools[key] == nil and util.count(M.data.tools) >= TOOL_LIMIT then
				-- A tool list is bounded by the registry, so this only trips if a host
				-- registers its own; dropping the new name is better than growing
				-- without limit.
				key = nil
			end
			if key then M.data.tools[key] = number(M.data.tools[key]) + 1 end
		end
		M.save()
	end

	function M.recordError(at)
		local day = dayFor(at)
		bump(day, "errors")
		bump(M.data.totals, "errors")
		M.save()
	end

	-- Recovering what is already on disk ---------------------------------------

	-- A persisted transcript carries the real timestamp of every message in it, so
	-- the conversations and messages of a client that has been in use since before
	-- this file existed are real history rather than a guess, and are counted once.
	--
	-- Tokens are deliberately not seeded. Nothing on disk records them, and an
	-- estimate would be a number with no measurement behind it.
	function M.seedFromSessions(list)
		if M.data.seededAt then return 0 end
		local messages, conversations = 0, 0
		for _, session in ipairs(list or {}) do
			local first = nil
			for _, message in ipairs((session.ctx and session.ctx.messages) or {}) do
				local role = tostring(message.role or "")
				local body = util.trim(tostring(message.content or ""))
				-- An assistant turn with no prose is a tool-call round, not a reply.
				if role == "user" or (role == "assistant" and body ~= "") then
					local at = tonumber(message.at) or tonumber(session.createdAt) or clock.ms()
					M.recordMessage(role, at, true)
					messages = messages + 1
					if not first then first = at end
				end
			end
			if first and M.recordSession(session.id, first, true) then
				conversations = conversations + 1
			end
		end
		M.data.seededAt = clock.ms()
		if messages > 0 then
			log.info("stats", string.format("%s recovered from %s already on disk",
				util.pluralise(messages, "message"), util.pluralise(conversations, "conversation")))
		end
		M.saveNow()
		M.changed:fire(M.data)
		return messages
	end

	-- Observation --------------------------------------------------------------

	function M.observe()
		if M.observing then return function() end end
		M.observing = true
		local hooks = env.require("agent/hooks")
		local usage = env.require("agent/usage")

		-- Every session event passes through the hook bus, which is how this stays out
		-- of the loop and the session object entirely.
		local unhook = hooks.register("onEvent", function(payload)
			local event = payload and payload.event
			local session = payload and payload.session
			if type(event) ~= "table" then return end
			-- A subagent's requests and tokens are work the conversation asked for and
			-- are counted with it, but its messages are not messages anyone typed or
			-- read: counting those would inflate the card by however many helpers a
			-- turn happened to dispatch.
			local nested = session ~= nil
				and (session.headless == true or (tonumber(session.depth) or 0) > 0)
			local kind = event.kind
			local at = tonumber(event.at) or clock.ms()

			if kind == "user" then
				if nested then return end
				if session then M.recordSession(session.id, at) end
				M.recordMessage("user", at)
			elseif kind == "assistant:text" then
				if nested then return end
				if util.trim(tostring(event.text or "")) ~= "" then
					M.recordMessage("assistant", at)
				end
			elseif kind == "tool:result" then
				M.recordTool(event.name, event.ok ~= false, at)
			elseif kind == "tool:error" then
				M.recordTool(event.name, false, at)
			elseif kind == "error" then
				M.recordError(at)
			end
		end, { name = "stats", order = -1000 })

		local untoken = usage.recorded:connect(function(delta) M.recordRequest(delta) end)

		dispose.add(unhook, "stats.events")
		dispose.add(untoken, "stats.usage")
		-- The last few seconds of a session are the ones the debounce has not written
		-- yet, and an unload is exactly when they would be lost.
		dispose.add(function() M.saveNow() end, "stats.flush")
		return unhook
	end

	function M.init()
		if M.loaded then return M end
		M.load()
		M.observe()
		local ok, err = pcall(function()
			M.seedFromSessions(env.require("agent/session").list())
		end)
		if not ok then log.warn("stats", "could not read history from disk", err) end
		return M
	end

	-- Reading ------------------------------------------------------------------

	local RANGES = { all = 0, ["30d"] = 30, ["7d"] = 7 }
	M.RANGES = { { value = "all", label = "All" }, { value = "30d", label = "30d" }, { value = "7d", label = "7d" } }

	local function dayIsActive(day)
		return number(day.messages) > 0 or number(day.requests) > 0 or number(day.sessions) > 0
	end

	-- A streak is consecutive active days ending today, or ending yesterday when
	-- today has not started yet -- otherwise every streak would read as broken until
	-- the first message of the morning.
	local function streaksOf(active, today, from)
		local current, cursor = 0, today
		if not active[cursor] then cursor = cursor - 1 end
		while active[cursor] and (from == nil or cursor >= from) do
			current = current + 1
			cursor = cursor - 1
		end

		local ordered = {}
		for value in pairs(active) do ordered[#ordered + 1] = value end
		table.sort(ordered)
		local longest, run = 0, 0
		for index, value in ipairs(ordered) do
			if index > 1 and value == ordered[index - 1] + 1 then
				run = run + 1
			else
				run = 1
			end
			if run > longest then longest = run end
		end
		return current, longest
	end

	-- Everything the home card shows for one range, aggregated from the day records
	-- so that "all" and "7d" are the same computation over a different span rather
	-- than two sources that can disagree.
	function M.window(range)
		if not RANGES[range] then range = "all" end
		local span = RANGES[range]
		local today = clock.dayNumber()
		local from = nil
		if span > 0 then from = today - (span - 1) end

		local out = {
			range = range,
			today = clock.keyFromDayNumber(today),
			fromKey = from and clock.keyFromDayNumber(from) or nil,
			activeDays = 0,
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, tokens = 0, cost = 0,
			requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
			estimated = M.data.estimated == true,
			hours = {},
			models = {},
			tokensFrom = M.data.tokensFrom,
			startedAt = M.data.startedAt,
		}
		local active, perModel = {}, {}

		for key, day in pairs(M.data.days) do
			local index = clock.dayNumberOfKey(key)
			if index and index <= today and (from == nil or index >= from) then
				out.sessions = out.sessions + number(day.sessions)
				out.messages = out.messages + number(day.messages)
				out.userMessages = out.userMessages + number(day.userMessages)
				out.replies = out.replies + number(day.replies)
				out.tokensIn = out.tokensIn + number(day.tokensIn)
				out.tokensOut = out.tokensOut + number(day.tokensOut)
				out.cost = out.cost + number(day.cost)
				out.requests = out.requests + number(day.requests)
				out.toolCalls = out.toolCalls + number(day.toolCalls)
				out.toolErrors = out.toolErrors + number(day.toolErrors)
				out.errors = out.errors + number(day.errors)
				for hour, count in pairs(day.hours or {}) do
					out.hours[hour] = number(out.hours[hour]) + number(count)
				end
				for id, entry in pairs(day.models or {}) do
					local row = perModel[id]
					if not row then
						row = { id = id, requests = 0, tokensIn = 0, tokensOut = 0, cost = 0 }
						perModel[id] = row
					end
					row.requests = row.requests + number(entry.requests)
					row.tokensIn = row.tokensIn + number(entry.tokensIn)
					row.tokensOut = row.tokensOut + number(entry.tokensOut)
					row.cost = row.cost + number(entry.cost)
				end
				if dayIsActive(day) then
					active[index] = true
					out.activeDays = out.activeDays + 1
				end
			end
		end

		out.tokens = out.tokensIn + out.tokensOut
		out.currentStreak, out.longestStreak = streaksOf(active, today, from)

		local peakHour, peakCount = nil, 0
		for hour = 0, 23 do
			local count = number(out.hours[tostring(hour)])
			if count > peakCount then peakHour, peakCount = hour, count end
		end
		out.peakHour = peakHour
		out.peakHourCount = peakCount

		for _, row in pairs(perModel) do
			row.tokens = row.tokensIn + row.tokensOut
			local lifetime = M.data.models[row.id]
			row.firstAt = lifetime and lifetime.firstAt or nil
			row.lastAt = lifetime and lifetime.lastAt or nil
			out.models[#out.models + 1] = row
		end
		-- Tokens first, then requests: two models with one request each are ordered by
		-- which actually did the work.
		table.sort(out.models, function(a, b)
			if a.tokens ~= b.tokens then return a.tokens > b.tokens end
			if a.requests ~= b.requests then return a.requests > b.requests end
			return a.id < b.id
		end)
		for _, row in pairs(out.models) do
			row.share = out.tokens > 0 and (row.tokens / out.tokens)
				or (out.requests > 0 and (row.requests / out.requests) or 0)
		end
		out.topModel = out.models[1]
		return out
	end

	-- One column per week, seven rows per column, ending on the week that contains
	-- today. Every cell names the day it stands for, so a cell with no record is
	-- reported as a real day with nothing on it rather than as a gap.
	function M.heatmap(weeks)
		weeks = math.max(math.floor(tonumber(weeks) or 26), 1)
		local today = clock.dayNumber()
		-- Monday-based columns, so the last column is the current week.
		local weekday = clock.weekdayOfDayNumber(today)
		local lastMonday = today - (weekday - 1)
		local firstMonday = lastMonday - (weeks - 1) * 7

		local peak = 0
		local columns = {}
		for column = 1, weeks do
			local cells = {}
			for row = 1, 7 do
				local index = firstMonday + (column - 1) * 7 + (row - 1)
				local key = clock.keyFromDayNumber(index)
				local day = M.data.days[key]
				local value = day and (number(day.tokensIn) + number(day.tokensOut)) or 0
				local messages = day and number(day.messages) or 0
				if value > peak then peak = value end
				cells[row] = {
					key = key,
					day = index,
					future = index > today,
					tokens = value,
					messages = messages,
					sessions = day and number(day.sessions) or 0,
					requests = day and number(day.requests) or 0,
					active = day ~= nil and dayIsActive(day),
				}
			end
			columns[column] = cells
		end

		-- Four levels, so a quiet day still reads as activity next to a heavy one.
		for _, cells in ipairs(columns) do
			for _, cell in ipairs(cells) do
				cell.level = 0
				if cell.active then
					cell.level = 1
					if peak > 0 and cell.tokens > 0 then
						local share = cell.tokens / peak
						if share > 0.66 then
							cell.level = 4
						elseif share > 0.33 then
							cell.level = 3
						else
							cell.level = 2
						end
					end
				end
			end
		end
		return { columns = columns, weeks = weeks, peak = peak, fromKey = clock.keyFromDayNumber(firstMonday) }
	end

	-- The comparison the home card ends on. Absent below one whole book, because
	-- "0.4x a book" is a sentence nobody wants and a rounding away from claiming a
	-- book that was not written.
	function M.comparison(tokens)
		local value = number(tokens)
		if value < BOOK.tokens then return nil end
		local times = value / BOOK.tokens
		local rendered = string.format("%d", math.floor(times + 0.5))
		if times < 10 then rendered = string.format("%.1f", times) end
		return string.format("You've used ~%s\195\151 more tokens than %s.", rendered, BOOK.title)
	end

	function M.topTools(limit)
		local out = {}
		for name, count in pairs(M.data.tools) do
			out[#out + 1] = { name = name, count = number(count) }
		end
		table.sort(out, function(a, b)
			if a.count ~= b.count then return a.count > b.count end
			return a.name < b.name
		end)
		if limit and #out > limit then out = util.slice(out, 1, limit) end
		return out
	end

	function M.reset()
		M.data = blank()
		M.data.seededAt = clock.ms()
		rebuildSeen()
		M.saveNow()
		M.changed:fire(M.data)
	end

	return M
end
end)()

-- ==========================================================================
-- agent/subagent
-- ==========================================================================
__UAI_MODULES["agent/subagent"] = (function()
-- Subagent dispatch.
--
-- A subagent is a full session with a smaller tool set, its own context and no
-- interface. It exists to keep long or repetitive work out of the main
-- conversation: the parent pays for one paragraph of report instead of forty tool
-- results, and a search that goes nowhere costs the main context nothing.
--
-- Depth is capped because a subagent that can spawn subagents indefinitely is a
-- fork bomb with a token bill.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local prompt = env.require("agent/prompt")
	local session = env.require("agent/session")

	local M = {}

	-- Groups a subagent may be given. Anything that changes the world is absent
	-- from the read-only preset, which is the default: the point of a subagent is
	-- usually to go and find out, and a delegated write is hard for the user to
	-- attribute afterwards.
	M.PRESETS = {
		read = { instance = true, world = true, players = true, perf = true, meta = true, web = true, net = true, fs = true, skills = true },
		web = { web = true, net = true, skills = true },
		game = { instance = true, world = true, players = true, gui = true, remotes = true, meta = true, skills = true },
		full = nil,
	}

	-- The register.
	--
	-- `live` was a bare counter, which is enough to enforce a ceiling and nothing else:
	-- there was no way to ask what is running, what it was asked to do, or to stop one
	-- of them without stopping the whole turn. A dispatch is the longest-lived and least
	-- visible thing this client does -- minutes of work, its own context, its own tool
	-- calls, and a transcript card that scrolls away -- so each one gets a record here
	-- that outlives its card, and the interface reads this rather than the log.
	--
	-- Bounded, because a long session dispatches a lot: running records are never
	-- dropped, finished ones are kept newest-first up to the history limit.
	--
	-- Of those, only the newest few keep the session they ran on. A child's context is
	-- the expensive half of it -- every tool result it collected -- and holding two dozen
	-- of them for the life of the client would make delegation the largest thing in
	-- memory. So a record outlives its session: the newest are resumable, the rest keep
	-- their report and lose the context behind it.
	local HISTORY = 24
	local RESUMABLE = 6

	M.records = {}
	M.changed = signal.new("subagents")

	local function announceChange()
		M.changed:fire(M.records)
	end

	local function isLive(record)
		return record.status == "running" or record.status == "queued"
	end

	-- Newest first, which is the order the register is held in, so the count runs from
	-- the most recent finished dispatch outward. It used to run from the oldest, which
	-- inverted both rules: the twenty-four kept were the oldest twenty-four, and the
	-- dispatch that had just reported back was the first one dropped.
	local function trimHistory()
		local finished = 0
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				kept[#kept + 1] = record
			else
				finished = finished + 1
				if finished <= HISTORY then
					if finished > RESUMABLE then
						-- Nothing can address this one any more, so neither reference earns its
						-- keep: the child's context, and the conversation that was waiting on
						-- it. `parentTitle` is a string and stays, because the card still says
						-- where the dispatch came from.
						record.session = nil
						record.parent = nil
					end
					kept[#kept + 1] = record
				end
			end
		end
		M.records = kept
	end

	local function track(record)
		record.startedAt = clock.ms()
		record.status = "queued"
		record.calls = 0
		record.finishedCalls = 0
		record.tools = {}
		table.insert(M.records, 1, record)
		trimHistory()
		announceChange()
		return record
	end

	-- Newest first, running before finished: what a panel wants to draw in order.
	function M.list()
		local running, done = {}, {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				running[#running + 1] = record
			else
				done[#done + 1] = record
			end
		end
		local out = {}
		for _, record in ipairs(running) do out[#out + 1] = record end
		for _, record in ipairs(done) do out[#out + 1] = record end
		return out
	end

	function M.running()
		local out = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	-- The finished dispatches that still have their context, newest first: the ones a
	-- follow-up can be sent to.
	function M.resumable()
		local out = {}
		for _, record in ipairs(M.records) do
			if record.session and not isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	function M.get(id)
		for _, record in ipairs(M.records) do
			if record.id == id then return record end
		end
		return nil
	end

	-- Finds the dispatch the model named.
	--
	-- The id is what the report hands back, so that is the exact match. A label prefix
	-- is accepted too: a model that has lost the id reaches for the task's first line
	-- instead, and refusing that spends a step teaching it nothing.
	function M.find(reference)
		local needle = util.trim(tostring(reference or ""))
		if needle == "" then return nil end
		local exact = M.get(needle)
		if exact then return exact end
		local lowered = needle:lower()
		for _, record in ipairs(M.records) do
			if tostring(record.label):lower():find(lowered, 1, true) then return record end
		end
		return nil
	end

	-- Stops one dispatch without stopping the turn that asked for it.
	--
	-- The child notices between steps, so this returns before it has actually stopped;
	-- the record says so until its loop unwinds. There is no way to kill a Luau thread,
	-- which is why the flag is the mechanism everywhere in this client.
	function M.stop(id)
		local record = M.get(id)
		if not record or not record.session then return false end
		if not isLive(record) then return false end
		record.session.abortFlag = true
		record.stopping = true
		announceChange()
		log.info("subagent", "stop requested for " .. tostring(record.label))
		return true
	end

	function M.stopAll()
		local stopped = 0
		for _, record in ipairs(M.running()) do
			if M.stop(record.id) then stopped = stopped + 1 end
		end
		return stopped
	end

	-- Clears the finished ones. Running dispatches are left alone.
	function M.clearHistory()
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then kept[#kept + 1] = record end
		end
		M.records = kept
		announceChange()
		return true
	end

	function M.available(depth)
		local limit = config.get("agent.subagentDepth", 2)
		return (depth or 0) < limit
	end

	-- How long a subagent may run, and how long the tool that started it waits.
	--
	-- Both come from one number on purpose. They used to be independent: the child was
	-- given four minutes and the call that started it was bounded by the generic
	-- `agent.toolTimeout` of twenty-five seconds, so nearly every dispatch was reported
	-- to the model as "did not finish within 25s and was left running in the
	-- background" -- and it was, against a caller that had stopped listening. The
	-- report arrived a minute later with nowhere to go, and the model, asked what its
	-- subagents found, could only say it never heard back.
	--
	-- The slack covers one request. A child notices its own deadline between steps, so
	-- it returns a moment after the budget expires rather than exactly on it, and the
	-- tool has to still be there to take the answer.
	local SLACK_SECONDS = 60

	-- Whether a child runs with its clocks off. Read per run rather than captured, so
	-- flipping the switch applies to the next dispatch and to the next follow-up on a
	-- child that has already reported.
	function M.unlimited()
		return config.get("agent.subagentUnlimited", false) == true
	end

	function M.budgetSeconds()
		return math.max(tonumber(config.get("agent.subagentBudget", 240)) or 240, 15)
	end

	-- A day, and it is not a deadline in disguise: with the ceiling lifted there is no
	-- budget to derive a timeout from, and the honest bound on the call above is "as
	-- long as the child takes". A caller that gives up first is the failure this number
	-- exists to avoid -- the child cannot be killed, so it finishes into a void and the
	-- user pays for a report nobody collects.
	local FOREVER_SECONDS = 86400

	function M.toolTimeout()
		if M.unlimited() then return FOREVER_SECONDS end
		return M.budgetSeconds() + SLACK_SECONDS
	end

	-- Width, not just depth.
	--
	-- Several dispatch_agent calls in one step run at the same time, which is the
	-- point: three searches in parallel cost one step instead of three. What that
	-- leaves unbounded is the tree. `agent.toolConcurrency` caps one batch, so it caps
	-- a parallel dispatch from the main conversation -- but a subagent given the
	-- `full` preset dispatches its own batch under its own cap, and two levels of
	-- that multiply rather than add. This is the ceiling on live children anywhere,
	-- and the depth cap above is no substitute for it.
	M.live = 0

	function M.concurrencyLimit()
		return math.max(tonumber(config.get("agent.subagentConcurrency", 8)) or 8, 1)
	end

	-- A dispatch over the ceiling waits for a slot instead of failing: the model has
	-- already paid for the step that asked, and a refusal would spend another one
	-- learning that it asked for too much at once.
	--
	-- The wait is bounded and comes out of the child's own budget, which is what keeps
	-- `toolTimeout` a valid bound on the call above it. Without that subtraction a
	-- queued child could finish after the tool that started it had given up, and a
	-- report nobody is left to collect is exactly the failure the budget and the
	-- timeout were tied together to prevent.
	--
	-- Returns the budget to run on, `nil` when there is no budget to run against, or
	-- `false` when the turn was stopped while queued. An unlimited child has nothing to
	-- subtract from, so its wait is capped by the ceiling alone.
	local QUEUE_CEILING = 45

	local function waitForSlot(budget, aborted)
		local ceiling = budget and math.min(QUEUE_CEILING, budget / 4) or QUEUE_CEILING
		local waited = 0
		while M.live >= M.concurrencyLimit() and waited < ceiling do
			if aborted and aborted() then return false end
			waited = waited + (clock.wait(0.2) or 0.2)
		end
		if waited <= 0 then return budget end
		log.info("subagent", string.format("queued %.1fs for a slot (%d live)", waited, M.live))
		if not budget then return nil end
		return math.max(budget - waited, 15)
	end

	-- The card in the transcript is titled with the task, so the first line of it is
	-- what the user reads to tell three concurrent subagents apart.
	local function labelFor(task)
		local first = tostring(task):match("^%s*([^\n]*)") or ""
		first = util.trim(first)
		if first == "" then first = "task" end
		return util.ellipsis(first, 64)
	end

	-- Live view.
	--
	-- The transcript renders the parent's event stream and nothing else, so a subagent
	-- that wants to be watched has to speak through it. Every event carries the child's
	-- id, which keys the card, and the id of the tool call that started it, which tells
	-- the view what to nest the card under.
	--
	-- One subscription per child, made with it and kept for the rest of its life: a
	-- follow-up runs the same session again, and a second subscription would draw every
	-- row twice. Which conversation to narrate into is read off the record rather than
	-- captured here, for the same reason -- the turn asking a follow-up is a different
	-- tool call, sometimes in a different conversation, and the card has to appear under
	-- the row the user is looking at now.
	--
	-- Tool RESULTS are summarised to one line rather than forwarded: absorbing that
	-- volume is the entire point of a subagent, and the parent's log is bounded. What
	-- does go across is names, outcomes and timings, because that is the difference
	-- between watching work happen and watching a spinner.
	local function wire(record, child)
		local function announce(kind, payload)
			local parent = record.parent
			if not parent then return end
			payload = payload or {}
			payload.id = record.id
			payload.call = record.callId
			payload.label = record.label
			parent.emit(kind, payload)
		end
		record.announce = announce

		-- Stop has to reach the child, from whichever conversation is waiting on it.
		-- Without this, aborting the turn left every dispatched subagent running out its
		-- full budget against a conversation that had already moved on -- billed,
		-- invisible and unstoppable.
		child.aborted = function()
			if child.abortFlag == true then return true end
			local parent = record.parent
			return parent ~= nil and parent.aborted() == true
		end

		child.events:connect(function(event)
			if event.kind == "tool:call" then
				record.calls = (record.calls or 0) + 1
				record.currentTool = tostring(event.name)
				-- Names only, and the last twelve of them: the register is read by a
				-- panel that lists every dispatch in the session, so it cannot hold
				-- their arguments as well.
				record.tools[#record.tools + 1] = tostring(event.name)
				if #record.tools > 12 then table.remove(record.tools, 1) end
				announceChange()
				announce("subagent:tool", {
					callId = event.id,
					name = event.name,
					risk = event.risk,
					-- Forwarded whole, and summarised by the view instead.
					--
					-- A child session is headless and therefore keeps no log of its own, so
					-- this event is the only record that the call ever happened. At 160
					-- characters, whitespace-collapsed, the Luau a subagent executed was
					-- unrecoverable -- and a subagent is exactly where the long-running code
					-- in this client gets run. The parent's log is bounded at 400 events,
					-- which is what caps the cost of keeping it.
					arguments = tostring(event.arguments or ""),
					index = record.calls,
				})
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				record.finishedCalls = (record.finishedCalls or 0) + 1
				announceChange()
				announce("subagent:tool:done", {
					callId = event.id,
					name = event.name,
					ok = event.kind == "tool:result",
					ms = event.ms,
					summary = util.ellipsis(tostring(event.text or ""):gsub("%s+", " "), 140),
					-- The full result as well, for the row that can open. `summary` is what
					-- the collapsed line shows and stays short.
					text = tostring(event.text or ""),
				})
			elseif event.kind == "assistant:text" then
				if util.trim(tostring(event.text or "")) ~= "" then
					announce("subagent:text", { text = util.ellipsis(util.trim(event.text), 400) })
				end
			elseif event.kind == "status" then
				-- "Ready" is the child's own idle text and means nothing on a card that
				-- reports its finish separately. Dropping it here rather than in the
				-- view keeps one entry per turn out of the parent's bounded log.
				if tostring(event.text) ~= "Ready" then
					record.statusText = tostring(event.text)
					announceChange()
					announce("subagent:status", { text = tostring(event.text) })
				end
			elseif event.kind == "error" then
				record.statusText = tostring(event.message)
				announceChange()
				announce("subagent:status", { text = tostring(event.message), bad = true })
			elseif event.kind == "permission:ask" then
				-- Nothing is subscribed to a headless session, so a prompt raised
				-- inside a subagent has to surface on the parent's stream or it
				-- would sit unanswered until its own deadline.
				local parent = record.parent
				if parent then parent.emit("permission:ask", event) end
			end
		end)
	end

	-- One run of a child: the slot, the announcement, the loop and the report. Shared
	-- by the first dispatch and by every follow-up, so a resumed subagent is watched,
	-- counted and bounded exactly like a fresh one.
	--
	-- Everything a run needs is read here rather than fixed when the child was created,
	-- because a second turn is a different turn: a different caller, and possibly a
	-- different answer from the unlimited switch.
	local function runChild(record, text, opts)
		opts = opts or {}
		local child = record.session
		local unlimited = M.unlimited()
		local announce = record.announce

		local budget = waitForSlot(unlimited and nil or (opts.budgetSeconds or M.budgetSeconds()),
			record.parent and record.parent.aborted or nil)
		if budget == false then
			record.status = "stopped"
			record.ms = clock.since(record.startedAt)
			record.report = "Stopped before it started."
			announceChange()
			return nil, "the turn was stopped before this subagent started"
		end

		child.abortFlag = false
		child.turns = child.turns + 1
		child.toolEpoch = {}
		child.unlimited = unlimited
		child.budgetSeconds = budget
		if opts.turns then child.maxTurns = opts.turns end
		record.status = "running"
		record.stopping = nil
		record.startedAt = clock.ms()
		record.budget = budget
		record.unlimited = unlimited
		record.turns = child.maxTurns
		record.runs = (record.runs or 0) + 1
		announceChange()

		announce("subagent:start", {
			task = util.ellipsis(text, 400),
			preset = record.preset,
			turns = unlimited and 0 or child.maxTurns,
			budget = budget,
			unlimited = unlimited,
			depth = record.depth,
			followUp = record.runs > 1,
		})

		-- Counted around the pcall rather than around the whole setup, so a raise
		-- anywhere inside cannot leak a slot and permanently narrow the ceiling.
		local started = clock.ms()
		M.live = M.live + 1
		local ok, reply = pcall(function() return env.require("agent/loop").run(child, text) end)
		M.live = math.max(M.live - 1, 0)

		local elapsed = clock.since(started)
		if not ok then
			child.abortFlag = true
			log.warn("subagent", "failed", reply)
			local note = "the subagent failed: " .. util.ellipsis(tostring(reply), 200)
			record.status = "failed"
			record.ms = elapsed
			record.report = note
			record.currentTool = nil
			announceChange()
			announce("subagent:done", { ms = elapsed, ok = false, text = note })
			return nil, note
		end

		local stats = child.ctx.stats()
		local aborted = child.aborted() == true
		log.info("subagent", string.format("finished in %s over %d messages%s",
			util.formatDuration(elapsed), stats.messages, aborted and " (stopped)" or ""))

		record.status = aborted and "stopped" or "done"
		record.ms = elapsed
		record.messages = stats.messages
		record.turnsUsed = stats.turns
		record.report = tostring(reply)
		record.currentTool = nil
		record.stopping = nil
		-- Now that this one has finished, it is the newest resumable record -- which is
		-- what pushes the oldest past the line and releases the context behind it.
		trimHistory()
		announceChange()

		announce("subagent:done", {
			ms = elapsed,
			ok = not aborted,
			aborted = aborted,
			messages = stats.messages,
			turns = stats.turns,
			resumable = record.session ~= nil and not aborted,
			text = util.ellipsis(tostring(reply), 600),
		})

		return {
			id = record.id,
			text = tostring(reply),
			ms = elapsed,
			messages = stats.messages,
			turns = stats.turns,
			aborted = aborted,
			resumable = record.session ~= nil,
		}
	end

	-- Blocks until the subagent finishes. The caller is already on a tool thread, so
	-- yielding here is correct; the tool timeout above it comes from M.toolTimeout so it
	-- outlasts the child rather than the other way round.
	function M.dispatch(opts)
		local parent = opts.parent
		local depth = (parent and parent.depth or 0) + 1

		if not M.available(depth - 1) then
			return nil, "subagent depth limit reached (" .. tostring(config.get("agent.subagentDepth", 2)) .. ")"
		end

		local task_text = util.trim(opts.task)
		if task_text == "" then return nil, "a subagent needs a task" end

		local turns = opts.turns or config.get("agent.subagentTurns", 14)

		-- Registered before the queue wait, so a dispatch parked waiting for a slot is
		-- visible as one rather than looking like nothing happened.
		local record = track({
			id = util.uid("agent"),
			label = labelFor(task_text),
			task = task_text,
			preset = opts.preset or "read",
			depth = depth,
			-- The conversation currently waiting on this child, and the tool call inside
			-- it. Both move when a follow-up arrives from somewhere else, which is why
			-- they live on the record rather than in a closure.
			parent = parent,
			callId = opts.callId,
			parentId = parent and parent.id or nil,
			parentTitle = parent and parent.title or nil,
			turns = turns,
		})

		local excluded = { ask_user = true }
		if record.preset ~= "full" then
			-- Every preset must be able to read skills first. This does not grant a
			-- restricted worker permission to change the user's standing playbooks.
			excluded.skills_write, excluded.skills_install, excluded.skills_delete = true, true, true
		end
		local child = session.create({
			title = "subagent",
			depth = depth,
			headless = true,
			maxTurns = turns,
			toolGroups = M.PRESETS[opts.preset or "read"],
			-- A child has no user to ask, so the tool that asks is absent from its
			-- catalogue entirely rather than described-and-refused. The brief also
			-- says so, because a model that knows it cannot ask writes a complete
			-- report instead of stopping at a question.
			toolExclude = excluded,
			-- Streaming is left to the provider and the Ask-for-streams setting, the
			-- same as the main conversation. It used to be refused here, on the reading
			-- that a child with no interface has nothing to stream into -- but no Roblox
			-- transport delivers a body incrementally anyway, so that bought nothing and
			-- cost the two things the streamed shape carries: reasoning text, and the
			-- per-request usage block some gateways report token counts in at all. Every
			-- subagent request landing without one was enough to mark the whole session's
			-- cost readout estimated.
		})
		-- The record is what the Subagents panel reads, so it is kept whether or not
		-- there is a parent transcript to narrate into. The wiring below is therefore
		-- unconditional; only the forwarding inside it is not.
		record.session = child

		-- The brief replaces the main system prompt rather than appending to it, and it
		-- is a function so that every turn -- including a follow-up months of tool calls
		-- later -- is built against the environment and the switches in force then.
		-- Carrying it on the session, instead of swapping the prompt module's builder, is
		-- what makes two subagents dispatched in the same batch safe.
		child.systemPrompt = function()
			return prompt.subagent(task_text, {
				extra = (opts.extra or "") .. "\nNative workspace references are shared with the user. Respect this subagent's tool scope; never use a controller or generated script to bypass a denied native action.",
				unlimited = M.unlimited(),
			})
		end

		wire(record, child)
		return runChild(record, task_text, {
			turns = opts.turns,
			budgetSeconds = opts.budgetSeconds,
		})
	end

	-- A second turn on a subagent that has already reported back.
	--
	-- A dispatch used to be one shot: the child answered, its context went on the floor,
	-- and a parent that wanted one more fact had to describe the whole job again to a
	-- fresh subagent that would go and rediscover it. This continues the same
	-- conversation instead -- the child still has everything it found -- which is what
	-- makes a subagent that stopped at a limit worth talking to rather than worth
	-- replacing, and what lets the parent steer one instead of only reading it.
	function M.followUp(opts)
		local record = M.find(opts.id)
		if not record then
			local open = M.resumable()
			if #open == 0 then
				return nil, "no subagent is open for a follow-up. Dispatch one with dispatch_agent first."
			end
			local names = {}
			for _, candidate in ipairs(open) do
				names[#names + 1] = string.format("%s (%s)", candidate.id, candidate.label)
			end
			return nil, string.format("no subagent matches '%s'. Open for a follow-up: %s",
				tostring(opts.id), table.concat(names, "; "))
		end
		if isLive(record) then
			return nil, "that subagent is still working. Its report will arrive on the call that started it."
		end
		if not record.session then
			return nil, "that subagent's context has already been released, so there is nothing to continue. Dispatch a new one with what you know."
		end

		local text = util.trim(opts.task)
		if text == "" then return nil, "a follow-up needs a message" end

		record.parent = opts.parent or record.parent
		record.callId = opts.callId
		return runChild(record, text, { turns = opts.turns })
	end

	return M
end
end)()

-- ==========================================================================
-- agent/usage
-- ==========================================================================
__UAI_MODULES["agent/usage"] = (function()
-- Token and cost accounting.
--
-- Providers report usage inconsistently -- some only in a streamed final chunk,
-- some not at all -- so counts are taken from the response when present and
-- estimated when not, and an estimated figure is always labelled as one. Prices
-- are a convenience, not an invoice: they are per million tokens, they date from
-- when this was written, and the panel says so.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")

	local M = {
		session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false },
		turn = { prompt = 0, completion = 0, total = 0, cost = 0 },
		changed = signal.new("usage"),
		-- One request, as it was measured, rather than the running totals `changed`
		-- carries. This is the only place in the client where a model id and the tokens
		-- it actually spent are in scope together, so anything keeping a per-model
		-- history has to hear about it here.
		recorded = signal.new("usage:recorded"),
	}

	-- input, output per million tokens. Matched longest-prefix, so a dated model
	-- id still resolves.
	--
	-- The current Claude generations are listed individually because the family
	-- names no longer predict the price: an Opus has cost $5/$25 since 4.6, a third
	-- of what the 4.5-and-earlier line did, and reporting the old number made every
	-- turn in this client look three times more expensive than it was.
	local PRICES = {
		["gpt-4o-mini"] = { 0.15, 0.60 },
		["gpt-4o"] = { 2.50, 10.00 },
		["gpt-4.1-mini"] = { 0.40, 1.60 },
		["gpt-4.1"] = { 2.00, 8.00 },
		["o4-mini"] = { 1.10, 4.40 },
		["claude-haiku"] = { 1.00, 5.00 },
		["claude-sonnet"] = { 3.00, 15.00 },
		["claude-sonnet-5"] = { 2.00, 10.00 },
		["claude-opus"] = { 15.00, 75.00 },
		["claude-opus-4-6"] = { 5.00, 25.00 },
		["claude-opus-4-7"] = { 5.00, 25.00 },
		["claude-opus-4-8"] = { 5.00, 25.00 },
		["claude-opus-5"] = { 5.00, 25.00 },
		-- Covers the .1 revisions too: the id is a superstring of this prefix.
		["claude-fable-5"] = { 10.00, 50.00 },
		["claude-mythos-5"] = { 10.00, 50.00 },
		["deepseek-reasoner"] = { 0.55, 2.19 },
		["deepseek-chat"] = { 0.27, 1.10 },
		["llama-3.3-70b"] = { 0.59, 0.79 },
		["llama-3.1-8b"] = { 0.05, 0.08 },
		["mistral-large"] = { 2.00, 6.00 },
		["mistral-small"] = { 0.20, 0.60 },
		["grok-4"] = { 3.00, 15.00 },
		["grok-3-mini"] = { 0.30, 0.50 },
		["qwen"] = { 0.40, 0.80 },
		["gemini-2.5-flash"] = { 0.30, 2.50 },
	}

	function M.priceFor(model, record) local ok, pricing = pcall(env.require, "agent/pricing"); if ok and pricing and pricing.priceFor then local price = pricing.priceFor(model, record); if price then return price end end
		local id = tostring(model or ""):lower()
		local best, bestLength = nil, 0
		for prefix, price in pairs(PRICES) do
			if id:find(prefix, 1, true) and #prefix > bestLength then
				best, bestLength = price, #prefix
			end
		end
		return best
	end

	-- Four characters per token is the usual English approximation; it is within
	-- about ten percent for prose and pessimistic for code, which is the right
	-- direction for a context budget.
	function M.estimateText(text)
		if type(text) ~= "string" then return 0 end
		return math.ceil(#text / 4)
	end

	function M.estimateMessages(messages)
		local total = 0
		for _, message in ipairs(messages or {}) do
			-- Per-message framing overhead, plus the role name.
			total = total + 4 + M.estimateText(message.content)
			local reasoning = message.reasoning_content or message.reasoning
			if reasoning then total = total + M.estimateText(reasoning) end
			-- Internal messages carry toolCalls; wire messages carry tool_calls, and
			-- the loop estimates over the wire form.
			for _, call in ipairs(message.toolCalls or message.tool_calls or {}) do
				local fn = call["function"] or {}
				total = total + 8 + M.estimateText(fn.name) + M.estimateText(fn.arguments)
			end
		end
		return total
	end

	function M.startTurn()
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
	end

	-- `usage` is the provider block when it exists. `fallback` supplies estimates
	-- so a provider that reports nothing still moves the counters.
	function M.record(usage, model, fallback, record)
		local prompt, completion, estimated
		if type(usage) == "table" and (usage.prompt_tokens or usage.completion_tokens) then
			prompt = tonumber(usage.prompt_tokens) or 0
			completion = tonumber(usage.completion_tokens) or 0
			estimated = false
		else
			prompt = (fallback and fallback.prompt) or 0
			completion = (fallback and fallback.completion) or 0
			estimated = true
		end

		local price = M.priceFor(model, record)
		local cost = 0
		if price then
			cost = (prompt / 1000000) * price[1] + (completion / 1000000) * price[2]
		end

		if not (fallback and fallback.background) then
			M.turn.prompt = M.turn.prompt + prompt
			M.turn.completion = M.turn.completion + completion
			M.turn.total = M.turn.prompt + M.turn.completion
			M.turn.cost = M.turn.cost + cost
		end

		M.session.prompt = M.session.prompt + prompt
		M.session.completion = M.session.completion + completion
		M.session.total = M.session.prompt + M.session.completion
		M.session.cost = M.session.cost + cost
		M.session.requests = M.session.requests + 1
		if estimated then M.session.estimated = true end

		local cached = util.get(usage or {}, "prompt_tokens_details.cached_tokens", 0)
		local reasoning = util.get(usage or {}, "completion_tokens_details.reasoning_tokens", 0)
		M.session.cached = (M.session.cached or 0) + (tonumber(cached) or 0)
		M.session.reasoning = (M.session.reasoning or 0) + (tonumber(reasoning) or 0)

		local delta = {
			model = model,
			prompt = prompt,
			completion = completion,
			cost = cost,
			estimated = estimated,
			cached = tonumber(cached) or 0,
			reasoning = tonumber(reasoning) or 0,
		}
		M.recorded:fire(delta)
		M.changed:fire(M.session, M.turn)
		return { prompt = prompt, completion = completion, cost = cost, estimated = estimated }
	end

	function M.reset()
		M.session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false }
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
		M.changed:fire(M.session, M.turn)
	end

	function M.formatCost(value)
		if value <= 0 then return "" end
		if value < 0.01 then return string.format("$%.4f", value) end
		return string.format("$%.3f", value)
	end

	function M.line()
		local parts = {
			util.formatNumber(M.session.total) .. " tokens",
			util.formatNumber(M.session.prompt) .. " in",
			util.formatNumber(M.session.completion) .. " out",
		}
		local cost = M.formatCost(M.session.cost)
		if cost ~= "" then parts[#parts + 1] = cost .. (M.session.estimated and " est." or "") end
		return table.concat(parts, "  ")
	end

	return M
end
end)()

-- ==========================================================================
-- net/bridge
-- ==========================================================================
__UAI_MODULES["net/bridge"] = (function()
-- The game half of the web bridge.
--
-- A Roblox client cannot listen for a connection, so it cannot be talked to -- it
-- can only talk. This module is therefore a client of a small local process
-- (bridge/server.js) rather than a server: it pushes the session's events up and
-- long-polls for anything typed in the browser.
--
-- Two threads, because the two directions have different rhythms. Events must
-- leave promptly and in order, so they are batched off a queue every fraction of a
-- second. Commands arrive rarely, so that direction is one request held open for
-- eighteen seconds at a time -- which reads as instant and costs three requests a
-- minute, where a busy poll would cost hundreds.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local config = env.require("runtime/config")
	local dispose = env.require("runtime/dispose")
	local caps = env.require("runtime/caps")
	local http = env.require("net/http")
	local signal = env.require("runtime/signal")

	-- Fired on a state transition only -- started, stopped, reachable, unreachable --
	-- so the Settings panel can show the truth without polling for it.
	local M = { running = false, online = false, lastError = nil, changed = signal.new("bridge") }
	local clientId = env.services.HttpService:GenerateGUID(false)

	-- Queue bounds limit offline buffering; event text itself stays lossless so
	-- Markdown, code listings, and streamed finals agree between both interfaces.
	local QUEUE_CAP = 200
	local DRAIN_SECONDS = 0.15
	local POLL_TIMEOUT = 25

	-- What the browser renders. Everything else -- reasoning, usage, request and turn
	-- bookkeeping, compaction -- stays in the client, so a thinking block does not
	-- travel over the wire to be discarded on arrival.
	local FORWARD = {
		["user"] = true,
		["assistant:text"] = true,
		["tool:call"] = true,
		["tool:result"] = true,
		["tool:error"] = true,
		["tool:progress"] = true,
		["status"] = true,
		["error"] = true,
		["abort"] = true,
		["cleared"] = true,
		["provider:switch"] = true,
		["permission:ask"] = true,
		["subagent:start"] = true,
		["subagent:done"] = true,
		-- The running commentary around a turn. None of it is conversation, but the
		-- browser's telemetry, latency readouts and live subagent cards are built
		-- from exactly these.
		["assistant:reasoning"] = true,
		["request:start"] = true,
		["request:retry"] = true,
		["request:done"] = true,
		["usage"] = true,
		["turn:start"] = true,
		["turn:end"] = true,
		["compact"] = true,
		["ask:user"] = true,
		["subagent:text"] = true,
		["subagent:tool"] = true,
		["subagent:tool:done"] = true,
	}

	-- Event payloads are not automatically safe to encode. `permission:ask` carries
	-- the resolve function the in-game panel calls, and signal.lua exists precisely
	-- so that payloads like it can hold non-serialisable values. Anything that is
	-- not a string, number, boolean or table is dropped rather than encoded.
	local function scrub(value, depth)
		local kind = type(value)
		if kind == "string" then return value end
		if kind == "number" or kind == "boolean" then return value end
		if kind ~= "table" or depth > 5 then return nil end
		local out = {}
		for key, item in pairs(value) do
			local keyKind = type(key)
			if keyKind == "string" or keyKind == "number" then
				local cleaned = scrub(item, depth + 1)
				if cleaned ~= nil then out[key] = cleaned end
			end
		end
		return out
	end

	local queue = {}
	local snapshotPending = nil
	local attachedId, detach = nil, nil

	local function enqueue(payload)
		if type(payload) ~= "table" or not FORWARD[payload.kind] then return end
		local entry = scrub(payload, 0)
		entry.sessionId = payload.sessionId or attachedId
		queue[#queue + 1] = entry
		-- Dropping the oldest rather than the newest: a browser that reconnects gets
		-- a fresh snapshot anyway, so the recent end is the half worth keeping.
		while #queue > QUEUE_CAP do table.remove(queue, 1) end
	end

	-- A browser can open at any point in a turn, so the game sends its whole
	-- transcript on connect and whenever the active thread changes. session.log is
	-- already bounded to 400 entries, which is the same ceiling the in-game view
	-- redraws from.
	local function snapshotOf(session)
		local out = {}
		for _, payload in ipairs(session.log or {}) do
			if FORWARD[payload.kind] then out[#out + 1] = scrub(payload, 0) end
		end
		return out
	end

	-- The browser follows the active thread rather than owning one, so switching
	-- conversations in-game moves the browser with it. Re-checked on every drain
	-- because a switch is not announced to this module directly.
	local function attach()
		local sessions = env.require("agent/session")
		local session = sessions.current()
		if attachedId == session.id then return session end
		if detach then
			pcall(detach)
			detach = nil
		end
		attachedId = session.id
		detach = session.events:connect(enqueue)
		snapshotPending = snapshotOf(session)
		-- The snapshot already includes these events; uploading both would repeat them.
		queue = {}
		return session
	end

	local function base()
		return "http://127.0.0.1:" .. tostring(config.get("bridge.port", 8790))
	end

	local function headers()
		return { ["Authorization"] = "Bearer " .. tostring(config.get("bridge.token", "")), ["X-UAI-Client"] = clientId }
	end

	-- `identity = "none"` because the Claude Code headers identify this client to an
	-- inference gateway and mean nothing to a local relay. `silent` keeps the poll
	-- out of the Requests view.
	local function call(spec)
		spec.headers = headers()
		spec.identity = "none"
		spec.silent = true
		spec.tag = "bridge"
		return http.request(spec)
	end

	local function runCommand(command)
		if type(command) ~= "table" then return end
		local sessions = env.require("agent/session")
		local kind = tostring(command.type or "")
		local session = command.sessionId and sessions.threads[command.sessionId] or sessions.current()
		if not session then error("Conversation no longer exists", 0) end

		if kind == "send" then
			local ok, why = session.send(tostring(command.text or ""), nil, command.files)
			-- A refusal has to travel back, or the browser shows a message it sent and
			-- then nothing at all. session.send declines while a turn is in flight.
			if not ok then
				error(tostring(why or "could not send"), 0)
			end
		elseif kind == "abort" then
			session.abort()
		elseif kind == "clear" then
			if session.busy then error("Stop this conversation before clearing it", 0) end
			session.clear()
		elseif kind == "permission" then
			-- The same door the in-game panel uses: the agent left a resolve function
			-- behind and whoever answers first calls it. No new authority is created
			-- here, and an id that has already been answered is simply absent.
			local permissions = env.require("agent/permissions")
			local entry = permissions.pending[tostring(command.id or "")]
			if entry and type(entry.resolve) == "function" then
				entry.resolve(command.allow == true, command.remember == true)
			end
		elseif kind == "provider" then
			env.require("provider/registry").setActive(tostring(command.id or ""))
		elseif kind == "model" then
			env.require("provider/registry").setModel(tostring(command.provider or ""), tostring(command.model or ""))
			env.require("provider/registry").setActive(tostring(command.provider or ""))
		elseif kind == "models:discover" then
			-- Discovery is a network round trip, so it runs on its own thread: the
			-- poller must not park behind it or the browser would stall for seconds.
			local providers = env.require("provider/registry")
			local record = providers.get(tostring(command.provider or ""))
			if record then
				clock.spawn(function()
					local models = env.require("provider/models")
					local ids, note = models.discover(record, { force = true })
					local count = type(ids) == "table" and #ids or 0
					log.info("bridge", "model discovery: " .. tostring(note) .. " (" .. count .. " models)")
				end)
			end
		elseif kind == "thread" then
			env.require("agent/session").switch(tostring(command.id or ""))
		elseif kind == "thread:new" then
			env.require("agent/session").newThread()
		elseif kind == "thread:delete" then
			env.require("agent/session").remove(tostring(command.id or ""))
		elseif kind == "thread:rename" then
			local target = env.require("agent/session").threads[tostring(command.id or "")]
			if target and target.rename then target.rename(tostring(command.title or "")) end
		elseif kind == "permission-mode" then
			env.require("agent/permissions").setMode(tostring(command.mode or "ask"))
		elseif kind == "subagent:stop" then
			env.require("agent/subagent").stop(tostring(command.id or ""))
		else
			local result = env.require("net/bridge_commands").run(command)
			if result == false then error("Unknown command: " .. kind, 0) end
			return result
		end
	end

	-- Reported once per streak rather than per attempt: with the bridge not running,
	-- a per-attempt warning would be the only thing in the log.
	local function offline(reason)
		local moved = M.online or M.lastError == nil
		M.online = false
		M.lastError = reason
		if moved then
			log.warn("bridge", "not reachable", reason)
			M.changed:fire()
		end
	end

	local function onlineNow()
		if M.online then return end
		M.online = true
		M.lastError = nil
		log.info("bridge", "connected to the local bridge")
		M.changed:fire()
	end

	local alive = false

	-- The browser's panels are drawn from the same modules the in-game interface
	-- reads, so nothing in the web UI is a guess: providers and their real model
	-- lists, the tool registry, threads, subagents, usage and the host's
	-- capabilities all arrive as they are. Pushed at most once a second and only
	-- when the encoded form changed, so a still session costs nothing.
	local function stateOf()
		local sessions = env.require("agent/session")
		local providers = env.require("provider/registry")
		local models = env.require("provider/models")
		local registry = env.require("agent/registry")
		local subagents = env.require("agent/subagent")
		local usage = env.require("agent/usage")
		local permissions = env.require("agent/permissions")
		local place = env.require("runtime/place")

		pcall(function() registry.load() end)

		local threads = {}
		for _, session in ipairs(sessions.list()) do
			threads[#threads + 1] = {
				id = session.id,
				title = session.title,
				place = session.placeName,
				busy = session.busy == true,
				turns = session.turns or 0,
				updatedAt = session.updatedAt or 0,
				active = session.id == sessions.activeId,
				ephemeral = session.ephemeral == true,
			}
		end

		local providerList = {}
		for _, record in ipairs(providers.list()) do
			local health = record.health or {}
			providerList[#providerList + 1] = {
				id = record.id,
				label = record.label,
				baseUrl = record.baseUrl,
				api = record.api,
				authStyle = record.authStyle,
				preset = record.preset,
				hasKey = util.trim(record.apiKey or "") ~= "",
				model = record.model,
				models = models.list(record),
				enabled = record.enabled ~= false,
				health = {
					ok = health.ok or 0,
					fail = health.fail or 0,
					lastError = health.lastError or "",
				},
				cooling = providers.cooling(record),
			}
		end

		local tools = {}
		for _, tool in ipairs(registry.list()) do
			tools[#tools + 1] = {
				name = tool.name,
				group = tool.group,
				description = tool.description,
				risk = tool.risk or "write",
				parameters = tool.parameters,
				available = registry.missingCapability(tool) == nil,
				enabled = registry.groupEnabled(tool.group),
				rule = permissions.ruleFor(tool.name) or "default",
			}
		end

		local subs = {}
		for _, record in ipairs(subagents.list()) do
			subs[#subs + 1] = {
				id = record.id,
				label = record.label,
				task = record.task,
				preset = record.preset,
				status = record.status,
				ms = record.ms,
				messages = record.messages,
				report = record.report and util.ellipsis(record.report, 600) or nil,
			}
		end

		local activeRecord = providers.active()
		local current = sessions.current()
		local loops = {}
		for _, job in ipairs(env.require("runtime/chatloops").list()) do
			loops[#loops + 1] = { id = job.id, kind = job.kind, state = job.state, channel = job.channel,
				sent = job.sent, count = job.count, completed = job.completed, reason = job.reason, scores = job.scores }
		end
		local pendingPermissions = {}
		for id, request in pairs(permissions.pending) do
			pendingPermissions[#pendingPermissions + 1] = { id = id, name = request.tool.name,
				description = request.tool.description, args = request.args,
				sessionId = request.session and request.session.id }
		end
		local asks = env.require("ui/panels/ask")
		local questions = {}
		local function question(request)
			if request then questions[#questions + 1] = { id = request.id, question = request.question,
				options = request.options, sessionTitle = request.sessionTitle } end
		end
		question(asks.current)
		for _, request in ipairs(asks.queue) do question(request) end
		local settings = {}
		for _, section in ipairs({ "ui", "agent", "logs", "iy", "identity" }) do
			settings[section] = {}
			for key, value in pairs(config.get(section, {})) do
				if type(value) ~= "table" then settings[section][key] = value end
			end
		end
		local themeColors = {}
		for _, key in ipairs({ "canvas", "sidebar", "surface", "surfaceRaised", "surfaceActive", "border", "text", "textSecondary", "textTertiary", "accent", "accentHot", "solid", "onSolid" }) do
			themeColors[key] = "#" .. env.require("ui/theme").color[key]:ToHex()
		end

		return {
			protocol = 2,
			attachments = { inlineLimit = env.require("runtime/attachments").INLINE_LIMIT,
				maxBytes = env.require("runtime/attachments").MAX_BYTES, available = caps.fs },
			runtime = config.get("bridge.runtime", "game"),
			relayTimeout = config.get("bridge.requestTimeout", 180),
			sessionId = current.id,
			player = env.plr and env.plr.DisplayName or "you",
			settings = settings, theme = themeColors, loops = loops, todos = current.todos,
			questions = questions, pendingPermissions = pendingPermissions,
			logs = util.slice(log.entries, math.max(1, #log.entries - 59), #log.entries),
			requests = http.history,
			presets = env.require("provider/catalog").presets,
			place = { id = place.id, name = place.label() },
			caps = { executor = caps.executor, http = caps.http, summary = caps.summary() },
			agent = {
				status = current.status,
				busy = current.busy == true,
				provider = activeRecord and activeRecord.label or nil,
				model = activeRecord and activeRecord.model or nil,
			},
			usage = {
				prompt = usage.session.prompt,
				completion = usage.session.completion,
				total = usage.session.total,
				cost = usage.session.cost,
				requests = usage.session.requests,
				estimated = usage.session.estimated == true,
			},
			permissions = { mode = permissions.mode(), pending = permissions.pendingCount() },
			threads = threads,
			providers = providerList,
			activeProvider = activeRecord and activeRecord.id or nil,
			tools = tools,
			subagents = subs,
		}
	end

	local lastStateJson, lastStateAt = nil, 0
	local STATE_EVERY = 1000
	local inflight, commandResults = nil, {}

	local function drain()
		if next(commandResults) then
			local results = {}
			for _, result in pairs(commandResults) do results[#results + 1] = result end
			local res = call({ url = base() .. "/api/agent/ack", method = "POST", body = util.encode({ results = results }), timeout = 10 })
			if res and res.ok then
				for _, result in ipairs(results) do
					if commandResults[result.id] == result then commandResults[result.id] = nil end
				end
			end
		end
		if inflight then
			local res, err = call({ url = base() .. "/api/agent/events", method = "POST", body = inflight, timeout = 10 })
			if res and res.ok then inflight = nil; return true end
			return false, err or "Bridge upload failed"
		end
		attach()
		local stateDue = nil
		if clock.since(lastStateAt) >= STATE_EVERY then
			lastStateAt = clock.ms()
			local ok, built = pcall(stateOf)
			if ok then
				local encoded = util.encode(built)
				if encoded ~= lastStateJson then
					lastStateJson = encoded
					stateDue = built
				end
			end
		end
		if #queue == 0 and snapshotPending == nil and stateDue == nil then return true end
		local batch = queue
		local snapshot = snapshotPending
		queue = {}
		snapshotPending = nil

		inflight = util.encode({ batchId = env.services.HttpService:GenerateGUID(false), events = batch, snapshot = snapshot, state = stateDue,
			sessionId = attachedId })
		local res, err = call({
			url = base() .. "/api/agent/events",
			method = "POST",
			body = inflight,
			timeout = 10,
		})
		if res and res.ok then inflight = nil; return true end

		-- Keep this exact encoded batch and ID until acknowledged. Events arriving
		-- during the request stay in the next batch instead of being duplicated.
		return false, err or ("status " .. tostring(res and res.status or 0))
	end

	local generation = 0
	local function uploadLoop(mine)
		local attempt = 0
		while alive and mine == generation do
			local ok, reason = drain()
			if not alive or mine ~= generation then return end
			if ok then
				attempt = 0
				clock.wait(DRAIN_SECONDS)
			else
				attempt = attempt + 1
				offline(reason)
				clock.wait(clock.backoff(attempt, { cap = 10 }))
			end
		end
	end

	local handledCommands = {}
	local function pollLoop(mine)
		local attempt = 0
		while alive and mine == generation do
			local res, err = call({
				url = base() .. "/api/agent/inbox",
				method = "GET",
				timeout = POLL_TIMEOUT,
			})
			-- The request parked for up to eighteen seconds; an unload during that
			-- window means the answer is no longer wanted.
			if not alive or mine ~= generation then return end

			if res and res.ok then
				attempt = 0
				onlineNow()
				local decoded = util.decode(res.body)
				local commands = type(decoded) == "table" and decoded.commands or nil
				local handled = 0
				if type(commands) == "table" then
					for _, command in ipairs(commands) do
						handled = handled + 1
						-- One bad command must not stop the poller: that would take the
						-- browser offline until the next reload.
						local id = command.commandId
						if id and handledCommands[id] then
							if handledCommands[id] ~= true then commandResults[id] = handledCommands[id] end
						else
							if id then
								handledCommands[id] = true
								commandResults[id] = { id = id, pending = true }
							end
							clock.spawn(function()
								local ok, result = pcall(runCommand, command)
								if id then
									local answer = { id = id, ok = ok, error = not ok and tostring(result) or nil,
										data = ok and type(result) == "table" and result or nil }
									handledCommands[id], commandResults[id] = answer, answer
								elseif not ok then log.warn("bridge", "command failed", result) end
							end)
						end
					end
				end
				-- The bridge is expected to hold this request open until it has
				-- something to say. One that answers empty straight away -- an older
				-- build, or a proxy that will not park a connection -- would otherwise
				-- turn this loop into a flood of requests.
				if (res.ms or 0) < 100 then clock.wait(handled == 0 and 0.25 or 0.05) end
			else
				attempt = attempt + 1
				offline(err or ("status " .. tostring(res and res.status or 0)))
				clock.wait(clock.backoff(attempt, { cap = 10 }))
			end
		end
	end

	local unregister = nil

	local function shutdown()
		generation = generation + 1
		alive = false
		M.running = false
		M.online = false
		if detach then pcall(detach) end
		detach, attachedId = nil, nil
		queue = {}
		snapshotPending = nil
		inflight = nil
	end

	function M.start()
		if M.running then return true end
		if not caps.has("http") then return false, caps.reason("http") end
		if util.trim(tostring(config.get("bridge.token", ""))) == "" then
			return false, "no token yet -- run bridge/server.js and paste the token it prints"
		end

		M.running = true
		alive = true
		generation = generation + 1
		lastStateJson, lastStateAt = nil, 0
		M.lastError = nil
		attach()
		clock.spawn(uploadLoop, generation)
		clock.spawn(pollLoop, generation)
		-- Two threads that outlive the interface, so unloading has to be able to
		-- stop them. The canceller is kept rather than discarded because stopping
		-- from Settings has to unregister as well, or the drain would run it twice.
		unregister = dispose.add(shutdown, "bridge")
		log.info("bridge", "polling " .. base())
		M.changed:fire()
		return true
	end

	function M.stop()
		if not M.running then return false end
		if unregister then
			unregister()
			unregister = nil
		else
			shutdown()
		end
		log.info("bridge", "stopped")
		M.changed:fire()
		return true
	end

	-- One place decides whether the bridge should be up, so boot and the Settings
	-- toggle cannot disagree about it.
	function M.sync()
		if config.get("bridge.enabled", false) == true then return M.start() end
		M.stop()
		return false
	end

	function M.status()
		return {
			running = M.running,
			online = M.online,
			url = base(),
			queued = #queue,
			error = M.lastError,
		}
	end

	-- Any route that changes the setting takes effect, whether that is the Settings
	-- panel, a console call or a host script, so the panel only has to write config
	-- rather than orchestrate this. A port or token change aims the connection
	-- somewhere new, so it is torn down and rebuilt rather than adjusted in place.
	dispose.add(config.changed:connect(function(path)
		if path == "bridge.runtime" or path == "bridge.requestTimeout" then lastStateJson = nil; return end
		if path ~= nil and not util.startsWith(tostring(path), "bridge.") then return end
		if M.running then M.stop() end
		if config.get("bridge.enabled", false) == true then M.start() end
	end), "bridge config")

	return M






end
end)()

-- ==========================================================================
-- net/bridge_commands
-- ==========================================================================
__UAI_MODULES["net/bridge_commands"] = (function()
-- Browser controls use the same stores and validated tool dispatcher as Roblox UI.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local sessions = env.require("agent/session")
	local M = {}
	function M.run(command)
		local kind = command.type
		local session = command.sessionId and sessions.threads[command.sessionId] or sessions.current()
		if not session then error("Conversation no longer exists", 0) end
		if kind == "attachment:upload" then
			local result, err = env.require("runtime/attachments").upload(session.id, command)
			if not result then error(err, 0) end
			return result
		elseif kind == "runtime" then
			if #sessions.busy() > 0 or #env.require("agent/subagent").running() > 0
				or #env.require("runtime/chatloops").running() > 0 then error("Stop running work before switching runtime", 0) end
			if command.value ~= "game" and command.value ~= "web" then error("Unknown runtime", 0) end
			config.set("bridge.runtime", command.value)
		elseif kind == "setting" then
			local path = tostring(command.path or "")
			local section = path:match("^([^.]+)%.")
			if not ({ ui = true, agent = true, logs = true, memory = true, iy = true, identity = true })[section]
				and path ~= "bridge.requestTimeout" then error("Setting is not editable here", 0) end
			local default = util.get(config.defaults, path)
			if default == nil or type(default) == "table" or type(command.value) ~= type(default) then error("Invalid setting value", 0) end
			if type(command.value) == "number" and (command.value ~= command.value or math.abs(command.value) > 10000000 or command.value < 0) then error("Invalid numeric setting", 0) end
			if type(command.value) == "string" and #command.value > 16000 then error("Setting is too long", 0) end
			local choices = {
				["ui.density"] = { comfortable = true, compact = true },
				["ui.accent"] = { claude = true, aurora = true, indigo = true, amber = true, rose = true },
				["ui.reduceMotion"] = { auto = true, on = true, off = true },
				["ui.layout"] = { auto = true, sheet = true, panel = true, window = true, tv = true },
				["ui.codeTheme"] = { dark = true, light = true },
				["ui.transcriptWidth"] = { narrow = true, medium = true, wide = true },
				["iy.mode"] = { off = true, hidden = true, visible = true },
				["agent.effort"] = { low = true, medium = true, high = true, xhigh = true, max = true },
			}
			if choices[path] and not choices[path][command.value] then error("Unsupported setting choice", 0) end
			local ranges = { ["ui.fontScale"] = { 0.85, 1.4 }, ["agent.temperature"] = { 0, 2 },
				["agent.toolConcurrency"] = { 1, 8 }, ["agent.maxTurns"] = { 1, 1000 },
				["agent.toolTimeout"] = { 1, 86400 }, ["agent.requestTimeout"] = { 1, 86400 },
				["bridge.requestTimeout"] = { 10, 86400 }, ["agent.retries"] = { 1, 10 },
				["agent.contextTokens"] = { 1000, 2000000 }, ["agent.contextFraction"] = { 0.3, 0.95 },
				["agent.maxTokens"] = { 1, 1000000 } }
			local range = ranges[path]
			if range and (command.value < range[1] or command.value > range[2]) then error("Setting is outside its supported range", 0) end
			config.set(path, command.value)
		elseif kind == "tool:rule" then
			local rule = command.rule
			if not ({ allow = true, deny = true, ask = true, default = true })[rule] then error("Invalid rule", 0) end
			env.require("agent/permissions").setRule(tostring(command.name), rule)
		elseif kind == "tool:group" then
			env.require("agent/registry").setGroupEnabled(tostring(command.group), command.enabled == true)
		elseif kind == "tool:run" then
			local registry = env.require("agent/registry")
			if session.busy then error("Conversation is already working", 0) end
			local tool = registry.get(command.name)
			if not tool or not registry.groupEnabled(tool.group) then error("Tool unavailable", 0) end
			session.busy, session.abortFlag = true, false
			sessions.listChanged:fire()
			session.emit("tool:call", { id = command.commandId, name = command.name,
				arguments = util.encode(command.arguments or {}) })
			local ok, result = pcall(registry.dispatch, { id = command.commandId, name = command.name,
				arguments = util.encode(command.arguments or {}) }, session.toolContext())
			session.busy = false
			sessions.listChanged:fire()
			if not ok then error(result, 0) end
			session.emit(result.ok and "tool:result" or "tool:error", result)
			session.emit("status", { text = "Ready" })
			sessions.persist(session)
			return result
		elseif kind == "provider:save" then
			local providers = env.require("provider/registry")
			local fields = command.provider or {}
			local record = fields.id and providers.get(fields.id) or providers.blank(fields.preset or "custom")
			if not record then error("Unknown provider", 0) end
			record = util.deepCopy(record)
			for _, name in ipairs({ "label", "baseUrl", "api", "authStyle", "apiKey", "model", "wsUrl" }) do
				if fields[name] ~= nil then record[name] = tostring(fields[name]) end
			end
			for _, name in ipairs({ "models", "headers", "params", "query", "apiKeys" }) do
				if type(fields[name]) == "table" then record[name] = fields[name] end
			end
			if fields.enabled ~= nil then record.enabled = fields.enabled == true end
			local ok, errors = providers.save(record)
			if not ok then error(table.concat(errors or {}, "; "), 0) end
		elseif kind == "provider:remove" then env.require("provider/registry").remove(command.id)
		elseif kind == "provider:test" then
			local record = env.require("provider/registry").get(command.id)
			if not record then error("Unknown provider", 0) end
			local result, err = env.require("provider/chat").complete(record, {
				messages = { { role = "user", content = "Reply with OK." } }, maxTokens = 12, attempts = 1,
			})
			if not result then error(err, 0) end
			return { text = "Connected: " .. tostring(result.content), ms = result.ms }
		elseif kind == "loops:stop" then return { stopped = env.require("runtime/chatloops").stop(command.id or "all") }
		elseif kind == "thread:isolate" then session.setEphemeral(command.value == true)
		elseif kind == "ask:answer" then
			local asks = env.require("ui/panels/ask")
			if not asks.answer(command.id, tostring(command.text or "")) then error("Question is no longer pending", 0) end
		elseif kind == "config:export" then
			local text, err = env.require("runtime/config_transfer").export()
			if not text then error(err, 0) end
			return { text = text }
		elseif kind == "config:import" then
			if #sessions.busy() > 0 then error("Stop running work before importing settings", 0) end
			local transfer = env.require("runtime/config_transfer")
			local preview, err = transfer.preview(command.text)
			if not preview then error(err, 0) end
			-- Connection credentials stay valid until the acknowledgement is delivered.
			preview.config.bridge = util.deepCopy(config.get("bridge"))
			local ok, why = transfer.apply(preview)
			if not ok then error(why, 0) end
		elseif kind == "logs:clear" then env.require("runtime/log").clear(); env.require("net/http").clearHistory()
		else return false end
		return true
	end
	return M
end
end)()

-- ==========================================================================
-- net/http
-- ==========================================================================
__UAI_MODULES["net/http"] = (function()
-- The only module that performs an HTTP request.
--
-- Centralising it buys three things the client depends on: the Claude Code
-- identity cannot be omitted by a forgetful caller, every request lands in one
-- redacted history the Logs panel reads, and retry policy is written once rather
-- than per call site.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local ua = env.require("net/ua")
	local signal = env.require("runtime/signal")

	local HISTORY_LIMIT = 60

	-- A browser agent for the public web: search engines and CDNs answer 403 to
	-- anything else, so the web tools opt into this explicitly. Everything else,
	-- inference included, carries the Claude Code identity.
	local BROWSER_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"

	-- Statuses that are always worth another attempt, regardless of what the body
	-- says. Everything in 5xx joins them by range below.
	local RETRY_STATUS = {
		[408] = true, [409] = true, [425] = true, [429] = true, [499] = true,
	}

	-- How long an attempt has to run before "nothing came back" reads as a deadline
	-- rather than a decision, in milliseconds.
	--
	-- A refusal arrives in milliseconds: an edge filter and an exhausted quota both
	-- answer immediately. Only a transport that ran out of time takes tens of seconds
	-- to produce nothing at all, and by then the gateway has accepted the request and
	-- billed the whole prompt. Retrying that re-sends every token to arrive at the same
	-- wall, so above this an empty answer ends the sequence instead of extending it.
	local DEADLINE_FLOOR = 10000

	-- Substrings that mean "transient", wherever they appear in a response body.
	--
	-- These gateways report an overloaded or rate-limited upstream in the body and
	-- pick the status code almost at random, so the text is the more reliable signal.
	-- The list is taken from the reference proxy that sits in front of them, which
	-- sees the upstream errors this client only ever sees second-hand -- including the
	-- Chinese quota wording, which arrives under a 403.
	local TRANSIENT_MARKERS = {
		"rate_limit", "chatratelimited",
		"upstream_provider_rate_limit", "server_is_overloaded",
		"service_unavailable_error", "server_error", "overloaded_error",
		"internal_server_error", "temporarily unavailable", "please try again",
		"用户额度不足", "剩余额度",
	}

	local function transient(body)
		if type(body) ~= "string" or body == "" then return false end
		local lowered = body:lower()
		for _, marker in ipairs(TRANSIENT_MARKERS) do
			if lowered:find(marker, 1, true) then return true end
		end
		return false
	end

	-- A gateway that answers 200 and then puts the failure in the body. Detected
	-- structurally -- a decodable object carrying an `error`, or an SSE frame whose
	-- type is "error" -- and never by substring, because a reply that happens to
	-- discuss rate limits must not be mistaken for one.
	local function errorPayload(body)
		if type(body) ~= "string" or body == "" then return nil end
		local function check(text)
			local decoded = util.decode(text)
			if type(decoded) ~= "table" then return nil end
			if decoded.type == "error" then return decoded end
			if decoded.error ~= nil then return decoded end
			return nil
		end
		local direct = check(body)
		if direct then return direct end
		for line in body:gmatch("[^\r\n]+") do
			local data = line:match("^data:%s*(.+)$")
			if data and data ~= "[DONE]" then
				local hit = check(data)
				if hit then return hit end
			end
		end
		return nil
	end

	local M = {
		history = {},
		changed = signal.new("http"),
		count = 0,
	}

	function M.header(res, name)
		local headers = res and res.headers
		if type(headers) ~= "table" then return nil end
		local wanted = tostring(name):lower()
		for key, value in pairs(headers) do
			if type(key) == "string" and key:lower() == wanted then
				-- Some transports hand back a list of values for one header.
				if type(value) == "table" then return value[1] end
				return value
			end
		end
		return nil
	end

	local function record(entry)
		M.count = M.count + 1
		entry.id = M.count
		M.history[#M.history + 1] = entry
		if #M.history > HISTORY_LIMIT then table.remove(M.history, 1) end
		M.changed:fire(entry)
		return entry
	end

	local function identityHeaders(kind, attempt, timeout)
		if kind == "none" then return {} end
		if kind == "browser" then
			return {
				["User-Agent"] = BROWSER_UA,
				["Accept"] = "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
				["Accept-Language"] = "en-US,en;q=0.9",
			}
		end
		if kind == "openrouter" then
			return {
				["User-Agent"] = "ProjectUAI/1.0.0",
				["HTTP-Referer"] = "https://carldv.github.io/ProjectUAI/",
				["X-Title"] = "Project UAI",
				["X-OpenRouter-Title"] = "Project UAI",
				["X-OpenRouter-Categories"] = "game,cli-agent",
			}
		end
		if not ua.enabled() then return {} end
		return ua.headers({ attempt = attempt, timeout = timeout })
	end

	-- Header merge order: identity first, then the caller's, so a caller can
	-- deliberately override one value without losing the rest of the set.
	local function buildHeaders(spec, attempt)
		local url = tostring(spec.url or "")
		local isOpenRouter = url:find("openrouter.ai", 1, true) ~= nil
		local identity = isOpenRouter and "openrouter" or (spec.identity or "claude")

		local headers = identityHeaders(identity, attempt, spec.timeout)
		for key, value in pairs(spec.headers or {}) do
			if value ~= nil then headers[key] = tostring(value) end
		end
		-- A gateway requiring this identity must retain it even when the global
		-- preference is off or a saved custom header would otherwise replace it.
		if spec.identityRequired and identity == "claude" then
			local required = ua.headers({ attempt = attempt, timeout = spec.timeout, required = true })
			local names = {}
			for key in pairs(required) do names[key:lower()] = true end
			for key in pairs(headers) do
				if names[key:lower()] then headers[key] = nil end
			end
			for key, value in pairs(required) do headers[key] = value end
		end

		if isOpenRouter then
			-- Ensure OpenRouter attribution headers are always present for rankings and app stats
			if not headers["HTTP-Referer"] and not headers["http-referer"] then
				headers["HTTP-Referer"] = "https://carldv.github.io/ProjectUAI/"
			end
			if not headers["X-Title"] and not headers["x-title"] then
				headers["X-Title"] = "Project UAI"
			end
			if not headers["X-OpenRouter-Title"] and not headers["x-openrouter-title"] then
				headers["X-OpenRouter-Title"] = "Project UAI"
			end
			if not headers["X-OpenRouter-Categories"] and not headers["x-openrouter-categories"] then
				headers["X-OpenRouter-Categories"] = "game,cli-agent"
			end
			if not headers["User-Agent"] and not headers["user-agent"] then
				headers["User-Agent"] = "ProjectUAI/1.0.0"
			end
			-- Suppress Claude Code / Stainless headers for OpenRouter
			headers["x-app"] = nil
			headers["X-Stainless-Lang"] = nil
			headers["X-Stainless-Package-Version"] = nil
			headers["X-Stainless-OS"] = nil
			headers["X-Stainless-Arch"] = nil
			headers["X-Stainless-Runtime"] = nil
			headers["X-Stainless-Runtime-Version"] = nil
			headers["X-Stainless-Retry-Count"] = nil
			headers["X-Stainless-Timeout"] = nil
		end

		if spec.body and not headers["Content-Type"] and not headers["content-type"] then
			headers["Content-Type"] = "application/json"
		end
		return headers
	end

	-- Socket envelopes can carry the same required identity as HTTP requests.
	function M.headersFor(spec)
		return buildHeaders(spec, spec.attempt or 1)
	end

	-- What a transport hands back when it never got an answer varies: some set
	-- Success = false, some invent a status code. What they share is that nothing came
	-- off the wire -- no body and no headers -- and a real HTTP reply always carries at
	-- least one header. Reporting that as a status writes a number into the log no
	-- server ever sent, and the retry policy then reasons about a refusal nobody
	-- issued: the gateway had already accepted the request and billed the prompt.
	local function normalise(res, via)
		local headers = res.Headers or res.ResponseHeaders or {}
		if type(headers) ~= "table" then headers = {} end
		local body = res.Body or res.ResponseData or ""
		if body == "" and next(headers) == nil then
			local said = util.trim(tostring(res.StatusMessage or ""))
			return nil, said ~= "" and said or "the transport returned no response"
		end
		return {
			status = tonumber(res.StatusCode or res.Status) or 0,
			body = body,
			headers = headers,
			message = res.StatusMessage,
			via = via,
		}
	end

	local function send(url, method, headers, body, timeout)
		local options = { Url = url, Method = method, Headers = headers }
		if body and body ~= "" and method ~= "GET" and method ~= "HEAD" then
			options.Body = body
		end

		if caps.fn.request then
			-- Set only on this path: RequestAsync accepts a fixed set of keys. Not every
			-- executor honours it either, which is why an attempt that runs long is also
			-- recognised after the fact rather than only prevented here.
			if timeout and timeout > 0 then options.Timeout = math.floor(timeout) end
			local ok, res = pcall(caps.fn.request, options)
			if not ok then return nil, tostring(res) end
			if type(res) ~= "table" then return nil, "empty executor response" end
			return normalise(res, "executor")
		end

		if caps.http == "none" then return nil, caps.reason("http") end
		local ok, res = pcall(function() return env.hs:RequestAsync(options) end)
		if not ok then return nil, tostring(res) end
		if type(res) ~= "table" then return nil, "empty HttpService response" end
		return normalise(res, "roblox")
	end

	-- One attempt. Returns res (with .ok) or nil plus a transport error string.
	function M.request(spec)
		local url = tostring(spec.url or "")
		if url == "" then return nil, "no url" end
		local method = (spec.method or "GET"):upper()
		local attempt = spec.attempt or 1
		local headers = buildHeaders(spec, attempt)
		local started = clock.ms()

		local res, err
		if spec.relay then
			res, err = env.require("net/relay").request(spec, headers, M.request)
		else res, err = send(url, method, headers, spec.body, spec.timeout) end
		local elapsed = clock.since(started)

		-- `spec.silent` keeps a request out of the history and out of the log. The web
		-- bridge polls continuously for as long as it is enabled, and against a
		-- 60-entry ceiling that would evict the inference calls the Requests view
		-- exists to explain. A silent caller reports its own failures instead.
		local entry = {
			at = started,
			stamp = clock.stamp(),
			method = method,
			url = log.redact(url),
			tag = spec.tag or "http",
			ms = elapsed,
			status = res and res.status or 0,
			bytes = res and #tostring(res.body or "") or 0,
			via = res and res.via or (caps.fn.request and "executor" or "roblox"),
			identity = (url:find("openrouter.ai", 1, true) and "openrouter") or spec.identity or "claude",
			uaSent = ((spec.identity ~= "none") or url:find("openrouter.ai", 1, true)) and caps.uaSupported or false,
			error = err,
			attempt = attempt,
			-- A refusal with an empty body cannot be diagnosed from a status code
			-- alone, and until now nothing about the response was kept at all. These
			-- four are what distinguish an API decision from an edge filter: a
			-- Cloudflare 403 carries `server` and `cf-ray` and usually `cf-mitigated`,
			-- and the API's own 403 carries a JSON body. Kept short -- this is what the
			-- Requests view shows, not an archive.
			response = res and util.ellipsis(res.body, 400) or nil,
			server = res and M.header(res, "server") or nil,
			trace = res and (M.header(res, "cf-ray") or M.header(res, "x-request-id")) or nil,
			mitigated = res and M.header(res, "cf-mitigated") or nil,
		}
		if not spec.silent then record(entry) end

		if not res then
			-- How long it ran is the whole diagnosis: a transport that refuses fails at
			-- once, one that ran out of time fails slowly, and only the second is a
			-- deadline. The caller needs the number to tell them apart.
			if not spec.silent then
				log.warn("http", string.format("%s %s failed after %s", method, entry.url,
					util.formatDuration(elapsed)), err)
			end
			return nil, err or "request failed", elapsed
		end

		res.ms = elapsed
		res.ok = res.status >= 200 and res.status < 300
		res.entry = entry
		if spec.silent then
			return res
		end
		if not res.ok then
			log.warn("http", string.format("%s %s -> %d", method, entry.url, res.status),
				util.ellipsis(res.body, 240))
		else
			log.debug("http", string.format("%s %s -> %d in %s", method, entry.url, res.status,
				util.formatDuration(elapsed)))
		end
		return res
	end

	-- Retry-After is seconds or an HTTP date. Only the numeric form is honoured:
	-- parsing an RFC date to save a couple of seconds is not worth the code, and
	-- the backoff curve is a sane fallback.
	local function retryDelay(res, attempt, opts)
		if res then
			local header = M.header(res, "retry-after")
			local seconds = tonumber(header)
			if seconds and seconds > 0 then return math.min(seconds, 60), "retry-after" end
		end
		return clock.backoff(attempt, opts), "backoff"
	end

	-- Whether an attempt is worth repeating, and why -- the reason is reported to the
	-- transcript so a slow turn explains itself rather than just being slow. `info`
	-- carries what the response cannot: how long the attempt took, which is the only
	-- way to tell a refusal apart from a deadline when neither carries a body.
	--
	-- `info.skipStatus` is a caller's veto over the statuses it would rather handle
	-- itself: a provider with a key pool passes 429 so the transport does not sleep
	-- its way through a backoff on a key that rotation can replace at once.
	function M.shouldRetry(res, err, info)
		if (res and res.terminal) or err == "aborted" then return false end
		local elapsed = tonumber(info and info.elapsed) or 0
		local status = res and res.status or 0
		local body = tostring(res and res.body or "")

		-- The caller's veto is consulted first and answers completely: a status it
		-- named is not retried here, whatever the body says.
		if info and type(info.skipStatus) == "table" and info.skipStatus[status] then
			return false, "status " .. tostring(status) .. " (left to the caller)"
		end

		-- An attempt that ran this long and returned nothing hit a deadline, whatever
		-- status was attached to it -- most often none at all, because the transport gave
		-- up rather than the server answering. The next attempt re-sends the entire
		-- prompt to reach the same wall, and the gateway bills it on arrival, so the
		-- sequence ends here and says why instead of paying three times over.
		--
		-- Retry-After is the exception, and the only one: a server naming a moment to
		-- come back has told us the request will work later, which is precisely what a
		-- deadline cannot promise.
		local told = res and tonumber(M.header(res, "retry-after"))
		if elapsed >= DEADLINE_FLOOR and util.trim(body) == "" and not told then
			return false, string.format("nothing returned after %s", util.formatDuration(elapsed))
		end

		-- The transport itself failed. Nothing was decided upstream, so try again.
		if err then return true, "transport error" end
		if not res then return true, "no response" end

		if RETRY_STATUS[status] then return true, "status " .. tostring(status) end
		if status >= 500 and status <= 599 then return true, "status " .. tostring(status) end

		-- A 403 from these gateways is usually an edge filter or an exhausted shared
		-- quota pool rather than a decision about this key: in the log that prompted
		-- this they arrive interleaved with 200s on the same endpoint, seconds apart.
		-- A genuine permission refusal explains itself in the body, so one that
		-- explains nothing gets another attempt and one that does is reported.
		if status == 403 then
			if util.trim(body) == "" then return true, "403 with no explanation" end
			if transient(body) then return true, "403, upstream busy" end
			return false
		end

		if res.ok then
			local payload = errorPayload(body)
			if payload then
				local text = type(payload.error) == "table" and tostring(payload.error.message or "")
					or tostring(payload.error or payload.message or "")
				if transient(text) or transient(body) then return true, "error inside a 200" end
			end
			return false
		end

		if transient(body) then return true, "upstream busy" end
		return false
	end

	-- Retries the whole attempt sequence. `spec.attempts` caps it; `spec.onRetry`
	-- lets the caller report the wait to the interface, and `spec.aborted` lets a
	-- user cancel during the sleep rather than after it.
	function M.send(spec)
		local attempts = math.max(spec.attempts or 1, 1)
		local lastRes, lastErr
		for attempt = 1, attempts do
			if spec.aborted and spec.aborted() then return nil, "aborted" end
			local copy = util.copy(spec)
			copy.attempt = attempt
			local res, err, failedMs = M.request(copy)
			lastRes, lastErr = res, err
			-- Asked before the success check, because a 200 can carry the failure in
			-- its body and returning that as a reply is worse than retrying it.
			local retry, why = M.shouldRetry(res, err, {
				elapsed = res and res.ms or failedMs,
				skipStatus = spec.skipStatus,
			})
			if not retry then
				-- A deadline is the one outcome the caller cannot read off the response,
				-- because there is no response to read. The transport's own words for it
				-- stay in the log entry rather than the message: they are usually a raise
				-- from inside the executor ("Argument 1 missing or nil") and say nothing
				-- a reader can act on, where the wait and its cause do.
				if why and not res then
					return nil, why .. " -- the transport gave up while the request was still " ..
						"running. A smaller context budget or reply ceiling fits inside it."
				end
				return res, err
			end
			if attempt >= attempts then return res, err end
			local wait, source = retryDelay(res, attempt, spec.backoff)
			if spec.onRetry then
				spec.onRetry({
					attempt = attempt,
					attempts = attempts,
					wait = wait,
					reason = why or source,
					status = res and res.status or 0,
					error = err,
				})
			end
			-- Slice the sleep so an abort lands promptly instead of after the full
			-- backoff, which at the top of the curve is twenty seconds.
			local slept = 0
			while slept < wait do
				if spec.aborted and spec.aborted() then return nil, "aborted" end
				local step = math.min(0.25, wait - slept)
				clock.wait(step)
				slept = slept + step
			end
		end
		return lastRes, lastErr
	end

	function M.json(spec)
		local res, err = M.send(spec)
		if not res then return nil, err, nil end
		local decoded, decodeErr = util.decode(res.body)
		if decoded == nil then return nil, decodeErr or "invalid json", res end
		return decoded, nil, res
	end

	function M.clearHistory()
		M.history = {}
		M.changed:fire(nil)
	end

	M.BROWSER_UA = BROWSER_UA

	return M
end
end)()

-- ==========================================================================
-- net/relay
-- ==========================================================================
__UAI_MODULES["net/relay"] = (function()
-- Node owns the provider connection; every executor exchange is short. A lost
-- submission is retried with the same ID, never as a second inference request.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local dispose = env.require("runtime/dispose")
	local alive, pending = true, {}
	local M = {}
	function M.request(spec, headers, call)
		local base = "http://127.0.0.1:" .. tostring(config.get("bridge.port", 8790))
		local token = tostring(config.get("bridge.token", ""))
		local timeout = util.clamp(tonumber(config.get("bridge.requestTimeout", 180)) or 180, 10, 86400)
		local id = "inference_" .. env.services.HttpService:GenerateGUID(false)
		local deadline = clock.ms() + (timeout + 30) * 1000
		local function short(method, path, body)
			return call({ url = base .. path, method = method, body = body,
				headers = { Authorization = "Bearer " .. token }, identity = "none", silent = true, timeout = 15 })
		end
		local function cancel()
			clock.spawn(function() pcall(short, "DELETE", "/api/inference/" .. id) end)
		end
		pending[id] = cancel
		local function ended()
			return not alive or not config.get("bridge.enabled", false) or (spec.aborted and spec.aborted())
		end
		local function failure(message)
			pending[id] = nil
			return { status = 599, body = util.encode({ error = { message = message } }), headers = {},
				via = "web", terminal = true }, nil
		end
		if token == "" then return failure("Web runtime needs the bridge token in Cowork settings.") end
		local hello = short("GET", "/api/hello")
		local info = hello and hello.ok and util.decode(hello.body)
		if type(info) ~= "table" or info.protocol ~= 2 or not info.instance then
			return failure("Web runtime cannot connect. Start the updated bridge/server.js and check its token.")
		end
		local payload = util.encode({ id = id, instance = info.instance, url = spec.url, headers = headers,
			body = spec.body, timeout = timeout, sessionId = spec.sessionId })
		local submitted, attempts = false, 0
		while clock.ms() < deadline do
			if ended() then cancel(); pending[id] = nil; return nil, "aborted" end
			local response
			if not submitted then
				attempts = attempts + 1
				response = short("POST", "/api/inference", payload)
			else response = short("GET", "/api/inference/" .. id) end
			if ended() then cancel(); pending[id] = nil; return nil, "aborted" end
			if response and response.ok then
				local job = util.decode(response.body)
				if type(job) ~= "table" or job.id ~= id then cancel(); return failure("Invalid relay response; inference was not resubmitted.") end
				submitted = true
				if job.state == "completed" then
					pending[id] = nil
					return { status = job.status, headers = job.headers or {}, body = job.body or "", via = "web", inferenceId = id }
				elseif job.state ~= "running" then
					return failure(job.error or ("Relay job " .. tostring(job.state) .. "; inference was not resubmitted."))
				end
			elseif response and response.status >= 400 and response.status < 500 then
				cancel()
				return failure("Relay rejected the request (" .. response.status .. "). Check the bridge token and restart state; inference was not resubmitted.")
			elseif not submitted and attempts >= 3 then
				cancel(); return failure("Could not confirm relay submission; stopped without resubmitting inference.")
			end
			local slept = 0
			while slept < 1 do
				if ended() then cancel(); pending[id] = nil; return nil, "aborted" end
				slept = slept + (clock.wait(0.1) or 0.1)
			end
		end
		cancel()
		return failure("Relay result deadline reached; inference was cancelled rather than retried.")
	end
	dispose.add(function()
		alive = false
		for _, cancel in pairs(pending) do cancel() end
		pending = {}
	end, "web inference")
