		return body
	end

	-- Error text, in the order gateways actually use. A 401 with an empty body is
	-- common enough that the status alone has to produce something readable.
	local STATUS_TEXT = {
		[400] = "the provider rejected the request",
		[401] = "the API key was rejected",
		[402] = "the account is out of credit",
		[403] = "the provider refused the request -- the key may lack access to it",
		[404] = "endpoint or model not found -- check the base URL and model name",
		[413] = "the request was too large",
		[422] = "the provider could not process the request",
		[429] = "rate limited",
		[500] = "the provider had an internal error",
		[502] = "the provider gateway is unavailable",
		[503] = "the provider is overloaded",
		[529] = "the provider is overloaded",
	}

	-- An HTML body on a refusal is not the API talking.
	--
	-- A gateway answers in JSON. A whole HTML document -- especially one opening with
	-- Cloudflare's `<!--[if lt IE 7]>` conditional-comment block -- means the request was
	-- stopped in front of the API and never reached the account, the key or the model. So
	-- naming any of those as a possible cause, which the 403 text did, sends the reader
	-- off to check three things that are all fine. The response headers say which edge it
	-- was: `server`, `cf-ray` and `cf-mitigated` are already kept for the Requests view.
	local function edgeBlock(res)
		if not res then return nil end
		local body = util.trim(tostring(res.body or ""))
		if body == "" then return nil end
		local head = body:sub(1, 400):lower()
		local looksHtml = body:sub(1, 1) == "<"
			and (head:find("<!doctype", 1, true) or head:find("<html", 1, true)
				or head:find("<!--[if", 1, true))
		if not looksHtml then return nil end
		local bits = {}
		local server = util.trim(tostring(http.header(res, "server") or ""))
		local mitigated = util.trim(tostring(http.header(res, "cf-mitigated") or ""))
		local ray = util.trim(tostring(http.header(res, "cf-ray") or ""))
		if server ~= "" then bits[#bits + 1] = server end
		if mitigated ~= "" then bits[#bits + 1] = "cf-mitigated " .. mitigated end
		if ray ~= "" then bits[#bits + 1] = ray end
		return #bits > 0 and table.concat(bits, ", ") or "an edge in front of the API"
	end

	function M.errorText(res, err)
		if err and not res then return tostring(err) end
		local status = res and res.status or 0
		-- Checked before the status table, because the status is the least informative
		-- thing about this class of failure.
		local edge = edgeBlock(res)
		if edge then
			return string.format(
				"stopped before it reached the API (%d) by %s. It answered with an HTML page "
				.. "rather than JSON, so the key, the model and the account are not implicated -- "
				.. "the request itself was refused. Turning off the Claude Code identity for this "
				.. "provider is the one thing this client can change about how it looks.",
				status, edge)
		end
		local decoded = res and util.decode(res.body) or nil
		local message
		if type(decoded) == "table" then
			if type(decoded.error) == "table" then
				local errType = tostring(decoded.error.type or "")
				local errMsg = tostring(decoded.error.message or "")
				if errType == "FreeTierError" or errMsg:find("free tier can only be used from within OpenCode", 1, true) then
					message = (errMsg ~= "" and errMsg or "Error from provider (Console): OpenCode's free tier can only be used from within OpenCode")
						.. " -- the OpenCode server restricts free-tier models (like big-pickle) to its official app; use paid credits or an OpenCode Go subscription."
				else
					message = decoded.error.message or decoded.error.type or decoded.error.code
				end
			elseif type(decoded.error) == "string" then
				message = decoded.error
			elseif type(decoded.message) == "string" then
				message = decoded.message
			elseif type(decoded.detail) == "string" then
				message = decoded.detail
			end
		end
		if not message or message == "" then
			local raw = res and util.trim(res.body) or ""
			if raw ~= "" and #raw < 400 and not raw:find("^<") then
				message = raw
			end
		end
		local prefix = STATUS_TEXT[status]
		-- A refusal that carries no body at all is worth naming as such. It usually
		-- means the call never reached the API, so nothing about the key or the model
		-- accounts for it, and the answer is in the response headers the Requests view
		-- now keeps rather than anywhere in this string.
		if (not message or message == "") and res and util.trim(res.body or "") == "" then
			return string.format("%s (%d), and the response had no body -- see the Requests view",
				prefix or "the request was refused", status)
		end
		if message and prefix then return string.format("%s (%d): %s", prefix, status, message) end
		if message then return string.format("%s (%d)", message, status) end
		if prefix then return string.format("%s (%d)", prefix, status) end
		return string.format("request failed with status %d", status)
	end

	-- The output ceiling a refusal names, or nil when it names nothing usable.
	--
	-- Every model has its own max_tokens limit and no endpoint publishes it: /models
	-- reports ids, not capabilities. The one place the number appears is the 400 that
	-- comes back when a request exceeds it, and the wording is different everywhere --
	-- "max_tokens: 200000 > 64000, which is the maximum allowed number of output
	-- tokens for claude-sonnet-4-5-20250929", "max_tokens is too large: 200000. This
	-- model supports at most 16384 completion tokens", "must be less than or equal to
	-- 8192". What they share is that the limit is the largest number in the sentence
	-- below what was sent, so that is what is taken.
	--
	-- The floor is a thousand and it is load-bearing: the status code is part of the
	-- text this is handed, and clamping a reply ceiling to 400 tokens because "(400)"
	-- appeared in the prefix would be worse than the original error. Nothing caps
	-- output below a thousand tokens.
	function M.ceilingFromMessage(message, current)
		current = tonumber(current) or 0
		if current <= 0 then return nil end
		local best
		for digits in tostring(message or ""):gmatch("%d+") do
			local number = tonumber(digits)
			if number and number >= 1000 and number < current and (not best or number > best) then
				best = number
			end
		end
		if best then return best end
		-- Nothing quotable. Halving converges in a couple of attempts and cannot loop,
		-- because each attempt is a fresh request against a smaller number.
		local halved = math.floor(current / 2)
		return (halved >= 1000) and halved or nil
	end

	-- The ceiling to actually send: what the user asked for, lowered to whatever this
	-- record has already been told its model allows.
	--
	-- Kept per model rather than per record, because the limit belongs to the model.
	-- Pointing a record at a wider Claude has to stop clamping it to the narrower
	-- one's limit, and there would be nothing on screen to explain it if it did not:
	-- the slider would read 64k while every request asked for 32k.
	function M.cappedMaxTokens(record, wanted)
		wanted = tonumber(wanted) or 0
		-- What the model documents comes first, so a slider set above a model's
		-- ceiling costs nothing to discover. What a refusal actually taught this
		-- record still applies after it, because the gateway is the final word on
		-- what it will accept.
		local documented = traits.maxOutput(record.model)
		if documented and wanted > documented then wanted = documented end
		local cap = record.maxTokensCap
		if type(cap) ~= "table" or cap.model ~= record.model then return wanted end
		local limit = tonumber(cap.tokens) or 0
		if limit > 0 and wanted > limit then return limit end
		return wanted
	end

	-- SSE over executor HTTP is still a buffered body. Bound its default reply,
	-- while retaining explicit token overrides and transports that stream/poll.
	-- Also called after a failed socket so its HTTP fallback gets the same bound.
	function M.limitExecutorReply(record, request, body, socket)
		if socket or (config.get("bridge.enabled", false) and config.get("bridge.runtime", "game") == "web") then return end
		local params, extra = record.params or {}, request.extra or {}
		if request.maxTokens ~= nil or params.max_tokens ~= nil or params.max_completion_tokens ~= nil
			or extra.max_tokens ~= nil or extra.max_completion_tokens ~= nil then return end
		local ceiling = tonumber(config.get("agent.executorReplyCeiling", 8192)) or 8192
		if ceiling ~= ceiling or ceiling == math.huge or ceiling == -math.huge then ceiling = 8192 end
		if ceiling <= 0 then return end
		ceiling = math.max(1, math.floor(ceiling))
		local field = body.max_completion_tokens ~= nil and "max_completion_tokens" or "max_tokens"
		local wanted = tonumber(body[field])
		if not wanted or wanted <= 0 or wanted > ceiling then body[field] = ceiling end
	end

	-- The effort level to send, or nil for none. Both adapters ask this and differ
	-- only in how the answer is spelled on the wire.
	--
	-- Clamped to the model's own scale rather than passed through, because the scales
	-- differ by generation -- "xhigh" arrived after 4.6 -- and a level a model has
	-- never heard of is a refusal rather than a rounding.
	function M.effortFor(record, request)
		local wanted = request and request.effort
		if wanted == nil then wanted = config.get("agent.effort", "high") end
		wanted = tostring(wanted or "")
		if wanted == "" or wanted == "off" then return nil end
		-- nearestEffort passes the level through for a model the user has manually
		-- marked as a reasoner, and clamps it against the documented scale for one
		-- the table knows -- which is the same contract as before, plus the override.
		return traits.nearestEffort(record and record.model, wanted)
	end

	-- Stores a refusal's limit or a successful smaller reply after a transport wall.
	-- Both adapters call this; the record persists, so the lesson outlives a session.
	function M.rememberMaxTokens(record, tokens)
		tokens = tonumber(tokens)
		if not tokens or tokens ~= tokens or tokens <= 0 or tokens == math.huge then return end
		local previous = record.maxTokensCap
		local previousTokens = type(previous) == "table" and tonumber(previous.tokens)
		if previousTokens and previous.model == record.model and previousTokens > 0 then
			tokens = math.min(tokens, previousTokens)
		end
		record.maxTokensCap = { model = record.model, tokens = tokens }
		registry.save(record, { force = true })
	end

	-- Read the window named by a context refusal, never the request size or the
	-- output budget beside it. A max_tokens refusal alone cannot teach a window.
	function M.contextWindowFromMessage(message)
		local text = tostring(message or ""):lower()
		local isContext = text:find("context length", 1, true)
			or text:find("context window", 1, true)
			or text:find("context_length_exceeded", 1, true)
			or text:find("prompt is too long", 1, true)
			or text:find("maximum context", 1, true)
			or text:find("too many tokens", 1, true)
			or text:find("reduce the length of the messages", 1, true)
		if not isContext then return nil end
		-- Some gateways format limits as 128,000 or 1,048,576.
		text = text:gsub("(%d),(%d%d%d)", "%1%2"):gsub("(%d),(%d%d%d)", "%1%2")
		local patterns = {
			"maximum context length is%s*(%d+)",
			"maximum context length of%s*(%d+)",
			"maximum context window is%s*(%d+)",
			"context length of%s*(%d+)",
			"context window of%s*(%d+)",
			"context length%s*[:=]%s*(%d+)",
			"context window%s*[:=]%s*(%d+)",
			">%s*(%d+)%s*maximum",
			"maximum of%s*(%d+)%s*tokens",
			"at most%s*(%d+)%s*tokens",
		}
		for _, pattern in ipairs(patterns) do
			local window = tonumber(text:match(pattern))
			if window and window >= 8000 and window < math.huge then return window end
		end
		return nil
	end

	-- A refusal can only lower an existing claim. The shared model map feeds
	-- compaction, badges and configuration export, and persists across executions.
	function M.rememberContextWindow(record, window)
		window = tonumber(window)
		if not window or window ~= window or window < 8000 or window == math.huge then return end
		local id = util.trim(tostring(record and record.model or "")):lower()
		if id == "" then return end
		window = math.floor(window)
		local contexts = util.deepCopy(config.get("agent.forceContext", {}) or {})
		local previous = tonumber(contexts[id])
		if previous and previous > 0 then window = math.min(window, previous) end
		if previous == window then return end
		contexts[id] = window
		config.set("agent.forceContext", contexts)
		log.info("provider", string.format("%s: learned context window %d for %s",
			tostring(record.label or id), window, tostring(record.model)))
	end

	function M.learnContextWindow(record, res)
		if not res then return nil end
		local window = M.contextWindowFromMessage(M.errorText(res, nil))
		if window then M.rememberContextWindow(record, window) end
		return window
	end

	-- Gateways reject different subsets of the payload. Rather than maintaining a
	-- per-vendor allowlist that goes stale, a 400 whose text names a field is
	-- repaired once and retried -- and the repair is remembered on the record so
	-- the next turn does not pay for it again.
	local REPAIRS = {
		{
			match = "max_completion_tokens",
			apply = function(body)
				if body.max_tokens then
					body.max_completion_tokens = body.max_tokens
					body.max_tokens = nil
					return "renamed max_tokens to max_completion_tokens"
				end
			end,
		},
		{
			-- Ordered after the rename on purpose: a gateway that wants the other field
			-- name says so in a message this would otherwise read as a size complaint.
			match = "max_tokens",
			apply = function(body, message)
				-- Only ever driven by a live refusal. Replayed from record.repairs there
				-- is no message, and halving on every request would be a silent bug.
				if not message then return nil end
				local current = body.max_tokens or body.max_completion_tokens
				if not current then return nil end
				local allowed = M.ceilingFromMessage(message, current)
				if not allowed or allowed >= current then return nil end
				if body.max_tokens then body.max_tokens = allowed end
				if body.max_completion_tokens then body.max_completion_tokens = allowed end
				return string.format("lowered max_tokens from %d to %d", current, allowed)
			end,
		},
		{
			match = "temperature",
			apply = function(body)
				if body.temperature ~= nil then
					body.temperature = nil
					return "dropped temperature"
				end
			end,
		},
		{
			match = "parallel_tool_calls",
			apply = function(body)
				if body.parallel_tool_calls ~= nil then
					body.parallel_tool_calls = nil
					return "dropped parallel_tool_calls"
				end
			end,
		},
		{
			match = "stream_options",
			apply = function(body)
				if body.stream_options ~= nil then
					body.stream_options = nil
					return "dropped stream_options"
				end
			end,
		},
		{
			-- Not every gateway that relays to a reasoning model forwards the field
			-- that asks for a depth. Dropping it costs the setting, not the turn.
			match = "reasoning_effort",
			apply = function(body)
				if body.reasoning_effort ~= nil then
					body.reasoning_effort = nil
					return "dropped reasoning_effort"
				end
			end,
		},
		{
			match = "tool_choice",
			apply = function(body)
				if body.tool_choice ~= nil then
					body.tool_choice = nil
					return "dropped tool_choice"
				end
			end,
		},
		{
			-- Gateways relaying to reasoning models reject the classic system role and
			-- name the newer one in the message. Rewriting the first system message to
			-- `developer` is the documented mapping, and it is remembered on the record
			-- like every other repair so only the first turn pays for the lesson.
			match = "developer",
			apply = function(body)
				local renamed = false
				for _, message in ipairs(body.messages or {}) do
					if type(message) == "table" and message.role == "system" then
						message.role = "developer"
						renamed = true
					end
				end
				if renamed then return "rewrote system messages as developer" end
			end,
		},
		{
			-- Thinking mode on Anthropic gateways (e.g. AgentRouter/NewAPI routing to Claude):
			-- requires assistant turns to carry content blocks with type = "thinking".
			--
			-- Ephemeral (see EPHEMERAL_REPAIRS): a gateway like AgentRouter multiplexes
			-- several backends behind one endpoint, and a sibling backend rejects these
			-- blocks as an unknown variant. Remembering the conversion would poison every
			-- later turn that lands on the OpenAI-schema backend, so it is applied per
			-- refusal and never saved.
			--
			-- Only turns that actually captured reasoning are converted: a thinking block
			-- rebuilt from empty text has no signature and is rejected again, so a turn
			-- with nothing to replay is left as-is for the sibling backend to accept.
			match = "content[].thinking",
			apply = function(body)
				local fixed = 0
				for _, msg in ipairs(body.messages or {}) do
					if type(msg) == "table" and msg.role == "assistant" and type(msg.content) ~= "table" then
						local reasoning = msg.reasoning_content
						local text = type(msg.content) == "string" and msg.content or ""
						if type(reasoning) == "string" and util.trim(reasoning) ~= "" then
							local blocks = { { type = "thinking", thinking = reasoning } }
							if text ~= "" then
								blocks[#blocks + 1] = { type = "text", text = text }
							end
							msg.content = blocks
							msg.reasoning_content = nil
							fixed = fixed + 1
						end
					end
				end
				if fixed > 0 then
					return string.format("converted %d assistant message(s) to thinking content blocks", fixed), "content[].thinking"
				end
			end,
		},
		{
			-- The inverse of the conversion above. A sibling backend behind the same
			-- gateway uses an OpenAI-style deserializer with no `thinking` variant and
			-- rejects the blocks with "unknown variant `thinking`, expected one of
			-- `text`, `image_url`, `file`". Flatten assistant content back to a plain
			-- string and restore reasoning_content so the request the sibling backend
			-- can read goes out. Ephemeral for the same reason its inverse is: neither
			-- content shape is stable across the gateway's routing.
			match = "unknown variant `thinking`",
			apply = function(body)
				local fixed = 0
				for _, msg in ipairs(body.messages or {}) do
					if type(msg) == "table" and msg.role == "assistant" and type(msg.content) == "table" then
						local textParts, thinkParts = {}, {}
						for _, block in ipairs(msg.content) do
							if type(block) == "table" then
								if block.type == "thinking" then
									local think = block.thinking or block.text
									if type(think) == "string" and think ~= "" then
										thinkParts[#thinkParts + 1] = think
									end
								elseif type(block.text) == "string" then
									textParts[#textParts + 1] = block.text
								end
							end
						end
						msg.content = table.concat(textParts)
						if #thinkParts > 0 then
							msg.reasoning_content = table.concat(thinkParts, "\n")
						end
						fixed = fixed + 1
					end
				end
				if fixed > 0 then
					return string.format("flattened %d assistant message(s) back to plain content", fixed), "revert_thinking_blocks"
				end
			end,
		},
		{
			-- Reasoning models (DeepSeek-R1, QwQ, Step, etc.) require reasoning_content passed back
			-- on every assistant turn, even when empty. If a gateway rejects because reasoning_content
			-- is missing or required, ensure it is set. If a gateway rejects reasoning_content as
			-- an unknown/unsupported parameter, drop it.
			match = "reasoning_content",
			apply = function(body, message)
				local lowered = tostring(message or ""):lower()
				local isForbidden = lowered:find("unrecognized", 1, true)
					or lowered:find("not permitted", 1, true)
					or lowered:find("unknown", 1, true)
					or lowered:find("unexpected", 1, true)
					or lowered:find("extra", 1, true)

				if isForbidden then
					local dropped = 0
					for _, msg in ipairs(body.messages or {}) do
						if type(msg) == "table" and msg.role == "assistant" and msg.reasoning_content ~= nil then
							msg.reasoning_content = nil
							dropped = dropped + 1
						end
					end
					if dropped > 0 then
						return "dropped reasoning_content", "drop_reasoning_content"
					end
					return nil
				end

				-- Required in thinking mode: ensure reasoning_content is present on all assistant messages
				local fixed = 0
				for _, msg in ipairs(body.messages or {}) do
					if type(msg) == "table" and msg.role == "assistant" then
						if msg.reasoning_content == nil then
							msg.reasoning_content = ""
							fixed = fixed + 1
						end
					end
				end
				if fixed > 0 then
					return string.format("ensured reasoning_content on %d assistant message(s)", fixed), "require_reasoning_content"
				end
			end,
		},
		{
			match = "require_reasoning_content",
			apply = function(body)
				for _, msg in ipairs(body.messages or {}) do
					if type(msg) == "table" and msg.role == "assistant" and msg.reasoning_content == nil then
						msg.reasoning_content = ""
					end
				end
			end,
		},
		{
			match = "drop_reasoning_content",
			apply = function(body)
				for _, msg in ipairs(body.messages or {}) do
					if type(msg) == "table" and msg.role == "assistant" and msg.reasoning_content ~= nil then
						msg.reasoning_content = nil
					end
				end
			end,
		},
	}

	-- Repairs that change the shape of message content rather than a top-level
	-- parameter. AgentRouter and other NewAPI gateways multiplex several backends
	-- behind one endpoint, and the two backends disagree about content shape: one
	-- demands thinking blocks, the other rejects them. A remembered content repair
	-- would replay onto whichever backend the next turn happens to hit and fail
	-- there, so these are applied per refusal and never saved to the record.
	local EPHEMERAL_REPAIRS = {
		["content[].thinking"] = true,
		["revert_thinking_blocks"] = true,
	}

	local function repair(body, message)
		-- A context error often mentions max_tokens too. It needs shorter history,
		-- not output-ceiling repairs that would learn the wrong limit.
		if M.contextWindowFromMessage(message) then return nil end
		local lowered = tostring(message or ""):lower()
		for _, entry in ipairs(REPAIRS) do
			if lowered:find(entry.match:lower(), 1, true) then
				local note, keyOverride = entry.apply(body, message)
				if note then return note, keyOverride or entry.match end
			end
		end
		return nil
	end

	-- Exposed for tests: repair mutates the body in place and returns the note and
	-- key the dispatch loop would act on, without needing a live transport.
	M.repairForTest = repair

	local function applyRemembered(record, body)
		for _, key in ipairs(record.repairs or {}) do
			for _, entry in ipairs(REPAIRS) do
				if entry.match == key then entry.apply(body) end
			end
		end
	end

	local function remember(record, key)
		record.repairs = record.repairs or {}
		for _, existing in ipairs(record.repairs) do
			if existing == key then return end
		end
		record.repairs[#record.repairs + 1] = key
		registry.save(record, { force = true })
	end

	-- Performs one completion against one provider. Returns result, nil on success
	-- or nil, message on failure. Retries inside net/http cover transport and
	-- 5xx/429; the provider chain above this handles a dead endpoint.
	--
	-- A record with several keys gets one more layer: a 429 or quota refusal
	-- benches the key that carried it and re-fires on the next key immediately.
	-- No sleep, because the refusal arrived in milliseconds and the next key's
	-- quota is untouched -- waiting would only spend the wall clock the reply
	-- still has to fit inside.
	local function quotaRefusal(res)
		if not res then return false end
		if res.status == 429 then return true end
		if res.status == 402 or res.status == 403 then
			local body = tostring(res.body or ""):lower()
			if body:find("resource_exhausted", 1, true) then return true end
			if body:find("quota", 1, true) then return true end
			if body:find("rate limit", 1, true) then return true end
		end
		return false
	end

	local function rotationSuffix(index)
		return string.format(" (key %d)", index)
	end

	function M.complete(record, request)
		local wantStream = request.stream
		if wantStream == nil then wantStream = record.stream ~= false and config.get("agent.stream", true) end
		if config.get("bridge.enabled", false) and config.get("bridge.runtime", "game") == "web" then wantStream = true end

		local body = M.buildBody(record, util.merge(request, { stream = wantStream }))
		applyRemembered(record, body)

		local url = registry.endpoint(record, "/chat/completions")
		local pool = registry.keysOf(record)
		local currentKey = nil
		local currentKeyIndex = 0

		local function rebuildHeaders()
			-- With a pool, the key is chosen per attempt; without one this is the
			-- record's own key and nothing changes from before the pool existed.
			if #pool > 1 then
				currentKey = registry.nextKey(record)
				for index, key in ipairs(pool) do
					if key == currentKey then currentKeyIndex = index end
				end
			end
			local headers = registry.authHeaders(record, currentKey)
			for key, value in pairs(registry.opencodeHeaders(record, request)) do headers[key] = value end
			for key, value in pairs(record.headers or {}) do headers[key] = value end
			headers["Accept"] = (wantStream or registry.isOpencode(record)) and "text/event-stream" or "application/json"
			return headers
		end

		local headers = rebuildHeaders()

		local started = clock.ms()
		local lastRequestMs = 0
		local attemptsAllowed = request.attempts or config.get("agent.retries", 3)
		local rotationsLeft = math.max(#pool - 1, 0)
		-- With a pool, a 429 belongs to the rotation above, not to the transport's
		-- backoff: sleeping on an exhausted key spends the wall clock the reply still
		-- needs, and the next key answers at once. Without a pool the flag is nil and
		-- the transport behaves exactly as it always has.
		local skip429 = (#pool > 1) and { [429] = true } or nil

		local function fire(payload)
			-- A socket is only used when the record names one and the host has
			-- WebSocket support; otherwise the SSE body arrives whole over HTTP.
			local web = config.get("bridge.enabled", false) and config.get("bridge.runtime", "game") == "web"
			if not web and wantStream and util.trim(record.wsUrl) ~= "" and caps.ws then
				local ws = env.require("net/ws")
				local socketHeaders = headers
				if registry.requiresClaude(record) then
					socketHeaders = http.headersFor({ url = url, headers = headers, body = payload,
						identity = "claude", identityRequired = true, timeout = requestTimeout(request) })
				end
				local streamBody, wsErr = ws.stream({
					url = record.wsUrl,
					path = "/chat/completions",
					headers = socketHeaders,
					body = payload,
					aborted = request.aborted,
					onFrame = request.onFrame,
					-- Same deadline as the HTTP path: a long think is not a failure, and the
					-- socket only ends the exchange when this runs out.
					timeout = requestTimeout(request),
				})
				if streamBody then
					return { ok = true, status = 200, body = streamBody, via = "websocket", ms = clock.since(started) }
				end
				if wsErr == "aborted" then return nil, "aborted" end
				log.warn("provider", "websocket stream failed, falling back to http", wsErr)
			end
			M.limitExecutorReply(record, request, payload)
			local requestStarted = clock.ms()
			local res, err = http.send({
				relay = web,
				sessionId = request.sessionId,
				url = url,
				method = "POST",
				headers = headers,
				body = util.encode(payload),
				identity = registry.identityFor(record),
				identityRequired = registry.requiresClaude(record),
				attempts = attemptsAllowed,
				skipStatus = skip429,
				aborted = request.aborted,
				onRetry = request.onRetry,
				tag = "chat:" .. record.id,
				-- The one deadline that matters for a reasoning model: nothing arrives
				-- until it finishes thinking, so this has to outlast the think.
				timeout = requestTimeout(request),
			})
			lastRequestMs = clock.since(requestStarted)
			if request.aborted and request.aborted() then return nil, "aborted" end
			return res, err
		end

		local function fireWithRotation(payload)
			local res, err = fire(payload)
			while res and not res.ok and quotaRefusal(res) and rotationsLeft > 0 do
				rotationsLeft = rotationsLeft - 1
				local benched = currentKey or pool[1]
				registry.cooldownKey(record, benched)
				currentKey = registry.nextKey(record)
				for index, key in ipairs(pool) do
					if key == currentKey then currentKeyIndex = index end
				end
				headers = rebuildHeaders()
				local label = "rate limited, rotating to key #" .. currentKeyIndex
				log.info("provider", record.label .. ": " .. label)
				if request.onRetry then
					request.onRetry({ attempt = 1, attempts = 2, wait = 0, reason = label, status = res.status })
				end
				res, err = fire(payload)
			end
			return res, err
		end

		local res, err = fireWithRotation(body)
		-- A gateway names a bad field in a 400, and a NewAPI gateway names a bad
		-- content variant in a 422. Both are repairable, and both can chain: a
		-- gateway that multiplexes backends can refuse the very shape a sibling
		-- backend just demanded, so a single repair is not enough -- the reversal
		-- has to get its own retry. Bounded so a gateway that flip-flops between
		-- two backends cannot spin here forever; when the budget runs out the body
		-- falls through to the normal failure path and the chain moves on.
		local repairsLeft = 4
		while res and (res.status == 400 or res.status == 422) and repairsLeft > 0 do
			repairsLeft = repairsLeft - 1
			local message = M.errorText(res, nil)
			local note, key = repair(body, message)
			if not note then break end
			log.info("provider", record.label .. ": " .. note .. ", retrying")
			if key == "max_tokens" then
				-- A value, not a switch, so it cannot ride in record.repairs -- that
				-- list replays a key with no error text to read a number out of.
				M.rememberMaxTokens(record, body.max_tokens or body.max_completion_tokens)
			elseif not EPHEMERAL_REPAIRS[key] then
				remember(record, key)
			end
			if request.onRetry then
				request.onRetry({ attempt = 1, attempts = 2, wait = 0, reason = note, status = res.status })
			end
			res, err = fireWithRotation(body)
		end

		-- The executor's transport wall: no body, no headers, an executor raise for
		-- the error text, and no config value can lift that wall because the option
		-- was never honoured. Retry once with a smaller ask -- less thinking, half the
		-- reply ceiling -- so the model finishes inside the wall instead of dying at
		-- it. Only when an HTTP request produced nothing after 20-130 seconds,
		-- and only when the smaller ask is actually smaller: a
		-- deadline on an already-minimal body would re-send the same prompt to the
		-- same wall, and that is the one outcome this must not do.
		local recoveredTokens
		if not res and err and err ~= "aborted" and lastRequestMs >= 20000 and lastRequestMs <= 130000 then
			local lowered, note = smallerAsk(body)
			if lowered and util.encode(lowered) ~= util.encode(body) then
				log.info("provider", record.label .. ": hit the transport wall, retrying smaller (" .. note .. ")")
				if request.onRetry then
					request.onRetry({ attempt = 1, attempts = 2, wait = 0, reason = note, status = 0 })
				end
				res, err = fireWithRotation(lowered)
				if res and res.ok then recoveredTokens = lowered.max_tokens or lowered.max_completion_tokens end
			end
		end

		if not res or not res.ok then
			M.learnContextWindow(record, res)
			local message = M.errorText(res, err)
			registry.markFail(record, message)
			return nil, message, res
		end

		local parsed
		if sse.looksStreamed(res.body) then
			parsed = sse.parse(res.body)
		else
			local decoded, decodeErr = util.decode(res.body)
			if type(decoded) ~= "table" then
				local message = "provider returned a body that is not JSON: " .. tostring(decodeErr)
				registry.markFail(record, message)
				return nil, message, res
			end
			if decoded.error then
				local message = M.errorText(res, nil)
				registry.markFail(record, message)
				return nil, message, res
			end
			parsed = sse.fromResponse(decoded)
		end

		if parsed.streamError then
			registry.markFail(record, parsed.streamError)
			return nil, "stream error: " .. parsed.streamError, res
		end

		local hasText = util.trim(parsed.content) ~= ""
		local hasCalls = #(parsed.toolCalls or {}) > 0
		if not hasText and not hasCalls and util.trim(parsed.reasoning) == "" then
			-- An empty completion is not an error the model can act on, so it is
			-- reported as a failure and the chain may try elsewhere.
			local message = "the provider returned an empty completion"
			registry.markFail(record, message)
			return nil, message, res
		end

		-- A 200 with an error, malformed JSON or an empty completion did not recover.
		if recoveredTokens then
			M.rememberMaxTokens(record, recoveredTokens)
			log.info("provider", record.label .. ": smaller request succeeded; remembered max_tokens " .. tostring(recoveredTokens))
		end
		parsed.ms = clock.since(started)
		parsed.provider = record.id
		parsed.providerLabel = record.label
		parsed.via = res.via
		parsed.requestId = res.inferenceId
		parsed.streamed = parsed.frames and parsed.frames > 0 or false
		registry.markOk(record, parsed.ms)
		return parsed, nil, res
	end

	return M
end
end)()

-- ==========================================================================
-- provider/registry
-- ==========================================================================
__UAI_MODULES["provider/registry"] = (function()
-- Provider records: creation, validation, persistence, health and fallback order.
--
-- A record is the whole description of one endpoint, so switching provider is a
-- data change rather than a code path. Nothing above this module knows which
-- vendor is in use.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local catalog = env.require("provider/catalog")

	local COOLDOWN_AFTER = 3
	local COOLDOWN_SECONDS = 45

	local M = {
		changed = signal.new("providers"),
	}

	-- Key pool ------------------------------------------------------------
	--
	-- One record may carry several keys, pasted one per line (or comma
	-- separated). The pool is what beats a free-tier RPM ceiling: Google AI
	-- Studio hands out keys in batches and caps each at 10-15 requests a
	-- minute, so N keys in one record is N times the ceiling with no second
	-- provider to configure.
	--
	-- The selection is sticky, not round-robin: the same key is used until it
	-- is rate limited, then the next one takes over instantly. Round-robin
	-- would spread the limit evenly but also spend every key's quota on
	-- requests a single exhausted key could have answered, and it makes a
	-- genuinely dead key indistinguishable from a cooling one.
	local KEY_COOLDOWN_SECONDS = 30

	function M.keysOf(record)
		local raw = tostring(record and record.apiKey or "")
		local keys, seen = {}, {}
		-- Line breaks are the primary form (that is what a multi-line paste
		-- produces); commas are accepted because a user who was handed
		-- "key1,key2" should not have to edit it.
		for token in raw:gmatch("[^\r\n,]+") do
			local key = util.trim(token)
			if key ~= "" and not seen[key] then
				seen[key] = true
				keys[#keys + 1] = key
			end
		end
		return keys
	end

	function M.keyPoolSize(record)
		return #M.keysOf(record)
	end

	-- Rotation state is kept on the record, not in this module's memory, so it
	-- survives nothing it should not and is visible to the health views. It is
	-- deliberately NOT persisted to config: which key is current is a fact about
	-- this session, and a saved index would be stale on the next start.
	local function keyState(record)
		record.keyRotation = record.keyRotation or { index = 1, cooldowns = {} }
		return record.keyRotation
	end

	-- The key a request should use. Sticky: the current index unless that key
	-- is on cooldown, then the next one that is not. When every key is cooling,
	-- the one whose cooldown expires soonest -- a pool that is entirely spent
	-- is a pool that was just load-balanced, and waiting out the shortest
	-- remaining bench is faster than hammering any single key.
	function M.nextKey(record)
		local keys = M.keysOf(record)
		if #keys == 0 then return nil end
		if #keys == 1 then return keys[1] end

		local state = keyState(record)
		local now = clock.ms()
		local function ready(index)
			local until_ = state.cooldowns[keys[index]]
			return until_ == nil or until_ <= now
		end

		-- Walk the pool from the current index, wrapping once.
		for offset = 0, #keys - 1 do
			local index = ((state.index - 1 + offset) % #keys) + 1
			if ready(index) then
				state.index = index
				return keys[index]
			end
		end

		-- All cooling: soonest to expire.
		local best, bestAt = nil, math.huge
		for index = 1, #keys do
			local until_ = state.cooldowns[keys[index]] or 0
			if until_ < bestAt then
				best, bestAt = keys[index], until_
			end
		end
		return best
	end

	-- Bench one key after it was refused. `seconds` may be overridden by a
	-- caller that read a Retry-After header, which outranks our default.
	function M.cooldownKey(record, key, seconds)
		local keys = M.keysOf(record)
		if #keys < 2 then return false end
		local state = keyState(record)
		state.cooldowns[key] = clock.ms() + (seconds or KEY_COOLDOWN_SECONDS) * 1000
		return true
	end

	function M.keyCooldowns(record)
		local state = record and record.keyRotation
		if type(state) ~= "table" then return nil end
		return state.cooldowns
	end

	-- Base URL normalisation, done once on save so no request path has to guess.
	--
	--   api.openai.com            -> https://api.openai.com/v1
	--   https://x.dev/            -> https://x.dev/v1
	--   https://x.dev/openai/v1   -> unchanged (it already names a path)
	--   https://x.dev/v1/chat/completions -> unchanged, used verbatim
	function M.normaliseBaseUrl(raw)
		local text = util.trim(raw)
		if text == "" then return "" end
		if not text:find("^https?://") then text = "https://" .. text end
		text = text:gsub("/+$", "")
		local scheme, rest = text:match("^(https?://)(.*)$")
		if not scheme then return text end
		local hostAndPath = rest
		local path = hostAndPath:match("^[^/]+(/.*)$")
		if not path or path == "" then
			return text .. "/v1"
		end
		return text
	end

	function M.isFullEndpoint(url)
		return tostring(url):find("/chat/completions$") ~= nil
	end

	function M.endpoint(record, suffix)
		local base = record.baseUrl or ""
		local url
		if M.isFullEndpoint(base) then
			url = (suffix == "/chat/completions") and base or (base:gsub("/chat/completions$", "") .. suffix)
		else
			url = base .. suffix
		end
		local query = {}
		for key, value in pairs(record.query or {}) do
			query[#query + 1] = util.urlEncode(key) .. "=" .. util.urlEncode(value)
		end
		if #query > 0 then
			url = url .. (url:find("%?") and "&" or "?") .. table.concat(query, "&")
		end
		return url
	end

	function M.authHeaders(record, explicitKey)
		local key = util.trim(explicitKey or record.apiKey)
		local style = record.authStyle or "bearer"
		if key == "" or style == "none" then return {} end
		if style == "x-api-key" then return { ["x-api-key"] = key } end
		if style == "api-key" then return { ["api-key"] = key } end
		if style == "both" then
			return { ["Authorization"] = "Bearer " .. key, ["x-api-key"] = key }
		end
		return { ["Authorization"] = "Bearer " .. key }
	end

	-- OpenCode compatibility metadata belongs only to the official host.
	function M.isOpencode(record)
		local base = util.trim(tostring(record and record.baseUrl or "")):lower()
		local authority = base:match("^https?://([^/%?#]+)")
		if not authority then return false end
		return authority == "opencode.ai" or authority:match("^opencode%.ai:%d+$") ~= nil
	end

	-- Host based so manually entered gateways keep the same required identity.
	function M.requiresClaude(record)
		local base = util.trim(tostring(record and record.baseUrl or "")):lower()
		local authority = base:match("^https?://([^/%?#]+)")
		if not authority or authority:find("@", 1, true) then return false end
		local host = authority:gsub(":%d+$", ""):gsub("%.$", "")
		return host == "agentrouter.org" or host:match("^[%w%.%-]+%.agentrouter%.org$") ~= nil
	end

	function M.identityFor(record)
		-- A manually entered Zen endpoint gets the same compatibility identity as
		-- the preset without competing Claude/Stainless headers.
		if M.isOpencode(record) then return "none" end
		if M.requiresClaude(record) then return "claude" end
		return (record.claudeUa ~= false) and "claude" or "none"
	end

	local BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
	local function randomBase62(len)
		local t = {}
		for i = 1, len do
			local r = math.random(1, 62)
			t[i] = BASE62:sub(r, r)
		end
		return table.concat(t)
	end

	local function randomHex(len)
		local t = {}
		for i = 1, len do
			local r = math.random(0, 15)
			t[i] = string.format("%x", r)
		end
		return table.concat(t)
	end

	local function opencodeId(prefix)
		return (prefix or "ses_") .. randomHex(12) .. randomBase62(14)
	end
	M.opencodeId = opencodeId

	local sessionCache = {}
	M.opencodeSessionCache = sessionCache

	function M.opencodeSessionFor(record, context)
		local session = nil
		local sessionId = nil
		if type(context) == "table" then
			if context.session then
				session = context.session
				sessionId = session.id or context.sessionId
			elseif context.id and (type(context.emit) == "function" or type(context.send) == "function") then
				session = context
				sessionId = session.id
			elseif context.sessionId then
				sessionId = context.sessionId
			end
		elseif type(context) == "string" and context ~= "" then
			sessionId = context
		end

		if session then
			local existing = session.opencodeSession
			if type(existing) == "string" and util.trim(existing) ~= "" and #existing >= 25 then
				if session.id then sessionCache[session.id] = existing end
				return existing
			end
			if session.id and sessionCache[session.id] then
				session.opencodeSession = sessionCache[session.id]
				return sessionCache[session.id]
			end
			local created = opencodeId("ses_")
			session.opencodeSession = created
			if session.id then sessionCache[session.id] = created end
			return created
		end

		if sessionId then
			if sessionCache[sessionId] then
				return sessionCache[sessionId]
			end
			local created = opencodeId("ses_")
			sessionCache[sessionId] = created
			return created
		end

		if util.trim(record.opencodeSession or "") == "" or #record.opencodeSession < 25 then
			record.opencodeSession = opencodeId("ses_")
			M.save(record, { quiet = true })
		end
		return record.opencodeSession
	end

	function M.opencodeHeaders(record, context)
		if not M.isOpencode(record) then return {} end
		-- Match the current upstream CLI defaults; saved overrides remain supported.
		local version, client = "1.18.31", "cli"
		if type(record.opencode) == "table" then
			local configuredVersion = util.trim(tostring(record.opencode.version or ""))
			local configuredClient = util.trim(tostring(record.opencode.client or ""))
			if configuredVersion ~= "" then version = configuredVersion end
			if configuredClient ~= "" then client = configuredClient end
		end
		local sessionId = M.opencodeSessionFor(record, context)
		return {
			["x-opencode-session"] = sessionId,
			["x-opencode-request"] = opencodeId("req_"),
			["x-opencode-project"] = "global",
			["x-opencode-client"] = client,
			["User-Agent"] = "opencode/" .. version,
		}
	end

	-- A record always has every field, so no consumer needs a nil check.
	function M.blank(presetId)
		local preset = catalog.get(presetId or "custom") or catalog.get("custom")
		return {
			id = "",
			preset = preset.id,
			label = preset.label,
			baseUrl = preset.baseUrl,
			apiKey = "",
			authStyle = preset.authStyle or "bearer",
			-- Which wire protocol the record speaks. Absent means chat completions,
			-- which is what every record saved before the second adapter existed has.
			api = preset.api or "openai",
			models = util.deepCopy(preset.models or {}),
			model = (preset.models or {})[1] or "",
			headers = util.deepCopy(preset.headers or {}),
			params = util.deepCopy(preset.params or {}),
			query = util.deepCopy(preset.query or {}),

			stream = true,
			-- `~= false` rather than an and/or chain: `(x == false) and false or true`
			-- is still true when x is false, which is the trap both forms of this line
			-- fell into. A preset's deliberate `false` has to survive the copy.
			claudeUa = preset.claudeUa ~= false,
			enabled = true,
			order = 0,
			wsUrl = "",
			note = preset.note,
			requires = preset.requires,
			health = { ok = 0, fail = 0, streak = 0, lastError = "", cooldownUntil = 0, lastMs = 0 },
		}
	end

	local function ensureId(wanted)
		local base = util.trim(wanted):lower():gsub("[^%w%-_]", "-"):gsub("%-+", "-"):gsub("^%-", "")
		if base == "" then base = "provider" end
		local taken = {}
		for _, record in ipairs(M.list()) do taken[record.id] = true end
		if not taken[base] then return base end
		for index = 2, 99 do
			local candidate = base .. "-" .. tostring(index)
			if not taken[candidate] then return candidate end
		end
		return base .. "-" .. tostring(clock.ms())
	end

	function M.list()
		local stored = config.get("providers.list", {})
		if type(stored) ~= "table" then return {} end
		local out = {}
		for _, record in ipairs(stored) do
			if type(record) == "table" then out[#out + 1] = record end
		end
		table.sort(out, function(a, b)
			if (a.order or 0) ~= (b.order or 0) then return (a.order or 0) < (b.order or 0) end
			return tostring(a.id) < tostring(b.id)
		end)
		return out
	end

	function M.get(id)
		for _, record in ipairs(M.list()) do
			if record.id == id then return record end
		end
		return nil
	end

	function M.count()
		return #M.list()
	end

	-- Validation is deliberately about reachability, not taste: a record with a
	-- plausible URL and, where needed, a key is allowed even if the vendor turns
	-- out to reject it. The health counters are what report that.
	function M.validate(record)
		local problems = {}
		if util.trim(record.label) == "" then problems[#problems + 1] = "give the provider a name" end
		local base = M.normaliseBaseUrl(record.baseUrl)
		if base == "" then
			problems[#problems + 1] = "base URL is required"
		elseif not base:find("^https?://[^/]+") then
			problems[#problems + 1] = "base URL does not look like a URL"
		end
		if (record.authStyle or "bearer") ~= "none" and util.trim(record.apiKey) == "" then
			problems[#problems + 1] = "an API key is required for this auth style"
		end
		-- Azure takes the model from the deployment in the URL; everyone else needs
		-- one named, and nothing here will guess it.
		if record.preset ~= "azure" and util.trim(record.model) == "" then
			problems[#problems + 1] = "fetch the model list or add a model id"
		end
		if record.requires == "executor" and caps.http ~= "executor" then
			problems[#problems + 1] = "this endpoint needs an executor HTTP function; this host has none"
		end
		return #problems == 0, problems
	end

	function M.save(record, opts)
		opts = opts or {}
		record.baseUrl = M.normaliseBaseUrl(record.baseUrl)
		if M.requiresClaude(record) then record.claudeUa = true end
		local ok, problems = M.validate(record)
		if not ok and not opts.force then return false, problems end

		local list = config.get("providers.list", {})
		if type(list) ~= "table" then list = {} end
		if util.trim(record.id) == "" then
			record.id = ensureId(record.label ~= "" and record.label or record.preset)
			record.order = #list + 1
			list[#list + 1] = record
		else
			local replaced = false
			for index, existing in ipairs(list) do
				if existing.id == record.id then
					list[index] = record
					replaced = true
				end
			end
			if not replaced then
				record.order = #list + 1
				list[#list + 1] = record
			end
		end
		config.set("providers.list", list)
		if util.trim(config.get("providers.active", "")) == "" then
			config.set("providers.active", record.id)
		end
		M.changed:fire("save", record)
		return true, record
	end

	function M.remove(id)
		local list = config.get("providers.list", {})
		local kept = {}
		for _, record in ipairs(list) do
			if record.id ~= id then kept[#kept + 1] = record end
		end
		config.set("providers.list", kept)
		if config.get("providers.active", "") == id then
			config.set("providers.active", kept[1] and kept[1].id or "")
		end
		M.changed:fire("remove", id)
		return true
	end

	function M.setActive(id)
		if not M.get(id) then return false, "unknown provider" end
		config.set("providers.active", id)
		M.changed:fire("active", id)
		return true
	end

	function M.active()
		local wanted = config.get("providers.active", "")
		local record = M.get(wanted)
		if record then return record end
		for _, candidate in ipairs(M.list()) do
			if candidate.enabled ~= false then return candidate end
		end
		return nil
	end

	function M.setModel(id, model)
		local record = M.get(id)
		if not record then return false end
		record.model = model
		if not util.find(record.models or {}, function(item) return item == model end) then
			record.models = record.models or {}
			table.insert(record.models, 1, model)
		end
		M.save(record, { force = true })
		M.changed:fire("model", record)
		return true
	end

	function M.reorder(id, direction)
		local list = M.list()
		for index, record in ipairs(list) do
			if record.id == id then
				local swapWith = list[index + direction]
				if not swapWith then return false end
				local mine, theirs = record.order or index, swapWith.order or (index + direction)
				record.order, swapWith.order = theirs, mine
				config.set("providers.list", list)
				M.changed:fire("order", id)
				return true
			end
		end
		return false
	end

	-- Health -----------------------------------------------------------------

	local function health(record)
		record.health = record.health or { ok = 0, fail = 0, streak = 0, lastError = "", cooldownUntil = 0 }
		return record.health
	end

	function M.markOk(record, ms)
		local state = health(record)
		state.ok = state.ok + 1
		state.streak = 0
		state.lastError = ""
		state.cooldownUntil = 0
		state.lastMs = ms or state.lastMs
		M.changed:fire("health", record)
	end

	-- Consecutive failures put a provider on the bench rather than the first one:
	-- a single 500 from an otherwise healthy endpoint is noise, and demoting on it
	-- would flap the active provider on every hiccup.
	function M.markFail(record, message)
		local state = health(record)
		state.fail = state.fail + 1
		state.streak = state.streak + 1
		state.lastError = util.ellipsis(message or "request failed", 200)
		if state.streak >= COOLDOWN_AFTER then
			state.cooldownUntil = clock.ms() + COOLDOWN_SECONDS * 1000
			log.warn("provider", record.label .. " benched for " .. tostring(COOLDOWN_SECONDS) .. "s", state.lastError)
		end
		M.changed:fire("health", record)
	end

	function M.cooling(record)
		local state = health(record)
		return (state.cooldownUntil or 0) > clock.ms()
	end

	-- Ordered attempt list: the active provider, then every other enabled one that
	-- is not cooling down, then -- if that leaves nothing -- the cooling ones
	-- anyway, because refusing to try at all is worse than trying a bad endpoint.
	function M.chain()
		local out = {}
		local seen = {}
		local activeRecord = M.active()
		if activeRecord and activeRecord.enabled ~= false then
			out[#out + 1] = activeRecord
			seen[activeRecord.id] = true
		end
		if config.get("agent.fallback", true) then
			for _, record in ipairs(M.list()) do
				if not seen[record.id] and record.enabled ~= false and not M.cooling(record) then
					out[#out + 1] = record
					seen[record.id] = true
				end
			end
			if #out == 0 then
				for _, record in ipairs(M.list()) do
					if record.enabled ~= false then out[#out + 1] = record end
				end
			end
		end
		return out
	end

	function M.summary(record)
		if not record then return "no provider configured" end
		local state = health(record)
		local bits = { record.label }
		if record.model ~= "" then bits[#bits + 1] = record.model end
		if M.cooling(record) then bits[#bits + 1] = "cooling down" end
		if state.lastMs and state.lastMs > 0 then bits[#bits + 1] = util.formatDuration(state.lastMs) end
		return table.concat(bits, " | ")
	end

	return M
end
end)()

-- ==========================================================================
-- provider/traits
-- ==========================================================================
__UAI_MODULES["provider/traits"] = (function()
-- What a model accepts, and how much it can hold.
--
-- Every gateway claims to be OpenAI-compatible and none of them publishes
-- capabilities: /models returns ids, not limits. So the facts that change how a
-- request must be built live here, in one table, rather than being rediscovered
-- from a 400 at each call site.
--
-- Matched by longest substring, the same way `usage.priceFor` resolves a price,
-- because gateways prefix and suffix ids freely -- "anthropic/claude-opus-5",
-- "claude-opus-5-1m", a dated snapshot -- and an exact-match table would miss
-- every one of them. Only families this client has a documented fact about appear;
-- an unknown id resolves to an empty trait set, which means "behave as before".
return function(env)
	local config = env.require("runtime/config")

	local M = {}

	-- context  the input window, in tokens.
	-- output   the ceiling on a single reply, in tokens.
	-- sampling false only where temperature/top_p/top_k are *rejected* rather than
	--          ignored. Absent means "send them", which is what every other model
	--          in this client has always had.
	-- effort   the levels `output_config.effort` accepts, cheapest first, or absent
	--          where the model has no effort control.
	-- thinking "adaptive" for models that reason without a token budget and take
	--          `{ type = "adaptive" }`; "budget" for the older shape that requires
	--          `budget_tokens`. Absent means the model does not expose reasoning.
	-- default  the effort level the API itself uses when none is sent, so the
	--          interface can mark it rather than implying the client picked it.
	local FIVE = { "low", "medium", "high", "xhigh", "max" }
	local FOUR = { "low", "medium", "high", "max" }

	local TRAITS = {
		["claude-fable-5-1"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		["claude-mythos-5-1"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		["claude-fable-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high", alwaysThinks = true },
		-- Opus 5 thinks by default, unlike 4.8 and 4.7, and refuses a disabled
		-- thinking block above effort "high".
		["claude-opus-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-opus-4-8"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-opus-4-7"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		-- 4.6 is the last generation that still takes sampling parameters, and its
		-- effort scale has no "xhigh".
		["claude-opus-4-6"] = { context = 1000000, output = 128000,
			effort = FOUR, thinking = "adaptive", default = "high" },
		["claude-sonnet-5"] = { context = 1000000, output = 128000, sampling = false,
			effort = FIVE, thinking = "adaptive", default = "high" },
		["claude-sonnet-4-6"] = { context = 1000000, output = 128000,
			effort = FOUR, thinking = "adaptive", default = "high" },
		["claude-haiku-4-5"] = { context = 200000 },
	}

	local EMPTY = {}

	-- What the user has told this client to assume about a model id, in place of
	-- what this table documents. Gateways relay ids this table has never heard of
	-- -- "openrouter/qwen3-235b", a relay's own spelling of a frontier model -- and
	-- the honest answer to those used to be "no reasoning, no badge", when the user
	-- knows perfectly well the model behind the id thinks and holds a million tokens.
	-- `agent.forceReasoning` / `agent.forceContext` are those two claims, keyed by
	-- the lowercased model id. A forced context also feeds what the sliders clamp
	-- against, which is what makes a 1M setting real rather than decorative.
	local function forced(model)
		local id = tostring(model or ""):lower()
		if id == "" then return nil end
		local reasoning = config.get("agent.forceReasoning", {}) or {}
		local contexts = config.get("agent.forceContext", {}) or {}
		return {
			thinking = reasoning[id] == true and "adaptive" or nil,
			context = tonumber(contexts[id]) or nil,
		}
	end

	function M.of(model)
		local id = tostring(model or ""):lower()
		if id == "" then return EMPTY end
		local best, bestLength = EMPTY, 0
		for prefix, traits in pairs(TRAITS) do
			if id:find(prefix, 1, true) and #prefix > bestLength then
				best, bestLength = traits, #prefix
			end
		end
		return best
	end

	function M.contextWindow(model)
		local id = tostring(model or ""):lower()
		local over = tonumber((config.get("agent.forceContext", {}) or {})[id])
		return over or M.of(model).context
	end

	function M.maxOutput(model)
		return M.of(model).output
	end

	-- True unless the model is documented to reject them. Withholding a parameter a
	-- model would have accepted changes behaviour for every gateway this client
	-- talks to, so silence is not the safe default here -- only a known refusal is.
	function M.allowsSampling(model)
		return M.of(model).sampling ~= false
	end

	function M.effortLevels(model)
		return M.of(model).effort
	end

	function M.defaultEffort(model)
		return M.of(model).default
	end

	-- The nearest level this model actually has, never rounding up: asking for
	-- "xhigh" on a scale that stops at "high" must land on "high" rather than
	-- spending "max", because the setting is a ceiling the user chose.
	local RANK = { low = 1, medium = 2, high = 3, xhigh = 4, max = 5 }

	function M.nearestEffort(model, wanted)
		local levels = M.effortLevels(model)
		-- A model with no documented scale but a manual reasoning claim has no
		-- levels to clamp against, so the wanted level passes through: the user
		-- said it reasons, and this client has no basis to round them down.
		if not levels then
			if M.thinkingStyle(model) then return tostring(wanted or "") ~= "" and wanted or nil end
			return nil
		end
		local target = RANK[tostring(wanted or ""):lower()]
		if not target then return nil end
		local best
		for _, level in ipairs(levels) do
			local rank = RANK[level]
			if rank == target then return level end
			if rank and rank < target and (not best or RANK[best] < rank) then best = level end
		end
		-- Every level this model has sits above what was asked for, so the cheapest
		-- of them is the closest thing to it.
		return best or levels[1]
	end

	function M.thinkingStyle(model)
		local id = tostring(model or ""):lower()
		if (config.get("agent.forceReasoning", {}) or {})[id] == true then
			return "adaptive"
		end
		return M.of(model).thinking
	end

	function M.alwaysThinks(model)
		return M.of(model).alwaysThinks == true
	end

	-- A short badge for the model pickers: "1M", "200K". Nil when unknown, so a
	-- row for an id this table has never heard of simply has no badge. A manually
	-- declared context is a fact the user stated, so it earns the same badge.
	function M.badge(model)
		local context = M.contextWindow(model)
		if not context then return nil end
		if context >= 1000000 then
			local millions = context / 1000000
			return (millions % 1 == 0) and string.format("%dM", millions)
				or string.format("%.1fM", millions)
		end
		if context >= 1000 then return string.format("%dK", math.floor(context / 1000)) end
		return tostring(context)
	end

	M.TRAITS = TRAITS

	return M
end
end)()

-- ==========================================================================
-- runtime/attachments
-- ==========================================================================
__UAI_MODULES["runtime/attachments"] = (function()
-- User-provided text lives in real files, outside the model's conversation.
return function(env)
	local util = env.require("runtime/util")
	local fsx = env.require("runtime/fsx")
	local clock = env.require("runtime/clock")
	local M = { INLINE_LIMIT = 8000, MAX_BYTES = 2 * 1024 * 1024, READ_BYTES = 6000 }
	local pending = {}
	local SCOPE = { scope = "pastes" }

	local function filename(value)
		local name = tostring(value or "pasted-input.txt"):gsub("\\", "/"):match("[^/]+$") or "pasted-input.txt"
		name = name:gsub('[%z\1-\31\127<>:"|%?%*]', "_"):gsub("[%. ]+$", "")
		if #name == 0 or #name > 80 then name = "pasted-input.txt" end
		return name
	end

	function M.reference(entry)
		return string.format("[Attached file: %s (%d bytes, %d lines)]\nPath: %s\nRead relevant sections with file_read (offset/limit) or find text with file_search. The complete input is in this file.",
			filename(entry.name or entry.label), entry.bytes, entry.lines, entry.path)
	end

	function M.describe(path, content, name)
		local _, breaks = content:gsub("\n", "")
		return { file = true, path = path, name = filename(name or path), label = filename(name or path),
			bytes = #content, lines = #content == 0 and 0 or breaks + 1 }
	end

	function M.save(content, name)
		if type(content) ~= "string" or #content == 0 then return nil, "the attachment is empty" end
		if #content > M.MAX_BYTES then return nil, "attachments support up to 2 MiB; split this input into smaller files" end
		if content:find("\0", 1, true) then return nil, "attach a text or code file; binary files are not supported" end
		if not fsx.enabled then return nil, "file storage is unavailable on this host; long input was kept in your draft" end
		name = filename(name)
		local path
		-- A counter alone repeats after a reload. Check the actual destination too.
		for _ = 1, 100 do
			local candidate = os.date("!%Y%m%d-%H%M%S") .. "-" .. util.uid("input") .. "-" .. name
			if not fsx.exists(candidate, SCOPE) then path = candidate; break end
		end
		if not path then return nil, "could not allocate a new attachment file" end
		local ok, err = fsx.write(path, content, SCOPE)
		if not ok then return nil, "could not save attachment: " .. tostring(err) end
		local saved, readErr = fsx.read(path, SCOPE)
		if saved ~= content then return nil, "could not verify the saved attachment: " .. tostring(readErr or "file contents differ") end
		return M.describe("pastes/" .. path, content, name)
	end

	-- Identify one inserted block without swallowing the question on either side.
	-- TextBox gives a new value, not clipboard data, so compare the two versions.
	function M.inserted(before, after)
		if #after - #before <= M.INLINE_LIMIT then return nil end
		local first, last = 0, 0
		while first < #before and first < #after and before:byte(first + 1) == after:byte(first + 1) do first = first + 1 end
		while first > 0 and after:byte(first + 1) and after:byte(first + 1) >= 128 and after:byte(first + 1) < 192 do first = first - 1 end
		while last < #before - first and last < #after - first and before:byte(#before - last) == after:byte(#after - last) do last = last + 1 end
		while last > 0 and after:byte(#after - last + 1) >= 128 and after:byte(#after - last + 1) < 192 do last = last - 1 end
		local inserted = after:sub(first + 1, #after - last)
		if #inserted <= M.INLINE_LIMIT then return nil end
		return inserted, after:sub(1, first) .. after:sub(#after - last + 1)
	end

	-- Browser uploads travel separately from send, in bounded, ordered chunks.
	-- Only a verified final write produces a file reference. Retries are idempotent.
	function M.upload(owner, args)
		local now, active, retained = clock.ms(), 0, 0
		for id, item in pairs(pending) do
			if now - item.at > 600000 then pending[id] = nil
			else active = active + 1; retained = retained + (item.result and 0 or item.bytes) end
		end
		local id, content, offset = args.uploadId, args.content, args.offset
		if type(id) ~= "string" or #id < 8 or #id > 100 or not id:match("^[%w_-]+$") then return nil, "invalid upload ID" end
		if type(content) ~= "string" or #content > 128 * 1024 then return nil, "upload chunks must be at most 128 KiB" end
		if type(offset) ~= "number" or offset < 0 or offset % 1 ~= 0 then return nil, "invalid upload offset" end
		local item = pending[id]
		if item and item.owner ~= owner then return nil, "upload belongs to another conversation" end
		if item and item.lastOffset == offset and item.lastContent == content and item.final == (args.final == true) then
			return item.result or { received = item.bytes }
		end
		if item and item.result then return nil, "upload ID already belongs to a completed file" end
		if not item then
			if offset ~= 0 then return nil, "upload expired; start again" end
			if active >= 64 then return nil, "too many uploads; retry after earlier uploads expire" end
			item = { owner = owner, name = filename(args.name), parts = {}, bytes = 0, at = now }
			pending[id] = item
		end
		if offset ~= item.bytes then return nil, "upload offset does not match received bytes" end
		if item.bytes + #content > M.MAX_BYTES or retained + #content > 8 * 1024 * 1024 then return nil, "upload exceeds the file or pending upload budget" end
		item.parts[#item.parts + 1], item.bytes, item.at = content, item.bytes + #content, now
		item.lastOffset, item.lastContent, item.final = offset, content, args.final == true
		if args.final ~= true then return { received = item.bytes } end
		local entry, err = M.save(table.concat(item.parts), item.name)
		if not entry then pending[id] = nil; return nil, err end
		entry.reference = M.reference(entry)
		item.result, item.parts = entry, nil
		return entry
	end

	function M.clearUploads(owner)
		for id, item in pairs(pending) do if owner == nil or item.owner == owner then pending[id] = nil end end
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/bridge_install
-- ==========================================================================
__UAI_MODULES["runtime/bridge_install"] = (function()
-- Install a consistent GitHub tree into the executor's UAI/bridge directory.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local http = env.require("net/http")
	local M = { busy = false }
	local API = "https://api.github.com/repos/CarlDV/ProjectUAI/"
	local RAW = "https://raw.githubusercontent.com/CarlDV/ProjectUAI/"
	function M.download(progress)
		if M.busy then return false, "Bridge download is already running." end
		if not fsx.enabled or not caps.fn.makefolder or not caps.fn.isfile then
			return false, "This executor needs file writing, reading, and folder creation to download the bridge."
		end
		if not caps.has("http") then return false, "This executor has no HTTP transport." end
		M.busy = true
		local function report(text) if progress then pcall(progress, text) end end
		local ok, result = pcall(function()
			report("Finding bridge files…")
			local response, err = http.send({ url = API .. "commits/main", method = "GET", timeout = 15, attempts = 2,
				identity = "none", headers = { Accept = "application/vnd.github+json", ["User-Agent"] = "ProjectUAI" }, tag = "bridge download" })
			if not response or not response.ok then error(err or ("GitHub returned " .. tostring(response and response.status)), 0) end
			local commit = util.decode(response.body)
			local revision = type(commit) == "table" and commit.sha
			local treeId = type(commit) == "table" and util.get(commit, "commit.tree.sha")
			if type(revision) ~= "string" or not revision:match("^%x+$") or type(treeId) ~= "string" or not treeId:match("^%x+$") then
				error("GitHub returned an invalid revision.", 0)
			end
			response, err = http.send({ url = API .. "git/trees/" .. treeId .. "?recursive=1", method = "GET", timeout = 15, attempts = 2,
				identity = "none", headers = { Accept = "application/vnd.github+json", ["User-Agent"] = "ProjectUAI" }, tag = "bridge download" })
			if not response or not response.ok then error(err or ("GitHub returned " .. tostring(response and response.status)), 0) end
			local tree = util.decode(response.body)
			if type(tree) ~= "table" or type(tree.tree) ~= "table" or not tostring(tree.sha or ""):match("^%x+$") then error("GitHub returned an invalid file list.", 0) end
			if tree.truncated then error("GitHub file list was truncated; download was not started.", 0) end
			local files, total, server = {}, 0, false
			for _, entry in ipairs(tree.tree) do
				local path = tostring(entry.path or "")
				if path:sub(1, 7) == "bridge/" and entry.type == "blob" then
					local clean = fsx.sanitise(path)
					if clean ~= path or entry.mode == "120000" then error("Invalid bridge file path.", 0) end
					total = total + (tonumber(entry.size) or 0)
					if total > 20 * 1024 * 1024 or #files >= 200 then error("Bridge download exceeds the installation limit.", 0) end
					files[#files + 1] = { path = path, size = entry.size }
					if path == "bridge/server.js" then server = true end
				end
			end
			if not server then error("No bridge/server.js found on GitHub.", 0) end
			-- Fetch everything before changing the installed version. Pin the commit SHA
			-- so a push halfway through the download cannot mix incompatible files.
			for index, file in ipairs(files) do
				report(string.format("Downloading %d/%d · %s", index, #files, file.path))
				local response2, why = http.send({ url = RAW .. revision .. "/" .. file.path, method = "GET",
					timeout = 15, attempts = 2, identity = "none", tag = "bridge download" })
				if not response2 or not response2.ok then error("Could not download " .. file.path .. ": " .. tostring(why or (response2 and response2.status)), 0) end
				file.body = response2.body
				if type(file.body) ~= "string" or (file.size and #file.body ~= file.size) then error("Incomplete download: " .. file.path, 0) end
			end
			for index, file in ipairs(files) do
				report(string.format("Saving %d/%d · %s", index, #files, file.path))
				local full = fsx.resolve(file.path)
				if not fsx.ensure(full:match("^(.*)/[^/]+$")) then error("Could not create the bridge folder.", 0) end
				local wrote, why = fsx.write(file.path, file.body)
				if not wrote or fsx.read(file.path) ~= file.body then error("Could not verify " .. file.path .. ": " .. tostring(why), 0) end
			end
			return string.format("Saved %d files to %s/bridge. In your executor workspace, run: node %s/bridge/server.js", #files, fsx.root, fsx.root)
		end)
		M.busy = false
		if not ok then return false, tostring(result) end
		return true, result
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/caps
-- ==========================================================================
__UAI_MODULES["runtime/caps"] = (function()
-- What this host can actually do.
--
-- Every optional capability is probed exactly once, here, and the rest of the
-- project asks this module rather than testing for a global inline. That matters
-- for more than tidiness: the same script has to run under an executor with a
-- full filesystem, under one with only HTTP, and inside a plain client with
-- neither, and each of those has to degrade in a way the interface can explain
-- to the user instead of erroring.
return function(env)
	local M = {}

	local function callable(value)
		return type(value) == "function" and value or nil
	end

	-- Executors disagree on where the HTTP function lives. Order matters only in
	-- that the bare global is the modern spelling.
	local function findRequest()
		local candidates = {
			{ name = "request", fn = callable(request) },
			{ name = "http_request", fn = callable(http_request) },
			{ name = "syn.request", fn = type(syn) == "table" and callable(syn.request) or nil },
			{ name = "http.request", fn = type(http) == "table" and callable(http.request) or nil },
			{ name = "fluxus.request", fn = type(fluxus) == "table" and callable(fluxus.request) or nil },
		}
		for _, candidate in ipairs(candidates) do
			if candidate.fn then return candidate.fn, candidate.name end
		end
		return nil, nil
	end

	local function findClipboard()
		return callable(setclipboard)
			or callable(toclipboard)
			or (type(syn) == "table" and callable(syn.write_clipboard))
			or nil
	end

	local requestFn, requestName = findRequest()

	M.fn = {
		request = requestFn,
		readfile = callable(readfile),
		writefile = callable(writefile),
		appendfile = callable(appendfile),
		isfile = callable(isfile),
		isfolder = callable(isfolder),
		makefolder = callable(makefolder),
		listfiles = callable(listfiles),
		delfile = callable(delfile),
		delfolder = callable(delfolder),
		loadstring = callable(loadstring) or (callable(getgenv) and callable(getgenv().loadstring)) or nil,
		getgenv = callable(getgenv),
		gethui = callable(gethui),
		clipboard = findClipboard(),
		identify = callable(identifyexecutor) or callable(getexecutorname),
		websocket = (type(WebSocket) == "table" and callable(WebSocket.connect)) or nil,
		getconnections = callable(getconnections),
		hookmetamethod = callable(hookmetamethod),
		getnamecallmethod = callable(getnamecallmethod),
		hookfunction = callable(hookfunction),
		newcclosure = callable(newcclosure),
		checkcaller = callable(checkcaller),
		getcallingscript = callable(getcallingscript),
		firesignal = callable(firesignal),
		fireclickdetector = callable(fireclickdetector),
		firetouchinterest = callable(firetouchinterest),
		getnilinstances = callable(getnilinstances),
		getinstances = callable(getinstances),
		getscripts = callable(getscripts),
		decompile = callable(decompile),
		cloneref = callable(cloneref),
		queueTeleport = callable(queue_on_teleport),
		setfflag = callable(setfflag),
		customasset = callable(getcustomasset),
	}

	M.requestName = requestName

	-- HTTP -------------------------------------------------------------------
	-- The executor path is preferred for one specific reason: RequestAsync
	-- refuses to send a User-Agent (along with Cookie, Host and Content-Length),
	-- so it physically cannot carry the Claude Code identity. When that is the
	-- only transport available the client says so rather than silently sending
	-- Roblox's own agent string.
	if M.fn.request then
		M.http = "executor"
		M.uaSupported = true
	else
		local ok = pcall(function()
			return env.services.HttpService ~= nil
		end)
		M.http = ok and "roblox" or "none"
		M.uaSupported = false
	end

	M.fs = (M.fn.writefile ~= nil and M.fn.readfile ~= nil)
	M.exec = M.fn.loadstring ~= nil
	M.ws = M.fn.websocket ~= nil
	M.clipboard = M.fn.clipboard ~= nil
	M.hui = M.fn.gethui ~= nil
	M.hooks = M.fn.getconnections ~= nil
	M.remoteHooks = {
		namecall = { state = M.fn.hookmetamethod and M.fn.getnamecallmethod and "available_unverified" or "unavailable" },
		direct = { state = M.fn.hookfunction and "available_unverified" or "unavailable" },
		invokeOutcomes = { state = "available_unverified", reason = "Requires a yielding native backend fixture" },
	}
	M.sourceRead = M.fn.decompile ~= nil or M.fn.getscripts ~= nil

	M.executor = "unknown"
	if M.fn.identify then
		local ok, name = pcall(M.fn.identify)
		if ok and type(name) == "string" and name ~= "" then M.executor = name end
	end

	do
		local ok, isStudio = pcall(function() return env.services.RunService:IsStudio() end)
		M.studio = ok and isStudio or false
	end

	do
		local ok, tenFoot = pcall(function() return env.services.GuiService:IsTenFootInterface() end)
		M.console = ok and tenFoot or false
	end

	M.available = {
		http = M.http ~= "none",
		fs = M.fs,
		exec = M.exec,
		ws = M.ws,
		clipboard = M.clipboard,
		hooks = M.hooks,
		["ua"] = M.uaSupported,
	}

	-- Tools declare `needs = { "fs" }`; the registry checks the answer here
	-- before dispatch so an unavailable tool reports a clear reason to the model
	-- instead of erroring somewhere inside a nil call.
	function M.has(key)
		if key == "gravity" then return env.require("runtime/gravity").current() ~= nil end
		return M.available[key] == true
	end

	M.MISSING = {
		http = "no HTTP transport is available in this host",
		fs = "this host has no filesystem functions (writefile/readfile)",
		exec = "this host cannot compile code (loadstring is unavailable)",
		ws = "this host has no WebSocket support",
		clipboard = "this host has no clipboard function",
		hooks = "this host does not expose signal introspection (getconnections)",
		ua = "this host cannot set a custom User-Agent",
		gravity = "Project Gravity is not connected; run the updated Gravity loader and open its PROJECT UAI button",
	}

	function M.reason(key)
		return M.MISSING[key] or ("capability '" .. tostring(key) .. "' is unavailable")
	end

	function M.summary()
		local parts = {
			"transport " .. M.http .. (M.requestName and (" (" .. M.requestName .. ")") or ""),
			"ua " .. (M.uaSupported and "yes" or "no"),
			"fs " .. (M.fs and "yes" or "no"),
			"exec " .. (M.exec and "yes" or "no"),
		}
		if M.executor ~= "unknown" then table.insert(parts, 1, M.executor) end
		return table.concat(parts, " | ")
	end

	return M
end
end)()

