-- UAI is standalone, so nothing guarantees Infinite Yield is running when the
-- agent wants it. Two paths cover both cases, and both end in the same place:
-- a held reference to IY's `execCmd` and `cmds`.
--
--   1. Ambient. The user already ran IY; it left `execCmd` in the executor's
--      global table. Latching on costs nothing, so it is tried first.
--   2. Internal. UAI loads IY itself. The fetched source is run through
--      loadstring against a captured copy of the global table, so the
--      chunk-level globals IY writes (execCmd, cmds, PARENT -- it never
--      getgenv's them, they are just chunk globals in the executor env) land
--      in a table we hold a reference to, whatever the host calls its shared
--      environment.
--
-- Re-running IY's source while IY_LOADED is truthy is a no-op by IY's own
-- guard, so an internal load after an ambient detection cannot double it.
--
-- The GUI toggle is a mode, not a hide-after-load: "hidden" loads IY and then
-- parks its ScreenGui, "visible" leaves it exactly as IY drew it. Either way
-- the agent gets every command through the same execCmd.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")

	local SOURCE_URL = "https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source"

	-- How long the fetch-and-load may take before a caller gives up on it. IY's
	-- source is around a megabyte, and parsing it on a slow client is seconds
	-- rather than the tens the HTTP transport alone might suggest.
	local LOAD_TIMEOUT = 45

	local M = {
		-- "off" | "hidden" | "visible" -- what the user asked for in Settings.
		-- "off" is not stored state, it is the absence of a request.
		mode = nil,
		-- Set once an internal load has been attempted, successful or not, so a
		-- failed load is reported rather than retried by every tool call.
		loadTried = false,
		loadError = nil,
		-- How IY was obtained, once known: "ambient" or "internal".
		source = nil,
		-- IY's globals, captured. execCmd, cmds, prefix, IY_LOADED, PARENT.
		iy = nil,
		-- The environment an internal load ran against. Kept because a plugin
		-- loaded later through iy_plugin needs the same table.
		sandbox = nil,
	}

	local function genv()
		if caps.fn.getgenv then
			local ok, shared = pcall(caps.fn.getgenv)
			if ok and type(shared) == "table" then return shared end
		end
		return _G
	end

	-- Read one of IY's globals through whichever route can see it. The ambient
	-- route only: after an internal load we read through `sandbox` directly.
	-- Exposed on the module because the plugin store needs the same reach for
	-- IY's addPlugin/deletePlugin, and a second copy of the route would be a
	-- second thing to keep in step with the sandbox.
	local function ambient(name)
		local shared = genv()
		local value = rawget(shared, name)
		if value ~= nil then return value end
		-- Some hosts isolate chunks from the shared table; IY's globals then live
		-- nowhere UAI can name. That is the case the internal load exists for.
		return nil
	end

	M.ambient = ambient

	-- Tables such as binds and aliases are replaced by IY's own editors. Read the
	-- live environment instead of holding stale copies of their initial values.
	function M.environment()
		if M.sandbox then return M.sandbox end
		local fn = M.iy and M.iy.execCmd or ambient("execCmd")
		if type(fn) == "function" and getfenv then
			local ok, scope = pcall(getfenv, fn)
			if ok and type(scope) == "table" and rawget(scope, "execCmd") == fn then return scope end
		end
		return genv()
	end

	function M.value(name)
		local value = rawget(M.environment(), name)
		if value ~= nil then return value end
		if M.iy and M.iy[name] ~= nil then return M.iy[name] end
		return ambient(name)
	end

	function M.assign(name, value)
		rawset(M.environment(), name, value)
		if M.iy then M.iy[name] = value end
	end

	function M.getMode()
		local stored = config.get("iy.mode", "hidden")
		M.mode = (stored == "hidden" or stored == "visible") and stored or "off"
		return M.mode
	end

	function M.execFn()
		if M.iy then return M.iy.execCmd end
		local fn = ambient("execCmd")
		if type(fn) == "function" then return fn end
		return nil
	end

	function M.cmdsTable()
		local list = M.value("cmds")
		if type(list) == "table" then return list end
		return nil
	end

	-- Human-readable signatures, separate from the executable registry. Read the
	-- live environment so later plugin additions and replacement tables are seen.
	function M.descriptions()
		local list = M.value("CMDs")
		if type(list) == "table" then return list end
		return nil
	end

	function M.resolvePlayers(selector)
		local fn = M.value("getPlayer")
		if type(fn) ~= "function" then return nil, "this IY does not expose getPlayer" end
		local ok, names = pcall(fn, selector, env.plr)
		if not ok then return nil, tostring(names) end
		if type(names) ~= "table" then return nil, "getPlayer returned no list" end
		for _, name in ipairs(names) do
			if type(name) ~= "string" then return nil, "getPlayer returned an invalid player name" end
		end
		return names
	end

	function M.isLoaded()
		return type(M.execFn()) == "function"
	end

	-- One command through IY's dispatcher. The third argument of execCmd is
	-- `store` (history), not quiet -- passing true would push every agent call
	-- into the user's visible command history, so false.
	function M.exec(command)
		if M.getMode() == "off" then return false, "Infinite Yield integration is off in Settings" end
		local fn = M.execFn()
		if not fn then return false, "Infinite Yield is not loaded" end
		local speaker = env.plr
		local ok, err = pcall(fn, command, speaker, false)
		if not ok then return false, tostring(err) end
		return true, nil
	end

	-- Hide or show IY's own interface after a load.
	--
	-- IY parents everything under a randomly-named ScreenGui (its `PARENT`
	-- global) and remembers nothing about being hidden, so the reference has to
	-- be captured at load time -- after the load returns there is no way back to
	-- it. Setting Enabled keeps IY's loops, bindings and the command bar alive;
	-- only the pixels go away, which is the whole point: the agent keeps every
	-- command, the user keeps their screen.
	--
	-- The guard exists because IY flips this bit itself: its CaptureService
	-- handlers set PARENT.Enabled = false when a screenshot starts and back to
	-- true the moment it ends, so a hidden IY would resurface on the first
	-- screenshot the user takes. Enforcing the bit on change, rather than hiding
	-- children (which would also un-hide panels IY manages the visibility of
	-- itself), is the one intervention that cannot corrupt IY's own UI state.
	local guard = nil

	local function stopGuard()
		if guard then
			pcall(function() guard:Disconnect() end)
			guard = nil
		end
	end

	env.require("runtime/dispose").add(stopGuard, "iy.guard")

	function M.applyGui()
		local gui = M.value("PARENT")
		if not gui then return false, "IY's GUI reference was not captured" end
		if typeof and typeof(gui) ~= "Instance" then return false, "IY's GUI reference is not an Instance" end
		local hidden = (M.mode ~= "visible")
		stopGuard()
		local ok = pcall(function() gui.Enabled = not hidden end)
		if not ok then return false, "could not set the GUI's Enabled flag" end
		if hidden then
			local okConn, conn = pcall(function()
				return gui:GetPropertyChangedSignal("Enabled"):Connect(function()
					if M.mode ~= "visible" and gui.Enabled then gui.Enabled = false end
				end)
			end)
			if okConn then guard = conn end
		end
		return true, nil
	end

	-- Fetch, compile and run IY's source against a captured global table.
	--
	-- The sandbox is the live shared table with a metatable, not a copy: IY
	-- reaches for Roblox globals and its own earlier declarations constantly,
	-- and a frozen copy would make its `function execCmd` declarations local to
	-- a table nobody reads. __index falls through to the real environment; the
	-- chunk's own writes land in `holder`, which is what we keep.
	local function runInternal()
		local compile = caps.fn.loadstring
		if not compile then return nil, "this host cannot compile code (loadstring is unavailable)" end

		local holder = {}
		local sandbox = setmetatable(holder, { __index = genv() })
		-- IY loads plugins with loadfile. Bind those chunks to the same environment,
		-- so helpers and globals above a plugin's returned table remain available to
		-- every command without evaluating the plugin twice.
		if setfenv and caps.fn.readfile then
			sandbox.loadfile = function(path)
				local plugin, err = compile(caps.fn.readfile(path), tostring(path))
				if not plugin then error(err, 0) end
				setfenv(plugin, sandbox)
				return plugin
			end
		end

		-- The fetch goes through net/http rather than raw game:HttpGet so it is
		-- subject to the same transport fallback, identity and history the rest
		-- of the client's traffic is. Browser identity: raw.githubusercontent
		-- answers 403 to some CLI agent strings.
		local http = env.require("net/http")
		local res, err = http.send({
			url = SOURCE_URL,
			method = "GET",
			identity = "browser",
			tag = "iy",
			timeout = LOAD_TIMEOUT * 1000,
			attempts = 2,
		})
		if not res then return nil, "could not fetch the source: " .. tostring(err) end
		if res.status ~= 200 then
			return nil, string.format("the download answered HTTP %d", res.status)
		end
		local src = tostring(res.body or "")
		if #src < 10000 then return nil, "the download was too small to be Infinite Yield" end

		local fn, compileErr = compile(src, "infiniteyield")
		if not fn then return nil, "compile error: " .. tostring(compileErr) end

		-- setfenv where the host offers it, so the chunk's globals are the holder
		-- rather than the executor's shared table. Without setfenv (some hosts
		-- restrict it under identity sandboxing) the writes go to the real shared
		-- table instead, which is also fine: the ambient probe finds them there
		-- on the next look.
		local captured = setfenv and pcall(setfenv, fn, sandbox)

		local ok, runErr = pcall(fn)
		if not ok then return nil, "the source raised: " .. tostring(runErr) end

		-- Give task.spawn'ed init threads one scheduler round to declare
		-- themselves, then look for the dispatcher wherever it landed.
		clock.wait(0.5)
		local exec = rawget(holder, "execCmd") or ambient("execCmd")
		if type(exec) ~= "function" then
			return nil, "the source ran but exposed no execCmd -- IY may have refused to load here"
		end

		M.sandbox = captured and sandbox or nil
		-- prefix and PARENT carry the ambient fallback too: on a host without
		-- setfenv the chunk's globals land in the shared table instead of the
		-- holder, and cmds already looks there. addPlugin, deletePlugin and
		-- PluginsTable ride along for the plugin store -- they are chunk globals
		-- like the rest, written the same way.
		M.iy = {
			execCmd = exec,
			cmds = rawget(holder, "cmds") or ambient("cmds"),
			prefix = rawget(holder, "prefix") or ambient("prefix"),
			PARENT = rawget(holder, "PARENT") or ambient("PARENT"),
			addPlugin = rawget(holder, "addPlugin") or ambient("addPlugin"),
			deletePlugin = rawget(holder, "deletePlugin") or ambient("deletePlugin"),
			PluginsTable = rawget(holder, "PluginsTable") or ambient("PluginsTable"),
		}
		return true, nil
	end

	-- Bring IY up to the mode the user asked for. Cheap when it is already
	-- there: ambient first, then one internal load, then never again this
	-- session unless the caller forces a retry.
	function M.ensure()
		if M.getMode() == "off" then
			return false, "Infinite Yield integration is off in Settings"
		end
		if M.loading then
			local started = clock.ms()
			while M.loading and clock.since(started) < 120000 do clock.wait(0.1) end
			if M.loading then return false, "Infinite Yield is still loading" end
			if M.getMode() == "off" then return false, "Infinite Yield integration is off in Settings" end
		end
		if M.isLoaded() then
			if M.source == nil then M.source = "ambient" end
			-- The GUI follow only applies to a load UAI made; an ambient IY the
			-- user started themselves is theirs to see.
			if M.source == "internal" then
				local ok, err = M.applyGui()
				if not ok then log.warn("iy", "could not apply the GUI mode", err) end
			end
			return true, nil
		end
		if M.loadTried then
			return false, M.loadError or "an earlier load attempt failed"
		end
		M.loadTried = true
		M.loading = true
		local ran, ok, err = pcall(runInternal)
		M.loading = false
		if not ran then err, ok = ok, false end
		if not ok then
			M.loadError = err
			log.warn("iy", "internal load failed", err)
			return false, err
		end

		M.source = "internal"
		M.getMode()
		log.info("iy", "Infinite Yield loaded internally (" .. M.mode .. ")")
		local guiOk, guiErr = M.applyGui()
		if not guiOk then log.warn("iy", "GUI mode could not be applied", guiErr) end
		if M.mode == "off" then return false, "Infinite Yield integration was switched off while loading" end
		return true, nil
	end

	-- The settings toggle. Setting a mode does not load anything by itself --
	-- loading is one fetch of a megabyte and a GUI, and a settings row is not
	-- the place to spend that. The next tool call picks the mode up. What does
	-- happen immediately is the GUI following a load that already exists:
	-- switching Hidden to With GUI in Settings should show the interface now,
	-- not after the next command.
	function M.setMode(mode)
		if mode ~= "off" and mode ~= "hidden" and mode ~= "visible" then return false end
		M.mode = mode
		config.set("iy.mode", mode)
		if M.source == "internal" and M.isLoaded() then
			local ok, err = M.applyGui()
			if not ok then log.warn("iy", "could not apply the GUI mode", err) end
		end
		return true
	end

	function M.status()
		local rows = {}
		rows[#rows + 1] = { "Setting", config.get("iy.mode", "hidden") }
		if M.isLoaded() then
			rows[#rows + 1] = { "Loaded", "yes, via " .. (M.source or "ambient") }
			local cmds = M.cmdsTable()
			if type(cmds) == "table" then
				rows[#rows + 1] = { "Commands", tostring(#cmds) }
			end
			local prefix = M.value("prefix")
			if prefix then rows[#rows + 1] = { "Prefix", tostring(prefix) } end
			rows[#rows + 1] = { "Event editor", type(M.value("eventEditor")) == "table" and "available" or "not exposed by this IY" }
			local binds = M.value("binds")
			if type(binds) == "table" then rows[#rows + 1] = { "Keybinds", tostring(#binds) } end
			local plugins = M.value("PluginsTable")
			if type(plugins) == "table" then rows[#rows + 1] = { "Plugins", tostring(#plugins) } end
			if M.source == "internal" then
				rows[#rows + 1] = { "GUI", (M.mode == "visible") and "visible" or "hidden" }
			else
				rows[#rows + 1] = { "GUI", "the user's own -- not managed here" }
			end
		else
			rows[#rows + 1] = { "Loaded", "no" }
			if M.loadTried and M.loadError then
				rows[#rows + 1] = { "Last load", M.loadError }
			end
		end
		rows[#rows + 1] = { "Host can load it", caps.exec and "yes" or "no (no loadstring)" }
		return rows
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/iy_control
-- ==========================================================================
__UAI_MODULES["runtime/iy_control"] = (function()
-- Native IY configuration, using the event editor's SaveData/LoadData contract.
-- Source reviewed: EdgeIY/infiniteyield master/source, 2026-09-20. Event entries
-- are { command, ordered filters, delay }; player 0 means self and 1 means all.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local iy = env.require("runtime/iy")
	local M = {}

	local EVENTS = {
		{ name = "OnExecute", fields = {}, defaults = {} },
		{ name = "OnSpawn", fields = { "player" }, defaults = { 0 } },
		{ name = "OnDied", fields = { "player" }, defaults = { 0 } },
		{ name = "OnDamage", fields = { "player", "health_below" }, defaults = { 0, 0 } },
		{ name = "OnKilled", fields = { "player", "killer" }, defaults = { 0, 1 } },
		{ name = "OnJoin", fields = { "player" }, defaults = { 1 } },
		{ name = "OnLeave", fields = { "player" }, defaults = { 1 } },
		{ name = "OnChatted", fields = { "player", "message" }, defaults = { 1, 0 } },
	}
	local SETTINGS = {
		prefix = { global = "prefix", kind = "string" },
		keep_open = { global = "StayOpen", kind = "boolean" },
		keep_on_teleport = { global = "KeepInfYield", kind = "boolean" },
		chat_logs = { global = "logsEnabled", kind = "boolean" },
		join_logs = { global = "jLogsEnabled", kind = "boolean" },
		esp_transparency = { global = "espTransparency", kind = "number", min = 0, max = 1 },
	}
	local COMMAND_SETTINGS = { gui_scale = "guiscale", logs_webhook = "chatlogswebhook" }
	local function finite(value)
		return type(value) == "number" and value == value and value > -math.huge and value < math.huge
	end
	local function cancelled(ctx)
		return ctx and ctx.aborted and ctx.aborted()
	end
	local function refresh(fn)
		if type(fn) == "function" then
			local ok, err = pcall(fn)
			if not ok then return tostring(err) end
		end
	end
	local function persist(wanted)
		if wanted == false then return "session only" end
		if iy.value("nosaves") ~= false or not caps.fn.writefile then return "session only: IY saving is unavailable" end
		local save = iy.value("updatesaves")
		if type(save) ~= "function" then return "session only: IY's save function is unavailable" end
		local ok, err = pcall(save)
		-- updatesaves queues an asynchronous write; it does not acknowledge disk I/O.
		return ok and "save requested through IY" or ("live, but saving failed: " .. tostring(err))
	end
	local function changed(args, detail, warning)
		return { action = args.action, result = detail, persistence = persist(args.persist), warning = warning }
	end
	local function findCommand(name)
		for _, entry in ipairs(iy.cmdsTable() or {}) do
			if type(entry) == "table" and type(entry.NAME) == "string" then
				if entry.NAME:lower() == name then return entry end
				if type(entry.ALIAS) == "table" then
					for _, alias in ipairs(entry.ALIAS) do
						if type(alias) == "string" and alias:lower() == name then return entry end
					end
				end
			end
		end
	end
	local function named(value, label, maximum)
		if type(value) ~= "string" then return nil, label .. " must be a string" end
		value = util.trim(value)
		if value == "" or #value > maximum or value:find("%c") then
			return nil, label .. " must contain 1-" .. maximum .. " bytes without control characters"
		end
		return value
	end
	local function clearTable(list)
		for key in pairs(list) do list[key] = nil end
	end
	local function removeWhere(list, matches)
		local removed = 0
		for index = #list, 1, -1 do
			if matches(list[index]) then table.remove(list, index); removed = removed + 1 end
		end
		return removed
	end

	function M.command(value)
		if type(value) ~= "string" then return nil, "command must be a string" end
		local command = util.trim(value)
		local prefix = iy.value("prefix")
		if type(prefix) == "string" and prefix ~= "" and command:sub(1, #prefix) == prefix then
			command = util.trim(command:sub(#prefix + 1))
		elseif command:sub(1, 1) == ";" then command = util.trim(command:sub(2)) end
		if command == "" or #command > 4000 then return nil, "command must contain 1–4000 bytes" end
		return command
	end

	local function eventData()
		local editor = iy.value("eventEditor")
		if type(editor) ~= "table" or type(editor.SaveData) ~= "function" or type(editor.LoadData) ~= "function" then
			return nil, "this IY does not expose its event editor"
		end
		local ok, source = pcall(editor.SaveData)
		if not ok then return nil, "could not read IY events: " .. tostring(source) end
		local data, err = util.decode(source)
		if type(data) ~= "table" then return nil, "invalid IY event data: " .. tostring(err) end
		return data, nil, editor
	end
	local function eventSpec(name)
		for _, spec in ipairs(EVENTS) do
			if spec.name:lower() == tostring(name or ""):lower() then return spec end
		end
	end
	local function indexOf(value, list)
		return finite(value) and value == math.floor(value) and value >= 1 and value <= #list and value or nil
	end
	local function filtersFor(spec, values, previous)
		if values ~= nil and type(values) ~= "table" then return nil, "conditions must be an object" end
		local out, allowed = util.deepCopy(previous or spec.defaults), {}
		for index, field in ipairs(spec.fields) do
			allowed[field] = true
			local value = values and values[field]
			if value ~= nil then
				if field == "player" or field == "killer" then
					if type(value) ~= "string" or util.trim(value) == "" or #value > 200 then
						return nil, field .. " must be me, all, or an IY player selector"
					end
					value = util.trim(value)
					if value:lower() == "me" then value = 0 elseif value:lower() == "all" then value = 1 end
				elseif field == "health_below" then
					if not finite(value) or value < 0 then return nil, "health_below must be a nonnegative number (0 matches any health)" end
				elseif field == "message" then
					if type(value) ~= "string" or #value > 500 then return nil, "message must be a Lua pattern of at most 500 bytes" end
					local ok, err = pcall(string.find, "", value:lower())
					if not ok then return nil, "invalid message pattern: " .. tostring(err) end
					if value == "" then value = 0 end
				end
				out[index] = value
			end
		end
		for field in pairs(values or {}) do
			if not allowed[field] then return nil, spec.name .. " has no " .. tostring(field) .. " condition" end
		end
		return out
	end

	local function inspect(args)
		local out = { mode = iy.getMode() }
		local section = args.section or "all"
		if section ~= "all" and section ~= "events" and section ~= "keybinds" and section ~= "settings" and section ~= "aliases" and section ~= "waypoints" then
			return nil, "section must be all, events, keybinds, settings, aliases, or waypoints"
		end
		local limit = math.max(1, math.min(50, math.floor(tonumber(args.limit) or 25)))
		local offset = math.max(1, math.floor(tonumber(args.offset) or 1))
		if section == "all" or section == "events" then
			local data, err = eventData()
			if data then
				local bindings, total, definitions = {}, 0, {}
				for _, name in ipairs(util.keys(data, true)) do
					if type(name) == "string" and type(data[name]) == "table" then
						local spec = eventSpec(name)
						definitions[#definitions + 1] = { name = name, fields = spec and spec.fields,
							defaults = spec and spec.defaults, count = #data[name] }
						if not args.event or name:lower() == args.event:lower() then
							for index, binding in ipairs(data[name]) do
								total = total + 1
								if total >= offset and #bindings < limit then
									bindings[#bindings + 1] = { event = name, index = index, command = binding[1], filters = binding[2], delay = binding[3] or 0 }
								end
							end
						end
					end
				end
				out.events = { definitions = definitions, bindings = bindings, total = total,
					nextOffset = offset + #bindings <= total and offset + #bindings or nil }
			else out.events = { unavailable = err } end
		end
		if section == "all" or section == "keybinds" then
			local binds = iy.value("binds")
			if type(binds) == "table" then
				local items = {}
				for index = offset, math.min(#binds, offset + limit - 1) do
					local bind = binds[index]
					items[#items + 1] = { index = index, key = bind.KEY, command = bind.COMMAND, on_release = bind.ISKEYUP == true, toggle = bind.TOGGLE }
				end
				out.keybinds = { items = items, total = #binds, nextOffset = offset + #items <= #binds and offset + #items or nil }
			else out.keybinds = { unavailable = "IY's keybind table is not exposed" } end
		end
		if section == "all" or section == "aliases" then
			local aliases = iy.value("aliases")
			if type(aliases) == "table" then
				local items = {}
				for index = offset, math.min(#aliases, offset + limit - 1) do
					local entry, item = aliases[index], { index = index }
					if type(entry) == "table" and type(entry.CMD) == "string" and type(entry.ALIAS) == "string" then
						item.command, item.alias = entry.CMD, entry.ALIAS
					else item.malformed = "expected CMD and ALIAS strings" end
					items[#items + 1] = item
				end
				out.aliases = { items = items, total = #aliases, nextOffset = offset + #items <= #aliases and offset + #items or nil }
			else out.aliases = { unavailable = "IY's alias table is not exposed" } end
		end
		if section == "all" or section == "waypoints" then
			local waypoints, all = iy.value("WayPoints"), iy.value("AllWaypoints")
			if type(waypoints) == "table" then
				local items = {}
				for index = offset, math.min(#waypoints, offset + limit - 1) do
					local entry, item = waypoints[index], { index = index }
					local coord = type(entry) == "table" and entry.COORD
					if type(entry) == "table" and type(entry.NAME) == "string" and type(coord) == "table" and finite(coord[1]) and finite(coord[2]) and finite(coord[3]) then
						item.name, item.x, item.y, item.z = entry.NAME, coord[1], coord[2], coord[3]
					else item.malformed = "expected NAME and three finite COORD numbers" end
					items[#items + 1] = item
				end
				out.waypoints = { items = items, total = #waypoints, placeId = iy.value("PlaceId"),
					allPlacesTotal = type(all) == "table" and #all or nil,
					nextOffset = offset + #items <= #waypoints and offset + #items or nil }
			else out.waypoints = { unavailable = "IY's waypoint table is not exposed" } end
		end
		if section == "all" or section == "settings" then
			out.settings = {}
			for key, spec in pairs(SETTINGS) do out.settings[key] = iy.value(spec.global) end
			out.settings.gui_scale = iy.value("guiScale")
			out.settings.logs_webhook = iy.value("logsWebhook") or ""
			out.saving = iy.value("nosaves") == false and type(iy.value("updatesaves")) == "function"
		end
		return out
	end

	local function configure(args, ctx)
		if type(args.settings) ~= "table" or next(args.settings) == nil then return nil, "provide settings to change" end
		for key, value in pairs(args.settings) do
			local spec = SETTINGS[key]
			if key == "mode" then
				if value ~= "off" and value ~= "hidden" and value ~= "visible" then return nil, "invalid IY mode" end
			elseif COMMAND_SETTINGS[key] then
				if args.persist == false then return nil, key .. " uses an IY command that saves automatically; omit persist=false" end
				if key == "gui_scale" then
					if not finite(value) or value < 0.4 or value > 2 then return nil, "gui_scale must be between 0.4 and 2" end
				elseif type(value) ~= "string" or #value > 500 or (value ~= "" and (not value:match("^https?://[^/%s?#]+") or value:find("[%s%c\\]"))) then
					return nil, "logs_webhook must be an HTTP(S) URL without whitespace or backslashes, or empty to disable"
				end
			elseif not spec then return nil, "unknown IY setting: " .. tostring(key)
			elseif type(value) ~= spec.kind then return nil, key .. " must be " .. spec.kind
			elseif spec.kind == "number" and (not finite(value) or value < spec.min or value > spec.max) then
				return nil, key .. " is outside its supported range"
			elseif key == "prefix" and (#value < 1 or #value > 8 or value:find("%s")) then
				return nil, "prefix must be 1–8 characters without whitespace"
			end
		end
		local mode = args.settings.mode
		if mode and util.count(args.settings) == 1 then
			if cancelled(ctx) then return nil, "cancelled before changing IY" end
			iy.setMode(mode)
			return { action = args.action, settings = args.settings, persistence = "integration mode saved in UAI" }
		end
		if mode == "off" then return nil, "set IY settings before switching the integration off" end
		local ok, err = iy.ensure()
		if not ok then return nil, err end
		if cancelled(ctx) then return nil, "cancelled before changing IY" end
		for key in pairs(args.settings) do
			if COMMAND_SETTINGS[key] then
				if not findCommand(COMMAND_SETTINGS[key]) then return nil, "this IY does not expose command " .. COMMAND_SETTINGS[key] end
			elseif key ~= "mode" and type(iy.value(SETTINGS[key].global)) ~= SETTINGS[key].kind then
				return nil, "this IY does not expose setting " .. key
			end
		end
		local dispatched = {}
		for _, key in ipairs({ "gui_scale", "logs_webhook" }) do
			local value = args.settings[key]
			if value ~= nil then
				local command = COMMAND_SETTINGS[key] .. (value == "" and "" or (" " .. tostring(value)))
				local accepted, reason = iy.exec(command)
				if not accepted then
					return nil, "could not dispatch " .. key .. ": " .. tostring(reason)
						.. (#dispatched > 0 and "; earlier commands were accepted and may still apply" or "")
				end
				dispatched[#dispatched + 1] = command
			end
		end
		for key, value in pairs(args.settings) do
			if key == "mode" then iy.setMode(value)
			elseif not COMMAND_SETTINGS[key] then iy.assign(SETTINGS[key].global, value) end
		end
		-- Keep IY's own visible controls in sync with the live values.
		local function property(name, key, value)
			local instance = iy.value(name)
			if instance then pcall(function() instance[key] = value end) end
		end
		if args.settings.prefix then
			property("PrefixBox", "Text", args.settings.prefix)
			property("Cmdbar", "PlaceholderText", "Command Bar (" .. args.settings.prefix .. ")")
		end
		if args.settings.keep_open ~= nil then property("On", "BackgroundTransparency", args.settings.keep_open and 0 or 1) end
		if args.settings.chat_logs ~= nil then property("Toggle", "Text", args.settings.chat_logs and "Enabled" or "Disabled") end
		if args.settings.join_logs ~= nil then property("Toggle_2", "Text", args.settings.join_logs and "Enabled" or "Disabled") end
		local result = changed(args, args.settings, #dispatched > 0 and "IY applies the dispatched commands asynchronously and requests its own saves; inspect settings to confirm." or nil)
		if #dispatched > 0 then result.dispatched = dispatched end
		return result
	end

	function M.run(args, ctx)
		if args.action == "configure" then return configure(args, ctx) end
		local ok, err = iy.ensure()
		if not ok then return nil, err end
		if cancelled(ctx) then return nil, "cancelled before changing IY" end
		if args.action == "inspect" then return inspect(args) end
		if args.action == "stop_loops" then
			local accepted, reason = iy.exec("breakloops")
			if not accepted then return nil, reason end
			return { result = "Accepted breakloops; this stops IY repeat prefixes, not event bindings or individual commands' own loops." }
		end
		if tostring(args.action):sub(1, 6) == "event_" then
			local spec = eventSpec(args.event)
			if not spec then return nil, "choose a native IY event from inspect; custom events can be defined by an IY plugin" end
			local data, reason, editor = eventData()
			if not data then return nil, reason end
			local list = data[spec.name]
			if type(list) ~= "table" then return nil, spec.name .. " is not registered in this IY" end
			if args.action == "event_fire" then
				if type(editor.FireEvent) ~= "function" then return nil, "IY's event dispatcher is unavailable" end
				local values = args.arguments or {}
				if type(values) ~= "table" or not util.isArray(values) or #values ~= #spec.fields then
					return nil, "arguments must match the event fields in order: " .. table.concat(spec.fields, ", ")
				end
				for index, field in ipairs(spec.fields) do
					if field == "health_below" then
						if not finite(tonumber(values[index])) then return nil, "health argument must be a number" end
						values[index] = tonumber(values[index])
					elseif type(values[index]) ~= "string" then return nil, field .. " argument must be a string" end
				end
				local fired, fireErr = pcall(editor.FireEvent, spec.name, unpack(values))
				if not fired then return nil, "IY rejected the event: " .. tostring(fireErr) end
				return { result = "Accepted " .. spec.name .. "; matching commands run asynchronously." }
			end
			local index = indexOf(args.index, list)
			if args.action == "event_remove" then
				if not index then return nil, "binding index is out of range; inspect events again" end
				table.remove(list, index)
			elseif args.action == "event_clear" then data[spec.name] = {}
			elseif args.action == "event_add" or args.action == "event_update" then
				if args.action == "event_update" and not index then return nil, "binding index is out of range; inspect events again" end
				if args.action == "event_add" and #list >= 100 then return nil, "this event already has 100 bindings" end
				local previous = args.action == "event_update" and list[index] or nil
				local command, commandErr = M.command(args.command or (previous and previous[1]))
				if not command then return nil, commandErr end
				if command:lower():find("plugin", 1, true) then return nil, "IY ignores event commands containing 'plugin'; use the plugin tools to load plugins" end
				local filters, filterErr = filtersFor(spec, args.conditions, previous and previous[2])
				if not filters then return nil, filterErr end
				local delay = args.delay
				if delay == nil then delay = previous and previous[3] or 0 end
				if not finite(delay) or delay < 0 or delay > 3600 then return nil, "delay must be between 0 and 3600 seconds" end
				index = previous and index or #list + 1
				list[index] = { command, filters, delay }
			else return nil, "unknown event action" end
			local loaded, loadErr = pcall(editor.LoadData, util.encode(data))
			if not loaded then return nil, "IY could not apply the event data: " .. tostring(loadErr) end
			return changed(args, { event = spec.name, index = index, count = #data[spec.name] }, refresh(editor.Refresh))
		end
		if args.action == "keybind_add" or args.action == "keybind_remove" then
			local binds = iy.value("binds")
			if type(binds) ~= "table" then return nil, "IY's keybind table is unavailable" end
			local index
			if args.action == "keybind_remove" then
				index = indexOf(args.index, binds)
				if not index then return nil, "keybind index is out of range; inspect keybinds again" end
				local toggles = iy.value("toggleOn")
				if type(toggles) == "table" then toggles[binds[index]] = nil end
				table.remove(binds, index)
			else
				if #binds >= 100 then return nil, "IY already has 100 keybinds" end
				local key = tostring(args.key or ""):gsub("^Enum%.KeyCode%.", "")
				if key ~= "LeftClick" and key ~= "RightClick" then
					local valid, enum = pcall(function() return Enum.KeyCode[key] end)
					if not valid or not enum or key == "Unknown" then return nil, "key must be a Roblox KeyCode name, LeftClick, or RightClick" end
					key = tostring(enum)
				end
				local command, commandErr = M.command(args.command)
				if not command then return nil, commandErr end
				local toggle
				if args.toggle then
					toggle, commandErr = M.command(args.toggle)
					if not toggle then return nil, commandErr end
					if args.on_release then return nil, "toggle bindings run on key press, not release" end
				end
				for i, bind in ipairs(binds) do
					if bind.KEY == key and bind.COMMAND == command and bind.TOGGLE == toggle and (bind.ISKEYUP == true) == (args.on_release == true) then
						return { result = "Keybind already exists", index = i }
					end
				end
				index = #binds + 1
				binds[index] = { COMMAND = command, KEY = key, ISKEYUP = args.on_release == true, TOGGLE = toggle }
			end
			return changed(args, { index = index, count = #binds }, refresh(iy.value("refreshbinds")))
		end
		if args.action == "alias_add" or args.action == "alias_remove" or args.action == "alias_clear" then
			local aliases, custom = iy.value("aliases"), iy.value("customAlias")
			if type(aliases) ~= "table" or type(custom) ~= "table" then return nil, "IY's alias tables are unavailable" end
			local alias, command
			if args.action == "alias_clear" then
				clearTable(custom)
				clearTable(aliases)
			else
				alias, err = named(args.alias, "alias", 50)
				if not alias then return nil, err end
				alias = alias:lower()
				if args.action == "alias_add" then
					local prefix = iy.value("prefix")
					if alias:find("[%s\\%^]") or alias:find("^[;!]") or (type(prefix) == "string" and prefix ~= "" and alias:sub(1, #prefix) == prefix:lower()) then
						return nil, "alias must be one command token without an IY prefix, history/repeat marker, or command separator"
					end
					if custom[alias] ~= nil then return nil, "alias '" .. alias .. "' already exists" end
					for _, entry in ipairs(aliases) do
						if type(entry) == "table" and type(entry.ALIAS) == "string" and entry.ALIAS:lower() == alias then return nil, "alias '" .. alias .. "' already exists" end
					end
					if findCommand(alias) then return nil, "alias '" .. alias .. "' conflicts with an IY command" end
					command, err = M.command(args.command)
					if not command then return nil, err end
					command = command:match("^(%S+)"):lower()
					local entry = findCommand(command)
					if not entry then return nil, "no IY command named '" .. command .. "' to alias" end
					custom[alias] = entry
					aliases[#aliases + 1] = { CMD = command, ALIAS = alias }
				else
					if custom[alias] == nil then return nil, "no such alias: " .. alias end
					custom[alias] = nil
					removeWhere(aliases, function(entry) return type(entry) == "table" and type(entry.ALIAS) == "string" and entry.ALIAS:lower() == alias end)
				end
			end
			return changed(args, { alias = alias, command = command, count = #aliases }, refresh(iy.value("refreshaliases")))
		end
		if args.action == "waypoint_add" or args.action == "waypoint_remove" or args.action == "waypoint_clear" then
			local waypoints, all = iy.value("WayPoints"), iy.value("AllWaypoints")
			if type(waypoints) ~= "table" then return nil, "IY's waypoint table is unavailable" end
			local placeId = iy.value("PlaceId")
			if not finite(placeId) then placeId = 0 end
			local function inPlace(entry)
				return type(entry) == "table" and (entry.GAME == nil or entry.GAME == placeId)
			end
			local name
			if args.action ~= "waypoint_clear" then
				name, err = named(args.name, "name", 100)
				if not name then return nil, err end
			end
			local removed, savedRemoved
			if args.action == "waypoint_add" then
				-- IY's GUI inserts the name into loadpos/delete command strings.
				if name:find("\\", 1, true) then return nil, "waypoint names must not contain IY's backslash command separator" end
				local x, y, z
				if args.position ~= nil then
					if type(args.position) ~= "table" then return nil, "position must contain finite x, y, z numbers" end
					x, y, z = args.position.x, args.position.y, args.position.z
					if not finite(x) or not finite(y) or not finite(z) then return nil, "position must contain finite x, y, z numbers" end
				else
					local found
					found, x, y, z = pcall(function()
						local getRoot = iy.value("getRoot")
						if type(getRoot) ~= "function" then return end
						local root = getRoot(env.plr and env.plr.Character)
						local position = root and root.Position
						if position then return position.X, position.Y, position.Z end
					end)
					if not found or not finite(x) or not finite(y) or not finite(z) then return nil, "no position given and your character has no root part" end
				end
				if cancelled(ctx) then return nil, "cancelled before changing IY" end
				local entry = { NAME = name, COORD = { math.floor(x), math.floor(y), math.floor(z) }, GAME = placeId }
				waypoints[#waypoints + 1] = entry
				if type(all) == "table" and all ~= waypoints then all[#all + 1] = util.deepCopy(entry) end
			elseif args.action == "waypoint_remove" then
				local function matches(entry)
					return type(entry) == "table" and type(entry.NAME) == "string" and entry.NAME:lower() == name:lower()
				end
				removed = removeWhere(waypoints, matches)
				if type(all) == "table" and all ~= waypoints then
					savedRemoved = removeWhere(all, function(entry) return inPlace(entry) and matches(entry) end)
				end
				if removed + (savedRemoved or 0) == 0 then return nil, "no waypoint named '" .. name .. "' in this place" end
			else
				removed = #waypoints
				clearTable(waypoints)
				if type(all) == "table" and all ~= waypoints then
					if args.all_places == true then savedRemoved = #all; clearTable(all)
					else savedRemoved = removeWhere(all, inPlace) end
				end
			end
			return changed(args, { name = name, count = #waypoints, placeId = placeId, removed = removed, savedRemoved = savedRemoved,
				all_places = args.action == "waypoint_clear" and args.all_places == true or nil }, refresh(iy.value("refreshwaypoints")))
		end
		return nil, "unknown IY control action"
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/iy_plugins
-- ==========================================================================
__UAI_MODULES["runtime/iy_plugins"] = (function()
-- Author-owned IY plugins. The on-disk format is the ordinary IY plugin table;
-- top-level globals and shared locals are kept in the live IY environment.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local iy = env.require("runtime/iy")
	local M = {}
	local MAX_BYTES = 256000
	M.template = [=[-- Shared locals or globals may be declared above Plugin.
local count = 0

local Plugin = {
	["PluginName"] = "ExamplePlugin",
	["PluginDescription"] = "Two commands with shared state.",
	["Commands"] = {
		["example"] = {
			["ListName"] = "example / ex",
			["Description"] = "Prints a message to the console",
			["Aliases"] = {"ex"},
			["Function"] = function(args, speaker)
				count = count + 1
				print("Hello from ExamplePlugin!", count)
			end
		},
		["resetexample"] = {
			["ListName"] = "resetexample",
			["Description"] = "Resets the shared counter",
			["Aliases"] = {},
			["Function"] = function(args, speaker)
				count = 0
			end
		}
	}
}

return Plugin
]=]

	function M.filename(value)
		if type(value) ~= "string" then return nil, "plugin must be a plain .iy filename" end
		local name = util.trim(value)
		if name:lower():sub(-3) == ".iy" then name = name:sub(1, -4) end
		if #name < 1 or #name > 80 or not name:match("^[%w_%-]+$") then
			return nil, "use a plugin name containing only letters, numbers, underscores, or hyphens; no paths"
		end
		local lower = name:lower()
		if lower == "iy_fe" or lower == "con" or lower == "prn" or lower == "aux" or lower == "nul"
			or lower:match("^com%d$") or lower:match("^lpt%d$") then return nil, "that filename is reserved" end
		return name .. ".iy"
	end

	local function readExisting(name)
		local read = caps.fn.readfile
		if not read then return nil, "this host cannot read plugin files" end
		local present
		if caps.fn.isfile then
			local ok, result = pcall(caps.fn.isfile, name)
			if not ok then return nil, "could not check whether " .. name .. " exists" end
			present = result
			if not present then return nil end
		end
		local ok, source = pcall(read, name)
		if ok and type(source) == "string" then return source end
		if present then return nil, "could not read existing " .. name .. "; refusing to overwrite it" end
		if not caps.fn.isfile then return nil, "could not establish whether " .. name .. " exists (isfile is unavailable)" end
	end

	function M.read(name)
		local filename, err = M.filename(name)
		if not filename then return nil, err end
		local source, readErr = readExisting(filename)
		if not source then return nil, readErr or (filename .. " does not exist") end
		if #source > MAX_BYTES then return nil, "plugin is larger than 256 KB" end
		return source, nil, filename
	end

	local function validate(plugin)
		if type(plugin) ~= "table" then return nil, "plugin must return a Plugin table" end
		if type(plugin.PluginName) ~= "string" or util.trim(plugin.PluginName) == "" then return nil, "PluginName must be a nonempty string" end
		if type(plugin.PluginDescription) ~= "string" then return nil, "PluginDescription must be a string" end
		if type(plugin.Commands) ~= "table" or next(plugin.Commands) == nil then return nil, "Commands must contain at least one command" end
		local count, names = 0, {}
		for name, command in pairs(plugin.Commands) do
			count = count + 1
			if count > 100 then return nil, "a plugin may contain at most 100 commands" end
			if type(name) ~= "string" or not name:match("^[%w_%-]+$") then return nil, "command names must be single words" end
			if type(command) ~= "table" or type(command.Function) ~= "function" then return nil, name .. " needs a Function(args, speaker)" end
			if type(command.ListName) ~= "string" or type(command.Description) ~= "string" then return nil, name .. " needs ListName and Description strings" end
			if type(command.Aliases) ~= "table" or not util.isArray(command.Aliases) then return nil, name .. " needs an Aliases array (use {} for none)" end
			for _, alias in ipairs(command.Aliases) do
				if type(alias) ~= "string" or not alias:match("^[%w_%-]+$") then return nil, name .. " has an invalid alias" end
			end
			names[#names + 1] = name
		end
		table.sort(names)
		return names
	end
	local function registered(name)
		for _, plugin in ipairs(iy.value("PluginsTable") or {}) do if plugin == name then return true end end
		return false
	end
	local function commands(name)
		local out = {}
		for _, command in ipairs(iy.cmdsTable() or {}) do
			if command.PLUGIN == name then out[#out + 1] = command.NAME end
		end
		table.sort(out)
		return out
	end
	local function cancelled(ctx) return ctx and ctx.aborted and ctx.aborted() end

	local function write(args, ctx)
		local name, err = M.filename(args.plugin)
		if not name then return nil, err end
		if type(args.source) ~= "string" or #args.source == 0 or #args.source > MAX_BYTES then return nil, "source must contain 1–256000 bytes" end
		if not caps.fn.writefile or not caps.fn.loadstring then return nil, "plugin authoring needs writefile and loadstring" end
		local previous, readErr = readExisting(name)
		if readErr then return nil, readErr end
		if previous ~= nil and args.overwrite ~= true then return nil, name .. " exists; read it first and set overwrite=true to update it" end
		local compiled, chunk, compileErr = pcall(caps.fn.loadstring, args.source, "@" .. name)
		if not compiled or not chunk then return nil, "syntax error: " .. tostring(compiled and compileErr or chunk) end
		local load = args.load ~= false
		local add, remove, scope, fallback, wasRegistered
		if load then
			local ready, why = iy.ensure()
			if not ready then return nil, why end
			add, remove = iy.value("addPlugin"), iy.value("deletePlugin")
			if type(add) ~= "function" or type(iy.value("PluginsTable")) ~= "table" or type(iy.cmdsTable()) ~= "table" then
				return nil, "IY's plugin loader and registries must be exposed to verify a load"
			end
			wasRegistered = registered(name)
			if wasRegistered and type(remove) ~= "function" then return nil, "IY's plugin remover is unavailable; cannot reload this plugin" end
			scope = iy.environment()
			fallback = scope.loadfile
			if type(fallback) ~= "function" then return nil, "IY's loadfile is unavailable" end
			if not setfenv then return nil, "this host cannot bind plugin globals to IY (setfenv is unavailable); use load=false to save only" end
			local bound, why = pcall(setfenv, chunk, scope)
			if not bound then return nil, "could not bind plugin globals: " .. tostring(why) end
		end
		if cancelled(ctx) then return nil, "cancelled before writing the plugin" end
		local function restore()
			if previous ~= nil then
				local ok = pcall(caps.fn.writefile, name, previous)
				return ok and "Previous file restored." or "The previous file could not be restored."
			elseif caps.fn.delfile then
				local ok = pcall(caps.fn.delfile, name)
				return ok and "New file removed." or "The new file could not be removed."
			end
			return "The new file remains on disk."
		end
		local written, writeErr = pcall(caps.fn.writefile, name, args.source)
		if not written then return nil, "could not write " .. name .. ": " .. tostring(writeErr) .. ". " .. restore() end
		local verified, saved = pcall(caps.fn.readfile, name)
		if not verified or saved ~= args.source then return nil, "plugin write could not be verified. " .. restore() end
		if not load then return { plugin = name, bytes = #args.source, loaded = false, validation = "syntax checked; source was not executed" } end

		-- Evaluate once before removing existing commands. IY will consume this same
		-- returned table, preserving globals and closures without rerunning setup.
		local ran, plugin = pcall(chunk)
		if not ran then return nil, "plugin setup failed: " .. tostring(plugin) .. ". " .. restore() end
		local expected, invalid = validate(plugin)
		if not expected then return nil, "invalid plugin: " .. invalid .. ". " .. restore() end
		if cancelled(ctx) then return nil, "cancelled before registering the plugin. " .. restore() end
		local original = rawget(scope, "loadfile")
		rawset(scope, "loadfile", function(path, ...)
			if path == name then return function() return plugin end end
			return fallback(path, ...)
		end)
		local ok, loadErr = pcall(function()
			if wasRegistered then remove(name) end
			add(name)
		end)
		rawset(scope, "loadfile", original)
		local live = commands(name)
		if not ok or not registered(name) or #live ~= #expected then
			return nil, name .. " was saved, but IY did not register all commands: " .. tostring(loadErr or "check IY's plugin error")
		end
		return { plugin = name, name = plugin.PluginName, description = plugin.PluginDescription,
			bytes = #args.source, loaded = true, commands = live, validation = "syntax and plugin table checked" }
	end
	local writing = {}
	function M.write(args, ctx)
		local name, err = M.filename(args.plugin)
		if not name then return nil, err end
		local key = name:lower()
		if writing[key] then return nil, name .. " is already being updated; wait for that call to finish" end
		writing[key] = true
		local ok, result, reason = pcall(write, args, ctx)
		writing[key] = nil
		if not ok then return nil, "plugin authoring failed: " .. tostring(result) end
		return result, reason
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/iy_store
-- ==========================================================================
__UAI_MODULES["runtime/iy_store"] = (function()
-- The Infinite Yield plugin store, as a runtime.
--
-- iyplugins.pages.dev publishes a JSON index of community plugins -- several
-- hundred .iy files with names, authors and download paths. This module turns
-- that index into three operations -- search, install, uninstall -- and the
-- tools in tools/iy expose them to the agent. There is deliberately no store
-- UI: the catalog is browsed in conversation, by asking for what is wanted.
--
-- Install mechanics, matching what IY's own `plugin <name>` command does:
--   1. download the .iy source from the store,
--   2. write it into the executor's workspace ROOT by that name -- IY's
--      addPlugin reads `readfile(name)`, an executor-relative path, so the
--      file cannot live in UAI's own folder,
--   3. call IY's addPlugin(name), which loads the file and registers its
--      commands.
-- Uninstall is deletePlugin(name) plus delfile, in that order: unregister
-- first so nothing holds a reference to code that is about to disappear.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local iy = env.require("runtime/iy")

	local API_URL = "https://iyplugins.pages.dev/data/api.json"
	local SITE = "https://iyplugins.pages.dev/"
	local DOWNLOAD_TIMEOUT = 30
	local CATALOG_STALE_MS = 10 * 60 * 1000

	local M = {
		catalog = nil,
		catalogAt = 0,
		catalogError = nil,
	}

	local function httpGet(url, tag)
		local http = env.require("net/http")
		return http.send({
			url = url,
			method = "GET",
			identity = "browser",
			tag = tag,
			timeout = DOWNLOAD_TIMEOUT * 1000,
			attempts = 2,
		})
	end

	-- The index, fetched at most once every ten minutes. A search tool the
	-- model calls repeatedly in one turn must not re-download half a megabyte
	-- each time; a cache with no expiry would hide new plugins for a session.
	function M.fetchCatalog(force)
		if M.catalog and not force and (clock.ms() - M.catalogAt) < CATALOG_STALE_MS then
			return M.catalog, nil
		end
		local res, err = httpGet(API_URL, "iy-store")
		if not res then
			M.catalogError = err
			return nil, "could not reach the store: " .. tostring(err)
		end
		if res.status ~= 200 then
			M.catalogError = "HTTP " .. res.status
			return nil, "the store answered HTTP " .. res.status
		end
		local decoded, decodeErr = util.decode(res.body)
		if type(decoded) ~= "table" or type(decoded.plugins) ~= "table" then
			return nil, "the store's index is not the shape expected: " .. tostring(decodeErr)
		end
		M.catalog = decoded
		M.catalogAt = clock.ms()
		M.catalogError = nil
		return decoded, nil
	end

	-- The .iy entry of a store record. A submission may carry screenshots and
	-- videos alongside the plugin; `is_plugin` is the store's own flag for
	-- which file is the code.
	local function pluginFile(entry)
		for _, file in ipairs(type(entry.files) == "table" and entry.files or {}) do
			if type(file) == "table" and file.is_plugin ~= false then
				local name = tostring(file.filename or "")
				local url = tostring(file.url or "")
				if name ~= "" and url ~= "" then
					return { name = name, url = url, size = tonumber(file.size) }
				end
			end
		end
		return nil
	end

	-- Every entry that matches a query. Matches the name (strongest), the
	-- author, and the filename; a query that is an id matches exactly.
	function M.search(query, limit)
		local catalog, err = M.fetchCatalog()
		if not catalog then return nil, err end

		local needle = util.trim(tostring(query or "")):lower()
		local out = {}
		for _, entry in ipairs(catalog.plugins) do
			if type(entry) == "table" then
				local name = tostring(entry.name or "")
				local author = tostring(entry.author or "")
				local file = pluginFile(entry)
				local matched = false
				local score = 0
				if needle == "" then
					matched = true
				elseif tostring(entry.id or "") == needle then
					matched, score = true, 4
				elseif name:lower():find(needle, 1, true) then
					matched, score = true, 3
				elseif file and file.name:lower():find(needle, 1, true) then
					matched, score = true, 2
				elseif author:lower():find(needle, 1, true) then
					matched, score = true, 1
				end
				if matched then
					out[#out + 1] = {
						id = tostring(entry.id or ""),
						name = name,
						author = author,
						score = score,
						file = file,
					}
				end
			end
		end
		-- Stronger matches first, then alphabetical, so "dex" finds
		-- "dexrecontinued" ahead of "indexviewer".
		table.sort(out, function(a, b)
			if a.score ~= b.score then return a.score > b.score end
			return a.name:lower() < b.name:lower()
		end)
		if limit and limit > 0 then
			while #out > limit do table.remove(out) end
		end
		return out, nil
	end

	-- IY's plugin functions are chunk globals like everything else: present in
	-- the shared table after an ambient load, or in the holder after ours.
	local function iyFunction(name)
		return iy.value(name)
	end

	-- Download, write to the workspace root, register with IY.
	function M.install(plugin)
		local wanted = util.trim(tostring(plugin or ""))
		if wanted == "" then return false, "no plugin named" end

		local ready, reason = iy.ensure()
		if not ready then return false, reason end

		local results, err = M.search(wanted, 5)
		if not results then return false, err end
		if #results == 0 then
			return false, "nothing on the store matches '" .. wanted .. "'"
		end
		local entry = results[1]
		if #results > 1 and not (entry.name:lower() == wanted:lower()
			or entry.id == wanted
			or (entry.file and entry.file.name:lower() == wanted:lower() .. ".iy")) then
			local names = {}
			for index = 1, math.min(#results, 5) do
				names[#names + 1] = results[index].name
			end
			return false, "several plugins match; name one: " .. table.concat(names, ", ")
		end
		if not entry.file then
			return false, "'" .. entry.name .. "' has no .iy file on the store"
		end

		local write = caps.fn.writefile
		local read = caps.fn.readfile
		if not write or not read then
			return false, "this host has no filesystem functions, so a plugin cannot be saved"
		end

		-- Already on disk and registered: a re-install is a no-op, not an error.
		local registered = iyFunction("addPlugin")
		if type(registered) ~= "function" then
			return false, "IY is loaded but its plugin loader is not reachable"
		end
		local fileName = entry.file.name
		local okPresent = false
		local okRead = pcall(function()
			local existing = read(fileName)
			okPresent = type(existing) == "string" and #existing > 0
		end)
		if okRead and okPresent then
			return true, fileName .. " is already installed; load it with plugin " .. fileName:gsub("%.iy$", "")
		end

		local res, dlErr = httpGet(SITE .. entry.file.url, "iy-plugin")
		if not res then return false, "could not download it: " .. tostring(dlErr) end
		if res.status ~= 200 then
			return false, "the download answered HTTP " .. res.status
		end
		local source = tostring(res.body or "")
		if #source == 0 then return false, "the download was empty" end

		-- A size sanity check against the index: a body wildly larger than the
		-- catalogue's number is an error page or a redirect, not a plugin.
		if entry.file.size and #source > entry.file.size * 20 and #source > 50000 then
			log.warn("iy-store", "download was " .. #source .. " bytes, the index said " .. entry.file.size)
		end

		local okWrite = pcall(write, fileName, source)
		if not okWrite then return false, "could not write " .. fileName .. " to the workspace" end

		local okLoad, loadErr = pcall(registered, fileName)
		if not okLoad then
			pcall(function()
				if caps.fn.delfile then caps.fn.delfile(fileName) end
			end)
			return false, "saved, but IY could not load it: " .. tostring(loadErr)
		end

		log.info("iy-store", "installed " .. fileName .. " from the store")
		return true, fileName
	end

	-- Unregister from IY, then remove the file.
	function M.uninstall(plugin)
		if iy.getMode() == "off" then return false, "Infinite Yield integration is off in Settings" end
		local wanted = util.trim(tostring(plugin or "")):lower()
		if wanted == "" then return false, "no plugin named" end
		if wanted:sub(-3) ~= ".iy" then wanted = wanted .. ".iy" end

		local remover = iyFunction("deletePlugin")
		if type(remover) ~= "function" then
			return false, "IY is not loaded, so its plugin registry is not reachable"
		end

		local ok = pcall(remover, wanted)
		if not ok then return false, "IY could not remove " .. wanted end

		if caps.fn.delfile then
			pcall(caps.fn.delfile, wanted)
		end
		return true, wanted
	end

	-- What is on disk and registered right now. The registry side is read
	-- through IY's own PluginsTable when it is visible; otherwise the .iy files
	-- in the workspace root are the honest answer for what could be loaded.
	function M.listInstalled()
		local out = {}
		if iy.isLoaded() then
			local table_ = iyFunction("PluginsTable")
			if type(table_) == "table" then
				for _, name in ipairs(table_) do
					out[#out + 1] = tostring(name)
				end
			end
		end
		if caps.fn.listfiles then
			local ok, files = pcall(caps.fn.listfiles, "")
			if ok and type(files) == "table" then
				local seen = {}
				for _, name in ipairs(out) do seen[name] = true end
				for _, path in ipairs(files) do
					local clean = tostring(path):gsub("^%.?/", "")
					if clean:sub(-3) == ".iy" and not seen[clean] then
						out[#out + 1] = clean
					end
				end
			end
		end
		return out
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/legacy_values
-- ==========================================================================
__UAI_MODULES["runtime/legacy_values"] = (function()
-- Compatibility text codecs. Native snapshots use runtime/values.
return function(env)
	local util = env.require("runtime/util")
	local paths = env.require("runtime/instance_paths")
	local M = { resolve = paths.resolve, pathOf = paths.pathOf }
	-- Values -----------------------------------------------------------------

	-- Roblox value -> compact text a model can read and, importantly, feed back in.
	function M.show(value)
		local kind = typeof(value)
		if value == nil then return "nil" end
		if kind == "Vector3" then
			return string.format("%.2f, %.2f, %.2f", value.X, value.Y, value.Z)
		end
		if kind == "Vector2" then
			return string.format("%.2f, %.2f", value.X, value.Y)
		end
		if kind == "CFrame" then
			local p = value.Position
			return string.format("%.2f, %.2f, %.2f", p.X, p.Y, p.Z)
		end
		if kind == "Color3" then
			return string.format("%d, %d, %d",
				math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5))
		end
		if kind == "UDim2" then
			return string.format("%.3g, %d, %.3g, %d", value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset)
		end
		if kind == "UDim" then
			return string.format("%.3g, %d", value.Scale, value.Offset)
		end
		if kind == "NumberRange" then
			return string.format("%.3g..%.3g", value.Min, value.Max)
		end
		if kind == "EnumItem" then
			return "Enum." .. tostring(value.EnumType) .. "." .. tostring(value.Name)
		end
		if kind == "Instance" then
			return M.pathOf(value) .. " [" .. tostring(value.ClassName) .. "]"
		end
		if kind == "BrickColor" then return tostring(value.Name) end
		if kind == "number" then
			if value == math.floor(value) and math.abs(value) < 1e12 then return string.format("%d", value) end
			return string.format("%.4g", value)
		end
		if kind == "boolean" then return value and "true" or "false" end
		if kind == "string" then return value end
		if kind == "table" then return "{table}" end
		return tostring(value)
	end

	local function numbers(text, count)
		local out = {}
		for piece in tostring(text):gmatch("%-?%d+%.?%d*") do
			out[#out + 1] = tonumber(piece)
		end
		if count and #out < count then return nil end
		return out
	end

	-- Text (or a JSON object) -> a Roblox value of the same type as `current`.
	--
	-- Typing off the existing value is what makes one set_property tool work for
	-- both a Part's Vector3 Size and a Frame's UDim2 Size without the model having
	-- to know which it is looking at.
	function M.coerce(input, current)
		local wanted = typeof(current)
		if wanted == "string" then return tostring(input) end

		if type(input) == "table" and not (wanted == "table") then
			-- JSON object form: { x = 1, y = 2, z = 3 } or { r = 255, ... }.
			local parts = input
			if wanted == "Vector3" then
				return Vector3.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0, tonumber(parts.z or parts.Z) or 0)
			end
			if wanted == "Vector2" then
				return Vector2.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0)
			end
			if wanted == "Color3" then
				local r = tonumber(parts.r or parts.R) or 0
				local g = tonumber(parts.g or parts.G) or 0
				local b = tonumber(parts.b or parts.B) or 0
				if r <= 1 and g <= 1 and b <= 1 then return Color3.new(r, g, b) end
				return Color3.fromRGB(r, g, b)
			end
			if wanted == "UDim2" then
				return UDim2.new(
					tonumber(parts.xScale or parts.sx) or 0, tonumber(parts.xOffset or parts.ox) or 0,
					tonumber(parts.yScale or parts.sy) or 0, tonumber(parts.yOffset or parts.oy) or 0)
			end
			return nil, "cannot build a " .. tostring(wanted) .. " from an object"
		end

		local text = util.trim(input)

		if wanted == "number" then
			local value = tonumber(text)
			if not value or value ~= value or value == math.huge or value == -math.huge then
				return nil, "expected a finite number"
			end
			return value
		end
		if wanted == "boolean" then
			local lowered = text:lower()
			if lowered == "true" or lowered == "1" or lowered == "yes" then return true end
			if lowered == "false" or lowered == "0" or lowered == "no" then return false end
			return nil, "expected true or false"
		end
		if wanted == "Vector3" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers, e.g. '0, 10, 0'" end
			return Vector3.new(list[1], list[2], list[3])
		end
		if wanted == "Vector2" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers" end
			return Vector2.new(list[1], list[2])
		end
		if wanted == "CFrame" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers for a position" end
			return CFrame.new(list[1], list[2], list[3])
		end
		if wanted == "Color3" then
			local hex = text:match("^#?(%x%x%x%x%x%x)$")
			if hex then return Color3.fromHex(hex) end
			local list = numbers(text, 3)
			if not list then return nil, "expected 'r, g, b' or a hex colour" end
			if list[1] <= 1 and list[2] <= 1 and list[3] <= 1 then
				return Color3.new(list[1], list[2], list[3])
			end
			return Color3.fromRGB(list[1], list[2], list[3])
		end
		if wanted == "UDim2" then
			local list = numbers(text, 4)
			if not list then return nil, "expected four numbers: xScale, xOffset, yScale, yOffset" end
			return UDim2.new(list[1], list[2], list[3], list[4])
		end
		if wanted == "UDim" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers: scale, offset" end
			return UDim.new(list[1], list[2])
		end
		if wanted == "NumberRange" then
			local list = numbers(text, 1)
			if not list then return nil, "expected one or two numbers" end
			return NumberRange.new(list[1], list[2] or list[1])
		end
		if wanted == "EnumItem" then
			local enumType = tostring(current.EnumType)
			local wantedName = text:match("([%w_]+)$") or text
			local ok, items = pcall(function() return Enum[enumType]:GetEnumItems() end)
			if ok and type(items) == "table" then
				for _, item in ipairs(items) do
					if tostring(item.Name):lower() == wantedName:lower() then return item end
				end
				local names = {}
				for _, item in ipairs(items) do names[#names + 1] = item.Name end
				return nil, "expected one of: " .. table.concat(names, ", ")
			end
			return nil, "unknown enum " .. enumType
		end
		if wanted == "Instance" or current == nil then
			local instance, err = M.resolve(text)
			if instance then return instance end
			if current == nil then return text end
			return nil, err
		end
		if wanted == "BrickColor" then
			local ok, colour = pcall(function() return BrickColor.new(text) end)
			if ok then return colour end
			return nil, "unknown BrickColor"
		end
		return nil, "setting a " .. tostring(wanted) .. " is not supported"
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/log
-- ==========================================================================
__UAI_MODULES["runtime/log"] = (function()
-- Structured log with a bounded history.
--
-- Two audiences: the developer, who wants the last hundred lines including HTTP
-- detail, and the user, who occasionally needs to see why a provider rejected
-- them. Both read the same ring buffer through the Logs panel, so nothing is
-- printed to the console by default -- an in-game script that spams output is
-- indistinguishable from a broken one.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")

	local LIMIT = 400

	local M = {
		entries = {},
		changed = signal.new("log"),
		mirror = false,
		minLevel = 1,
	}

	local LEVELS = { debug = 1, info = 2, warn = 3, error = 4 }

	-- Published so a settings surface can set the floor by name rather than by
	-- guessing which integer "warn" is.
	M.LEVELS = LEVELS

	function M.setLevel(level)
		M.minLevel = LEVELS[tostring(level)] or 2
		return M.minLevel
	end

	-- An API key must never reach the buffer in full: the panel is screenshot and
	-- pasted into bug reports. Anything key-shaped keeps a four-character tail so
	-- a user can still tell two keys apart.
	local function redact(text)
		text = tostring(text)
		text = text:gsub("(sk%-[%w%-_]*)([%w%-_][%w%-_][%w%-_][%w%-_])", function(_, tail)
			return "sk-..." .. tail
		end)
		text = text:gsub("([Bb]earer%s+)[%w%.%-_]+([%w%.%-_][%w%.%-_][%w%.%-_][%w%.%-_])", "%1...%2")
		text = text:gsub('("api[_%-]?key"%s*:%s*")[^"]*([^"][^"][^"][^"])(")', "%1...%2%3")
		return text
	end
	M.redact = redact

	local function push(level, source, message, detail)
		if (LEVELS[level] or 2) < M.minLevel then return end
		local entry = {
			at = env.require("runtime/clock").ms(),
			stamp = env.require("runtime/clock").stamp(),
			level = level,
			source = tostring(source or "app"),
			message = redact(message),
			detail = detail ~= nil and redact(type(detail) == "table" and util.concatKeys(detail) or tostring(detail)) or nil,
		}
		M.entries[#M.entries + 1] = entry
		if #M.entries > LIMIT then
			-- Drop in blocks rather than one per push: table.remove(1) on a 400
			-- entry list on every log line is a copy each time.
			local kept = {}
			for index = math.floor(LIMIT * 0.25) + 1, #M.entries do kept[#kept + 1] = M.entries[index] end
			M.entries = kept
		end
		if M.mirror then
			local line = string.format("[uai:%s] %s: %s", entry.level, entry.source, entry.message)
			if level == "error" or level == "warn" then warn(line) else print(line) end
		end
		M.changed:fire(entry)
		return entry
	end

	function M.debug(source, message, detail) return push("debug", source, message, detail) end
	function M.info(source, message, detail) return push("info", source, message, detail) end
	function M.warn(source, message, detail) return push("warn", source, message, detail) end
	function M.error(source, message, detail) return push("error", source, message, detail) end

	function M.tail(count)
		local from = math.max(#M.entries - (count or 50) + 1, 1)
		return util.slice(M.entries, from, #M.entries)
	end

	function M.filter(level, text)
		local wanted = LEVELS[level] or 1
		local needle = text and text:lower() or nil
		local out = {}
		for _, entry in ipairs(M.entries) do
