			local char = code:sub(at, at)
			if char == "'" or char == '"' or char == "`" then
				at = skipQuoted(code, at)
			elseif code:sub(at, at + 1) == "--" then
				at = skipComment(code, at)
			elseif char == "[" and skipLong(code, at) then
				at = skipLong(code, at)
