					{ "Model", record and record.model or "-" },
					{ "Identity", ua.enabled() and ua.userAgent() or "client identity disabled" },
					{ "Transport", caps.http .. (caps.uaSupported and "" or " (cannot set User-Agent)") },
					{ "Permissions", permissions.mode() },
