			-- about to be added travels with the opening of its row.
			if name then view.run.pendingName = name end
			return view.run
		end

		local function closeRun()
			view.run = nil
		end

		-- Where a row belongs: inside the open block, or in the transcript itself.
		local function target()
			if view.run then return view.run.rows, view.run.slot() end
			return scroll.instance, nextOrder()
		end

		local function clearWorking()
			if view.working then
				pcall(function() view.working.root:Destroy() end)
				view.working = nil
			end
		end

		-- The working row is transient and always belongs at the end of the
		-- transcript, so it takes an order no real row will reach rather than the next
		-- sequential one. Otherwise a tool row created while it is up sorts below it
		-- and the indicator ends up stranded in the middle of the conversation.
		local WORKING_ORDER = 1e6

		local function ensureWorking()
			if not view.working then
				view.working = message.working(scroll.instance, WORKING_ORDER)
			end
			return view.working
		end

		-- Progressive reveal.
		--
		-- Adaptive pacing keeps replies fluid and alive: typing progresses smoothly
		-- by word boundaries with an accent typing indicator.
		local function stopReveal(complete)
			if not view.reveal then return end
			local reveal = view.reveal
			view.reveal = nil
			if reveal.stop then pcall(reveal.stop) end
			if complete and reveal.handle and reveal.text then
				pcall(function()
					reveal.handle.finish(reveal.text)
				end)
			end
		end

		local function revealAgent(text, animate)
			local isHarness = (env.require("runtime/caps").executor or ""):find("OfflineHarness") ~= nil
			-- Structured replies render once. Rebuilding a table or code viewport at
			-- every reveal tick creates layout jumps and repeatedly resets its scroll.
			local structured = false
			for _, block in ipairs(env.require("ui/markdown").blocks(text)) do
				if block.kind == "table" or block.kind == "code" then structured = true; break end
			end
			if not animate or responsive.reduceMotion or isHarness or structured then
				stopReveal(false)
				local handle = message.agent(scroll.instance, text, nextOrder(), view.model, props)
				view.agentHandle = handle
				follow()
				return handle
			end

			stopReveal(true)
			local handle = message.agent(scroll.instance, "", nextOrder(), view.model, props)
			view.agentHandle = handle

			local len = #text
			local targetDuration = util.clamp(0.4 + (len / 1200) * 0.7, 0.45, 1.25)
			local tickInterval = 0.03
			local totalTicks = math.max(12, math.floor(targetDuration / tickInterval))
			local charsPerTick = math.max(1, math.ceil(len / totalTicks))

			local shown = 0
			local reveal = {
				handle = handle,
				text = text,
			}
			view.reveal = reveal

			reveal.stop = clock.interval(tickInterval, function()
				shown = math.min(len, shown + charsPerTick)
				if shown < len then
					local nextSpace = text:find("%s", shown)
					if nextSpace and nextSpace <= shown + 6 then
						shown = nextSpace
					end
				end

				if shown >= len then
					stopReveal(false)
					handle.finish(text)
				else
					-- Reveal only complete UTF-8 characters, including emoji and CJK text.
					local boundary = shown
					while boundary > 0 do
						local byte = text:byte(boundary + 1)
						if not byte or byte < 128 or byte >= 192 then break end
						boundary = boundary - 1
					end
					handle.stream(text:sub(1, boundary))
				end
				follow()
			end)

			handle.root.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1
					or input.UserInputType == Enum.UserInputType.Touch then
					stopReveal(true)
				end
			end)

			follow()
			return handle
		end

		function view.empty()
			stopReveal(false)
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			scroll.clear()
			view.order = 0
			view.tools = {}
			view.agents = {}
			view.working = nil
			view.run = nil
			view.agentHandle = nil
			view.model = nil
			view.pinned = true
			latest.instance.Visible = false
		end


		-- What an empty conversation shows: the greeting, the activity card, and -- on a
		-- client with nothing configured yet -- the one thing to do about that. The card
		-- itself lives in ui/panels/home, which reads agent/stats.
		function view.greeting()
			local providers = env.require("provider/registry")
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			view.welcomeCard = env.require("ui/panels/home").card(scroll.instance, nextOrder(), props)
			scroll.instance.CanvasPosition = Vector2.new(0, 0)
			if mobile then
				local setup = P.button(view.welcomeCard, { name = "MobileSetup", text = "Connect a provider", icon = "sliders",
					variant = "secondary", layoutOrder = 5, onClick = function() env.require("ui/app").show("providers") end })
				setup.instance.Size = UDim2.new(1, 0, 0, responsive.minTarget())
				local function syncSetup() setup.instance.Visible = providers.count() == 0 end
				local unsubscribe = providers.changed:connect(syncSetup)
				setup.instance.Destroying:Connect(unsubscribe)
				syncSetup()
			elseif providers.count() == 0 then
				C.emptyState(view.welcomeCard, {
					title = "No provider configured",
					description = "Add an OpenAI-compatible endpoint to start. Anything that speaks /v1/chat/completions works: a hosted API, a relay, or a local server.",
					action = "Open providers",
					onAction = function()
						env.require("ui/app").show("providers")
					end,
					layoutOrder = 5,
				})
			end
		end

		-- One event in, one row out. Anything not listed is deliberately ignored:
		-- the log carries more than a transcript should show.
		function view.render(event)
			if event.kind == "user" then
				stopReveal(true)
				clearWorking()
				closeRun()
				if view.welcomeCard then
					pcall(function() view.welcomeCard:Destroy() end)
					view.welcomeCard = nil
				end
				view.agentHandle = nil
				message.user(scroll.instance, event.text, nextOrder(), props)
				view.pinned = true
				follow(true)
			elseif event.kind == "status" then
				if event.text and event.text ~= "Ready" then
					ensureWorking().set(event.text)
					follow()
				elseif event.text == "Ready" then
					clearWorking()
				end
			elseif event.kind == "request:start" then
				view.model = event.model or event.provider
				-- The entire HTTP round trip sits between this and request:done with no
				-- events in between, and it can run for the better part of a minute.
				-- Without a row here that whole wait looks like nothing is happening,
				-- which is the single largest gap in the turn.
				ensureWorking().set("Contacting " .. tostring(event.provider))
				follow()
			elseif event.kind == "assistant:reasoning" then
				if util.trim(event.text or "") == "" then return end
				local run = openRun()
				if run.thought then run.thought.append(event.text)
				else run.thought = message.reasoning(run.rows, event.text, run.slot()) end
				follow()
			elseif event.kind == "assistant:text" then
				local trimmed = util.trim(event.text or "")
				if trimmed ~= "" and trimmed ~= "..." and trimmed ~= "…" then
					stopReveal(true)
					clearWorking()
					closeRun()
					-- The reveal is for a reply that is landing now. A message replayed out
					-- of the log arrived long ago and goes up whole, or reopening a panel
					-- would re-type the entire conversation.
					revealAgent(event.text, view.replaying ~= true)
					follow()
				end
			elseif event.kind == "tool:call" then
				-- The working row deliberately survives a tool call: it is the "this
				-- turn is still running" indicator and it sorts last, so it stays put
				-- below the tool rows instead of being destroyed and rebuilt -- which
				-- restarted the spinner's phase and left the following request with no
				-- indicator at all.
				local run = openRun(event.name)
				run.thought = nil
				local handle = message.toolCall(run.rows, event, run.slot())
				handle.run = run
				run.opened()
				view.tools[event.id or util.uid("tool")] = handle
				follow()
			elseif event.kind == "tool:progress" then
				local handle = event.id and view.tools[event.id]
				-- Older hosts may emit unaddressed progress. It is only unambiguous
				-- when a single call is open; never copy it onto unrelated parallel work.
				if not event.id and util.count(view.tools) == 1 then
					local _, only = next(view.tools)
					handle = only
				end
				if handle and handle.progress then handle.progress(event.text) end
				follow()
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				local handle = view.tools[event.id]
				if handle then
					handle.finish(event)
					if handle.run then handle.run.closed(event.kind ~= "tool:error" and event.ok ~= false) end
					view.tools[event.id] = nil
				else
					local into, order = target()
					message.notice(into, {
						tone = event.kind == "tool:error" and "bad" or "info",
						text = string.format("%s: %s", tostring(event.name), util.ellipsis(event.text, 200)),
					}, order)
				end
				follow()
			elseif event.kind == "subagent:start" then
				-- Nested under the call that started it while that row is still tracked,
				-- so a delegated task reads as one block rather than as a card floating
				-- next to its own tool row. Standalone if the row is gone, which happens
				-- when the log has been trimmed past it.
				local host = event.call and view.tools[event.call] or nil
				if host and host.nest then
					view.agents[event.id] = message.subagent(host.nest(), event, 1, { nested = true })
				else
					local into, order = target()
					view.agents[event.id] = message.subagent(into, event, order, {})
				end
				follow()
			elseif event.kind == "subagent:status" then
				local handle = view.agents[event.id]
				if handle then handle.status(event) end
			elseif event.kind == "subagent:text" then
				local handle = view.agents[event.id]
				if handle then
					handle.say(event)
					follow()
				end
			elseif event.kind == "subagent:tool" then
				local handle = view.agents[event.id]
				if handle then
					handle.tool(event)
					follow()
				end
			elseif event.kind == "subagent:tool:done" then
				local handle = view.agents[event.id]
				if handle then handle.toolDone(event) end
			elseif event.kind == "subagent:done" then
				local handle = view.agents[event.id]
				if handle then
					handle.finish(event)
					view.agents[event.id] = nil
					follow()
				end
			elseif event.kind == "request:retry" then
				local into, order = target()
				message.notice(into, {
					tone = "warn",
					text = string.format("%s: %s, retrying in %.1fs (attempt %d of %d)",
						tostring(event.provider), tostring(event.reason), event.wait or 0,
						event.attempt or 1, event.attempts or 1),
				}, order)
				follow()
			elseif event.kind == "provider:switch" then
				local into, order = target()
				message.notice(into, {
					tone = "warn",
					text = string.format("%s failed, trying %s", tostring(event.from), tostring(event.to)),
				}, order)
				follow()
			elseif event.kind == "compact" then
				local into, order = target()
				local before, after = tonumber(event.before), tonumber(event.after)
				local text = "Older turns were summarised to stay inside the context budget."
				if before and after and before > after then
					text = string.format("Compacted context: about %s to %s tokens.",
						util.formatNumber(before), util.formatNumber(after))
				end
				message.notice(into, { tone = "info", text = text }, order)
				follow()
			elseif event.kind == "error" then
				stopReveal(true)
				clearWorking()
				closeRun()
				message.notice(scroll.instance, {
					tone = "bad",
					text = tostring(event.message),
				}, nextOrder())
				follow()
			elseif event.kind == "abort" then
				stopReveal(true)
				clearWorking()
				closeRun()
				message.notice(scroll.instance, { tone = "warn", text = "Stopped." }, nextOrder())
				follow()
			elseif event.kind == "cleared" then
				view.empty()
				view.greeting()
			end
		end

		-- Replays the session's own log, so opening the panel mid-turn shows what
		-- has happened rather than an empty pane.
		function view.attach(session)
			-- Re-showing the conversation that is already on screen must not tear the
			-- transcript down and replay every event again. On a long session that
			-- replay is hundreds of rows rebuilt from scratch on each open -- the lag
			-- when the window comes back -- and the half-built tree drawn over the old
			-- one for a frame is the overlap someone sees before it settles. Nothing
			-- changed, so the live view is already correct: just land at the bottom,
			-- the way `repin` does when the window is shown. The composer guards the
			-- same way on `draftId`.
			if session and view.session == session and view.unsubscribe then
				-- The transcript is already correct, but the working indicator is
				-- transient and not in the log, so a conversation that went busy while
				-- the panel was elsewhere has to have it restored here the same way a
				-- full replay would. Landing at the bottom is the rest of what a re-show
				-- owes the reader.
				if session.busy then
					ensureWorking().set(session.status or "Working")
				else
					clearWorking()
				end
				view.repin()
				return
			end
			if view.unsubscribe then
				view.unsubscribe()
				view.unsubscribe = nil
			end
			view.empty()
			view.session = session
			if not session then
				view.greeting()
				return
			end

			if #session.log == 0 then
				view.greeting()
			else
				view.replaying = true
				-- A restored conversation is replayed whole, and on a long one that is
				-- hundreds of rows built in one synchronous pass -- the freeze at the end
				-- of a boot, after the loader has already reached the interface. During
				-- the first mount the bootstrap sets this hook to yield the thread on a
				-- budget, so the replay renders in a few slices and the boot indicator
				-- keeps animating over it. Nil on every later attach, so switching a
				-- conversation by hand stays a single instant rebuild.
				local yield = env.onMountPhase
				local count = 0
				for _, event in ipairs(session.log) do
					local ok, err = pcall(view.render, event)
					if not ok then env.require("runtime/log").warn("ui", "replay failed", err) end
					count = count + 1
					if yield and count % 12 == 0 then yield("restoring your conversation") end
				end
				view.replaying = false
			end
			-- Anything still open after a replay is a call or a dispatch whose outcome is
			-- not in the log: trimmed away by the stored transcript's own ceiling, or lost
			-- because the turn died before it landed. On a live session those are genuinely
			-- in flight, so only a settled one is swept.
			if session.busy then
				ensureWorking().set(session.status or "Working")
			else
				clearWorking()
				closeRun()
				for id, handle in pairs(view.tools) do
					if handle.stale then pcall(handle.stale) end
					-- The block the row sits in is counting outstanding calls, and a row
					-- swept as stale is one it will never see a result for.
					if handle.run then pcall(handle.run.closed) end
					view.tools[id] = nil
				end
				for id, handle in pairs(view.agents) do
					if handle.stale then pcall(handle.stale) end
					view.agents[id] = nil
				end
			end

			view.unsubscribe = session.events:connect(function(event)
				local ok, err = pcall(view.render, event)
				if not ok then env.require("runtime/log").warn("ui", "render failed", err) end
			end)
			follow(true)
		end

		function view.destroy()
			stopReveal(false)
			pcall(function() latest.instance:Destroy() end)
			if view.unsubscribe then view.unsubscribe() end
			pcall(function() scroll.instance:Destroy() end)
		end

		return view
	end

	return M
end
end)()

-- ==========================================================================
-- ui/code/common
-- ==========================================================================
__UAI_MODULES["ui/code/common"] = (function()
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local overlay = env.require("ui/overlay")
	local caps = env.require("runtime/caps")
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local M = {}
	function M.inset() return math.max(8, theme.space.sm) end
	function M.gap() return math.max(4, theme.space.xs) end
	function M.controlHeight() return math.max(theme.size.controlSmall, responsive.minTarget(), theme.text.small.height + 12, theme.size.icon + 16) end
	function M.barHeight() return math.max(theme.size.codeToolbar, M.controlHeight() + 8) end
	local function buttonPadding(props) return math.max(8, props.padX or (props.tight and theme.space.sm or theme.space.md)) end
	function M.buttonWidth(label, props)
		props = props or {}
		if props.iconOnly or (props.icon and (not label or label == "")) then return M.controlHeight() end
		local width = P.measureText(label or "", { role = "small" }).X + buttonPadding(props) * 2 + 4
		if props.icon then width = width + theme.size.icon + theme.space.xs end
		if props.trailing then width = width + theme.size.icon + theme.space.xs end
		return math.max(props.minWidth or 0, M.controlHeight(), math.ceil(width))
	end
	function M.button(parent, props)
		props = util.copy(props or {}); props.size = props.size or "sm"; props.padX = buttonPadding(props)
		local button = P.button(parent, props)
		local size = button.instance.Size
		button.instance.Size = UDim2.new(size.X.Scale, size.X.Offset, 0, M.controlHeight())
		return button
	end
	-- Padded controls retain their hit targets. A crowded strip scrolls instead
	-- of removing a title's padding or overlapping the actions beside it.
	function M.toolbar(parent, options)
		options = options or {}
		local root = P.frame(parent, { name = options.name or "WorkspaceToolbar", size = UDim2.new(1, 0, 0, M.barHeight()), clip = true })
		local controls = P.scroll(root, { name = "ToolbarControls", horizontal = true, gap = 0, bar = 0 })
		controls.layout:Destroy(); controls.instance.AutomaticCanvasSize = Enum.AutomaticSize.None
		if options.divider ~= false then
			P.frame(root, { name = "ToolbarRule", size = UDim2.new(1, 0, 0, theme.stroke.hair),
				position = UDim2.new(0, 0, 1, -theme.stroke.hair), bg = theme.color.borderSubtle })
		end
		local buttons = {}
		local gap, padX = math.max(4, options.gap or M.gap()), math.max(8, options.padding or M.inset())
		local function widthOf(item) return M.buttonWidth(item.label, item) end
		local function place(item, x, w)
			local height = M.controlHeight()
			item.button.instance.Position = UDim2.fromOffset(math.floor(x), math.max(4, math.floor((root.AbsoluteSize.Y - height) / 2)))
			item.button.instance.Size = UDim2.fromOffset(math.max(1, math.floor(w)), height)
		end
		local layingOut = false
		local function layout()
			if layingOut then return end
			local width = root.AbsoluteSize.X
			if width <= 0 then return end
			layingOut = true
			local visibleButtons, widths, natural = {}, {}, padX * 2
			for _, item in ipairs(buttons) do
				if item.button.instance.Visible then
					visibleButtons[#visibleButtons + 1] = item
					widths[#visibleButtons] = widthOf(item); natural = natural + widths[#visibleButtons]
				end
			end
			natural = natural + math.max(0, #visibleButtons - 1) * gap
			for index, item in ipairs(visibleButtons) do
				if item.flex and natural > width then
					local minimum = buttonPadding(item) * 2 + 36 + (item.icon and theme.size.icon + theme.space.xs or 0) + (item.trailing and theme.size.icon + theme.space.xs or 0)
					local reduction = math.min(natural - width, math.max(0, widths[index] - minimum))
					widths[index], natural = widths[index] - reduction, natural - reduction
				end
			end
			local canvasWidth = math.max(width, natural)
			local split = #visibleButtons
			if natural <= width then for i, item in ipairs(visibleButtons) do if item.flex then split = i; break end end end
			local x = padX
			for i = 1, split do
				local item = visibleButtons[i]
				local w = widths[i]
				place(item, x, w)
				x = x + w + gap
			end
			local rx = canvasWidth - padX
			for i = #visibleButtons, split + 1, -1 do
				local w = widths[i]
				rx = rx - w
				place(visibleButtons[i], rx, w)
				rx = rx - gap
			end
			controls.instance.CanvasSize = UDim2.fromOffset(canvasWidth, 0)
			controls.instance.ScrollingEnabled = canvasWidth > width
			controls.instance.ScrollBarThickness = canvasWidth > width and 2 or 0
			controls.instance.CanvasPosition = Vector2.new(math.min(controls.instance.CanvasPosition.X, math.max(0, canvasWidth - width)), 0)
			layingOut = false
		end
		local bar = { root = root, controls = controls.instance, buttons = buttons, layout = layout }
		function bar.width()
			local width, count = padX * 2, 0
			for _, item in ipairs(buttons) do if item.button.instance.Visible then width = width + widthOf(item); count = count + 1 end end
			return width + math.max(0, count - 1) * gap
		end
		function bar.add(label, callback, props)
			props = props or {}
			local isDrop = props.flex or props.dropdown
			local trailing = props.trailing
			if isDrop and trailing == nil then trailing = "chevron" end
			local iconOnly = props.iconOnly or (props.icon and (label == "" or label == nil))
			local buttonText = iconOnly and "" or label
			local button = M.button(controls.instance, { text = buttonText, fill = true, size = "sm",
				variant = props.variant or (isDrop and "soft" or "ghost"),
				onClick = callback, name = props.name, enabled = props.enabled,
				icon = props.icon, padX = props.padX, align = isDrop and "Left" or props.align, trailing = trailing,
				trailingColor = isDrop and theme.color.textTertiary or props.trailingColor,
				tight = props.tight or iconOnly })
			local item = { button = button, label = buttonText, flex = props.flex, icon = props.icon,
				trailing = trailing, minWidth = props.minWidth, iconOnly = iconOnly, tight = props.tight,
				padX = buttonPadding(props) }
			buttons[#buttons + 1] = item
			local setText = button.setText
			button.setText = function(text)
				if not item.iconOnly then setText(text); item.label = tostring(text) end
				layout()
			end
			button.instance:GetPropertyChangedSignal("Visible"):Connect(layout)
			button.instance.SelectionGained:Connect(function()
				local at, width = button.instance.Position.X.Offset, button.instance.Size.X.Offset
				local left, viewport = controls.instance.CanvasPosition.X, root.AbsoluteSize.X
				if at < left + padX then left = math.max(0, at - padX)
				elseif at + width > left + viewport - padX then left = math.max(0, at + width + padX - viewport) end
				controls.instance.CanvasPosition = Vector2.new(left, 0)
			end)
			layout(); return button
		end
		root:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout)
		return bar
	end
	function M.clear(parent)
		for _, child in ipairs(parent:GetChildren()) do if not child:IsA("UIComponent") then child:Destroy() end end
	end
	function M.work(fn, completed)
		env.require("runtime/clock").spawn(function()
			local ok, result, why = pcall(fn)
			if not ok then M.message(nil, result)
			elseif M.message(result, why) and completed then completed(result) end
		end)
	end
	function M.message(result, why)
		if not result then overlay.toast(tostring(why or "Operation unavailable"), "bad", 6); return false end
		if type(result) == "table" and result.ok == false then overlay.toast(result.text or result.status, "warn", 6); return false end
		return true
	end
	function M.copy(text)
		if not caps.clipboard then overlay.code({ title = "Select and copy", text = text, code = text }); return end
		local ok, why = pcall(caps.fn.clipboard, text); if not ok then overlay.toast(tostring(why), "bad") end
	end
	function M.menu(target, title, options, onSelect)
		local anchor = target
		if type(target) == "table" and typeof(target) ~= "Instance" then anchor = target.instance or target end
		return overlay.menu({ target = anchor, title = title, options = options, onSelect = onSelect })
	end
	function M.choice(parent, label, choices, value, onChange, order)
		local button
		button = M.button(parent, { text = label .. ": " .. tostring(value), fill = true, size = "sm", layoutOrder = order, onClick = function()
			local options = {}; for _, item in ipairs(choices) do options[#options + 1] = { label = tostring(item), value = item, selected = item == value } end
			M.menu(button, label, options, function(selected) value = selected; button.setText(label .. ": " .. tostring(value)); onChange(value) end)
		end })
		return button
	end
	function M.virtualList(parent, options)
		return env.require("ui/code/list").new(parent, options)
	end
	function M.ask(reference)
		local app = env.require("ui/app"); app.show("chat")
		local composer = app.chatPanel and app.chatPanel.composer
		if composer and composer.field then
			local text = composer.field.get(); composer.field.set(text .. (text ~= "" and "\n" or "") .. reference)
		end
	end
	return M
end
end)()

