			for _, action in ipairs(store.actions()) do if action.name:lower():find(needle, 1, true) then items[#items + 1] = { kind = "action", id = action.id, label = "Action · " .. action.name .. " · " .. #action.inputs .. " inputs · r" .. action.revision } end end
