		local tint = colour or theme.color.textTertiary
		local frame, custom = customOrHolder(parent, size, "IconEllipsis", "ellipsis", tint)
		if custom then return frame end
		for index, offset in ipairs({ 0.2, 0.5, 0.8 }) do
