		function panel.setVisible(visible) panel.visible = visible; layout(); sync() end
		function panel.destroy()
			if not panel.alive then return end; panel.alive = false
			input:Disconnect(); offStore(); offStorage(); offRun(); offCapture(); fileDivider.destroy(); outputDivider.destroy()
			for _, view in pairs(views) do if view.destroy then view.destroy() end end
			store.saveNow(); root:Destroy()
		end
		panel.navigate, panel.views = navigate, views
		layout(); sync(); return panel
	end
	return M
end
end)()

-- ==========================================================================
-- ui/panels/cowork
-- ==========================================================================
__UAI_MODULES["ui/panels/cowork"] = (function()
-- Cowork: the browser-shared conversation.
--
-- The mode switch in the sidebar offers "Cowork" beside "Code", and in the client
-- this is modelled on that means real-time pairing. There is exactly one thing here
-- that genuinely is two people in one conversation -- the local web bridge -- so that
-- is what this panel is: its live state, its switch, and the two values it needs.
--
-- A Roblox client cannot accept a connection, so both sides dial out to a small
-- process on the same machine. That is why this panel is mostly about whether that
-- process is reachable, and why it says so in those words rather than showing a
-- spinner.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local bridge = env.require("net/bridge")
	local sessions = env.require("agent/session")

	local M = {}

	function M.new(parent)
		local panel = {}
		local scroll = P.scroll(parent, {
			name = "Cowork",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.lg,
			padding = theme.space.lg,
		})

		P.sectionHeader(scroll.instance, {
			title = "Cowork",
			description = "Share this conversation with a browser on the same machine. "
				.. "Run bridge/server.js, paste the token it prints, and whoever opens the page "
				.. "joins the conversation that is already open here -- a turn begun in one place "
				.. "continues in the other, and a permission prompt can be answered from either.",
			layoutOrder = 1,
		})

		M.rows(scroll.instance, { layoutOrder = 2 })

		panel.scroll = scroll
		return panel
	end

	-- The live state and the two values it needs, as cards a caller drops into its own
	-- column. Both the Cowork panel and the settings dialog's Cowork pane use this, so
	-- there is one description of the bridge rather than two that can disagree.
	function M.rows(container, props)
		props = props or {}
		local order = (props.layoutOrder or 1) - 1
		local function nextOrder()
			order = order + 1
			return order
		end

		local statusCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })

		local statusRow = P.row(statusCard, {
			name = "Status",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local dot = P.statusDot(statusRow, {
			diameter = theme.size.dot,
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		local statusText = P.text(statusRow, {
			name = "StatusText",
			text = "",
			role = "small",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 2,
		})

		local detail = P.text(statusCard, {
			name = "StatusDetail",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		detail.Size = UDim2.new(1, 0, 0, 0)

		-- Everything on this row is a fact about the running bridge rather than a
		-- control, which is why it is text and not a badge: three of the four values are
		-- only interesting when something is wrong.
		local function describe()
			local status = bridge.status()
			local shared = sessions.current()
			if not status.running then
				dot.BackgroundColor3 = theme.color.textTertiary
				statusText.Text = "Off. Nothing is listening and nothing is being polled."
				detail.Text = string.format("%s\nwould share: %s", status.url, shared.title)
				return
			end
			if status.online then
				dot.BackgroundColor3 = theme.color.success
				statusText.Text = "Connected. Open the link the bridge printed in a browser."
				detail.Text = string.format("%s\nsharing: %s\nqueued: %d", status.url, shared.title, status.queued or 0)
				return
			end
			dot.BackgroundColor3 = theme.color.warn
			statusText.Text = "Polling, but nothing answered yet. Is bridge/server.js running?"
			detail.Text = string.format("%s\n%s", status.url, tostring(status.error or "no answer yet"))
		end

		local switchRow = P.row(statusCard, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 3,
		})
		local switchText = P.column(switchRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(switchText, { text = "Enabled", role = "small" })
		P.text(switchText, {
			text = "Off until you turn it on: it is a second way in to an agent that can run code.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local toggle = C.switch(switchRow, {
			value = config.get("bridge.enabled", false) == true,
			onChange = function(value) config.set("bridge.enabled", value) end,
		})
		toggle.instance.LayoutOrder = 2

		if not caps.has("http") then
			local warning = P.text(statusCard, {
				text = "This host has no HTTP transport, so the bridge cannot be reached from here at all.",
				role = "caption",
				color = theme.color.warn,
				wrap = true,
				auto = "Y",
				layoutOrder = 4,
			})
			warning.Size = UDim2.new(1, 0, 0, 0)
		end

		-- Every row in here states its order.
		--
		-- All six were LayoutOrder 0, so the label above the port field, the field, the
		-- label above the token field, that field, the hint and the button row were sorted
		-- by whatever the tie-break happened to produce -- which is a card whose two
		-- labels can end up over the wrong two fields.
		local settings = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		local installerCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(installerCard, { text = "Bridge files", role = "label", layoutOrder = 1 })
		local installStatus = P.text(installerCard, { name = "BridgeDownloadStatus",
			text = "Download the bridge from GitHub into UAI/bridge in your executor workspace. Requires Node.js 18+ to run.",
			role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
		P.button(installerCard, { name = "DownloadBridge", text = "Download bridge files", icon = "folder",
			variant = "secondary", size = "sm", fill = true, layoutOrder = 3,
			onClick = function(button)
				button.setEnabled(false)
				button.setText("Downloading…")
				task.spawn(function()
					local ok, message = env.require("runtime/bridge_install").download(function(text)
						if installStatus.Parent then installStatus.Text = text end
					end)
					if not installerCard.Parent then return end
					installStatus.Text = message
					button.setText(ok and "Download again" or "Retry download")
					button.setEnabled(true)
					overlay.toast(ok and "Bridge files downloaded" or message, ok and "good" or "warn", 4)
				end)
			end })
		local runtimeCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(runtimeCard, { text = "Inference runtime", role = "label", layoutOrder = 1 })
		P.text(runtimeCard, { text = "Web mode runs provider connections in Node and streams to the browser. Tools, memory, permissions, and subagents stay in this Roblox client.",
			role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
		C.segmented(runtimeCard, { options = { { label = "Game", value = "game" }, { label = "Web", value = "web" } },
			value = config.get("bridge.runtime", "game"), layoutOrder = 3, onChange = function(value)
				local ok, err = pcall(env.require("net/bridge_commands").run, { type = "runtime", value = value })
				if not ok then overlay.toast(tostring(err), "warn", 3) end
			end })
		P.field(runtimeCard, { name = "BridgeRequestTimeout", text = tostring(config.get("bridge.requestTimeout", 180)),
			placeholder = "Provider timeout in seconds", layoutOrder = 4, onBlur = function(value)
				config.set("bridge.requestTimeout", util.clamp(tonumber(value) or 180, 10, 86400))
			end })
		P.text(settings, { text = "Port", role = "small", layoutOrder = 1 })
		P.field(settings, {
			name = "BridgePort",
			text = tostring(config.get("bridge.port", 8790)),
			placeholder = "8790",
			layoutOrder = 2,
			onBlur = function(text)
				local port = tonumber(util.trim(text))
				config.set("bridge.port", (port and port > 0 and port < 65536) and math.floor(port) or 8790)
			end,
		})
		P.text(settings, { text = "Token", role = "small", layoutOrder = 3 })
		P.field(settings, {
			name = "BridgeToken",
			text = tostring(config.get("bridge.token", "")),
			placeholder = "paste from the bridge console",
			layoutOrder = 4,
			onBlur = function(text) config.set("bridge.token", util.trim(text)) end,
		})
		local tokenHint = P.text(settings, {
			text = "The token is regenerated every time bridge/server.js starts, so a stale one left here grants nothing.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 5,
		})
		tokenHint.Size = UDim2.new(1, 0, 0, 0)

		local buttons = P.row(settings, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.sm,
			layoutOrder = 6,
		})
		if caps.clipboard then
			P.button(buttons, {
				name = "CopyBridgeUrl",
				text = "Copy address",
				variant = "secondary",
				size = "sm",
				layoutOrder = 1,
				onClick = function()
					local ok = pcall(caps.fn.clipboard, bridge.status().url)
					overlay.toast(ok and "Address copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			})
		end
		P.button(buttons, {
			name = "Reconnect",
			text = "Reconnect",
			variant = "ghost",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				-- Stop then sync: the poller backs off up to ten seconds between
				-- attempts, and after starting the server on the other side nobody wants
				-- to wait out the backoff.
				bridge.stop()
				local ok, why = bridge.sync()
				if not ok and why then overlay.toast(tostring(why), "warn", 3) end
				describe()
			end,
		})

		describe()
		local unsubscribeConfig = config.changed:connect(function(path)
			if path == nil or path == "bridge" or path == "bridge.enabled" then
				toggle.set(config.get("bridge.enabled", false) == true, true)
			end
		end)
		local unsubscribeBridge = bridge.changed:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		statusCard.Destroying:Connect(function()
			pcall(unsubscribeBridge)
			pcall(unsubscribeSessions)
			pcall(unsubscribeConfig)
		end)

		return statusCard
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/home
-- ==========================================================================
__UAI_MODULES["ui/panels/home"] = (function()
-- The home card: the greeting, the activity summary and the contribution grid.
--
-- Every number on this surface is read from agent/stats, which counts what the
-- client actually observed. There are no placeholders here and no sample data: a
-- figure with nothing behind it is rendered as a zero and the card says why, because
-- an invented number on a dashboard is worse than an empty one -- it cannot be told
-- from a real one.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local stats = env.require("agent/stats")

	local M = {}

	-- How much of the grid fits. Twenty-six weeks is six months and is what the card
	-- is designed around, but a cell is a fixed eleven pixels and the card is only as
	-- wide as the window: at 340 the full grid is seventy pixels wider than the space
	-- it has, and a grid that overflows is clipped rather than scaled.
	local function heatmapWeeks()
		if responsive.mode == "sheet" then return 13 end
		if responsive.mode == "panel" then return 18 end
		return 26
	end

	-- Four tiles to a row on anything with room, two on a phone. Eight tiles of a
	-- quarter width each on a 276px card leaves 53px for "Longest streak".
	local function tilesPerRow()
		if responsive.mode == "sheet" or responsive.mode == "panel" then return 2 end
		return 4
	end

	local function levelColour(level)
		if level >= 4 then return theme.color.activityBlueDark end
		if level >= 3 then return theme.color.activityBlue end
		if level >= 2 then return theme.color.activityBlueLight end
		if level >= 1 then return theme.color.accentMuted end
		return theme.color.activityCell
	end

	-- The four sentences a cell can say, all of them about a real day.
	local function describeCell(cell, todayKey)
		local when = clock.describeDay(cell.key, todayKey)
		if not cell.active then
			return when .. " -- nothing recorded", "info"
		end
		local parts = {}
		if cell.messages > 0 then parts[#parts + 1] = util.pluralise(cell.messages, "message") end
		if cell.requests > 0 then parts[#parts + 1] = util.pluralise(cell.requests, "request") end
		if cell.tokens > 0 then parts[#parts + 1] = util.formatCompact(cell.tokens) .. " tokens" end
		return when .. " -- " .. table.concat(parts, ", "), "good"
	end

	-- One metric. The tile shows the short form; the exact figure and what it counts
	-- live in the Usage pane, which is where the click goes.
	local function tile(parent, spec, order, perRow)
		local holder = P.rowButton(parent, {
			name = "Metric_" .. tostring(spec.key),
			vertical = true,
			-- The gap is shared out across the tiles rather than subtracted whole from
			-- each: n children of (W/n - g) plus (n-1) gaps comes to W - g, so the row
			-- stopped a gap short of the well it sits in and the right edge never lined up
			-- with the card above it. The share is (n-1)/n of one gap per tile.
			size = UDim2.new(1 / (perRow or 4),
				-math.floor(theme.space.hair * ((perRow or 4) - 1) / (perRow or 4)),
				0, theme.size.statTile),
			height = theme.size.statTile,
			bg = theme.color.surfaceRaised,
			radius = theme.radius.none,
			gap = theme.space.hair,
			padding = { x = theme.space.sm, y = theme.space.xs },
			alignY = "Center",
			layoutOrder = order,
			onClick = function()
				env.require("ui/app").showSettingsDialog("usage")
			end,
		})
		P.text(holder.row, {
			name = "Title",
			text = spec.label,
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.caption.height),
			layoutOrder = 1,
		})
		P.text(holder.row, {
			name = "Value",
			text = spec.value,
			role = "title",
			color = spec.tone or theme.color.text,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.title.height),
			layoutOrder = 2,
		})
		return holder
	end

	-- A small pill that is either the selected one or not. Used for both the tab pair
	-- and the range triple, because they are the same control with different contents.
	local function pill(parent, label, selected, order, onClick)
		local handle = P.rowButton(parent, {
			name = "Pill_" .. tostring(label),
			auto = "X",
			height = math.max(theme.size.chip, responsive.minTarget()),
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			bgSelected = theme.color.surfaceActive,
			radius = theme.radius.sm,
			padding = { x = theme.space.sm },
			selected = selected,
			onClick = onClick,
		})
		P.text(handle.row, {
			text = label,
			role = "caption",
			color = selected and theme.color.text or theme.color.textTertiary,
			auto = "X",
			layoutOrder = 1,
		})
		return handle
	end

	-- The eight figures the overview shows, in the order the reference client puts
	-- them in. Each one names the window it was computed over, because "4 active days"
	-- means something different under All than under 7d.
	local function overviewTiles(window)
		local model = window.topModel
		local modelName = "--"
		if model then modelName = model.id end
		local peak = "--"
		if window.peakHour then peak = clock.describeHour(window.peakHour) end
		return {
			{ key = "sessions", label = "Sessions", value = util.formatNumber(window.sessions) },
			{ key = "messages", label = "Messages", value = util.formatNumber(window.messages) },
			{ key = "tokens", label = "Total tokens", value = util.formatCompact(window.tokens) },
			{ key = "days", label = "Active days", value = util.formatNumber(window.activeDays) },
			{ key = "streak", label = "Current streak", value = tostring(window.currentStreak) .. "d" },
			{ key = "longest", label = "Longest streak", value = tostring(window.longestStreak) .. "d" },
			{ key = "peak", label = "Peak hour", value = peak },
			{ key = "model", label = "Favorite model", value = modelName },
		}
	end

	local function buildOverview(parent, window)
		local box = P.column(parent, {
			name = "MetricsBox",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.hair,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		local specs = overviewTiles(window)
		local perRow = tilesPerRow()
		local rows = math.ceil(#specs / perRow)
		for rowIndex = 1, rows do
			local row = P.row(box, {
				name = "MetricRow" .. tostring(rowIndex),
				size = UDim2.new(1, 0, 0, theme.size.statTile),
				gap = theme.space.hair,
				layoutOrder = rowIndex,
			})
			for column = 1, perRow do
				local spec = specs[(rowIndex - 1) * perRow + column]
				if spec then tile(row, spec, column, perRow) end
			end
		end
		return box
	end

	local function buildModels(parent, window)
		local box = P.column(parent, {
			name = "ModelsBox",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.hair,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		if #window.models == 0 then
			local empty = P.text(box, {
				name = "NoModels",
				text = "No requests recorded in this window. A model appears here once it has answered something.",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				padding = { x = theme.space.sm, y = theme.space.sm },
				layoutOrder = 1,
			})
			empty.Size = UDim2.new(1, 0, 0, 0)
			return box
		end

		for index, row in ipairs(window.models) do
			local entry = P.column(box, {
				name = "Model_" .. tostring(index),
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.surfaceRaised,
				gap = theme.space.hair,
				padding = { x = theme.space.sm, y = theme.space.xs },
				layoutOrder = index,
			})
			local head = P.row(entry, {
				size = UDim2.new(1, 0, 0, theme.text.small.height),
				gap = theme.space.xs,
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Id",
				text = row.id,
				role = "small",
				color = theme.color.text,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.small.height),
				flex = "Fill",
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Share",
				text = string.format("%d%%", math.floor((row.share or 0) * 100 + 0.5)),
				role = "monoSmall",
				color = theme.color.accent,
				align = "Right",
				auto = "X",
				layoutOrder = 2,
			})

			local track = P.frame(entry, {
				name = "Bar",
				size = UDim2.new(1, 0, 0, theme.size.track),
				bg = theme.color.surfaceActive,
				radius = theme.radius.pill,
				layoutOrder = 2,
			})
			P.frame(track, {
				name = "Fill",
				size = UDim2.fromScale(util.clamp(row.share or 0, 0, 1), 1),
				bg = theme.color.accent,
				radius = theme.radius.pill,
			})

			local facts = { util.formatCompact(row.tokens) .. " tokens",
				util.pluralise(row.requests, "request") }
			local cost = env.require("agent/usage").formatCost(row.cost)
			if cost ~= "" then facts[#facts + 1] = cost end
			local detail = P.text(entry, {
				name = "Detail",
				text = table.concat(facts, "  ") .. (window.estimated and "  (some estimated)" or ""),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(1, 0, 0, theme.text.caption.height),
				layoutOrder = 3,
			})
			detail.Name = "Detail"
		end
		return box
	end

	local function buildHeatmap(parent, order)
		local map = stats.heatmap(heatmapWeeks())
		local todayKey = clock.dayKey()
		local holder = P.column(parent, {
			name = "Heatmap",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.sm,
			gap = theme.space.hair,
			layoutOrder = order,
		})
		P.stroke(holder, theme.color.borderSubtle)

		-- Rows are weekdays and columns are weeks, which is the arrangement that makes
		-- a habit visible: a column is a week of work, a row is "every Tuesday".
		for weekday = 1, 7 do
			local row = P.row(holder, {
				name = "Week_" .. clock.weekdayName(weekday),
				size = UDim2.new(1, 0, 0, theme.size.cell),
				maxSize = Vector2.new(#map.columns * theme.size.cell + (#map.columns - 1) * theme.space.hair, math.huge),
				gap = theme.space.hair,
				layoutOrder = weekday,
			})
			for column = 1, #map.columns do
				local cell = map.columns[column][weekday]
				local button = P.rowButton(row, {
					name = "Cell_" .. cell.key,
					size = UDim2.fromOffset(theme.size.cell, theme.size.cell),
					height = theme.size.cell,
					bg = cell.future and theme.color.surfaceOverlay or levelColour(cell.level),
					bgHover = theme.color.solid,
					radius = theme.radius.xs,
					padding = theme.space.none,
					layoutOrder = column,
					onClick = function()
						if cell.future then
							overlay.toast(clock.describeDay(cell.key, todayKey) .. " -- not yet", "info", 2)
							return
						end
						local text, tone = describeCell(cell, todayKey)
						overlay.toast(text, tone, 2.5)
					end,
				})
				-- A cell is eleven pixels square: the hit-target floor would make it a
				-- button the size of the whole row, so this one control opts out and the
				-- grid stays a grid.
				button.instance.Size = UDim2.new(1 / #map.columns,
				-theme.space.hair * (#map.columns - 1) / #map.columns, 0, theme.size.cell)
			end
		end
		return holder
	end

	-- The card, and the greeting above it. `order` is the layout order inside whatever
	-- column it is being dropped into -- the transcript, in practice.
	function M.card(parent, order, props)
		props = props or {}
		local mobile = responsive.isMobile()
		local name = "there"
		local okName, display = pcall(function()
			return env.plr and env.plr.DisplayName
		end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			name = display
		elseif env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			name = env.plr.Name
		end

		local holder = P.column(parent, {
			name = "Home",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = mobile and theme.space.sm or theme.space.xl,
			padding = { top = mobile and theme.space.xxs or theme.space.xxl,
				bottom = mobile and theme.space.sm or theme.space.lg },
			layoutOrder = order,
		})

		local greeting = P.column(holder, {
			name = "Greeting",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = mobile and theme.space.xxs or theme.space.md,
			layoutOrder = 1,
		})
		local brandSlot = P.frame(greeting, {
			name = "HomeBrand",
			size = UDim2.fromOffset(theme.size.controlLarge, theme.size.controlLarge),
			visible = not mobile,
			layoutOrder = 1,
		})
		icons.brand(brandSlot, theme.size.controlLarge)
		P.text(greeting, {
			name = "GreetingText",
			text = mobile and "What will we create?" or string.format("What will we create, %s?", name),
			role = mobile and "title" or "display",
			color = theme.color.text,
			align = "Center",
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})

		local subtitle = P.text(greeting, {
			name = "GreetingSubtitle", text = "Your ideas. Your game. An agent to help make it happen.",
			role = "small", color = theme.color.textTertiary, align = "Center", wrap = true,
			auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 3,
		})
		subtitle.Visible = not mobile
		if props.onInsert then
			local grid = P.frame(holder, {
				name = "PromptStarters", size = UDim2.new(1, 0, 0, 0),
				maxSize = Vector2.new(theme.size.statCard, math.huge), layoutOrder = 2,
			})
			local cards = {}
			local minStarterWidth = 0
			for index, entry in ipairs(env.require("ui/chat/prompts").items) do
				minStarterWidth = math.max(minStarterWidth, P.measureText(entry.label, { role = "small" }).X
					+ theme.size.icon + theme.space.xs + theme.space.sm * 2)
				local card = P.rowButton(grid, {
					name = "Starter_" .. entry.id, vertical = not mobile, size = UDim2.fromOffset(0, theme.size.promptCard),
					bg = not mobile and theme.color.surface or nil, stroke = not mobile,
					radius = mobile and theme.radius.md or theme.radius.lg, gap = theme.space.xs,
					padding = mobile and { x = theme.space.sm, y = theme.space.xxs } or theme.space.md,
					alignX = "Left", alignY = mobile and "Center" or "Top",
					onClick = function() props.onInsert(entry.text) end,
				})
				card.icon(entry.icon, 1, theme.color.accentHot, theme.size.icon)
				P.text(card.row, { text = entry.label, role = mobile and "small" or "label", layoutOrder = 2,
					flex = mobile and "Fill" or nil,
					size = UDim2.new(mobile and 0 or 1, 0, 0, mobile and theme.text.small.height or theme.text.label.height), truncate = true })
				if not mobile then
					P.text(card.row, { text = entry.detail, role = "caption", color = theme.color.textTertiary,
						layoutOrder = 3, size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true })
				end
				cards[index] = card.instance
			end
			local function fitStarters()
				local columns = grid.AbsoluteSize.X >= (mobile and minStarterWidth * 2 + theme.space.sm or theme.size.promptColumns) and 2 or 1
				local gap = theme.space.sm
				local height = math.max(theme.size.promptCard,
					theme.size.icon + theme.text.label.height + theme.text.caption.height * 2 + theme.space.md * 2 + theme.space.xs * 2)
				if mobile then height = math.max(responsive.minTarget(), theme.text.small.height + theme.space.xxs * 2) end
				for index, card in ipairs(cards) do
					local col = (index - 1) % columns
					local row = math.floor((index - 1) / columns)
					card.Size = UDim2.new(1 / columns, -gap * (columns - 1) / columns, 0, height)
					card.Position = UDim2.new(col / columns, col * gap / columns, 0, row * (height + gap))
				end
				grid.Size = UDim2.new(1, 0, 0, math.ceil(#cards / columns) * (height + gap) - gap)
			end
			grid:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitStarters)
			fitStarters()
		end

		if config.get("ui.showActivity", true) ~= true then return holder end

		local card = P.column(holder, {
			name = "ActivityCard",
			-- Fills the column up to the card's own width, rather than being a fixed
			-- 560 that overflows a phone.
			size = UDim2.new(1, 0, 0, 0),
			maxSize = Vector2.new(theme.size.statCard, math.huge),
			auto = "Y",
			bg = theme.color.surfaceRaised,
			radius = theme.radius.xl,
			gap = theme.space.md,
			padding = theme.space.lg,
			layoutOrder = 4,
		})
		P.stroke(card, theme.color.borderSubtle)
		card.Visible = false
		P.button(holder, {
			name = "ToggleActivity", text = "Your activity", icon = "chevron", iconDirection = "down",
			variant = "ghost", size = "sm", layoutOrder = 3,
			onClick = function(button)
				card.Visible = not card.Visible
				button.setText(card.Visible and "Hide activity" or "Your activity")
			end,
		})

		local state = {
			tab = "overview",
			range = config.get("ui.activityRange", "all"),
		}
		local body = nil

		local function render()
			if body then pcall(function() body:Destroy() end) end
			body = P.column(card, {
				name = "ActivityBody",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = 2,
			})

			local window = stats.window(state.range)
			if state.tab == "models" then
				buildModels(body, window)
			else
				buildOverview(body, window)
			end
			buildHeatmap(body, 2)

			local footer = stats.comparison(window.tokens)
			if not footer then
				if window.messages == 0 and window.requests == 0 then
					footer = "Your activity will appear here as you work. Every figure comes from this client's recorded usage."
				else
					footer = string.format("%s in, %s out across %s.",
						util.formatCompact(window.tokensIn), util.formatCompact(window.tokensOut),
						util.pluralise(window.requests, "request"))
				end
			end
			local note = P.text(body, {
				name = "Comparison",
				text = footer,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
			note.Size = UDim2.new(1, 0, 0, 0)
		end

		local header = P.row(card, {
			name = "CardHeader",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xs,
			layoutOrder = 1,
		})

		local tabs, ranges = {}, {}

		local function repaint()
			for value, handle in pairs(tabs) do
				handle.setSelected(value == state.tab)
				handle.text.TextColor3 = (value == state.tab) and theme.color.text or theme.color.textTertiary
			end
			for value, handle in pairs(ranges) do
				handle.setSelected(value == state.range)
				handle.text.TextColor3 = (value == state.range) and theme.color.text or theme.color.textTertiary
			end
		end

		local tabRow = P.row(header, {
			name = "Tabs",
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		for index, entry in ipairs({ { value = "overview", label = "Overview" }, { value = "models", label = "Models" } }) do
			local handle = pill(tabRow, entry.label, entry.value == state.tab, index, function()
				state.tab = entry.value
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			tabs[entry.value] = handle
		end

		P.spacer(header, { grow = true, layoutOrder = 2 })

		local rangeRow = P.row(header, {
			name = "Ranges",
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 3,
		})
		for index, entry in ipairs(stats.RANGES) do
			local handle = pill(rangeRow, entry.label, entry.value == state.range, index, function()
				state.range = entry.value
				config.set("ui.activityRange", entry.value, { quiet = true })
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			ranges[entry.value] = handle
		end

		render()
		repaint()

		-- The card is built once per transcript, and a turn that finishes while it is on
		-- screen changes every number on it. Debounced because a turn records a message,
		-- a request and a tool result within the same few frames, and rebuilding the
		-- grid three times for one turn is three times the work for one result.
		local refresh = clock.debounce(function()
			if not card.Parent then return end
			render()
		end, theme.motion.slow)
		local unsubscribe = stats.changed:connect(refresh)
		card.Destroying:Connect(function() pcall(unsubscribe) end)

		return holder
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/logs
-- ==========================================================================
__UAI_MODULES["ui/panels/logs"] = (function()
-- Logs panel: the request history and the application log.
--
-- Two views over the same question -- what did this thing just do -- kept separate
-- because they answer different halves of it. Requests explain a provider failure;
-- the log explains everything else.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local http = env.require("net/http")
	local log = env.require("runtime/log")

	local M = {}

	local LEVEL_TONE = { debug = "info", info = "info", warn = "warn", error = "bad" }

	-- Copy the same request evidence this panel shows, without including bodies or
	-- credentials from transport records. The application log has a separate export.
	local function requestExport()
		local lines = {}
		for index = #http.history, 1, -1 do
			local entry = http.history[index]
			lines[#lines + 1] = string.format("%s %s %s -> %s (%s)",
				tostring(entry.stamp or ""), tostring(entry.method or "GET"), tostring(entry.url or ""),
				tostring(entry.status or 0), util.formatDuration(entry.ms or 0))
			local details = { tostring(entry.tag or "http"), tostring(entry.via or "unknown"),
				util.formatNumber(entry.bytes or 0) .. " bytes",
				"identity: " .. tostring(entry.identity or "none") }
			if entry.identity ~= "none" then
				details[#details + 1] = entry.uaSent and "user-agent sent" or "user-agent dropped"
			end
			if entry.attempt then details[#details + 1] = "attempt " .. tostring(entry.attempt) end
			if entry.server then details[#details + 1] = "server " .. tostring(entry.server) end
			if entry.trace then details[#details + 1] = "trace " .. tostring(entry.trace) end
			if entry.mitigated then details[#details + 1] = "mitigated " .. tostring(entry.mitigated) end
			lines[#lines + 1] = "  " .. table.concat(details, " | ")
			if entry.error then lines[#lines + 1] = "  " .. tostring(entry.error) end
		end
		return log.redact(table.concat(lines, "\n"))
	end

	function M.new(parent)
		local panel = { view = "requests" }

		local column = P.column(parent, {
			name = "LogsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.md },
			layoutOrder = 1,
		})

		local scroll
		local function render() end

		P.sectionHeader(head, { title = "Logs & traces", description = "Request activity and application diagnostics.", layoutOrder = 1 })
		C.segmented(head, {
			layoutOrder = 2,
			options = {
				{ value = "requests", label = "Requests" },
				{ value = "log", label = "Log" },
			},
			value = panel.view,
			onChange = function(value)
				panel.view = value
				render()
				scroll.instance.CanvasPosition = Vector2.new(0, 0)
			end,
		})

		local actions = P.row(head, { size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, gap = theme.space.xs, layoutOrder = 3 })
		local countLabel = P.text(actions, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		countLabel.Size = UDim2.fromOffset(0, theme.text.caption.height + theme.space.hair)
		countLabel.AutomaticSize = Enum.AutomaticSize.X
		-- A growing spacer rather than a hardcoded reserve on the label: the buttons
		-- are auto-width and grow with the text scale, so any fixed number is either
		-- short of the right edge or overlapping them.
		P.spacer(actions, { grow = true, size = UDim2.new(0, 0, 0, 1), layoutOrder = 2 })

		if caps.clipboard then
			local copy = P.button(actions, {
				name = "CopyDiagnostics",
				text = "Copy",
				variant = "ghost",
				size = "sm",
				layoutOrder = 3,
				onClick = function(button)
					local exported = panel.view == "requests" and requestExport() or log.export()
					local ok = pcall(caps.fn.clipboard, exported)
					button.setText(ok and "Copied" or "Retry")
					if not ok then overlay.toast("Could not copy diagnostics", "bad", 3) end
					clock.delay(2, function()
						if button.instance.Parent then button.setText("Copy") end
					end)
				end,
			})
			copy.instance.LayoutOrder = 3
		end
		local clear = P.button(actions, {
			name = "ClearDiagnostics",
			text = "Clear",
			variant = "ghost",
			size = "sm",
			layoutOrder = 4,
			onClick = function()
				if panel.view == "requests" then http.clearHistory() else log.clear() end
				render()
			end,
		})
		clear.instance.LayoutOrder = 4

		local listHolder = P.frame(column, { name = "LogListHolder", size = UDim2.new(1, 0, 0, 0),
			flex = "Fill", layoutOrder = 2 })
		scroll = P.scroll(listHolder, {
			name = "LogList",
			size = UDim2.new(1, 0, 1, 0),
			-- Tight, because the rows now carry their own banding and padding; a six
			-- pixel gap between banded rows reads as a gap in the data.
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.sm, bottom = theme.space.xl },
			layoutOrder = 2,
		})

		local function requestRow(entry, order)
			local tone = "good"
			if entry.error then
				tone = "bad"
			elseif entry.status >= 400 then
				tone = entry.status == 429 and "warn" or "bad"
			elseif entry.status == 0 then
				tone = "warn"
			end

			local card = P.card(scroll.instance, {
				layoutOrder = order,
				gap = theme.space.xxs,
				padding = theme.space.sm,
			})
			local top = P.row(card, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
			P.statusDot(top, { color = theme.toneColor(tone), diameter = theme.size.dot, layoutOrder = 1 })
			local title = P.text(top, {
				text = string.format("%s %s", entry.method, entry.tag or ""),
				role = "monoSmall",
				-- Fills rather than reserving 150 for a dot and a 96px meta column,
				-- which left thirty-five pixels stranded on every card.
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				truncate = true,
				layoutOrder = 2,
			})
			local meta = P.text(top, {
				text = string.format("%s %s", entry.status > 0 and tostring(entry.status) or "-",
					util.formatDuration(entry.ms or 0)),
				role = "caption",
				color = theme.color.textTertiary,
				align = "Right",
				layoutOrder = 3,
			})
			meta.Size = UDim2.fromOffset(theme.size.metaColumnWide + theme.space.sm, theme.text.caption.height)

			local url = P.text(card, {
				text = entry.url,
				role = "caption",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			url.Size = UDim2.new(1, 0, 0, 0)

			local bits = {
				entry.via or "?",
				string.format("%s bytes", util.formatNumber(entry.bytes or 0)),
				entry.identity or "claude",
			}
			if entry.identity ~= "none" and not entry.uaSent then
				bits[#bits + 1] = "user-agent dropped by transport"
			end
			if entry.droppedHeaders and #entry.droppedHeaders > 0 then
				bits[#bits + 1] = "dropped: " .. table.concat(entry.droppedHeaders, ", ")
			end
			if entry.attempt and entry.attempt > 1 then
				bits[#bits + 1] = "attempt " .. tostring(entry.attempt)
			end
			-- The evidence for a bodyless refusal. `server` and a trace id say the
			-- response came from an edge rather than from the API, and `cf-mitigated`
			-- says so outright, which is the difference between a key problem and a
			-- filter problem.
			if entry.server then bits[#bits + 1] = "server " .. tostring(entry.server) end
			if entry.mitigated then bits[#bits + 1] = "mitigated " .. tostring(entry.mitigated) end
			if entry.trace then bits[#bits + 1] = tostring(entry.trace) end
			if entry.status >= 400 and (entry.bytes or 0) == 0 then
				bits[#bits + 1] = "empty body"
			end
			local detail = P.text(card, {
				text = table.concat(bits, "  |  "),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			detail.Size = UDim2.new(1, 0, 0, 0)

			if entry.error then
				local err = P.text(card, {
					text = tostring(entry.error),
					role = "caption",
					color = theme.color.danger,
					wrap = true,
					auto = "Y",
				})
				err.Size = UDim2.new(1, 0, 0, 0)
			end
			return card
		end

		local function logRow(entry, order)
			local tone = LEVEL_TONE[entry.level] or "info"
			local row = P.card(scroll.instance, {
				name = "LogEntry",
				gap = theme.space.xs,
				padding = theme.space.sm,
				layoutOrder = order,
			})
			local metadata = P.row(row, {
				name = "Metadata",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = 1,
			})
			P.badge(metadata, { text = entry.level or "info", tone = tone, layoutOrder = 1 })
			P.text(metadata, {
				name = "Source", text = entry.source, role = "caption",
				color = theme.color.textSecondary, truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill", layoutOrder = 2,
			})
			P.text(metadata, {
				name = "Timestamp", text = entry.stamp or "", role = "monoSmall",
				color = theme.color.textTertiary, auto = "X", layoutOrder = 3,
			})
			P.text(row, {
				name = "Message", text = entry.message, role = "monoSmall",
				color = entry.level == "error" and theme.color.danger or theme.color.textSecondary,
				wrap = true, auto = "Y", layoutOrder = 2,
			})
			if entry.detail then
				P.text(row, {
					name = "Detail", text = tostring(entry.detail), role = "monoSmall",
					color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 3,
				})
			end
			return row
		end

		render = function()
			if not column.Parent then return end
			local position = scroll.instance.CanvasPosition
			scroll.clear()
			if panel.view == "requests" then
				local entries = util.reverse(http.history)
				countLabel.Text = util.pluralise(#entries, "request") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, {
						icon = "document",
						title = "No requests yet",
						description = "Requests appear here with status, duration and transport details after you send a message.",
						layoutOrder = 1,
					})
					return
				end
				for index, entry in ipairs(entries) do requestRow(entry, index) end
			else
				local entries = util.reverse(log.entries)
				countLabel.Text = util.pluralise(#entries, "line") .. " kept"
				if #entries == 0 then
					C.emptyState(scroll.instance, { icon = "document", title = "All clear", description = "Application events will appear here as they occur.", layoutOrder = 1 })
					return
				end
				for index, entry in ipairs(entries) do logRow(entry, index) end
			end
			scroll.instance.CanvasPosition = position
		end

		render()
		panel.refresh = render
		-- Coalesce a burst while retaining its final entry. A leading-only throttle
		-- silently left the last requests absent until another event happened.
		local refreshLater, cancelRefresh = clock.debounce(render, 0.2)
		panel.unsubscribeLog = log.changed:connect(function()
			if panel.view == "log" then refreshLater() end
		end)
		panel.unsubscribeHttp = http.changed:connect(function()
			if panel.view == "requests" then refreshLater() end
		end)
		column.Destroying:Connect(function()
			cancelRefresh()
			pcall(panel.unsubscribeLog)
			pcall(panel.unsubscribeHttp)
		end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/modelpicker
-- ==========================================================================
__UAI_MODULES["ui/panels/modelpicker"] = (function()
-- A compact picker: provider, persistent search, a flat model list, and effort.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local providers = env.require("provider/registry")
	local models = env.require("provider/models")
	local traits = env.require("provider/traits")
	local M = {}
	local opened

	function M.open(onChange)
		if opened and not opened.closed then return opened end
		local modalProps = { title = "Models", width = theme.size.modelPicker,
			height = theme.size.modelPickerHeight, scroll = true }
		local modal = overlay.modal(modalProps)
		if not modal then return end
		opened = modal
		modal.scroll.instance.ScrollingEnabled = false
		modal.content.AutomaticSize = Enum.AutomaticSize.None
		modal.content.Size = UDim2.fromScale(1, 1)
		local root = P.frame(modal.content, { name = "ModelPicker", size = UDim2.fromScale(1, 1) })
		local control = math.max(theme.size.control, responsive.minTarget())
		local filter, freeOnly, fetching = "", false, false
		local visibleCount = 0
		local rows, render, filterRows, renderEffort, fit = {}, nil, nil, nil, nil
		local signature, fitting = nil, false
		local function notify() if not modal.closed and onChange then onChange() end end

		local providerButton = P.rowButton(root, { name = "Section_Endpoint", height = control,
			size = UDim2.new(1, 0, 0, control), padding = { x = theme.space.xs }, gap = theme.space.xs,
			onClick = function(button)
				local options = {}
				for _, provider in ipairs(providers.list()) do
					options[#options + 1] = { label = provider.label, detail = provider.baseUrl, value = provider.id,
						selected = providers.active() and providers.active().id == provider.id }
				end
				options[#options + 1] = { divider = true }
				options[#options + 1] = { label = "Manage providers", value = "manage", icon = "sliders" }
				overlay.menu({ target = button.instance, width = theme.size.menuWide, options = options, onSelect = function(id)
					if id == "manage" then modal.close(); env.require("ui/app").show("providers")
					else providers.setActive(id); notify() end
				end })
			end,
		})
		providerButton.icon("globe", 1, theme.color.textTertiary)
		local providerLabel = providerButton.label("Select provider", 2, theme.color.textSecondary, "small")
		providerButton.icon("chevron", 3, theme.color.textTertiary)
		local searchRow = P.frame(root, { name = "FilterRow", position = UDim2.fromOffset(0, control + theme.space.sm),
			size = UDim2.new(1, 0, 0, control) })
		local search = P.field(searchRow, { name = "ModelFilter", placeholder = "Search models…",
			size = UDim2.new(1, -(theme.size.metaColumn + theme.space.sm), 0, control),
			onChange = function(text) filter = text; if filterRows then filterRows() end end })
		local freeButton = P.button(searchRow, { name = "FreeOnly", text = "Free", width = theme.size.metaColumn,
			position = UDim2.new(1, -theme.size.metaColumn, 0, 0), size = "md", variant = "ghost",
			onClick = function(button)
				freeOnly = not freeOnly
				button.setVariant(freeOnly and "secondary" or "ghost")
				filterRows()
			end })
		local count = P.text(root, { name = "ModelCount", text = "", role = "caption", color = theme.color.textTertiary,
			position = UDim2.fromOffset(0, control * 2 + theme.space.sm * 2), size = UDim2.new(1, 0, 0, theme.text.caption.height) })
		local listTop = control * 2 + theme.space.sm * 3 + theme.text.caption.height
		local list = P.scroll(root, { name = "ModelScroll", position = UDim2.fromOffset(0, listTop),
			size = UDim2.new(1, 0, 1, -listTop), gap = theme.space.hair,
			padding = { left = theme.space.xxs, right = theme.space.sm, top = theme.space.xxs, bottom = theme.space.xxs },
			bg = theme.color.surface })
		P.corner(list.instance, theme.radius.md)
		local empty = P.text(list.instance, { name = "EmptySearch", text = "No models yet. Use Refresh or add a model ID.",
			role = "small", color = theme.color.textTertiary, wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0) })
		local effort = P.column(root, { name = "Section_ReasoningEffort", anchor = Vector2.new(0, 1),
			position = UDim2.fromScale(0, 1), size = UDim2.new(1, 0, 0, control + theme.text.caption.height + theme.space.sm),
			gap = theme.space.xs })

		filterRows = function()
			local visible = 0
			local needle = util.trim(filter):lower()
			for _, entry in ipairs(rows) do
				local match = (needle == "" or entry.id:lower():find(needle, 1, true) ~= nil) and (not freeOnly or entry.free)
				entry.button.instance.Visible = match
				if match then visible = visible + 1 end
			end
			count.Text = visible == #rows and util.pluralise(#rows, "model") or string.format("%d of %s", visible, util.pluralise(#rows, "model"))
			visibleCount = visible
			empty.Visible = visible == 0
			empty.Text = #rows == 0 and "No models yet. Use Refresh or add a model ID." or "No matching models. Try another search."
			if fit then fit() end
		end

		renderEffort = function()
			for _, child in ipairs(effort:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
			local record = providers.active()
			local levels = record and traits.effortLevels(record.model)
			local wanted = config.get("agent.effort", "high")
			local sending = record and traits.nearestEffort(record.model, wanted) or wanted
			P.text(effort, { text = levels and "Reasoning effort" or "No documented effort control", name = levels and "EffortLabel" or "NoEffort",
				role = "caption", color = theme.color.textTertiary, size = UDim2.new(1, 0, 0, theme.text.caption.height), layoutOrder = 1 })
			if levels then
				local strip = P.scroll(effort, { name = "EffortPills", horizontal = true, gap = theme.space.xs,
					size = UDim2.new(1, 0, 0, control), layoutOrder = 2, bar = 0 })
				for index, level in ipairs(levels) do
					P.button(strip.instance, { name = "Effort_" .. level, text = level:gsub("^%l", string.upper),
						variant = level == sending and "secondary" or "ghost", size = "sm", layoutOrder = index,
						onClick = function() config.set("agent.effort", level); notify(); renderEffort() end })
				end
			end
			local height = levels and (control + theme.text.caption.height + theme.space.sm) or 0
			effort.Visible = levels ~= nil
			effort.Size = UDim2.new(1, 0, 0, height)
			if fit then fit() end
		end
		fit = function()
			if modal.closed or fitting then return end
			fitting = true
			local height = effort.Size.Y.Offset
			local room = math.max(0, modal.scroll.viewportSize().Y)
			local footerSpace = height > 0 and height + theme.space.md or 0
			local natural = math.max(1, visibleCount) * (control + theme.space.hair) + theme.space.sm
			local compact = room < listTop + footerSpace + control * 2
			-- One scrolling owner: short/keyboard layouts scroll the whole body;
			-- ordinary layouts pin the search and scroll only the catalogue.
			local listHeight = compact and natural or math.max(control, room - listTop - footerSpace)
			local contentHeight = compact and listTop + natural + footerSpace or room
			modal.content.Size = UDim2.new(1, 0, 0, contentHeight)
			modal.scroll.instance.ScrollingEnabled = compact
			list.instance.ScrollingEnabled = not compact
			list.instance.Size = UDim2.new(1, 0, 0, listHeight)
			if compact then list.instance.CanvasPosition = Vector2.new(0, 0) end
			local providerWidth = math.ceil(P.measureText(providerLabel.Text, { role = "small" }).X)
				+ theme.size.icon * 2 + theme.space.xs * 4
			providerButton.instance.Size = UDim2.new(0, math.min(math.max(control, providerWidth),
				math.max(control, modal.scroll.viewportSize().X)), 0, control)
			fitting = false
		end
		modal.scroll.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() if fit then fit() end end)

		render = function()
			if modal.closed then return end
			local record = providers.active()
			providerLabel.Text = record and record.label or "Add a provider"
			local known = record and models.list(record) or {}
			local nextSignature = (record and record.id or "") .. "\0" .. table.concat(known, "\0")
			if signature ~= nextSignature then
				for _, entry in ipairs(rows) do entry.button.instance:Destroy() end
				rows = {}
				list.instance.CanvasPosition = Vector2.new(0, 0)
				for index, id in ipairs(known) do
					local selected = id == record.model
					local button = P.rowButton(list.instance, { name = "Model_" .. id, height = control,
						selected = selected, bgSelected = theme.color.surfaceActive, radius = theme.radius.sm,
						padding = { x = theme.space.sm }, gap = theme.space.sm, layoutOrder = index,
						onClick = function() providers.setModel(record.id, id); notify() end })
					local label = button.label(id, 1, selected and theme.color.text or theme.color.textSecondary, "small")
					local badge = traits.badge(id)
					local meta = P.text(button.row, { text = badge or "", role = "caption", color = theme.color.textTertiary, auto = "X", layoutOrder = 2 })
					local mark = button.icon("check", 3, theme.color.accentHot)
					mark.Visible = selected
					rows[#rows + 1] = { id = id, free = models.isFree(record, id), button = button, label = label, mark = mark, meta = meta }
				end
				signature = nextSignature
			end
			for _, entry in ipairs(rows) do
				local selected = record and entry.id == record.model
				entry.button.setSelected(selected)
				entry.label.TextColor3 = selected and theme.color.text or theme.color.textSecondary
				entry.mark.Visible = selected == true
				entry.meta.Text = traits.badge(entry.id) or ""
			end
			filterRows()
			renderEffort()
			local chrome = modal.card.Size.Y.Offset - modal.scroll.instance.Size.Y.Offset
			modalProps.height = math.min(theme.size.modelPickerHeight, chrome + listTop
				+ math.min(math.max(#rows, 2), 7) * (control + theme.space.hair) + theme.space.lg
				+ (effort.Visible and effort.Size.Y.Offset + theme.space.md or 0))
			modal.relayout()
			fit()
		end

		P.button(modal.footer, { name = "FetchModels", text = "Refresh", variant = "ghost", size = "sm", layoutOrder = 1,
			onClick = function(button)
				local record = providers.active()
				if not record or fetching then return end
				fetching = true; button.setEnabled(false); button.setText("Fetching…")
				task.spawn(function()
					local ok, found, note = pcall(models.discover, record, { force = true })
					fetching = false
					if modal.closed then return end
					button.setEnabled(true); button.setText("Refresh")
					overlay.toast(tostring(ok and note or found), ok and #found > 0 and "good" or "warn", 3)
					render(); notify()
				end)
			end })
		P.button(modal.footer, { name = "ModelOptions", text = "Options", variant = "ghost", size = "sm", layoutOrder = 2,
			onClick = function(button)
				local record = providers.active()
				local id = record and tostring(record.model):lower() or ""
				local forced = (config.get("agent.forceReasoning", {}) or {})[id] == true
				local options = {
					{ label = "Add model ID", value = "add", icon = "plus" },
					{ label = "Reasoning support", value = "reasoning", selected = forced, detail = "Override for the selected model" },
					{ label = "Context window", value = "context", detail = "Override for the selected model" },
					{ label = "Manage providers", value = "manage", icon = "sliders" },
				}
				overlay.menu({ target = button.instance, options = options, onSelect = function(value)
					if value == "manage" then modal.close(); env.require("ui/app").show("providers"); return end
					if not record then overlay.toast("Add a provider first", "info", 2); return end
					if value == "add" then
						overlay.prompt({ title = "Add a model ID", placeholder = "Exact model ID", confirmText = "Add", onConfirm = function(text)
							local ok, note = models.add(record, text)
							if ok then providers.setModel(record.id, util.trim(text)) end
							overlay.toast(tostring(note), ok and "good" or "warn", 3); notify()
						end })
					elseif id ~= "" and value == "reasoning" then
						local claims = config.get("agent.forceReasoning", {}) or {}
						claims[id] = not forced; config.set("agent.forceReasoning", claims); renderEffort(); notify()
					elseif id ~= "" and value == "context" then
						local claims = config.get("agent.forceContext", {}) or {}
						overlay.prompt({ title = "Context window", description = "Token limit. Leave empty to use the documented value.",
							placeholder = "1000000", value = claims[id] and tostring(claims[id]) or "", confirmText = "Save",
							onConfirm = function(text)
								local number = tonumber(text)
								if util.trim(text) ~= "" and (not number or number <= 0 or number == math.huge) then
									overlay.toast("Enter a positive token count", "warn", 2); return
								end
								claims[id] = number and math.floor(number) or nil
								config.set("agent.forceContext", claims); if not modal.closed then render(); notify() end
							end })
					end
				end })
			end })
		P.button(modal.footer, { name = "PickerDone", text = "Done", variant = "primary", size = "sm", layoutOrder = 3,
			onClick = function() modal.close() end })
		local unsubscribe = providers.changed:connect(function(kind) if kind ~= "health" then render() end end)
		local unsubscribeResponsive = responsive.changed:connect(function()
			if modal.closed then return end
			local target = math.max(theme.size.control, responsive.minTarget())
			if target == control then fit(); return end
			control = target
			searchRow.Position = UDim2.fromOffset(0, control + theme.space.sm)
			searchRow.Size = UDim2.new(1, 0, 0, control)
			search.shell.Size = UDim2.new(1, -(theme.size.metaColumn + theme.space.sm), 0, control)
			freeButton.instance.Size = UDim2.fromOffset(math.max(theme.size.metaColumn, target), control)
			count.Position = UDim2.fromOffset(0, control * 2 + theme.space.sm * 2)
			listTop = control * 2 + theme.space.sm * 3 + theme.text.caption.height
			list.instance.Position = UDim2.fromOffset(0, listTop)
			for _, entry in ipairs(rows) do entry.button.instance.Size = UDim2.new(1, 0, 0, control) end
			render()
		end)
		modal.scrim.Destroying:Connect(function() unsubscribe(); unsubscribeResponsive() end)
		render()
		modal.render = render
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/panels/permission
-- ==========================================================================
__UAI_MODULES["ui/panels/permission"] = (function()
-- The permission prompt.
--
-- The loop blocks on a thread while this is open, so it has to be reliable: one
-- prompt at a time, queued, and always resolved -- closing it counts as a refusal.
-- An unresolved prompt would park the agent until its own timeout.
--
-- It listens to every conversation rather than to the open one. It used to attach to
-- whichever session the transcript was showing, which meant a second conversation
-- left running in the background asked for permission into a stream nobody was
-- subscribed to: no prompt appeared, its three-minute deadline expired, and every
-- write it had planned came back to the model as a refusal. Since a prompt can now
-- arrive from a conversation that is not on screen, the modal says which one.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")

	local M = { queue = {}, showing = false }

	local RISK_TONE = { read = "info", write = "warn", danger = "bad" }

	local RISK_TEXT = {
		read = "This only reads. Nothing changes.",
		write = "This changes something in the game or on disk.",
		danger = "This runs code, deletes data, or reaches the server. It cannot be undone.",
	}

	local function present(request)
		M.showing = true

		local remember = false
		local resolved = false

		local function answer(allowed)
			if resolved then return end
			resolved = true
			pcall(request.resolve, allowed, remember)
			M.showing = false
			-- Drain the next prompt on the same frame so a batch of tool calls does
			-- not make the user wait between decisions.
			local next_request = table.remove(M.queue, 1)
			if next_request then present(next_request) end
		end

		local modal = overlay.modal({
			title = "Allow " .. tostring(request.name) .. "?",
			description = RISK_TEXT[request.risk or "write"] or RISK_TEXT.write,
			width = theme.size.modalWide,
			dismissable = true,
			onClose = function() answer(false) end,
		})
		if not modal then
			answer(false)
			return
		end

		local badgeRow = P.row(modal.content, {
			name = "Asking",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.badge(badgeRow, {
			text = tostring(request.risk or "write"),
			tone = RISK_TONE[request.risk or "write"] or "warn",
			layoutOrder = 1,
		})
		-- Which conversation is asking. With one prompt queue serving every open
		-- conversation, "Allow run_luau?" on its own does not say whose turn it
		-- belongs to -- and answering the wrong one is not recoverable.
		if request.sessionTitle then
			P.text(badgeRow, {
				name = "AskingIn",
				text = "in " .. tostring(request.sessionTitle),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill",
				layoutOrder = 2,
			})
		end

		if request.description then
			local description = P.text(modal.content, {
				text = tostring(request.description),
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			description.Size = UDim2.new(1, 0, 0, 0)
		end

		-- The arguments are the whole point of the prompt: "allow run_luau" means
		-- nothing without seeing the code.
		local argsText = ""
		local ok, encoded = pcall(util.encode, request.args or {})
		if ok then argsText = encoded end
		if util.trim(argsText) ~= "" and argsText ~= "[]" and argsText ~= "{}" then
			local box = P.frame(modal.content, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.codeSurface,
				radius = theme.radius.md,
				padding = theme.space.sm,
				layoutOrder = 3,
			})
			P.stroke(box, theme.color.codeBorder)
			local label = P.text(box, {
				text = (util.truncate(argsText, 900)),
				role = "monoSmall",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
			})
			label.Size = UDim2.new(1, 0, 0, 0)
		end

		local rememberRow = P.row(modal.content, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 4,
		})
		local rememberText = P.column(rememberRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(rememberText, { text = "Remember this answer", role = "small" })
		P.text(rememberText, {
			text = "Applies to every future " .. tostring(request.name) .. " call. Change it later in the Tools panel.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local switch = C.switch(rememberRow, {
			value = false,
			onChange = function(value) remember = value end,
		})
		switch.instance.LayoutOrder = 2

		-- Named, like every other control that decides something. Two buttons both
		-- called "Button" is unreadable from a dump and unreachable from a test, and
		-- this is the one dialog in the client where pressing the wrong one is not
		-- recoverable.
		P.button(modal.footer, {
			name = "PermissionDeny",
			text = "Deny",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			onClick = function()
				modal.close()
			end,
		})
		P.button(modal.footer, {
			name = "PermissionAllow",
			text = "Allow",
			variant = request.risk == "danger" and "danger" or "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				answer(true)
				modal.closed = true
				pcall(function() modal.scrim:Destroy() end)
			end,
		})
	end

	-- Watches every conversation in the client.
	--
	-- `attach` is kept because the app calls it whenever the open conversation changes,
	-- but it no longer decides what is heard: the subscription is to the session
	-- module's own fan-out, made once and never dropped, so a prompt from a
	-- conversation nobody is looking at still reaches the screen.
	local function onEvent(session, event)
		if event.kind ~= "permission:ask" then return end
		-- A subagent is headless and its prompts are forwarded onto its parent's
		-- stream by agent/subagent, so the child's own copy would be a second modal
		-- for one decision.
		if session and session.headless then return end
		local request = {
			id = event.id,
			name = event.name,
			risk = event.risk,
			description = event.description,
			args = event.args,
			resolve = event.resolve,
			sessionTitle = session and session.title or nil,
		}
		if M.showing then
			M.queue[#M.queue + 1] = request
		else
			present(request)
		end
	end

	function M.watch()
		if M.watching then return M end
		local sessions = env.require("agent/session")
		M.watching = env.require("runtime/dispose").add(
			sessions.anyEvent:connect(onEvent), "permission.watch")
		return M
	end

	-- Kept for the app, which calls it on every conversation switch. Starting the
	-- global watch is all it has left to do.
	function M.attach()
		return M.watch()
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/providers
-- ==========================================================================
__UAI_MODULES["ui/panels/providers"] = (function()
-- Providers panel: a list on the left, one provider's whole configuration on the
-- right.
--
-- This is the screen that makes the client universal, so it is deliberately plain: a
-- base URL, a key, an auth style and a model. Anything that speaks
-- /v1/chat/completions is a first-class citizen here, and the presets are only a way
-- to avoid typing a URL.
--
-- It was a list of cards plus one modal holding nine rows of form, and four things
-- were wrong with that beyond the density. The modal was the only way to see any of a
-- record's configuration, and it printed the API key in clear text while the hint
-- underneath said the key was redacted. Picking a different preset inside it rebuilt
-- the record from scratch and threw away whatever had been typed, with no warning. The
-- record's headers, params, query, order and note -- five fields the registry keeps,
-- two of which decide whether Azure and OpenRouter work at all -- had no
-- representation anywhere in the interface. And every completion fired a health event
-- that rebuilt the entire panel mid-turn, scroll position included.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local caps = env.require("runtime/caps")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local R = env.require("ui/settingsrows")
	local overlay = env.require("ui/overlay")
	local catalog = env.require("provider/catalog")
	local registry = env.require("provider/registry")
	local models = env.require("provider/models")
	local chat = env.require("provider/chat")
	local traits = env.require("provider/traits")

	local M = {}

	local AUTH_OPTIONS = {
		{ value = "bearer", label = "Bearer" },
		{ value = "x-api-key", label = "x-api-key" },
		{ value = "api-key", label = "api-key" },
		{ value = "both", label = "Both" },
		{ value = "none", label = "None" },
	}

	local function labelOf(options, value)
		for _, option in ipairs(options) do
			if option.value == value then return option.label end
		end
		return tostring(value)
	end

	-- Never the key itself.
	--
	-- The editor rendered record.apiKey into an ordinary field, so opening Edit on any
	-- saved provider printed the whole secret on screen -- while the hint under it said
	-- "redacted in the log", the privacy pane promised only the last four characters
	-- were kept, and the export path reduced it to exactly that.
	local function maskedKey(record)
		local raw = tostring(record.apiKey or "")
		if util.trim(raw) == "" then return "not set", "warn" end
		local pool = registry.keysOf(record)
		if #pool > 1 then
			local last = pool[#pool]
			return string.rep("\226\128\162", 4) .. " " .. last:sub(-4) .. "  \194\183  pool of " .. #pool .. " keys", nil
		end
		local key = pool[1] or ""
		if #key <= 4 then return "set", nil end
		return string.rep("\226\128\162", 4) .. " " .. key:sub(-4), nil
	end

	-- Everything the registry knows about a record and the panel never said.
	--
	-- `chat.endpointOf` and `registry.endpoint` both existed for this and both had zero
	-- call sites; the comment on endpointOf says "for the Providers panel to show".
	local function factsFor(record)
		local health = record.health or {}
		local key, keyTone = maskedKey(record)
		local out = {
			{ key = "Endpoint", value = chat.endpointOf(record) },
			{ key = "Model list", value = registry.endpoint(record, "/models") },
			{ key = "Protocol", value = labelOf(chat.STYLES, chat.styleOf(record)) },
			{ key = "Auth", value = labelOf(AUTH_OPTIONS, record.authStyle or "bearer")
				.. "  \194\183  " .. key, tone = keyTone },
			-- The one fact that decides whether a long reply can arrive at all. No Roblox
			-- HTTP transport reads a body incrementally and the host abandons a request
			-- after about a minute, so without a socket a large completion cannot land.
			{ key = "Streaming", value = util.trim(record.wsUrl or "") ~= ""
				and "socket, no length ceiling"
				or "HTTP only, replies capped near a minute" },
		}
		if (health.ok or 0) + (health.fail or 0) > 0 then
			out[#out + 1] = {
				key = "Health",
				value = string.format("%d ok, %d failed", health.ok or 0, health.fail or 0),
				tone = (health.streak or 0) > 0 and "warn" or "good",
			}
		end
		-- Recorded on every success and shown nowhere until now.
		if (health.lastMs or 0) > 0 then
			out[#out + 1] = { key = "Last reply", value = util.formatDuration(health.lastMs) }
		end
		-- The bench was a red dot with no words: no label, no remaining time, and no
		-- statement of the three-failure rule that put it there.
		if registry.cooling(record) then
			local left = math.max((health.cooldownUntil or 0) - clock.ms(), 0)
			out[#out + 1] = {
				key = "Benched",
				value = string.format("%s left, after 3 failures in a row", util.formatDuration(left)),
				tone = "bad",
			}
		end
		if record.requires == "executor" then
			local have = caps.http == "executor"
			out[#out + 1] = {
				key = "Requires",
				value = have and "an executor HTTP function, which this host has"
					or "an executor HTTP function, which this host does not have",
				tone = have and "good" or "bad",
			}
		end
		return out
	end

	-- The connection modal: preset, name, URL, protocol, auth, key. Six rows, not nine.
	--
	-- Everything else a record carries -- its models, its behaviour switches, its extra
	-- headers -- is edited in the detail pane, which is a surface that does not have to
	-- be dismissed to see the rest of the screen. This modal exists for the one moment
	-- when none of that is reachable yet: there is no record to select.
	function M.editor(record, onSaved)
		local editing = util.deepCopy(record)
		local adding = util.trim(editing.id) == ""
		local modal = overlay.modal({
			title = adding and "Add a provider" or ("Connection for " .. tostring(editing.label)),
			description = "Any endpoint that speaks /v1/chat/completions, or Anthropic's Messages API.",
			width = theme.size.modalWide,
			height = 620,
			-- Six labelled rows, two segmented pickers and a footer do not fit on a phone,
			-- and an unbounded modal is centred -- so what did not fit went off the top and
			-- the bottom at once, taking the title and the Save button with it. Bounded and
			-- scrolled, the header and the footer stay put and the form moves.
			scroll = true,
		})
		if not modal then return end

		local form = P.column(modal.content, {
			name = "Form",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.lg,
			layoutOrder = 1,
		})

		local problemLabel
		local presetButton, urlField, keyRow, nameField
		local protocolControl, authControl, keyHintLabel
		local docsRow, docsNoteRow, presetNoteRow
		-- The form slot after the key row, where the hint, docs link and preset note
		-- live. Declared here because refreshDocs -- which writes into it -- is
		-- defined before the rows are built but only called once they have been.
		local rowAfterKey = 0
		-- Assigned with the model row below, called from applyPreset above it: a preset
		-- change moves the endpoint, so anything a previous fetch turned up belongs to a
		-- different server and must not still be on offer.
		local forgetFetchedModels

		local function showProblems()
			local ok, problems = registry.validate(editing)
			problemLabel.Text = ok and "" or (problems[1]:gsub("^%l", string.upper) .. ".")
			problemLabel.Visible = not ok
			return ok
		end

		-- Rows carry explicit, sequential orders: the form also holds the key hint and
		-- the preset's docs link and note, which are rebuilt on a preset change and
		-- have to land back in their slots rather than at the end of whatever is there.
		local rowOrder = 0
		local function row(label, hint, build)
			rowOrder = rowOrder + 1
			local column = P.column(form, {
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = rowOrder * 10,
			})
			P.text(column, { text = tostring(label), role = "label", color = theme.color.text })
			local handle = build(column)
			if hint then
				local note = P.text(column, {
					text = hint,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end
			return handle
		end

		-- Applied in place, not by rebuilding the record.
		--
		-- Choosing a preset used to call registry.blank, replace `editing` wholesale,
		-- close the modal and re-open it -- so a name typed, a key pasted and a URL
		-- corrected were all discarded the moment someone realised they had picked the
		-- wrong vendor. Only the fields the preset actually describes move; the label is
		-- carried over when it still matches the old preset's own name, which is the case
		-- where it was never edited.
		--
		-- The docs link and the note are rebuilt rather than updated: they are whole
		-- rows a preset may or may not have, so the row count itself changes with the
		-- pick. Rebuilt into the same slots so the layout order they hold is kept.
		local function refreshDocs()
			if docsRow then docsRow:Destroy() docsRow = nil end
			if docsNoteRow then docsNoteRow:Destroy() docsNoteRow = nil end
			if presetNoteRow then presetNoteRow:Destroy() presetNoteRow = nil end
			local presetRecord = catalog.get(editing.preset)
			if not presetRecord then return end
			if presetRecord.docs then
				-- The full URL, selectable and copyable. Roblox cannot open a browser from
				-- a client GUI, so "get a key here" has to be text a person can select or
				-- one press away from the clipboard -- a "click here" label with the
				-- destination hidden behind it is neither.
				docsRow = P.row(form, {
					name = "KeyLink",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					layoutOrder = rowAfterKey + 2,
				})
				local linkText = P.text(docsRow, {
					name = "KeyLinkUrl",
					text = tostring(presetRecord.docs),
					role = "small",
					color = theme.color.accent,
					wrap = true,
					auto = "Y",
					size = UDim2.new(0, 0, 0, 0),
					flex = "Fill",
					layoutOrder = 1,
				})
				if caps.clipboard then
					P.iconButton(docsRow, {
						name = "CopyKeyLink",
						icon = "copy",
						diameter = theme.size.controlSmall,
						layoutOrder = 2,
						onClick = function()
							local ok = pcall(caps.fn.clipboard, tostring(presetRecord.docs))
							overlay.toast(ok and "Link copied" or "Could not reach the clipboard",
								ok and "good" or "warn", 2)
						end,
					})
				end
				docsNoteRow = R.paragraph(form,
					"Keys for this provider are issued at the address above.",
					{ layoutOrder = rowAfterKey + 3 })
			end
			if presetRecord.note then
				presetNoteRow = R.paragraph(form, presetRecord.note, { layoutOrder = rowAfterKey + 4 })
			end
		end

		local function applyPreset(id)
			local preset = catalog.get(id)
			if not preset then return end
			local previous = catalog.get(editing.preset)
			if previous and util.trim(editing.label) == util.trim(previous.label) then
				editing.label = preset.label
			end
			if util.trim(editing.label) == "" then editing.label = preset.label end
			editing.preset = preset.id
			editing.baseUrl = preset.baseUrl or ""
			editing.authStyle = preset.authStyle or "bearer"
			editing.api = preset.api or "openai"
			editing.headers = util.deepCopy(preset.headers or {})
			editing.params = util.deepCopy(preset.params or {})
			editing.query = util.deepCopy(preset.query or {})
			editing.note = preset.note
			editing.requires = preset.requires
			if presetButton then presetButton.setText(preset.label) end
			if urlField then urlField.set(editing.baseUrl) end
			-- The name follows when it was never hand-edited -- the same rule the label
		-- above applies -- and every control derived from the preset repaints, because a
		-- preset changes the protocol, the auth header, the key hint and the docs link,
		-- and a form where half the rows still describe the previous vendor reads as
			-- broken rather than as partially updated.
			if nameField then nameField.set(editing.label) end
			if protocolControl then protocolControl.set(chat.styleOf(editing)) end
			if authControl then authControl.set(editing.authStyle) end
			if keyHintLabel then
				keyHintLabel.Text = preset.keyHint
					and ("Key hint: " .. tostring(preset.keyHint))
					or ""
			end
			refreshDocs()
			if forgetFetchedModels then forgetFetchedModels() end
			showProblems()
		end

		row("Preset", "Pick a vendor to fill in the URL, the auth style and the key hint. Everything "
			.. "you have already typed -- the name, a pasted key -- is kept.", function(column)
			presetButton = P.button(column, {
				name = "Preset",
				text = (catalog.get(editing.preset) or {}).label or "Custom endpoint",
				variant = "secondary",
				fill = true,
				align = "Left",
				onClick = function(handle)
					local options = {}
					for _, preset in ipairs(catalog.presets) do
						options[#options + 1] = {
							label = preset.label,
							value = preset.id,
							detail = (preset.baseUrl ~= "" and preset.baseUrl) or "any URL you supply",
							selected = preset.id == editing.preset,
						}
					end
					overlay.menu({
						target = handle.instance,
						width = theme.size.menuWide,
						options = options,
						onSelect = applyPreset,
					})
				end,
			})
			return presetButton
		end)

		row("Name", nil, function(column)
			nameField = P.field(column, {
				name = "ProviderName",
				text = editing.label,
				placeholder = "My provider",
				onChange = function(text) editing.label = text end,
				onBlur = showProblems,
			})
			return nameField
		end)

		local normalisedNote
		row("Base URL", nil, function(column)
			urlField = P.field(column, {
				name = "BaseUrl",
				text = editing.baseUrl,
				placeholder = "https://api.example.com/v1",
				onChange = function(text)
					editing.baseUrl = text
					-- What will actually be stored, before it is stored.
					--
					-- registry.save normalises the URL *and then* validates, so a rejected
					-- save had already rewritten the value while the field still showed the
					-- old text. Saying what the rule does to the input is better than
					-- describing the rule.
					local normalised = registry.normaliseBaseUrl(text)
					if normalisedNote then
						normalisedNote.Text = (normalised ~= "" and normalised ~= util.trim(text))
							and ("Saved as " .. normalised) or ""
					end
				end,
				onBlur = showProblems,
			})
			normalisedNote = P.text(column, {
				text = "",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			normalisedNote.Size = UDim2.new(1, 0, 0, 0)
			return urlField
		end)

		row("Protocol", "Chat completions is the universal one. Anthropic's own Messages API keeps "
			.. "reasoning and tool calls in their real shape instead of translating them twice.",
			function(column)
				protocolControl = C.segmented(column, {
					name = "Protocol",
					options = chat.STYLES,
					value = chat.styleOf(editing),
					onChange = function(value) editing.api = value end,
				})
				return protocolControl
			end)

		row("Auth header", nil, function(column)
			authControl = C.segmented(column, {
				name = "AuthStyle",
				options = AUTH_OPTIONS,
				value = editing.authStyle,
				onChange = function(value)
					editing.authStyle = value
					showProblems()
				end,
			})
			return authControl
		end)

		-- The key goes in through a prompt and never comes back out.
		--
		-- A masked field would need a new primitive; a prompt needs none, and it has the
		-- better property that the secret is on screen only while it is being typed.
		local keyLabel
		row("API key", "Kept on this device, sent only to the endpoint above, and redacted in "
			.. "the request log.", function(column)
			local line = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm })
			local shown, tone = maskedKey(editing)
			keyLabel = P.text(line, {
				name = "KeyState",
				text = shown,
				role = "monoSmall",
				color = tone and theme.color.warn or theme.color.textSecondary,
				size = UDim2.new(0, 0, 0, math.max(theme.size.control, responsive.minTarget())),
				flex = "Fill",
				truncate = true,
				layoutOrder = 1,
			})
			local set = P.button(line, {
				name = "SetKey",
				text = util.trim(editing.apiKey or "") == "" and "Add key" or "Replace",
				variant = "secondary",
				size = "sm",
				layoutOrder = 2,
				onClick = function(handle)
					overlay.prompt({
						title = "API key",
						description = "Paste the key for " .. tostring(editing.label)
							.. ". It replaces whatever is stored now. Paste several keys, "
							.. "one per line, to rotate automatically on rate limits.",
						placeholder = (catalog.get(editing.preset) or {}).keyHint or "sk-...",
						confirmText = "Save key",
						multiline = true,
						onConfirm = function(text)
							-- Kept verbatim: the pool parser splits on newlines and
							-- commas, so what was pasted is what is stored, and a
							-- single key with a stray trailing newline is still one.
							editing.apiKey = tostring(text or "")
							local value, warn = maskedKey(editing)
							keyLabel.Text = value
							keyLabel.TextColor3 = warn and theme.color.warn or theme.color.textSecondary
							handle.setText("Replace")
							showProblems()
						end,
					})
				end,
			})
			set.instance.LayoutOrder = 2
			return keyLabel
		end)

		-- What a key for this preset looks like, when the preset knows. It is a hint,
		-- not a field: the shape of an OpenAI key is not the shape of a Gemini key, and
		-- the person pasting one wants to know they are pasting the right kind of thing
		-- before the request fails on the far end. The docs link and the preset note sit
		-- with it, in the slots after the key row, because all three are things the
		-- preset decides and a preset change has to move together.
		rowAfterKey = rowOrder * 10
		keyHintLabel = P.text(form, {
			name = "KeyHint",
			text = (catalog.get(editing.preset) or {}).keyHint
				and ("Key hint: " .. tostring((catalog.get(editing.preset) or {}).keyHint)) or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = rowAfterKey + 1,
		})
		keyHintLabel.Size = UDim2.new(1, 0, 0, 0)

		-- Model.
		--
		-- The one field a record cannot be saved without, and the editor had none. The
		-- picker lives on the detail pane, which you reach by selecting a provider that has
		-- already been saved -- and `registry.validate` refuses to save a record with no
		-- model. So adding a provider ended at "fetch the model list or add a model id"
		-- with nothing on screen that could do either, and Test asked the endpoint for a
		-- completion with no model named, which comes back as the provider's own wording
		-- for that and reads as a broken connection.
		local modelButton, modelNote
		local fetched = {}

		-- What the picker offers: the ids already on the record, plus whatever this
		-- editor's own fetch turned up. The session-wide discovery cache is deliberately
		-- not read here -- it is keyed by provider id and a record being added has none,
		-- so a second "Add a provider" would be offered the last endpoint's models.
		local function knownModels()
			local out, seen = {}, {}
			for _, id in ipairs(editing.models or {}) do
				if util.trim(id) ~= "" and not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			for _, id in ipairs(fetched) do
				if not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			return out
		end

		local DEFAULT_MODEL_NOTE = "The endpoint is the only authority on this, so nothing here "
			.. "guesses one. Fetch the list, or type the id exactly as the provider expects it."

		local function setModelNote(text, bad)
			if not modelNote then return end
			modelNote.Text = tostring(text)
			modelNote.TextColor3 = bad and theme.color.warn or theme.color.textTertiary
		end

		local function paintModel()
			local current = util.trim(editing.model)
			if modelButton then
				modelButton.setText(current ~= "" and current or "Choose a model")
			end
		end

		local openModelMenu

		-- Fetches against the record as it would be saved, not as it is typed: the URL is
		-- normalised the same way `save` normalises it, so what is asked for is the
		-- endpoint the provider will actually use.
		local function fetchModels(handle)
			local target = util.deepCopy(editing)
			target.baseUrl = registry.normaliseBaseUrl(target.baseUrl)
			if target.baseUrl == "" then
				setModelNote("Add the base URL first -- there is nothing to ask.", true)
				return
			end
			handle.setEnabled(false)
			setModelNote("Asking " .. registry.endpoint(target, "/models") .. "...", false)
			task.spawn(function()
				local found, note = models.discover(target, { force = true })
				if modal.closed or not handle.instance.Parent then return end
				handle.setEnabled(true)
				if target.baseUrl ~= registry.normaliseBaseUrl(editing.baseUrl)
					or target.preset ~= editing.preset or target.apiKey ~= editing.apiKey then
					setModelNote(DEFAULT_MODEL_NOTE, false)
					return
				end
				fetched = found
				setModelNote(note, #found == 0)
				-- Straight back into the list. Picking one is the reason to fetch, and a
				-- notice that says "42 models" while the menu stays shut makes someone press
				-- the same control twice for one decision.
				if #found > 0 then openModelMenu(handle) end
			end)
		end

		local function typeModel()
			overlay.prompt({
				title = "Model id",
				description = "Type it exactly as the provider expects it. It is saved with this "
					.. "provider and selected.",
				placeholder = "model id",
				confirmText = "Use it",
				onConfirm = function(text)
					-- Not persisted: the record is still being edited and may never be saved.
					local ok, result = models.add(editing, text, { persist = false, select = true })
					setModelNote(ok and ("Using " .. tostring(result)) or tostring(result), not ok)
					paintModel()
					showProblems()
				end,
			})
		end

		openModelMenu = function(handle)
			local options = {}
			local own = {}
			for _, id in ipairs(editing.models or {}) do own[id] = true end
			for _, id in ipairs(knownModels()) do
				local badge = traits.badge(id)
				local bits = {}
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from /models" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == editing.model,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = "Fetch from /models",
				value = "fetch",
				detail = registry.endpoint(editing, "/models"),
				tone = "info",
			}
			options[#options + 1] = { label = "Type an id", value = "add", tone = "info" }
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "fetch" then
						fetchModels(handle)
					elseif value == "add" then
						typeModel()
					elseif util.startsWith(tostring(value), "model:") then
						local id = tostring(value):sub(7)
						models.add(editing, id, { persist = false, select = true })
						editing.model = id
						setModelNote(DEFAULT_MODEL_NOTE, false)
						paintModel()
						showProblems()
					end
				end,
			})
		end

		row("Model", nil, function(column)
			modelButton = P.button(column, {
				name = "ActiveModel",
				text = "Choose a model",
				variant = "secondary",
				fill = true,
				align = "Left",
				onClick = openModelMenu,
			})
			modelNote = P.text(column, {
				name = "ModelNote",
				text = DEFAULT_MODEL_NOTE,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			modelNote.Size = UDim2.new(1, 0, 0, 0)
			paintModel()
			return modelButton
		end)

		forgetFetchedModels = function()
			fetched = {}
			setModelNote(DEFAULT_MODEL_NOTE, false)
		end

		refreshDocs()

		problemLabel = P.text(modal.content, {
			name = "Problem",
			text = "",
			role = "small",
			color = theme.color.danger,
			wrap = true,
			auto = "Y",
			visible = false,
			layoutOrder = 2,
		})
		problemLabel.Size = UDim2.new(1, 0, 0, 0)

		local testButton
		testButton = P.button(modal.footer, {
			name = "TestConnection",
			text = "Test",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			-- Through onClick, not a raw Activated connection: that is what P.button's own
			-- re-entry guard hangs off, and connecting to Activated directly meant a double
			-- tap fired two concurrent completions.
			onClick = function(handle)
				-- A completion needs a model named, so testing without one asks the endpoint
				-- a question it cannot answer -- and what comes back is that provider's own
				-- wording for "no model", which reads as a broken connection rather than as
				-- an empty field one row up.
				if editing.preset ~= "azure" and util.trim(editing.model) == "" then
					problemLabel.Text = "Choose a model first: fetch the list, or type the id."
					problemLabel.Visible = true
					return
				end
				handle.setEnabled(false)
				handle.setText("Testing")
				task.spawn(function()
					local candidate = util.deepCopy(editing)
					candidate.baseUrl = registry.normaliseBaseUrl(candidate.baseUrl)
					local result, err = chat.complete(candidate, {
						messages = { { role = "user", content = "Reply with the single word: ready" } },
						stream = false,
						maxTokens = 12,
						attempts = 1,
					})
					if modal.closed or not handle.instance.Parent then return end
					handle.setText("Test")
					handle.setEnabled(true)
					if result then
						overlay.toast(string.format("Reached %s in %s",
							candidate.label, util.formatDuration(result.ms)), "good")
					else
						problemLabel.Text = tostring(err)
						problemLabel.Visible = true
					end
				end)
			end,
		})

		P.button(modal.footer, {
			name = "SaveProvider",
			text = adding and "Add" or "Save",
			variant = "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				local ok, problems = registry.save(editing)
				if not ok then
					-- Sentence-cased and one per line. It was table.concat(problems, ". "),
					-- which turned two lowercase fragments into "give the provider a name.
					-- base URL is required".
					local lines = {}
					for index, problem in ipairs(problems) do
						lines[index] = problem:gsub("^%l", string.upper) .. "."
					end
					problemLabel.Text = table.concat(lines, "\n")
					problemLabel.Visible = true
					return
				end
				modal.close()
				overlay.toast("Saved " .. editing.label, "good", 2)
				if onSaved then onSaved(editing.id) end
			end,
		})

		showProblems()
		-- Nothing is wrong yet on a brand-new record; it is simply incomplete.
		if adding then problemLabel.Visible = false end
	end

	-- The entry point for adding: the editor, directly. The preset row inside it
	-- is where the vendor is chosen -- picking one there seeds the name, URL, auth
	-- style and key hint without losing anything already typed -- so a separate
	-- picker in front of the editor was a second modal for the same decision, and
	-- the one a person had to dismiss before they could see a single field.
	function M.add(onSaved)
		M.editor(registry.blank("custom"), onSaved)
	end

	-- The featured provider cards.
	--
	-- Recommended places to start, shown to a client with no provider configured:
	-- the name, the sign-up address (selectable and copyable -- a client GUI cannot
	-- open a browser, so the address has to be readable text, not a hidden
	-- destination), and one button that opens the editor seeded from the preset.
	-- The link keeps its referral parameter exactly as the catalog carries it.
	-- Every preset marked featured gets its own card, in catalog order.
	function M.featuredCard(parent, onSetup, nextOrder)
		local built = nil

		local function build(featured)
			local card = P.card(parent, {
				name = "Featured",
				gap = theme.space.sm,
				layoutOrder = type(nextOrder) == "function" and nextOrder() or 1,
				-- The accent border is the one thing that says "start here" on a panel
				-- that is otherwise all neutral surfaces; P.card has already drawn a
				-- border, so this recolours it rather than adding a second stroke.
				strokeColor = theme.color.accentBorder,
			})

			local head = P.row(card, {
				name = "FeaturedHead",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = 1,
			})
			local headText = P.column(head, {
				name = "HeadText",
				size = UDim2.new(0, 0, 0, 0),
				auto = "Y",
				flex = "Fill",
				gap = 0,
				layoutOrder = 1,
			})
			P.text(headText, {
				name = "FeaturedTitle",
				text = "Featured",
				role = "overline",
				color = theme.color.accent,
				size = UDim2.new(1, 0, 0, theme.text.overline.height),
				layoutOrder = 1,
			})
			P.text(headText, {
				name = "FeaturedName",
				text = tostring(featured.label),
				truncate = true,
				role = "title",
				color = theme.color.text,
				size = UDim2.new(1, 0, 0, theme.text.title.height),
				layoutOrder = 2,
			})

			if featured.note then
				local text = tostring(featured.note)
				local at = featured.noteHighlight and text:find(featured.noteHighlight, 1, true)
				if at then
					local function escape(value)
						return (value:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
					end
					text = escape(text:sub(1, at - 1))
						.. string.format('<b><font color="#%s">%s</font></b>',
							theme.color.accent:ToHex(), escape(featured.noteHighlight))
						.. escape(text:sub(at + #featured.noteHighlight))
				end
				local note = P.text(card, {
					name = "FeaturedNote",
					text = text,
					rich = at ~= nil,
					role = "small",
					color = theme.color.textSecondary,
					wrap = true,
					auto = "Y",
					layoutOrder = 2,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end

			-- The sign-up address. Copyable with one press, and visible in full so it
			-- can be selected by hand or read onto another device.
			if featured.docs then
				local linkRow = P.row(card, {
					name = "FeaturedLink",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					layoutOrder = 3,
				})
				local linkText = P.text(linkRow, {
					name = "FeaturedUrl",
					text = tostring(featured.docs),
					role = "small",
					color = theme.color.accent,
					wrap = true,
					auto = "Y",
					size = UDim2.new(0, 0, 0, 0),
					flex = "Fill",
					layoutOrder = 1,
				})
				if caps.clipboard then
					P.iconButton(linkRow, {
						name = "CopyFeaturedLink",
						icon = "copy",
						diameter = theme.size.controlSmall,
						layoutOrder = 2,
						onClick = function()
							local ok = pcall(caps.fn.clipboard, tostring(featured.docs))
							overlay.toast(ok and "Link copied" or "Could not reach the clipboard",
								ok and "good" or "warn", 2)
						end,
					})
				end
			end

			local actions = P.row(card, {
				name = "FeaturedActions",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = 4,
			})
			P.button(actions, {
				name = "FeaturedSetup",
				text = "Set up " .. tostring(featured.label),
				variant = "primary",
				size = "sm",
				fill = true,
				layoutOrder = 1,
				onClick = function()
					local preset = catalog.get(featured.id)
					if not preset then return end
					M.editor(registry.blank(preset.id), onSetup)
				end,
			})

			return card
		end

		for _, preset in ipairs(catalog.presets) do
			if preset.featured then
				local card = build(preset)
				if not built then built = card end
			end
		end
		return built
	end

	-- List and detail ---------------------------------------------------------

	function M.new(parent)
		local panel = {}
		local selected = nil

		-- Two columns where there is room for two, stacked where there is not. Same rule
		-- and same threshold as the settings dialog, which solved this first.
		local wide = responsive.mode == "window"
			and parent.AbsoluteSize.X >= (theme.size.dialogNav * 3)

		local root, rootLayout = P.row(parent, { name = "ProvidersRoot", size = UDim2.fromScale(1, 1), gap = 0 })
		rootLayout.FillDirection = wide and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		local railHeight = math.max(theme.size.controlLarge, responsive.minTarget(),
			theme.text.small.height + theme.space.xs * 2)

		local railHolder = P.frame(root, {
			name = "ProviderRail",
			size = wide and UDim2.new(0, theme.size.dialogNav, 1, 0)
				or UDim2.new(1, 0, 0, railHeight + theme.space.xs * 2 + theme.size.scrollbar),
			bg = theme.color.sidebar,
			layoutOrder = 1,
		})
		local rail = P.column(railHolder, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = theme.space.xs,
		})
		local railScrollHolder = P.frame(rail, {
			size = UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 1,
		})
		local railScroll = P.scroll(railScrollHolder, {
			name = "ProviderList",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.hair,
			horizontal = not wide,
			alignX = "Left",
		})
		-- Under the list where there is a column to put it under, and at the end of the
		-- strip where there is not -- so there is exactly one of it either way.
		local addButton = P.button(rail, {
			name = "AddProvider",
			text = "Add a provider",
			icon = "plus",
			variant = "secondary",
			size = "sm",
			fill = true,
			layoutOrder = 2,
			onClick = function()
				M.add(function(id) panel.select(id) end)
			end,
		})
		addButton.instance.Visible = wide

		local divider = P.divider(root, {
			vertical = wide,
			color = theme.color.borderSubtle,
			layoutOrder = 2,
		})

		local detailHolder = P.frame(root, {
			name = "ProviderDetail",
			size = wide and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 3,
		})
		local detail = P.scroll(detailHolder, {
			name = "DetailScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.lg,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.xl },
		})

		-- Rail -----------------------------------------------------------------

		local railRows = {}

		local function dotFor(record, isActive)
			if registry.cooling(record) then return theme.color.danger end
			if record.enabled == false then return theme.color.textDisabled end
			if isActive then return theme.color.accent end
			return theme.color.textTertiary
		end

		function panel.renderRail()
			local position = railScroll.instance.CanvasPosition
			railScroll.clear()
			railRows = {}
			local list = registry.list()
			local active = registry.active()
			for index, record in ipairs(list) do
				local isActive = active and active.id == record.id
				local row = P.rowButton(railScroll.instance, {
					name = "Provider_" .. tostring(record.id),
					size = (not wide) and UDim2.fromOffset(0, railHeight) or nil,
					auto = (not wide) and "X" or nil,
					height = railHeight,
					padding = { x = theme.space.sm },
					radius = theme.radius.md,
					selected = record.id == selected,
					layoutOrder = index,
					onClick = function() panel.select(record.id) end,
				})
				local dotSlot = P.frame(row.row, {
					name = "Health",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				local dot = P.statusDot(dotSlot, {
					diameter = theme.size.dot,
					color = dotFor(record, isActive),
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				local colour = record.id == selected and theme.color.text or theme.color.textSecondary
				if wide then
					row.label(record.label, 2, colour, "small")
				else
					-- Intrinsic tabs: no menu-width reserve and no Fill child in an
					-- auto-width row. Long names stop growing before consuming the strip.
					P.text(row.row, { name = "Label", text = record.label, role = "small",
						color = colour, auto = "X", truncate = true,
						maxSize = Vector2.new(theme.size.menuMin, math.huge), layoutOrder = 2 })
				end
				-- A badge, not text appended to the title. It used to be "  (active)"
				-- concatenated into a truncating label, so on a narrow rail the one fact
				-- that says which endpoint is in use was the first thing cut.
				if isActive then
					local badge = P.badge(row.row, { text = "Active", tone = "accent", layoutOrder = 3 })
					badge.LayoutOrder = 3
				end
				railRows[record.id] = { row = row, dot = dot }
			end
			if #list == 0 then
				local empty = P.text(railScroll.instance, {
					name = "NoProviders",
					text = "Nothing configured yet.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				empty.Size = wide and UDim2.new(1, 0, 0, 0) or UDim2.fromOffset(theme.size.menuMin, theme.text.caption.height)
			end
			if not wide then
				-- With the rail collapsed to a strip there is no room under it for the
				-- button, so it rides at the end of the strip instead.
				local add = P.button(railScroll.instance, {
					name = "AddProvider",
					text = "Add",
					icon = "plus",
					variant = "secondary",
					size = "sm",
					layoutOrder = #list + 1,
					onClick = function(handle)
						M.add(function(id) panel.select(id) end)
					end,
				})
				add.instance.LayoutOrder = #list + 1
			end
			railScroll.instance.CanvasPosition = position
		end

		-- AbsoluteSize may still be zero at construction, and desktop resizing does
		-- not change responsive.mode. Reflow the existing detail rather than replacing
		-- a form somebody is typing into.
		local function reflow()
			local width = root.AbsoluteSize.X
			if width <= 0 then return end
			local nextWide = responsive.mode == "window" and width >= theme.size.dialogNav * 3
			local changed = nextWide ~= wide
			wide = nextWide
			rootLayout.FillDirection = wide and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
			rootLayout.VerticalAlignment = Enum.VerticalAlignment.Top
			railHolder.Size = wide and UDim2.new(0, theme.size.dialogNav, 1, 0)
				or UDim2.new(1, 0, 0, railHeight + theme.space.xs * 2 + theme.size.scrollbar)
			addButton.instance.Visible = wide
			divider.Size = wide and UDim2.new(0, theme.stroke.hair, 1, 0)
				or UDim2.new(1, 0, 0, theme.stroke.hair)
			detailHolder.Size = wide and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0, 0)
			railScroll.layout.FillDirection = wide and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
			railScroll.instance.AutomaticCanvasSize = wide and Enum.AutomaticSize.Y or Enum.AutomaticSize.X
			railScroll.instance.ScrollingDirection = wide and Enum.ScrollingDirection.Y or Enum.ScrollingDirection.X
			railScroll.instance.VerticalScrollBarInset = wide and Enum.ScrollBarInset.ScrollBar or Enum.ScrollBarInset.None
			railScroll.instance.HorizontalScrollBarInset = wide and Enum.ScrollBarInset.None or Enum.ScrollBarInset.ScrollBar
			if changed then
				railScroll.instance.CanvasPosition = Vector2.new(0, 0)
				panel.renderRail()
			end
		end
		root:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		local unsubscribeLayout = responsive.changed:connect(reflow)
		reflow()

		-- Detail ---------------------------------------------------------------

		local statusBox = nil
		local healthError = nil

		local function order()
			panel.__order = (panel.__order or 0) + 1
			return panel.__order
		end

		local function modelMenu(record, target, onDone)
			local options = {}
			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for _, id in ipairs(models.list(record)) do
				local badge = traits.badge(id)
				local bits = {}
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from /models" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == record.model,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = "Fetch from /models",
				value = "fetch",
				detail = registry.endpoint(record, "/models"),
				tone = "info",
			}
			options[#options + 1] = { label = "Add a model by id", value = "add", tone = "info" }
			overlay.menu({
				target = target,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "fetch" then
						overlay.toast("Fetching models from " .. record.label, "info", 2)
						task.spawn(function()
							local found, note = models.discover(record, { force = true })
							overlay.toast(tostring(note), #found > 0 and "good" or "warn", 3)
							if onDone then pcall(onDone) end
						end)
					elseif value == "add" then
						overlay.prompt({
							title = "Add a model to " .. record.label,
							description = "Type the id exactly as the provider expects it. "
								.. "It is saved to this provider and selected.",
							placeholder = "model id",
							confirmText = "Add",
							onConfirm = function(text)
								local ok, result = models.add(record, text)
								if ok then registry.setModel(record.id, util.trim(text)) end
								overlay.toast(tostring(result), ok and "good" or "warn", 3)
								if onDone then pcall(onDone) end
							end,
						})
					elseif util.startsWith(tostring(value), "model:") then
						registry.setModel(record.id, tostring(value):sub(7))
						if onDone then pcall(onDone) end
					end
				end,
			})
		end

		function panel.renderDetail()
			detail.clear()
			statusBox = nil
			healthError = nil
			panel.__order = 0
			local record = selected and registry.get(selected) or nil
			if not record then
				-- The featured cards, shown only on a client with nothing configured:
				-- the recommended providers, each with its sign-up address and one
				-- button that starts the setup. After the first provider exists the
				-- rail is the interface and this stops being the loudest thing on the
				-- panel.
				if registry.count() == 0 then
					M.featuredCard(detail.instance, function(id)
						panel.select(id)
					end, order)
				end
				C.emptyState(detail.instance, {
					title = registry.count() == 0 and "No provider configured"
						or "Pick a provider from the list",
					description = registry.count() == 0
						and "Add an endpoint to start. Anything that speaks /v1/chat/completions works: "
							.. "a hosted API, a relay, or a local server reachable from this host."
						or "Its endpoint, key, model and health are all edited here.",
					action = registry.count() == 0 and "Add a provider" or nil,
					onAction = function()
						M.add(function(id) panel.select(id) end)
					end,
					layoutOrder = order(),
				})
				return
			end

			local active = registry.active()
			local isActive = active and active.id == record.id

			-- Header. The window chrome already names the panel and the active provider, so
			-- this names the record being edited instead of repeating either.
			local head = P.row(detail.instance, {
				name = "DetailHead",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = order(),
			})
			local titleColumn = P.column(head, {
				size = UDim2.new(0, 0, 0, 0),
				auto = "Y",
				flex = "Fill",
				gap = theme.space.hair,
				layoutOrder = 1,
			})
			local title = P.text(titleColumn, {
				name = "ProviderTitle",
				text = record.label,
				role = "display",
				color = theme.color.text,
				wrap = true,
				auto = "Y",
			})
			title.Size = UDim2.new(1, 0, 0, 0)
			local subtitle = P.text(titleColumn, {
				text = record.baseUrl,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			subtitle.Size = UDim2.new(1, 0, 0, 0)

			-- Status ------------------------------------------------------------
			local status = R.section(detail.instance, {
				name = "Status",
				title = "Status",
				description = "What this client will actually send, and how the endpoint has "
					.. "been answering.",
				layoutOrder = order(),
			})
			statusBox = R.facts(status, factsFor(record), { name = "StatusFacts", layoutOrder = 1 })

			local health = record.health or {}
			healthError = R.paragraph(status, health.lastError or "",
				{ name = "HealthError", color = theme.color.danger, layoutOrder = 2 })
			healthError.Visible = util.trim(health.lastError or "") ~= ""
			-- The preset's own guidance, which the registry copies onto every record and
			-- nothing has ever rendered: Azure's deployment-path rule, Ollama's loopback
			-- warning, DeepSeek's reasoning field.
			if util.trim(record.note or "") ~= "" then
				R.paragraph(status, record.note, { layoutOrder = 3 })
			end
			-- Fallback is a global switch, and the old header claimed the chain was always
			-- in use. Saying which it is beats asserting one of them.
			R.paragraph(status, config.get("agent.fallback", true)
				and "Requests try the active provider first, then every other enabled one."
				or "Fallback is off under Settings, so only the active provider is tried.",
				{ layoutOrder = 4 })

			local actions = {}
			if not isActive then
				actions[#actions + 1] = {
					name = "UseProvider",
					text = "Use this provider",
					variant = "primary",
					onClick = function()
						registry.setActive(record.id)
						overlay.toast(record.label .. " is now the active provider", "good", 2)
					end,
				}
			end
			actions[#actions + 1] = {
				name = "EditConnection",
				text = "Connection",
				variant = "secondary",
				onClick = function() M.editor(record, function() panel.select(record.id) end) end,
			}
			if caps.clipboard then
				actions[#actions + 1] = {
					name = "CopyEndpoint",
					text = "Copy endpoint",
					variant = "ghost",
					onClick = function()
						pcall(caps.fn.clipboard, chat.endpointOf(record))
						overlay.toast("Copied", "good", 1.5)
					end,
				}
			end
			R.actions(status, actions, { name = "StatusActions", layoutOrder = 5 })

			-- Model -------------------------------------------------------------
			local modelSection = R.section(detail.instance, {
				name = "Model",
				title = "Model",
				description = "Only what the endpoint reported and what you added -- never a guess, "
					.. "so this can legitimately be empty until one of those has happened.",
				layoutOrder = order(),
			})
			local known = models.list(record)
			R.select(modelSection, {
				name = "ActiveModel",
				label = "Active model",
				hint = #known == 0 and "Nothing known yet. Fetch the list, or add an id by hand."
					or (traits.badge(record.model) and ("Context window " .. traits.badge(record.model))
						or "No published context window for this id."),
				options = (function()
					local out = {}
					for _, id in ipairs(known) do out[#out + 1] = { value = id, label = id } end
					if #out == 0 then
						out[#out + 1] = { value = record.model, label = record.model ~= "" and record.model or "none" }
					end
					return out
				end)(),
				value = record.model ~= "" and record.model or (known[1] or ""),
				width = theme.size.menu,
				onChange = function(value) registry.setModel(record.id, value) end,
			})
			R.actions(modelSection, {
				{
					name = "ManageModels",
					text = #known == 0 and "Fetch or add a model" or "Fetch, add or remove",
					variant = "secondary",
					onClick = function(handle)
						modelMenu(record, handle.instance, function() panel.select(record.id) end)
					end,
				},
			}, { name = "ModelActions" })

			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for index, id in ipairs(known) do
				local row = P.rowButton(modelSection, {
					name = "Model_" .. tostring(index),
					height = theme.size.rowSmall,
					padding = { x = theme.space.sm },
					radius = theme.radius.sm,
					selected = id == record.model,
					layoutOrder = 100 + index,
					onClick = function()
						registry.setModel(record.id, id)
						panel.select(record.id)
					end,
				})
				local slot = P.frame(row.row, {
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				P.statusDot(slot, {
					diameter = theme.size.dot,
					color = id == record.model and theme.color.accent or theme.color.borderStrong,
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				row.label(id, 2, id == record.model and theme.color.text or theme.color.textSecondary,
					"monoSmall")
				if not own[id] then
					local mark = P.badge(row.row, { text = "fetched", layoutOrder = 3 })
					mark.LayoutOrder = 3
				end
				if own[id] and #known > 1 then
					local remove = P.iconButton(row.row, {
						name = "RemoveModel",
						icon = "close",
						diameter = theme.size.rowSmall,
						variant = "ghost",
						layoutOrder = 4,
						onClick = function()
							models.remove(record, id)
							panel.select(record.id)
						end,
					})
					remove.instance.LayoutOrder = 4
				end
			end

			-- Behaviour ---------------------------------------------------------
			local behaviour = R.section(detail.instance, {
				name = "Behaviour",
				title = "Behaviour",
				description = "Per-provider switches. Each one can only narrow what the matching "
					.. "global setting allows: turning one off always takes effect, turning it on "
					.. "needs the global on as well.",
				layoutOrder = order(),
			})
			R.toggle(behaviour, {
				name = "Enabled",
				label = "Enabled",
				hint = "A disabled provider is skipped by the fallback chain. Disabling the active "
					.. "one leaves it flagged active while requests go elsewhere.",
				value = record.enabled ~= false,
				layoutOrder = 1,
				onChange = function(value)
					record.enabled = value
					registry.save(record, { force = true })
				end,
			})
			R.toggle(behaviour, {
				name = "Stream",
				label = "Ask for a stream",
				hint = "Streamed replies carry reasoning text and token counts. Turning this off "
					.. "always takes effect; turning it on only does while Settings has streaming on.",
				value = record.stream ~= false,
				layoutOrder = 2,
				onChange = function(value)
					record.stream = value
					registry.save(record, { force = true })
				end,
			})
			if registry.requiresClaude(record) then
				R.paragraph(behaviour,
					"Claude Code identity is required by AgentRouter and is always sent. It cannot be turned off for this endpoint.",
					{ name = "ClaudeUaRequired", role = "small", color = theme.color.textSecondary, layoutOrder = 3 })
			else
				R.toggle(behaviour, {
					name = "ClaudeUa",
					label = "Send the Claude Code identity",
					hint = "The claude-cli User-Agent and its client headers. Turning this off suppresses "
						.. "the whole set for this endpoint whatever the global switch says, which is the "
						.. "one lever this client has when a CDN in front of an API refuses the request.",
					value = record.claudeUa ~= false,
					layoutOrder = 3,
					onChange = function(value)
						record.claudeUa = value
						registry.save(record, { force = true })
					end,
				})
			end

			-- Transport and the three invisible maps -----------------------------
			local advanced = R.section(detail.instance, {
				name = "Advanced",
				title = "Transport",
				description = "The socket URL, and the extra headers, body fields and query "
					.. "parameters this record sends. All three were stored and none were shown, "
					.. "which is why Azure's api-version and OpenRouter's attribution headers "
					.. "could not be inspected or corrected from here.",
				layoutOrder = order(),
			})
			R.field(advanced, {
				name = "SocketUrl",
				label = "Socket URL",
				hint = "Optional. A wss:// endpoint for streamed completions, which is what lifts "
					.. "the one-minute ceiling on a long reply.",
				value = record.wsUrl or "",
				placeholder = "wss://api.example.com/v1",
				layoutOrder = 1,
				onChange = function(text)
					record.wsUrl = util.trim(text)
					registry.save(record, { force = true })
				end,
			})

			local extras = {}
			for _, group in ipairs({
				{ field = "headers", label = "header" },
				{ field = "params", label = "body field" },
				{ field = "query", label = "query" },
			}) do
				for _, key in ipairs(util.keys(record[group.field] or {}, true)) do
					extras[#extras + 1] = {
						key = group.label .. " " .. tostring(key),
						value = tostring(record[group.field][key]),
					}
				end
			end
			if #extras > 0 then
				R.facts(advanced, extras, { name = "ExtraFacts", layoutOrder = 4 })
			else
				R.paragraph(advanced, "No extra headers, body fields or query parameters.",
					{ layoutOrder = 4 })
			end

			-- Fallback order ----------------------------------------------------
			local list = registry.list()
			if #list > 1 then
				local position = 1
				for index, entry in ipairs(list) do
					if entry.id == record.id then position = index end
				end
				local ordering = R.section(detail.instance, {
					name = "Order",
					title = "Fallback order",
					description = string.format(
						"Position %d of %d. When the active provider fails, the chain walks this list "
						.. "in order. registry.reorder has existed since the beginning with no control "
						.. "attached to it.", position, #list),
					layoutOrder = order(),
				})
				local moves = {}
				if position > 1 then
					moves[#moves + 1] = {
						name = "MoveUp",
						text = "Move up",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, -1) end,
					}
				end
				if position < #list then
					moves[#moves + 1] = {
						name = "MoveDown",
						text = "Move down",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, 1) end,
					}
				end
				R.actions(ordering, moves, { name = "OrderActions" })
			end

			-- Removal -----------------------------------------------------------
			local danger = R.section(detail.instance, {
				name = "Remove",
				title = "Remove",
				description = "The endpoint and its key are deleted from this device. This cannot "
					.. "be undone.",
				layoutOrder = order(),
			})
			R.actions(danger, {
				{
					name = "RemoveProvider",
					text = "Remove " .. record.label,
					-- The danger variant, which exists for exactly this and which every other
					-- destructive control in the app already uses. This one was a ghost button
					-- sitting between Edit and nothing.
					variant = "danger",
					onClick = function()
						-- Says what happens next. registry.remove silently promotes the first
						-- remaining record when the active one goes, and the old confirmation
						-- did not mention it.
						local successor = nil
						for _, entry in ipairs(registry.list()) do
							if entry.id ~= record.id and not successor then successor = entry end
						end
						local description = "The endpoint and its key are deleted from this device."
						if isActive and successor then
							description = description .. " " .. successor.label
								.. " becomes the active provider."
						elseif isActive then
							description = description .. " No provider will be configured afterwards."
						end
						overlay.confirm({
							title = "Remove " .. record.label .. "?",
							description = description,
							confirmText = "Remove",
							danger = true,
							onConfirm = function()
								registry.remove(record.id)
								panel.select(successor and successor.id or nil)
							end,
						})
					end,
				},
			}, { name = "DangerActions" })
		end

		-- Wiring ---------------------------------------------------------------

		function panel.select(id)
			if not root.Parent then return end
			local previous = selected
			local position = detail.instance.CanvasPosition
			local list = registry.list()
			if id and registry.get(id) then
				selected = id
			else
				local active = registry.active()
				selected = (active and active.id) or (list[1] and list[1].id) or nil
			end
			panel.renderRail()
			panel.renderDetail()
			detail.instance.CanvasPosition = previous == selected and position or Vector2.new(0, 0)
		end

		-- Health arrives on every single completion, and the panel used to rebuild
		-- itself from scratch each time -- header, rail, detail, scroll position, and the
		-- enable switch mid-animation. Only the facts block and the rail dots can change
		-- for a health event, so only those are repainted.
		local function repaintHealth()
			local record = selected and registry.get(selected) or nil
			local active = registry.active()
			for id, entry in pairs(railRows) do
				local candidate = registry.get(id)
				if candidate and entry.dot.Parent then
					entry.dot.BackgroundColor3 = dotFor(candidate, active and active.id == id)
				end
			end
			if record and statusBox and statusBox.Parent then
				local replacement = R.facts(statusBox.Parent, factsFor(record),
					{ name = "StatusFacts", layoutOrder = 1 })
				pcall(function() statusBox:Destroy() end)
				statusBox = replacement
			end
			if record and healthError and healthError.Parent then
				healthError.Text = tostring((record.health or {}).lastError or "")
				healthError.Visible = util.trim(healthError.Text) ~= ""
			end
		end

		panel.select(nil)

		panel.unsubscribe = registry.changed:connect(function(reason)
			if not root.Parent then return end
			if reason == "health" then
				repaintHealth()
			else
				panel.select(selected)
			end
		end)
		root.Destroying:Connect(function()
			pcall(panel.unsubscribe)
			pcall(unsubscribeLayout)
		end)

		panel.root = root
		panel.scroll = detail
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settings
-- ==========================================================================
__UAI_MODULES["ui/panels/settings"] = (function()
-- The Settings panel: every pane, stacked in one scroll.
--
-- The panes themselves live in ui/settingspanes, because the settings dialog the
-- sidebar opens shows the same ones behind a category list. This surface is the one
-- that shows all of them at once, which is what a panel in a five-panel client is
-- for -- and it means a setting cannot exist in one place and not the other.
return function(env)
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")

	local M = {}

	function M.new(parent)
		local panel = {}
		local scroll = P.scroll(parent, {
			name = "Settings",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.lg,
			padding = theme.space.lg,
		})

		for index, entry in ipairs(panes.PANES) do
			local column = P.column(scroll.instance, {
				name = "Pane_" .. entry.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = index,
			})
			panes.render(entry.id, column)
		end

		panel.scroll = scroll
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settingsdialog
-- ==========================================================================
__UAI_MODULES["ui/panels/settingsdialog"] = (function()
-- The settings dialog: a category list on the left, one pane on the right.
--
-- The same panes the Settings panel stacks, shown one at a time -- so this is a
-- different arrangement of the same settings rather than a second set. The one it is
-- modelled on opens from the profile menu and from Customize, and both of those land
-- here on a named category.
return function(env)
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")

	local M = {}

	local function openMobile(initial)
		local dialog = overlay.dialog({ name = "SettingsDialog" })
		if not dialog then return end
		local control = responsive.minTarget()
		local pad = theme.space.sm
		local top = control + pad * 2
		local body = P.scroll(dialog.card, { name = "PaneScroll", position = UDim2.fromOffset(0, top),
			size = UDim2.new(1, 0, 1, -top), gap = theme.space.md,
			padding = { x = theme.space.md, top = pad, bottom = theme.space.lg } })
		local active, category, select
		category = P.rowButton(dialog.card, { name = "CategoryPicker",
			position = UDim2.fromOffset(pad, pad), size = UDim2.new(1, -dialog.closeInset - pad, 0, control),
			padding = { x = pad }, onClick = function(button)
				local options = {}
				for _, section in ipairs(panes.sections()) do
					options[#options + 1] = { isHeader = true, title = section.title }
					for _, entry in ipairs(section.panes) do
						options[#options + 1] = { label = entry.label, value = entry.id, icon = entry.icon,
							selected = active == entry.id }
					end
				end
				overlay.menu({ target = button.instance, title = "Settings", options = options, onSelect = select })
			end })
		category.icon("gear", 1)
		local label = category.label("Settings", 2, nil, "bodyStrong")
		category.icon("chevron", 3)
		P.frame(dialog.card, { name = "DialogDivider", position = UDim2.fromOffset(0, top),
			size = UDim2.new(1, 0, 0, theme.stroke.hair), bg = theme.color.borderSubtle })
		select = function(id)
			local entry = panes.pane(id)
			if dialog.closed or not entry or active == id then return end
			active = id
			label.Text = entry.label
			body.clear()
			local column = P.column(body.instance, { name = "Pane_" .. id, size = UDim2.new(1, 0, 0, 0),
				auto = "Y", gap = theme.space.md })
			panes.render(id, column)
			body.instance.CanvasPosition = Vector2.new(0, 0)
		end
		select(panes.pane(initial) and initial or panes.PANES[1].id)
		dialog.select = select
		dialog.activeCategory = function() return active end
		return dialog
	end

	function M.open(initial)
		if responsive.isMobile() then return openMobile(initial) end
		local dialog = overlay.dialog({ name = "SettingsDialog" })
		if not dialog then return nil end

		-- On a phone the two panes do not fit side by side, so the list collapses to a
		-- row of categories above the pane rather than being cut off.
		local narrow = dialog.width < (theme.size.dialogNav * 3)
		local navWidth = narrow and dialog.width or theme.size.dialogNav
		-- The height of the collapsed category strip, and therefore the offset of
		-- everything under it. It was this same sum written out four times.
		local tabHeight = math.max(theme.size.controlLarge, responsive.minTarget(), theme.text.small.height + theme.space.xs * 2)
		local stripHeight = tabHeight + theme.space.xs * 2 + theme.size.scrollbar
		-- The corner the dialog's own close button occupies. Reserved rather than drawn
		-- under: with the strip spanning the full width, the button sat on top of the last
		-- category and nothing could reach it.
		local closeInset = dialog.closeInset or theme.space.xxl

		local navHolder = P.frame(dialog.card, {
			name = "DialogNav",
			size = narrow and UDim2.new(1, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 1, 0),
			bg = theme.color.sidebar,
		})
		local nav = P.scroll(navHolder, {
			name = "Categories",
			size = UDim2.new(1, narrow and -closeInset or 0, 1, 0),
			gap = theme.space.hair,
			padding = {
				left = theme.space.xs,
				right = theme.space.xs,
				y = theme.space.xs,
			},
			horizontal = narrow,
			alignX = "Left",
		})

		local divider = P.frame(dialog.card, {
			name = "DialogDivider",
			size = narrow and UDim2.new(1, 0, 0, theme.stroke.hair) or UDim2.new(0, theme.stroke.hair, 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 0, 0),
			bg = theme.color.borderSubtle,
		})

		local bodyHolder = P.frame(dialog.card, {
			name = "DialogBody",
			size = narrow and UDim2.new(1, 0, 1, -(stripHeight + theme.stroke.hair))
				or UDim2.new(1, -(navWidth + theme.stroke.hair), 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight + theme.stroke.hair)
				or UDim2.new(0, navWidth + theme.stroke.hair, 0, 0),
		})
		local body = P.scroll(bodyHolder, {
			name = "PaneScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.md,
			padding = {
				left = theme.space.lg,
				-- Wide layouts put the close button over the top of this pane, so the first
				-- row's right edge has to clear it.
				right = narrow and theme.space.lg or closeInset,
				top = theme.space.lg,
				bottom = theme.space.xl,
			},
		})

		local rows = {}
		local active = nil

		local function select(id)
			if dialog.closed or not panes.pane(id) or active == id then return end
			active = id
			for key, row in pairs(rows) do
				row.setSelected(key == id)
				row.text.TextColor3 = (key == id) and theme.color.text or theme.color.textSecondary
			end
			body.clear()
			local column = P.column(body.instance, {
				name = "Pane_" .. id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = 1,
			})
			panes.render(id, column)
			body.instance.CanvasPosition = Vector2.new(0, 0)
		end

		local function renderNav()
			nav.clear()
			rows = {}
			local order = 0
			local function nextOrder()
				order = order + 1
				return order
			end

			if not narrow then
				P.text(nav.instance, {
					name = "SettingsTitle", text = "Settings", role = "title",
					size = UDim2.new(1, 0, 0, theme.text.title.height + theme.space.lg),
					padding = { x = theme.space.sm, y = theme.space.sm },
					layoutOrder = nextOrder(),
				})
			end

			for _, section in ipairs(panes.sections()) do
				-- Section headings belong to the vertical list, not the tab strip.
				if not narrow then
					P.text(nav.instance, {
						name = "Section_" .. section.title, text = section.title, role = "caption",
						color = theme.color.textTertiary, truncate = true,
						size = UDim2.new(1, 0, 0, theme.text.caption.height + theme.space.xs),
						padding = { x = theme.space.xs, top = theme.space.xs }, layoutOrder = nextOrder(),
					})
				end
				for _, entry in ipairs(section.panes) do
					local row = P.rowButton(nav.instance, {
						name = "Category_" .. entry.id,
						size = narrow and UDim2.fromOffset(0, tabHeight) or nil,
						auto = narrow and "X" or nil,
						selected = active == entry.id,
						layoutOrder = nextOrder(),
						onClick = function() select(entry.id) end,
					})
					row.icon(entry.icon, 1, theme.color.textSecondary, theme.size.icon)
					if narrow then
						row.text = P.text(row.row, { name = "Label", text = entry.label, role = "small",
							auto = "X", truncate = true, maxSize = Vector2.new(theme.size.menuMin, math.huge),
							color = theme.color.textSecondary, layoutOrder = 2 })
					else
						row.text = row.label(entry.label, 2, theme.color.textSecondary, "small")
					end
					row.text.TextColor3 = active == entry.id and theme.color.text or theme.color.textSecondary
					rows[entry.id] = row
				end
			end
		end

		local function reflow()
			if dialog.closed then return end
			local width = dialog.card.AbsoluteSize.X
			if width <= 0 then width = dialog.width end
			local nextNarrow = width < theme.size.dialogNav * 3
			local changed = narrow ~= nextNarrow
			narrow = nextNarrow
			navWidth = theme.size.dialogNav
			navHolder.Size = narrow and UDim2.new(1, 0, 0, stripHeight) or UDim2.new(0, navWidth, 1, 0)
			nav.instance.Size = UDim2.new(1, narrow and -closeInset or 0, 1, 0)
			nav.layout.FillDirection = narrow and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
			nav.instance.AutomaticCanvasSize = narrow and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
			nav.instance.ScrollingDirection = narrow and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
			nav.instance.VerticalScrollBarInset = narrow and Enum.ScrollBarInset.None or Enum.ScrollBarInset.ScrollBar
			nav.instance.HorizontalScrollBarInset = narrow and Enum.ScrollBarInset.ScrollBar or Enum.ScrollBarInset.None
			divider.Size = narrow and UDim2.new(1, 0, 0, theme.stroke.hair) or UDim2.new(0, theme.stroke.hair, 1, 0)
			divider.Position = narrow and UDim2.new(0, 0, 0, stripHeight) or UDim2.new(0, navWidth, 0, 0)
			bodyHolder.Size = narrow and UDim2.new(1, 0, 1, -(stripHeight + theme.stroke.hair))
				or UDim2.new(1, -(navWidth + theme.stroke.hair), 1, 0)
			bodyHolder.Position = narrow and UDim2.new(0, 0, 0, stripHeight + theme.stroke.hair)
				or UDim2.new(0, navWidth + theme.stroke.hair, 0, 0)
			body.instance:FindFirstChildOfClass("UIPadding").PaddingRight = UDim.new(0, narrow and theme.space.lg or closeInset)
			if changed then
				nav.instance.CanvasPosition = Vector2.new(0, 0)
				renderNav()
			end
		end
		renderNav()
		dialog.card:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		reflow()

		select(panes.pane(initial) and initial or panes.PANES[1].id)

		dialog.select = select
		dialog.activeCategory = function() return active end
		return dialog
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/tools
-- ==========================================================================
__UAI_MODULES["ui/panels/tools"] = (function()
-- Tools panel: what the agent can do here, and what it is allowed to do.
--
-- Permission rules live next to the tool they govern rather than in a separate
-- list, because "can it delete files" is a question about file_delete, not about a
-- rules table.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local registry = env.require("agent/registry")
	local permissions = env.require("agent/permissions")
	local schema = env.require("agent/schema")

	local M = {}

	local RULE_OPTIONS = {
		{ value = "default", label = "Default" },
		{ value = "allow", label = "Allow" },
		{ value = "ask", label = "Ask" },
		{ value = "deny", label = "Deny" },
	}

	local GROUP_LABELS = registry.GROUP_LABELS

	function M.new(parent)
		local panel = {}
		local filter = ""
		local expanded = {}

		local column = P.column(parent, {
			name = "ToolsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.md },
			layoutOrder = 1,
		})

		local stats = registry.stats()
		P.text(head, {
			text = string.format("%d tools in %d groups", stats.total, util.count(stats.byGroup)),
			role = "heading",
			layoutOrder = 1,
		})
		local summary = P.text(head, {
			text = string.format("%d unavailable on this host: %s",
				#stats.unavailable,
				#stats.unavailable > 0 and caps.summary() or "everything is available"),
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		summary.Size = UDim2.new(1, 0, 0, 0)

		local scroll

		local function rebuild()
			if not column.Parent or not scroll then return end
			local scrollPosition = scroll.instance.CanvasPosition
			scroll.clear()
			local needle = filter:lower()
			local grouped = {}
			for _, tool in ipairs(registry.list()) do
				if needle == ""
					or tool.name:lower():find(needle, 1, true)
					or tostring(tool.description):lower():find(needle, 1, true) then
					grouped[tool.group] = grouped[tool.group] or {}
					table.insert(grouped[tool.group], tool)
				end
			end

			local order = util.keys(grouped, true)
			if #order == 0 then
				C.emptyState(scroll.instance, {
					icon = "search",
					title = "No matching tools",
					description = "Search by a tool name or what you want it to do.",
					layoutOrder = 1,
				})
				return
			end

			local position = 0
			for _, group in ipairs(order) do
				position = position + 1
				-- The group header carries its own switch: turning a family off removes it
				-- from the list the model is sent, which is a different thing from denying
				-- a call and belongs next to the family rather than in a settings pane.
				local header = P.row(scroll.instance, {
					name = "Group_" .. tostring(group),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.sm,
					-- The same inset a card gives its own contents, so a group's name lines up
					-- with the tool names under it instead of sitting sixteen pixels to their
					-- left, and its switch lines up with theirs.
					padding = { x = theme.space.lg, top = theme.space.sm, bottom = theme.space.xxs },
					layoutOrder = position,
				})
				local headText = P.column(header, {
					size = UDim2.new(0, 0, 0, 0),
					auto = "Y",
					flex = "Fill",
					gap = 0,
					layoutOrder = 1,
				})
				P.text(headText, {
					text = GROUP_LABELS[group] or group,
					role = "label",
					color = theme.color.text,
					auto = "Y",
					wrap = true,
				})
				local groupNote = P.text(headText, {
					text = "",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				local function describeGroup()
					groupNote.Text = registry.groupEnabled(group)
						and util.pluralise(#grouped[group], "tool")
						or (util.pluralise(#grouped[group], "tool") .. ", not offered to the model")
				end
				describeGroup()
				local groupSwitch = C.switch(header, {
					value = registry.groupEnabled(group),
					onChange = function(value)
						registry.setGroupEnabled(group, value)
						describeGroup()
					end,
				})
				groupSwitch.instance.LayoutOrder = 2

				for _, tool in ipairs(grouped[group]) do
					position = position + 1
					local missing = registry.missingCapability(tool)
					local card = P.card(scroll.instance, {
						name = tool.name,
						layoutOrder = position,
						gap = theme.space.xs,
						padding = theme.space.md,
						bg = theme.color.surface,
						radius = theme.radius.md,
					})

					local top = P.column(card, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						gap = theme.space.xs,
						layoutOrder = 1,
					})
					local name = P.text(top, {
						text = tool.name,
						role = "monoSmall",
						color = missing and theme.color.textDisabled or theme.color.text,
						wrap = true,
						auto = "Y",
						layoutOrder = 1,
					})
					local badges = P.row(top, { size = UDim2.new(1, 0, 0, 0), auto = "Y",
						wrap = true, gap = theme.space.xs, layoutOrder = 2 })
					P.badge(badges, {
						text = tool.risk,
						tone = tool.risk == "read" and "info" or (tool.risk == "danger" and "bad" or "warn"),
						layoutOrder = 2,
					})
					if missing then
						P.badge(badges, { text = "unavailable", tone = "warn", layoutOrder = 3 })
					end

					local description = P.text(card, {
						text = tostring(tool.description),
						role = "caption",
						color = theme.color.textSecondary,
						wrap = true,
						auto = "Y",
						layoutOrder = 2,
					})
					description.Size = UDim2.new(1, 0, 0, 0)

					local details = P.column(card, { name = "ToolDetails", size = UDim2.new(1, 0, 0, 0),
						auto = "Y", gap = theme.space.sm, layoutOrder = 4, visible = expanded[tool.name] == true })
					P.button(card, { name = "ToolDetailsToggle",
						text = expanded[tool.name] and "Hide details" or "Parameters & permissions", variant = "ghost",
						size = "sm", fill = true, align = "Left", tight = true, layoutOrder = 3, onClick = function(button)
							details.Visible = not details.Visible
							expanded[tool.name] = details.Visible
							button.setText(details.Visible and "Hide details" or "Parameters & permissions")
						end })
					local params = P.text(details, {
						text = schema.describe(tool.parameters),
						role = "caption",
						color = theme.color.textTertiary,
						wrap = true,
						auto = "Y",
						layoutOrder = 3,
					})
					params.Size = UDim2.new(1, 0, 0, 0)

					if missing then
						local reason = P.text(details, {
							text = caps.reason(missing),
							role = "caption",
							color = theme.color.warn,
							wrap = true,
							auto = "Y",
							layoutOrder = 4,
						})
						reason.Size = UDim2.new(1, 0, 0, 0)
					else
						C.segmented(details, {
							options = RULE_OPTIONS,
							value = permissions.ruleFor(tool.name) or "default",
							layoutOrder = 4,
							onChange = function(value)
								permissions.setRule(tool.name, value)
							end,
						})
					end
				end
			end
			scroll.instance.CanvasPosition = scrollPosition
		end

		-- Third in the head block, stated rather than left to the tie-break: the two
		-- labels above it are constructed earlier but neither of them sets an order.
		P.field(head, {
			name = "ToolSearch",
			placeholder = "Search tools",
			layoutOrder = 3,
			onChange = function(text)
				filter = util.trim(text)
				rebuild()
				if scroll then scroll.instance.CanvasPosition = Vector2.new(0, 0) end
			end,
		})
		P.button(head, { name = "ManageChatLoops", text = "Chat loops & quiz scores", variant = "ghost", size = "sm", fill = true, align = "Left",
			layoutOrder = 4, onClick = function(button) env.require("ui/chat/loops").open(button.instance) end })

		-- Keep the flex item outside the clearable list contents.
		local listHolder = P.frame(column, { name = "ToolListHolder", size = UDim2.new(1, 0, 0, 0),
			flex = "Fill", layoutOrder = 2 })
		scroll = P.scroll(listHolder, {
			name = "ToolList",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.sm,
			-- Top padding as well. Without it the first group header butted against the
			-- head block above it while the bottom of the list had twelve pixels of air.
			padding = { x = theme.space.lg, top = theme.space.md, bottom = theme.space.xl },
			layoutOrder = 2,
		})

		rebuild()
		panel.refresh = rebuild
		panel.unsubscribe = permissions.changed:connect(rebuild)
		column.Destroying:Connect(function() pcall(panel.unsubscribe) end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/primitives
-- ==========================================================================
__UAI_MODULES["ui/primitives"] = (function()
-- Layout and interaction primitives.
--
-- Everything visible is built from these, and they all take the same shape of
-- props table, so a panel reads as a description of what it is rather than a
-- hundred lines of instance plumbing. Three rules are enforced here rather than
-- left to each caller: nothing is positioned by hand-computed offsets, every
-- interactive element has a full state set, and every hit target respects the
-- platform minimum.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")

	local P = {}

	-- Shared helpers ---------------------------------------------------------

	-- One current transition per element. Repeated hover/focus changes retarget from
	-- the rendered value instead of leaving competing tweens behind.
	local transitions = setmetatable({}, { __mode = "k" })

	function P.animate(instance, motion, goals, onComplete)
		local state = transitions[instance]
		if not state then
			state = {}
			transitions[instance] = state
			instance.Destroying:Connect(function()
				state.dead = true
				if state.finished then state.finished:Disconnect() end
				if state.tween then state.tween:Cancel() end
				transitions[instance] = nil
			end)
		end
		if state.finished then state.finished:Disconnect() end
		local previous = state.tween
		state.tween = nil
		if previous then previous:Cancel() end
		local tween = env.tween:Create(instance, theme.tween(motion), goals)
		state.tween = tween
		state.finished = tween.Completed:Connect(function(playback)
			if state.dead or state.tween ~= tween then return end
			state.tween = nil
			if state.finished then state.finished:Disconnect() end
			state.finished = nil
			if playback ~= Enum.PlaybackState.Cancelled and onComplete then onComplete() end
		end)
		tween:Play()
		return tween
	end

	function P.corner(instance, radius)
		local corner = Instance.new("UICorner", instance)
		corner.CornerRadius = UDim.new(0, radius == nil and theme.radius.md or radius)
		return corner
	end

	function P.stroke(instance, colour, thickness)
		local stroke = Instance.new("UIStroke", instance)
		stroke.Color = colour or theme.color.borderSubtle
		stroke.Thickness = thickness or theme.stroke.hair
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		return stroke
	end

	function P.pad(instance, spec)
		local padding = Instance.new("UIPadding", instance)
		if type(spec) == "number" then
			padding.PaddingTop = UDim.new(0, spec)
			padding.PaddingBottom = UDim.new(0, spec)
			padding.PaddingLeft = UDim.new(0, spec)
			padding.PaddingRight = UDim.new(0, spec)
		elseif type(spec) == "table" then
			local x = spec.x or spec.horizontal
			local y = spec.y or spec.vertical
			padding.PaddingTop = UDim.new(0, spec.top or y or 0)
			padding.PaddingBottom = UDim.new(0, spec.bottom or y or 0)
			padding.PaddingLeft = UDim.new(0, spec.left or x or 0)
			padding.PaddingRight = UDim.new(0, spec.right or x or 0)
		end
		return padding
	end

	local AUTO = {
		X = Enum.AutomaticSize.X,
		Y = Enum.AutomaticSize.Y,
		XY = Enum.AutomaticSize.XY,
	}

	-- Applies the props every visual element shares. Kept in one place so adding a
	-- shared concern (a token, an accessibility flag) is one edit.
	local function base(instance, props)
		props = props or {}
		if props.name then instance.Name = props.name end
		instance.BorderSizePixel = 0
		if props.size then instance.Size = props.size end
		if props.position then instance.Position = props.position end
		if props.anchor then instance.AnchorPoint = props.anchor end
		if props.auto then instance.AutomaticSize = AUTO[props.auto] or Enum.AutomaticSize.None end
		if props.zIndex then instance.ZIndex = props.zIndex end
		if props.layoutOrder then instance.LayoutOrder = props.layoutOrder end
		if props.clip ~= nil then instance.ClipsDescendants = props.clip == true end
		if props.visible ~= nil then instance.Visible = props.visible == true end
		if props.rotation then instance.Rotation = props.rotation end

		if props.bg then
			instance.BackgroundColor3 = props.bg
			instance.BackgroundTransparency = props.bgTransparency or 0
		else
			instance.BackgroundTransparency = 1
		end
		if props.radius ~= nil then P.corner(instance, props.radius) end
		if props.stroke then P.stroke(instance, props.strokeColor, props.strokeWidth) end
		if props.padding then P.pad(instance, props.padding) end
		if props.minSize or props.maxSize then
			local constraint = Instance.new("UISizeConstraint", instance)
			if props.minSize then constraint.MinSize = props.minSize end
			if props.maxSize then constraint.MaxSize = props.maxSize end
		end
		if props.aspect then
			Instance.new("UIAspectRatioConstraint", instance).AspectRatio = props.aspect
		end
		if props.flex then
			local item = Instance.new("UIFlexItem", instance)
			item.FlexMode = Enum.UIFlexMode[props.flex] or Enum.UIFlexMode.Fill
		end
		return instance
	end

	function P.frame(parent, props)
		local frame = Instance.new("Frame", parent)
		return base(frame, props)
	end

	local function stack(parent, props, direction)
		props = props or {}
		local frame = P.frame(parent, props)
		local layout = Instance.new("UIListLayout", frame)
		layout.FillDirection = direction
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX or "Left"]
		layout.VerticalAlignment = Enum.VerticalAlignment[props.alignY or "Top"]
		if props.wrap then layout.Wraps = true end
		if props.stretch then layout.ItemLineAlignment = Enum.ItemLineAlignment.Stretch end
		return frame, layout
	end

	function P.column(parent, props)
		return stack(parent, props, Enum.FillDirection.Vertical)
	end

	function P.row(parent, props)
		props = props or {}
		props.alignY = props.alignY or "Center"
		return stack(parent, props, Enum.FillDirection.Horizontal)
	end

	-- A gap, or -- with `grow` -- whatever is left over on the line.
	--
	-- A growing spacer starts at nothing. UIFlexItem.Grow only ever hands out the
	-- space a line has left, and it never shrinks a child below its own size, so a
	-- spacer that began at full width left nothing over and pushed every sibling
	-- after it past the parent's edge. That is how a profile row loses its chevron
	-- and a card header loses its right-hand pills.
	function P.spacer(parent, props)
		props = props or {}
		local size = props.size
		if not size then
			if props.grow then
				size = UDim2.fromOffset(0, 0)
			else
				size = UDim2.new(1, 0, 0, props.height or theme.space.sm)
			end
		end
		local frame = P.frame(parent, {
			name = "Spacer",
			size = size,
			layoutOrder = props.layoutOrder,
		})
		if props.grow then
			local item = Instance.new("UIFlexItem", frame)
			item.FlexMode = Enum.UIFlexMode.Grow
		end
		return frame
	end

	function P.divider(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Divider",
			size = props.vertical and UDim2.new(0, 1, 1, 0) or UDim2.new(1, 0, 0, 1),
			bg = props.color or theme.color.borderSubtle,
			layoutOrder = props.layoutOrder,
		})
	end

	-- Text -------------------------------------------------------------------

	-- `size` is the UDim2 every element shares; the font size comes from the role,
	-- or from `textSize` when one label genuinely has to differ. Overloading `size`
	-- for both would assign a number to Size, which Roblox rejects outright.
	--
	-- Two font properties, applied in order. `Font` is the legacy enum and always
	-- takes; `FontFace` is the modern family-plus-weight pair and is layered over it
	-- only when the theme resolved one, so a client without the newer type stack keeps
	-- rendering rather than being assigned nil. Assigning Font *after* FontFace would
	-- undo it -- the two are the same underlying property with different resolutions --
	-- which is why the order here is not arbitrary.
	local function applyFont(label, role, props)
		label.Font = props.font or role.font
		local face = props.face or (not props.font and role.face)
		if face then pcall(function() label.FontFace = face end) end
	end

	-- Synchronous measurement for control widths. GetTextSize is the legacy fallback;
	-- byte counts overestimate UTF-8 and cannot distinguish a W from an i.
	function P.measureText(text, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local size = props.textSize or role.size
		local value = tostring(text or "")
		local width = props.width and math.max(1, props.width) or math.huge
		local ok, bounds = pcall(function()
			return env.services.TextService:GetTextSize(value, size, props.font or role.font,
				Vector2.new(width, math.huge))
		end)
		if ok and bounds then
			return Vector2.new(bounds.X, math.ceil(bounds.Y * (props.line or role.line or 1)))
		end
		local longest, lines = 0, 0
		for line in (value .. "\n"):gmatch("(.-)\n") do
			local _, characters = line:gsub("[^\128-\191]", "")
			longest = math.max(longest, characters * size)
			lines = lines + math.max(1, math.ceil(characters * size / width))
		end
		return Vector2.new(math.min(width, longest), lines * (role.height or size))
	end

	function P.text(parent, props)
