	end

	-- A heading with an optional trailing description, which is the pattern every
	-- settings group uses.
	--
	-- Sentence case, not upper. Small-caps headings were doing the work of separating
	-- groups, and spacing does that better: SHOUTED LABELS every hundred pixels are
	-- what makes an interface read as a control panel rather than as a page.
	function P.sectionHeader(parent, props)
		local holder = P.column(parent, {
			name = "Section",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = props.layoutOrder,
		})
		P.text(holder, {
			text = tostring(props.title or ""),
			role = "label",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
		})
		if props.description then
			P.text(holder, {
				text = props.description,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		return holder
	end

	-- Interaction ------------------------------------------------------------

	-- Button variants.
	--
	-- `primary` is a cream fill with dark text rather than an accent fill. There is
	-- normally one of them per view -- send, save, confirm -- and making it the
	-- brightest thing on the page rather than the most colourful is what leaves the
	-- accent free to mean something: inline code, a running turn, a risk level. Use
	-- `accent` when the colour itself is the message.
	local VARIANTS = {
		primary = function()
			return {
				bg = theme.color.solid, bgHover = theme.color.solidHover, bgPress = theme.color.solidPress,
				text = theme.color.onSolid, stroke = nil, font = "bodyStrong",
			}
		end,
		accent = function()
			return {
				bg = theme.color.accent, bgHover = theme.color.accentHot, bgPress = theme.color.accent,
				text = theme.color.textOnAccent, stroke = nil, font = "bodyStrong",
			}
		end,
		-- No fill at rest, only a hairline. A dark-grey fill on a dark-grey panel adds
		-- a rectangle without adding contrast; the outline is what says "control".
		secondary = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = theme.color.border, font = "bodyStrong",
			}
		end,
		ghost = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.textSecondary, stroke = nil, font = "body",
			}
		end,
		-- A quiet title/dropdown: no border at rest, full-strength text, hover fill. Used
		-- for the primary picker in a toolbar, where a bordered box would be one too many
		-- rectangles but the label still has to read as the loudest thing on the strip.
		soft = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = nil, font = "bodyStrong",
			}
		end,
		-- Code actions follow the selected code palette, including its light surface.
		code = function()
			return {
				bg = nil,
				bgHover = theme.mix(theme.color.codeSurface, theme.color.codeText, 0.08),
				bgPress = theme.mix(theme.color.codeSurface, theme.color.codeText, 0.14),
				text = theme.color.codeGutter, textHover = theme.color.codeText,
				textPress = theme.color.codeText, focus = theme.color.codeText,
				stroke = nil, font = "small",
			}
		end,
		-- Text and outline only until it is pressed. A pre-filled danger button reads
		-- as already-dangerous and gets clicked past; the fill arriving on hover is the
		-- moment it is worth noticing.
		danger = function()
			return {
				bg = nil, bgHover = theme.color.dangerSurface, bgPress = theme.color.danger,
				text = theme.color.danger, textHover = theme.color.danger, textPress = theme.color.onSolid,
				stroke = theme.color.dangerBorder, font = "bodyStrong",
			}
		end,
	}

	local HEIGHTS = { sm = "controlSmall", md = "control", lg = "controlLarge" }

	-- One button implementation with a full state set: rest, hover, press, focus,
	-- disabled and loading. Roblox gives none of that, and a project that hand-rolls
	-- it per call site ends up with buttons that behave differently from each other.
	function P.button(parent, props)
		props = props or {}
		local variant = (VARIANTS[props.variant or "secondary"] or VARIANTS.secondary)()
		local height = math.max(theme.size[HEIGHTS[props.size or "md"]], responsive.minTarget())
		-- A button with neither a fixed width nor fill sizes to its label. That means
		-- the content row has to size to its own children too: AutomaticSize ignores
		-- a child whose width is a scale, so a (1, 0) row inside an auto-width button
		-- collapses the button to nothing.
		local autoWidth = not props.width and not props.fill

		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Button",
			size = props.width and UDim2.new(0, props.width, 0, height)
				or (props.fill and UDim2.new(1, 0, 0, height) or UDim2.new(0, 0, 0, height)),
			auto = autoWidth and "X" or nil,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			bg = variant.bg,
			radius = props.radius or theme.radius.md,
			zIndex = props.zIndex,
		})
		local outline = P.stroke(button, variant.stroke or theme.color.accent)
		outline.Transparency = variant.stroke and 0 or 1
		if not variant.bg then button.BackgroundTransparency = 1 end

		local content, layout = P.row(button, {
			name = "Content",
			size = autoWidth and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 1, 0),
			auto = autoWidth and "X" or nil,
			gap = theme.space.xs,
			alignX = props.align or "Center",
			alignY = "Center",
			-- `padX` for the caller that has to line this button's label up with something
			-- outside it: a full-width ghost row under a block of code has to start where
			-- the code starts, and the default is the button's own inset, not that block's.
			padding = { x = props.padX or (props.tight and theme.space.xs or theme.space.md) },
		})
		layout.SortOrder = Enum.SortOrder.LayoutOrder

		local icons = env.require("ui/icons")
		local iconHolder
		local iconTint = props.iconColor
		if props.icon then
			iconHolder = P.frame(content, {
				name = "IconSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			icons.draw(props.icon, iconHolder, theme.size.icon, iconTint or variant.text, props.iconDirection)
		end

		local label
		if props.text and props.text ~= "" then
			-- Keep icon and text together at their natural width. Fill stretches the
			-- label alone, pinning the icon to the edge even in a centred button.
			-- Shrink still lets bounded buttons truncate when the pair cannot fit.
			label = P.text(content, {
				text = props.text,
				role = props.size == "sm" and "small" or variant.font,
				color = variant.text,
				align = props.align or "Center",
				auto = autoWidth and "XY" or "X",
				size = not autoWidth and UDim2.new(0, 0, 1, 0) or nil,
				flex = not autoWidth and (props.trailing and "Fill" or "Shrink") or nil,
				truncate = not autoWidth,
				layoutOrder = 2,
			})
			if autoWidth then label.Size = UDim2.fromOffset(0, 0) end
		end

		-- A trailing glyph pinned to the button's right edge -- the chevron that marks a
		-- control as a dropdown. The label above takes Fill so this sits flush right.
		local trailingHolder
		if props.trailing then
			trailingHolder = P.frame(content, {
				name = "TrailingSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 3,
			})
			icons.draw(props.trailing, trailingHolder, theme.size.icon, props.trailingColor or iconTint or variant.text, props.trailingDirection)
		end

		local handle = { instance = button, label = label, enabled = props.enabled ~= false, busy = false }
		local hovered, focused, pressed = false, false, false
		local iconParts = {}
		local function collectIconParts()
			iconParts = {}
			local holders = {}
			if iconHolder then holders[#holders + 1] = iconHolder end
			if trailingHolder then holders[#holders + 1] = trailingHolder end
			for _, holder in ipairs(holders) do
				for _, child in ipairs(holder:GetDescendants()) do
					if child:IsA("ImageLabel") then
						iconParts[#iconParts + 1] = { instance = child, property = "ImageColor3" }
					elseif child:IsA("UIStroke") then
						iconParts[#iconParts + 1] = { instance = child, property = "Color" }
					elseif child:IsA("Frame") and child.BackgroundTransparency < 1 then
						iconParts[#iconParts + 1] = { instance = child, property = "BackgroundColor3" }
					end
				end
			end
		end
		collectIconParts()

		local function paint()
			local target = variant.bg
			local textColour = variant.text
			local active = handle.enabled and not handle.busy
			local motion = pressed and "press" or "hover"
			if not handle.enabled then
				target = variant.bg and theme.color.surfaceRaised or nil
				textColour = theme.color.textDisabled
			elseif active and pressed then
				target = variant.bgPress or variant.bgHover or variant.bg
				textColour = variant.textPress or variant.textHover or variant.text
			elseif active and (hovered or focused) then
				target = variant.bgHover or variant.bg
				textColour = variant.textHover or variant.text
			end
			P.animate(button, motion, {
				BackgroundColor3 = target or variant.bgHover or theme.color.surfaceHover,
				BackgroundTransparency = target and 0 or 1,
			})
			P.animate(outline, motion, {
				Color = focused and (variant.focus or theme.color.accent) or (variant.stroke or theme.color.border),
				Transparency = (focused or variant.stroke) and 0 or 1,
			})
			if label then P.animate(label, motion, { TextColor3 = textColour }) end
			for _, part in ipairs(iconParts) do
				P.animate(part.instance, motion, {
					[part.property] = handle.enabled and (iconTint or textColour) or theme.color.textDisabled,
				})
			end
		end

		button.MouseEnter:Connect(function() hovered = true; paint() end)
		button.MouseLeave:Connect(function() hovered = false; pressed = false; paint() end)
		button.MouseButton1Down:Connect(function() pressed = true; paint() end)
		button.MouseButton1Up:Connect(function() pressed = false; paint() end)
		button.SelectionGained:Connect(function() focused = true; paint() end)
		button.SelectionLost:Connect(function() focused = false; pressed = false; paint() end)

		button.Activated:Connect(function()
			if not handle.enabled or handle.busy then return end
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then
					env.require("runtime/log").warn("ui", "button handler failed", err)
				end
			end
		end)

		function handle.setEnabled(value)
			handle.enabled = value ~= false
			button.Active = handle.enabled
			button.Selectable = handle.enabled
			if not handle.enabled then focused = false; pressed = false end
			paint()
		end

		function handle.setText(text)
			if label then label.Text = tostring(text) end
		end

		function handle.setIcon(name, colour)
			iconTint = colour
			if not iconHolder then
				iconHolder = P.frame(content, {
					name = "IconSlot",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
			end
			for _, child in ipairs(iconHolder:GetChildren()) do child:Destroy() end
			iconHolder.Visible = name ~= nil
			if name then icons.draw(name, iconHolder, theme.size.icon, iconTint or variant.text, props.iconDirection) end
			collectIconParts()
			paint()
		end

		function handle.setVariant(name)
			variant = (VARIANTS[name] or VARIANTS.secondary)()
			if label then applyFont(label, theme.textRole(props.size == "sm" and "small" or variant.font), {}) end
			paint()
		end

		handle.setEnabled(handle.enabled)
		return handle
	end

	function P.iconButton(parent, props)
		props = props or {}
		local size = math.max(props.diameter or theme.size.control, responsive.minTarget())
		-- Shallow, deliberately. `util.merge` deep-copies, and a deep copy of a UDim2 or
		-- a Vector2 is a plain table with the same fields and none of the type -- so an
		-- icon button given a position lost it, silently, on the way through.
		local merged = util.copy(props)
		merged.variant = props.variant or "ghost"
		merged.text = nil
		merged.width = size
		merged.tight = true
		merged.radius = props.radius or theme.radius.md
		local handle = P.button(parent, merged)
		handle.instance.Size = UDim2.fromOffset(size, size)
		handle.instance.AutomaticSize = Enum.AutomaticSize.None
		return handle
	end

	-- A whole row that is one hit target, with the row's own layout inside it.
	--
	-- The wrong way to make a row clickable -- and the way most of the rows in the
	-- sidebar, the composer and the settings dialog were built -- is to drop a
	-- transparent full-size TextButton into the row alongside its contents. A
	-- UIListLayout does not layer its children, it lays them out: the button takes a
	-- full-width slot of its own and pushes the icon and the label it was meant to
	-- cover out past the row's right edge, where they are still drawn because nothing
	-- clips them. What that renders as is an empty pill with its contents floating
	-- beside it, and the only part that answers a click is the empty part.
	--
	-- So the button *is* the row: the layout goes inside it. Which is what P.button
	-- has always done, and what the transcript's own rows already did correctly.
	function P.rowButton(parent, props)
		props = props or {}
		local height = math.max(props.height or theme.size.rowSmall, responsive.minTarget())
		-- The content row is as tall as the button actually is, not as tall as the
		-- floored minimum.
		--
		-- A caller that states its own `size` -- every chip in the composer, every pill on
		-- the home card, both segments of the sidebar's mode switch -- takes that size for
		-- the button while the row inside it kept the floored one. A 22px chip therefore
		-- held a 28px content row, 44 on a touch device, top-anchored: the icon and label
		-- centred three pixels below the chip's own centre line and drew through its
		-- bottom border. The hit-target floor still applies to any button that did not
		-- state a size, which is the case it exists for.
		local stated = props.size and props.size.Y.Scale == 0 and props.size.Y.Offset > 0
		local contentHeight = stated and props.size.Y.Offset or height
		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Row",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			zIndex = props.zIndex,
			bg = props.bg,
			radius = props.radius == nil and theme.radius.sm or props.radius,
			clip = props.clip,
			flex = props.flex,
		})
		local outline = P.stroke(button, props.strokeColor or theme.color.borderSubtle)
		outline.Transparency = props.stroke and 0 or 1

		local inner = P.row
		if props.vertical then inner = P.column end
		local autoX = props.auto == "X" or props.auto == "XY"
		local autoY = props.auto == "Y" or props.auto == "XY"
		local row = inner(button, {
			name = "Content",
			size = UDim2.new(autoX and 0 or 1, 0, (autoX or autoY) and 0 or 1,
				(autoX and not autoY) and contentHeight or 0),
			auto = props.auto,
			gap = props.gap or theme.space.xs,
			padding = props.padding or { x = theme.space.xs },
			alignX = props.alignX,
			alignY = props.alignY or "Center",
		})

		local handle = { instance = button, row = row, selected = props.selected == true }
		local hovered, focused, pressed = false, false, false

		local function paint()
			local target = props.bg
			if handle.selected then target = props.bgSelected or theme.color.surfaceActive end
			if (hovered or focused) and not handle.selected then target = props.bgHover or theme.color.surfaceHover end
			if pressed then target = props.bgPress or theme.color.surfaceActive end
			local motion = pressed and "press" or "hover"
			P.animate(button, motion, {
				BackgroundColor3 = target or props.bgHover or theme.color.surfaceHover,
				BackgroundTransparency = target and 0 or 1,
			})
			P.animate(outline, motion, {
				Color = focused and theme.color.accent or (props.strokeColor or theme.color.borderSubtle),
				Transparency = (focused or props.stroke) and 0 or 1,
			})
		end

		button.MouseEnter:Connect(function() hovered = true; paint() end)
		button.MouseLeave:Connect(function() hovered = false; pressed = false; paint() end)
		button.MouseButton1Down:Connect(function() pressed = true; paint() end)
		button.MouseButton1Up:Connect(function() pressed = false; paint() end)
		button.SelectionGained:Connect(function() focused = true; paint() end)
		button.SelectionLost:Connect(function() focused = false; pressed = false; paint() end)

		button.Activated:Connect(function()
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then env.require("runtime/log").warn("ui", "row handler failed", err) end
			end
		end)

		function handle.setSelected(value)
			handle.selected = value == true
			paint("rest")
		end

		-- The two things every one of these rows puts in itself, so a caller does not
		-- have to remember that an auto-width label needs a height and that an icon
		-- needs a square to be drawn into.
		function handle.icon(name, order, colour, size)
			local diameter = size or theme.size.icon
			local slot = P.frame(row, {
				name = "IconSlot",
				size = UDim2.fromOffset(diameter, diameter),
				layoutOrder = order or 1,
			})
			local icons = env.require("ui/icons")
			icons.draw(name, slot, diameter, colour or theme.color.textSecondary)
			return slot
		end

		function handle.label(text, order, colour, role)
			return P.text(row, {
				name = "Label",
				text = text,
				role = role or "caption",
				color = colour or theme.color.textSecondary,
				size = UDim2.new(0, 0, 0, theme.textRole(role or "caption").height),
				auto = autoX and "X" or nil,
				flex = not autoX and "Fill" or nil,
				truncate = not autoX,
				layoutOrder = order or 2,
			})
		end

		paint("rest")
		return handle
	end

	-- Input -----------------------------------------------------------------

	-- A text field with a real focus state. The reference client's prompt box gave
	-- no sign it had focus at all, which on a dark panel means typing into nothing;
	-- the border picking up the accent is the whole fix.
	--
	-- `bare` drops the field's own background, outline and corner so it can sit
	-- inside a container that owns them -- the composer puts the field and the send
	-- button in one bordered box, which is one control to look at rather than two.
	-- In that mode the caller paints focus itself, from onFocus and onBlur.
	function P.field(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local multiline = props.multiline == true
		local bare = props.bare == true
		-- `height` is honoured on a single line too, not only when multiline.
		--
		-- It used to be ignored there, so a caller that wanted a composer rather than a
		-- search box got the 32px control token and had no way to say otherwise -- which
		-- is why the prompt field and the search field were the same height even though
		-- one of them is the primary surface of the app. The platform floor still
		-- applies: it is a minimum, not the value.
		local height = multiline
			and (props.height or theme.size.control * 2)
			or math.max(props.height or theme.size.control, responsive.minTarget())

		local shell = P.frame(parent, {
			name = props.name or "Field",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			layoutOrder = props.layoutOrder,
			bg = (not bare) and (props.bg or theme.color.surfaceRaised) or nil,
			radius = (not bare) and (props.radius or theme.radius.md) or nil,
			clip = true,
			flex = props.flex,
		})
		local stroke = (not bare) and P.stroke(shell, theme.color.border) or nil

		local box = Instance.new("TextBox", shell)
		box.BackgroundTransparency = 1
		box.BorderSizePixel = 0
		box.Size = UDim2.new(1, 0, 1, 0)
		box.Text = tostring(props.text or "")
		box.PlaceholderText = tostring(props.placeholder or "")
		box.PlaceholderColor3 = theme.color.textTertiary
		box.TextColor3 = theme.color.text
		box.Font = role.font
		if role.face then pcall(function() box.FontFace = role.face end) end
		box.TextSize = role.size
		box.LineHeight = role.line
		box.ClearTextOnFocus = false
		box.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		box.TextYAlignment = multiline and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
		box.MultiLine = multiline
		box.TextWrapped = multiline
		box.ClipsDescendants = true
		box.Selectable = true
		P.pad(box, {
			x = props.padX or (bare and theme.space.none or theme.space.md),
			y = multiline and theme.space.sm or 0,
		})

		local handle = { instance = box, shell = shell, stroke = stroke }

		local focused, hovered = false, false
		local function paintField()
			if not stroke then return end
			P.animate(stroke, "hover", {
				Color = focused and theme.color.accent or (hovered and theme.color.borderStrong or theme.color.border),
			})
			P.animate(shell, "hover", {
				BackgroundColor3 = focused and theme.color.surfaceOverlay or (props.bg or theme.color.surfaceRaised),
			})
		end
		shell.MouseEnter:Connect(function() hovered = true; paintField() end)
		shell.MouseLeave:Connect(function() hovered = false; paintField() end)
		box.Focused:Connect(function()
			focused = true
			paintField()
			if props.onFocus then pcall(props.onFocus, handle) end
		end)

		box.FocusLost:Connect(function(enterPressed)
			focused = false
			paintField()
			-- On a multiline box Enter inserts a newline, so submit is the caller's
			-- job there; on a single line it means "go".
			if enterPressed and not multiline and props.onSubmit then
				pcall(props.onSubmit, box.Text, handle)
			end
			if props.onBlur then pcall(props.onBlur, box.Text, handle) end
		end)

		if props.onChange then
			box:GetPropertyChangedSignal("Text"):Connect(function()
				pcall(props.onChange, box.Text, handle)
			end)
		end

		function handle.get() return box.Text end
		function handle.set(value) box.Text = tostring(value or "") end
		function handle.focus() pcall(function() box:CaptureFocus() end) end
		function handle.clear() box.Text = "" end

		return handle
	end

	-- Containers -------------------------------------------------------------

	-- A group of related controls. One step above the surface it sits on plus a
	-- hairline, and nothing else -- no shadow, no heavier fill. `stroke = false`
	-- drops the outline for a card that is only there to hold padding.
	function P.card(parent, props)
		props = props or {}
		local card, layout = P.column(parent, {
			name = props.name or "Card",
			size = props.size or UDim2.new(1, 0, 0, 0),
			auto = props.auto or "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg or theme.color.surfaceRaised,
			radius = props.radius or theme.radius.lg,
			gap = props.gap or theme.space.md,
			padding = props.padding or theme.space.lg,
			clip = props.clip,
		})
		if props.stroke ~= false then
			P.stroke(card, props.strokeColor or theme.color.borderSubtle)
		end
		return card, layout
	end

	-- A small label for a fact or a status. Neutral unless it is given a tone: most
	-- of these are a model id or an auth style, and colouring those blue because
	-- "info" was the default made a row of plain facts look like a row of warnings.
	function P.badge(parent, props)
		props = props or {}
		local tone = props.tone or "neutral"
		local holder = P.row(parent, {
			name = "Badge",
			size = UDim2.fromOffset(0, math.max(theme.size.controlSmall - theme.space.xs,
				theme.text.caption.height + theme.space.hair * 2)),
			auto = "XY",
			bg = props.bg or theme.toneSurface(tone),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs, y = theme.space.hair },
			layoutOrder = props.layoutOrder,
		})
		if props.dot then
			local dot = P.frame(holder, {
				name = "Dot",
				size = UDim2.fromOffset(theme.space.xs, theme.space.xs),
				bg = props.dotColor or theme.toneColor(tone),
				radius = theme.radius.pill,
			})
			dot.LayoutOrder = 1
		end
		local label = P.text(holder, {
			text = tostring(props.text or ""),
			role = "caption",
			color = props.color or theme.toneColor(tone),
			auto = "XY",
			layoutOrder = 2,
		})
		label.Size = UDim2.fromOffset(0, 0)
		return holder, label
	end

	-- A scroll region with the two things Roblox does not give you: a canvas that
	-- sizes itself from its contents, and edge fades so a long list reads as
	-- continuing rather than as ending at a hard line.
	function P.scroll(parent, props)
		props = props or {}
		local scroll = Instance.new("ScrollingFrame", parent)
		base(scroll, {
			name = props.name or "Scroll",
			visible = props.visible,
			zIndex = props.zIndex,
			anchor = props.anchor,
			size = props.size or UDim2.new(1, 0, 1, 0),
			position = props.position,
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			-- Forwarded like every other layout prop. It was not, so a scroll region asked
			-- to fill its line kept whatever size it was given -- which for the intended
			-- `UDim2.new(0, 0, 1, 0)` is no width at all. Three call sites had already
			-- worked around it by attaching a UIFlexItem by hand afterwards.
			flex = props.flex,
			clip = true,
		})
		scroll.ScrollBarThickness = props.bar or theme.size.scrollbar
		scroll.ScrollBarImageColor3 = theme.color.border
		scroll.ScrollBarImageTransparency = theme.opacity.scrollbar
		scroll.BorderSizePixel = 0
		scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		scroll.AutomaticCanvasSize = props.horizontal and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
		scroll.ScrollingDirection = props.horizontal and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
		scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		scroll.Selectable = false
		scroll.Active = true
		if not props.horizontal then
			scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		end
		scroll.MouseEnter:Connect(function()
			P.animate(scroll, "hover", { ScrollBarImageTransparency = 0 })
		end)
		scroll.MouseLeave:Connect(function()
			P.animate(scroll, "hover", { ScrollBarImageTransparency = theme.opacity.scrollbar })
		end)

		local layout = Instance.new("UIListLayout", scroll)
		layout.FillDirection = props.horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		if props.alignX then layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX] end

		local padding = props.padding and P.pad(scroll, props.padding) or nil

		local handle = { instance = scroll, layout = layout }

		-- The room a fixed-height child can actually use. AbsoluteSize includes the
		-- scrollbar and padding, which makes a nested list overflow its outer canvas
		-- when callers use it as the child's height.
		function handle.viewportSize()
			local size = scroll.AbsoluteWindowSize
			if size.X <= 0 or size.Y <= 0 then size = scroll.AbsoluteSize end
			local width, height = size.X, size.Y
			if padding then
				width = width - (padding.PaddingLeft.Scale + padding.PaddingRight.Scale) * size.X
					- padding.PaddingLeft.Offset - padding.PaddingRight.Offset
				height = height - (padding.PaddingTop.Scale + padding.PaddingBottom.Scale) * size.Y
					- padding.PaddingTop.Offset - padding.PaddingBottom.Offset
			end
			return Vector2.new(math.max(0, width), math.max(0, height))
		end

		function handle.toBottom()
			if props.horizontal then
				scroll.CanvasPosition = Vector2.new(math.max(scroll.AbsoluteCanvasSize.X - scroll.AbsoluteWindowSize.X, 0), 0)
			else
				scroll.CanvasPosition = Vector2.new(0, math.max(scroll.AbsoluteCanvasSize.Y - scroll.AbsoluteWindowSize.Y, 0))
			end
		end

		function handle.atBottom(slack)
			local axis = props.horizontal and "X" or "Y"
			local visible = scroll.AbsoluteWindowSize[axis]
			local total = scroll.AbsoluteCanvasSize[axis]
			if total <= visible then return true end
			return (total - visible - scroll.CanvasPosition[axis]) <= (slack or theme.space.huge)
		end

		function handle.clear()
			for _, child in ipairs(scroll:GetChildren()) do
				if not child:IsA("UIComponent") then child:Destroy() end
			end
		end

		if props.fade and not props.horizontal then
			local fades = {}
			for _, spec in ipairs({
				{ name = "FadeTop", anchor = Vector2.new(0, 0), position = UDim2.fromScale(0, 0), rotation = 90 },
				{ name = "FadeBottom", anchor = Vector2.new(0, 1), position = UDim2.fromScale(0, 1), rotation = -90 },
			}) do
				local fade = P.frame(parent, {
					name = spec.name,
					size = UDim2.new(1, 0, 0, theme.space.xl),
					anchor = spec.anchor,
					position = spec.position,
					bg = props.fadeColor or theme.color.surface,
					zIndex = (props.zIndex or 1) + 5,
				})
				fades[spec.name] = fade
				local gradient = Instance.new("UIGradient", fade)
				gradient.Rotation = spec.rotation
				gradient.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0),
					NumberSequenceKeypoint.new(1, 1),
				})
			end
			local function updateFades()
				fades.FadeTop.Visible = scroll.CanvasPosition.Y > theme.space.hair
				fades.FadeBottom.Visible = not handle.atBottom(theme.space.hair)
			end
			scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(updateFades)
			scroll:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(updateFades)
			scroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(updateFades)
			scroll.Destroying:Connect(function()
				for _, fade in pairs(fades) do fade:Destroy() end
			end)
			updateFades()
		end

		return handle
	end

	-- A small coloured dot used for provider health and busy state. Separate from
	-- badge because it is used inline in dense rows where a pill is too heavy.
	function P.statusDot(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Status",
			size = UDim2.fromOffset(props.diameter or theme.size.dot, props.diameter or theme.size.dot),
			bg = props.color or theme.color.textTertiary,
			radius = theme.radius.pill,
			layoutOrder = props.layoutOrder,
			anchor = props.anchor,
			position = props.position,
		})
	end

	return P
end
end)()

-- ==========================================================================
-- ui/profile
-- ==========================================================================
__UAI_MODULES["ui/profile"] = (function()
-- The identity shared by the sidebar profile control and its menu.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local providers = env.require("provider/registry")
	local M = {}

	function M.identity()
		local username, display, userId = "", "", 0
		if env.plr then
			pcall(function() username = util.trim(tostring(env.plr.Name or "")) end)
			pcall(function() display = util.trim(tostring(env.plr.DisplayName or "")) end)
			pcall(function() userId = tonumber(env.plr.UserId) or 0 end)
		end
		local name = display ~= "" and display or (username ~= "" and username or "you")
		-- Preserve the first UTF-8 character, including non-Latin display names.
		local initial = name:match("^[%z\1-\127\194-\244][\128-\191]*") or "?"
		local image
		if userId > 0 and userId < math.huge and userId == math.floor(userId) then
			image = string.format("rbxthumb://type=AvatarHeadShot&id=%.0f&w=150&h=150", userId)
		end
		return { name = name, username = username, initial = initial:upper(), image = image, userId = image and userId or nil }
	end

	function M.providerLabel()
		local record = providers.active()
		local label = record and util.trim(tostring(record.label or "")) or ""
		return label ~= "" and label or "No provider selected"
	end

	function M.avatar(parent, identity, diameter, order)
		local avatar = P.frame(parent, {
			name = "ProfileAvatar",
			size = UDim2.fromOffset(diameter, diameter),
			bg = theme.color.accentSurface,
			radius = diameter / 2,
			layoutOrder = order,
		})
		P.stroke(avatar, theme.color.accentBorder)
		local fallback = P.text(avatar, {
			name = "AvatarInitial",
			text = identity.initial,
			role = "title",
			color = theme.color.text,
			size = UDim2.fromScale(1, 1),
			align = "Center",
		})
		if identity.image then
			local photo = Instance.new("ImageLabel", avatar)
			photo.Name = "AvatarImage"
			photo.BackgroundTransparency = 1
			photo.BorderSizePixel = 0
			photo.Size = UDim2.fromScale(1, 1)
			photo.ScaleType = Enum.ScaleType.Fit
			-- Let the image render as soon as it arrives. Keeping it fully transparent
			-- until IsLoaded changes can leave loading dependent on an invisible image.
			photo.ImageTransparency = 0
			P.corner(photo, diameter / 2)
			local alive = true
			local function syncImage()
				if alive then fallback.Visible = photo.IsLoaded ~= true end
			end
			avatar.Destroying:Connect(function()
				alive = false
			end)
			photo:GetPropertyChangedSignal("IsLoaded"):Connect(syncImage)
			photo.Image = identity.image
			syncImage()
			-- Resolve a ready headshot and explicitly request its pixels. Both calls
			-- can yield, so the UI is built first; failures retain the initial and retry
			-- a bounded number of times. A destroyed view discards late results. Never
			-- task.cancel a thumbnail/preload waiter: Roblox still owns its resumption.
			task.defer(function()
				for attempt = 1, 3 do
					if attempt > 1 then task.wait(attempt - 1) end
					if not alive or photo.IsLoaded then return end
					if identity.userId then
						local ok, url, ready = pcall(function()
							return env.services.Players:GetUserThumbnailAsync(identity.userId,
								Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size150x150)
						end)
						if not alive then return end
						if ok and ready == true and type(url) == "string" and url ~= "" then photo.Image = url end
					end
					pcall(function() env.services.ContentProvider:PreloadAsync({ photo }) end)
					if not alive then return end
					syncImage()
					if photo.IsLoaded then return end
				end
			end)
		end
		return avatar
	end

	function M.menuHeader()
		local identity = M.identity()
		local identityHeight = math.max(theme.size.profileAvatarLarge,
			theme.text.title.height + theme.text.caption.height + theme.space.hair)
		local providerHeight = theme.text.caption.height + theme.space.xs * 2
		local height = identityHeight + providerHeight + theme.space.sm * 3
		return {
			isHeader = true,
			title = identity.name,
			height = height,
			render = function(parent)
				local header = P.column(parent, {
					name = "ProfileMenuHeader",
					size = UDim2.fromScale(1, 1),
					padding = theme.space.sm,
					gap = theme.space.sm,
				})
				local row = P.row(header, {
					size = UDim2.new(1, 0, 0, identityHeight),
					gap = theme.space.md,
					layoutOrder = 1,
				})
				M.avatar(row, identity, theme.size.profileAvatarLarge, 1)
				local text = P.column(row, {
					name = "ProfileIdentity",
					size = UDim2.new(0, 0, 1, 0),
					flex = "Fill",
					gap = theme.space.hair,
					alignY = "Center",
					layoutOrder = 2,
				})
				P.text(text, {
					name = "ProfileName",
					text = identity.name,
					role = "title",
					size = UDim2.new(1, 0, 0, theme.text.title.height),
					truncate = true,
					layoutOrder = 1,
				})
				P.text(text, {
					name = "ProfileUsername",
					text = identity.username ~= "" and ("@" .. identity.username) or "Your profile",
					role = "caption",
					color = theme.color.textTertiary,
					size = UDim2.new(1, 0, 0, theme.text.caption.height),
					truncate = true,
					layoutOrder = 2,
				})
				local provider = P.row(header, {
					name = "ProfileProviderCard",
					size = UDim2.new(1, 0, 0, providerHeight),
					bg = theme.color.surface,
					radius = theme.radius.sm,
					padding = { x = theme.space.sm },
					gap = theme.space.sm,
					layoutOrder = 2,
				})
				P.text(provider, {
					text = "Provider",
					role = "overline",
					color = theme.color.textTertiary,
					auto = "X",
					layoutOrder = 1,
				})
				local label = P.text(provider, {
					name = "ProfileProvider",
					text = M.providerLabel(),
					role = "caption",
					color = theme.color.textSecondary,
					size = UDim2.new(0, 0, 0, theme.text.caption.height),
					flex = "Fill",
					truncate = true,
					layoutOrder = 2,
				})
				local release = providers.changed:connect(function()
					label.Text = M.providerLabel()
				end)
				header.Destroying:Connect(release)
			end,
		}
	end

	return M
end
end)()

-- ==========================================================================
-- ui/quickchat
-- ==========================================================================
__UAI_MODULES["ui/quickchat"] = (function()
-- Quick chat: one keypress, one message, gone again.
--
-- The window is the place to read a conversation; this is the place to start one
-- without leaving what you were doing. It floats in the middle of the screen, takes
-- a single line, sends to the same session the Chat panel shows -- so whatever is
-- typed here appears there -- and dismisses itself. Nothing about it is a second
-- transcript.
--
-- The key is captured rather than typed into a field: a user thinks "this key", not
-- "Enum.KeyCode.Semicolon", and capturing it also sidesteps mapping characters to
-- key codes across keyboard layouts.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")

	local M = { visible = false, mounted = false }

	local DEFAULT_KEY = "Semicolon"

	-- The bound key as an EnumItem, or nil when the stored name no longer exists.
	function M.keyCode()
		local name = tostring(config.get("ui.quickKey", DEFAULT_KEY))
		local ok, item = pcall(function() return Enum.KeyCode[name] end)
		if ok and item then return item end
		return Enum.KeyCode.Semicolon
	end

	function M.keyName()
		return tostring(config.get("ui.quickKey", DEFAULT_KEY))
	end

	function M.setKey(keyCode)
		local name = keyCode and keyCode.Name or DEFAULT_KEY
		config.set("ui.quickKey", name)
		return name
	end

	function M.mount(layer)
		if M.mounted and M.root and M.root.Parent then return M.root end
		M.visible = false

		M.root = P.frame(layer, {
			name = "QuickChat",
			size = UDim2.fromScale(1, 1),
			zIndex = theme.z.quick,
			visible = false,
		})
		M.root.Active = false

		-- A scrim, so the rest of the screen recedes and a click outside dismisses.
		local scrim = Instance.new("TextButton", M.root)
		scrim.Name = "QuickScrim"
		scrim.Text = ""
		scrim.AutoButtonColor = false
		scrim.BorderSizePixel = 0
		scrim.Size = UDim2.fromScale(1, 1)
		scrim.BackgroundColor3 = theme.color.scrim
		scrim.BackgroundTransparency = 1
		scrim.ZIndex = theme.z.quick
		M.scrim = scrim
		scrim.Activated:Connect(function() M.hide() end)

		local card = P.frame(M.root, {
			name = "QuickCard",
			size = UDim2.new(0, math.min(math.max(responsive.viewport.X * 0.5, theme.size.modal), theme.size.reading * 0.6), 0, 0),
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.42),
			bg = theme.color.surfaceRaised,
			radius = theme.radius.xl,
			clip = true,
			zIndex = theme.z.quick + 1,
		})
		card.Active = true
		local outline = P.stroke(card, theme.color.borderStrong)
		M.card = card
		M.scale = Instance.new("UIScale", card)
		M.scale.Scale = theme.scale.enter
		local scroll = P.scroll(card, { name = "QuickBody", size = UDim2.fromScale(1, 1), padding = theme.space.md, gap = 0 })
		local content, contentLayout = P.column(scroll.instance, {
			name = "QuickContent", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm,
		})

		local head = P.row(content, {
			name = "QuickHeader",
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget())),
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local mark = P.frame(head, {
			name = "QuickBrand", size = UDim2.fromOffset(theme.size.iconLarge, theme.size.iconLarge), layoutOrder = 0,
		})
		env.require("ui/brand").draw(mark, theme.size.iconLarge)
		P.text(head, {
			text = "A thought? A task?",
			role = "heading",
			size = UDim2.new(0, 0, 0, theme.text.heading.height),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		P.iconButton(head, {
			name = "DismissQuickChat", icon = "close",
			diameter = theme.size.controlSmall, layoutOrder = 2,
			onClick = function() M.hide() end,
		})

		M.field = P.field(content, {
			name = "QuickPrompt",
			placeholder = "Tell your agent what you have in mind…",
			bare = true,
			height = theme.size.control,
			layoutOrder = 2,
			onFocus = function() P.animate(outline, "hover", { Color = theme.color.accent }) end,
			onBlur = function() P.animate(outline, "hover", { Color = theme.color.borderStrong }) end,
			onSubmit = function(text) M.submit(text) end,
		})

		local footer = P.row(content, {
			name = "QuickFooter",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			layoutOrder = 3,
		})
		M.hint = P.text(footer, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			truncate = true,
			flex = "Fill",
			layoutOrder = 1,
		})
		P.iconButton(footer, {
			name = "OpenFullChat", icon = "windowMaximize", diameter = theme.size.controlSmall, layoutOrder = 2,
			onClick = function()
				local text = M.field.get()
				local app = env.require("ui/app")
				app.show("chat")
				if app.chatPanel and app.chatPanel.composer then
					if text ~= "" then app.chatPanel.composer.insert(text) end
					M.field.clear()
					M.hide()
					app.chatPanel.composer.focus()
				end
			end,
		})
		P.button(footer, {
			name = "SendQuickChat", text = "Send", icon = "send",
			variant = "primary", size = "sm", layoutOrder = 3,
			onClick = function() M.submit(M.field.get()) end,
		})
		local function layoutCard()
			local bounds = responsive.usableRect(layer, theme.space.md)
			local width = math.min(bounds.width,
				math.max(responsive.viewport.X * 0.5, theme.size.modal), theme.size.reading * 0.6)
			local measured = contentLayout.AbsoluteContentSize
			-- Layout initially reports zero, including while hidden. Keep enough room
			-- for the fixed controls until the first measured pass arrives.
			local minimum = head.Size.Y.Offset + M.field.shell.Size.Y.Offset
				+ math.max(theme.size.controlSmall, responsive.minTarget()) + theme.space.sm * 2
			local wanted = math.max(minimum, measured and measured.Y or 0)
			local height = math.max(1, math.min(bounds.height, wanted + theme.space.md * 2))
			card.Size = UDim2.fromOffset(math.max(math.floor(width), 1), math.floor(height))
			local half = height / 2
			local y = util.clamp(bounds.height * 0.42, math.min(half, bounds.height / 2), math.max(bounds.height / 2, bounds.height - half))
			card.Position = UDim2.fromOffset(math.floor(bounds.x + bounds.width / 2), math.floor(bounds.y + y))
		end
		M.layout = layoutCard
		contentLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(layoutCard)
		layoutCard()
		local unsubscribe = dispose.add(responsive.changed:connect(layoutCard), "quick chat layout")
		local root = M.root
		root.Destroying:Connect(function()
			unsubscribe()
			if M.root == root then M.mounted = false; M.visible = false end
		end)
		local function rebuild()
			if M.root ~= root or not M.mounted then return end
			local text, visible = M.field.get(), M.visible
			root:Destroy()
			M.mount(layer)
			M.field.set(text)
			if visible then M.show() end
		end
		local queueRebuild, cancelRebuild = clock.debounce(rebuild, theme.duration("fast"))
		local stopTheme = dispose.add(theme.changed:connect(queueRebuild), "quick chat theme")
		local stopMode = dispose.add(responsive.modeChanged:connect(queueRebuild), "quick chat mode")
		root.Destroying:Connect(function()
			cancelRebuild()
			stopTheme()
			stopMode()
		end)

		M.mounted = true
		return M.root
	end

	local function refreshHint()
		if not M.hint then return end
		local providers = env.require("provider/registry")
		local record = providers.active()
		M.hint.TextColor3 = theme.color.textTertiary
		M.hint.Text = record
			and string.format("%s  ·  Enter to send  ·  Esc to close",
				tostring(record.label))
			or "No provider configured yet -- open the window and add one."
	end

	function M.show()
		if not M.mounted or M.visible then return end
		M.visible = true
		refreshHint()
		if M.layout then M.layout() end
		M.root.Visible = true
		if responsive.reduceMotion then
			P.animate(M.scale, "instant", { Scale = 1 })
			P.animate(M.scrim, "instant", { BackgroundTransparency = theme.opacity.scrim })
		else
			M.scale.Scale = theme.scale.enter
			M.scrim.BackgroundTransparency = 1
			-- Snapped on completion: a card left mid-tween keeps its field laid out at
			-- 98% of its metrics until the next time it opens.
			P.animate(M.scale, "enter", { Scale = 1 }, function()
				if M.visible then M.scale.Scale = 1 end
			end)
			P.animate(M.scrim, "enter", { BackgroundTransparency = theme.opacity.scrim })
		end
		-- One frame late: capturing focus in the same frame the surface becomes
		-- visible is unreliable.
		local root = M.root
		clock.delay(theme.duration("fast"), function()
			if M.visible and M.root == root then M.field.focus() end
		end)
	end

	function M.hide()
		if not M.mounted or not M.visible then return end
		M.visible = false
		pcall(function() M.field.instance:ReleaseFocus() end)
		if responsive.reduceMotion then
			P.animate(M.scale, "instant", { Scale = 1 })
			P.animate(M.scrim, "instant", { BackgroundTransparency = 1 })
			M.root.Visible = false
			return
		end
		P.animate(M.scale, "exit", { Scale = theme.scale.enter })
		local root = M.root
		P.animate(M.scrim, "exit", { BackgroundTransparency = 1 }, function()
			-- Only hide if nothing reopened it while the tween ran.
			if not M.visible and M.root == root then root.Visible = false end
		end)
	end

	function M.toggle()
		if M.visible then M.hide() else M.show() end
	end

	function M.submit(text)
		local message = util.trim(tostring(text or ""))
		if message == "" then return end
		-- The same session the Chat panel is bound to, so the message and its reply
		-- land in the transcript rather than in a parallel conversation.
		local ok, reason = sessions.current().send(message)
		if ok then
			M.field.clear()
			M.hide()
		else
			-- Rejection is recoverable: keep the prompt in place for a retry instead of
			-- closing and clearing it on the next open.
			if M.hint then
				M.hint.Text = tostring(reason)
				M.hint.TextColor3 = theme.color.warn
			end
			if M.visible and M.field then M.field.focus() end
		end
	end

	-- Bound once, on the service, because the point of the shortcut is that it works
	-- when nothing of this interface has focus.
	function M.bind()
		if M.bound then return end
		M.bound = true

		dispose.connection(env.uis.InputBegan:Connect(function(input, processed)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

			if M.visible then
				if input.KeyCode == Enum.KeyCode.Escape then M.hide() end
				return
			end

			-- `processed` means the keystroke already went somewhere -- a text box, a
			-- CoreGui field. Opening on it would fire every time the bound character is
			-- typed into the composer, which is the one thing that would make this
			-- feature intolerable.
			if processed then return end
			local focused = nil
			pcall(function() focused = env.uis:GetFocusedTextBox() end)
			if focused then return end

			if M.capture then
				local pending = M.capture
				M.capture = nil
				pending(input.KeyCode)
				return
			end

			if input.KeyCode == M.keyCode() then M.show() end
		end))

	end

	-- Settings asks for the next keypress rather than parsing a typed character.
	function M.captureNext(callback)
		M.capture = function(keyCode)
			local name = M.setKey(keyCode)
			if callback then pcall(callback, name) end
		end
	end

	function M.cancelCapture()
		M.capture = nil
	end

	return M
end
end)()

-- ==========================================================================
-- ui/responsive
-- ==========================================================================
__UAI_MODULES["ui/responsive"] = (function()
-- Responsiveness.
--
-- The reference client decided phone-or-desktop once at boot from
-- TouchEnabled-and-not-KeyboardEnabled, and baked two tables of pixel metrics off
-- that. It gets the common cases right and everything else wrong: a tablet, a
-- phone that rotates, a desktop window resized to half width, a console, a device
-- with both touch and a keyboard.
--
-- This module holds no metrics. It reports what the viewport is right now and
-- republishes when that changes, so a surface either adapts continuously (scale
-- based layout, list layouts, automatic sizing) or rebuilds itself when the layout
-- mode genuinely changes -- and the second is debounced, because a desktop window
-- drag fires viewport changes every frame.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local log = env.require("runtime/log")
	local dispose = env.require("runtime/dispose")

	local BREAKPOINTS = {
		{ name = "xs", max = 520 },
		{ name = "sm", max = 900 },
		{ name = "md", max = 1280 },
		{ name = "lg", max = 1700 },
		{ name = "xl", max = math.huge },
	}

	local M = {
		viewport = Vector2.new(1280, 720),
		breakpoint = "md",
		mode = "window",
		orientation = "landscape",
		touch = false,
		pointer = true,
		gamepad = false,
		console = false,
		reduceMotion = false,
		transparency = 1,
		keyboardHeight = 0,
		keyboardTop = nil,
		inset = Vector2.new(0, 0),
		bottomInset = 0,
		changed = signal.new("responsive"),
		modeChanged = signal.new("responsive:mode"),
		ready = false,
	}

	local function breakpointFor(width)
		for _, entry in ipairs(BREAKPOINTS) do
			if width < entry.max then return entry.name end
		end
		return "xl"
	end

	-- Layout mode is the only thing surfaces branch on, and it is derived rather
	-- than configured: a console is gamepad-first regardless of resolution, a
	-- narrow viewport is a sheet whether it is a phone or a small window, and the
	-- user can still pin it by hand in settings.
	--
	-- Orientation matters as much as width. A tablet held portrait is 834 points
	-- wide and 1112 tall; a floating window in that space is a tall thin box, while
	-- a full-height dock reads properly.
	local function modeFor(breakpoint, forced)
		if forced and forced ~= "auto" then return forced end
		if M.console then return "tv" end
		if breakpoint == "xs" then return "sheet" end
		if M.touch and not M.pointer then return "panel" end
		if breakpoint == "sm" then return "panel" end
		if M.orientation == "portrait" then return "panel" end
		return "window"
	end

	local function sample()
		local width, height = 1280, 720

		-- The camera's viewport is the honest number: a ScreenGui's AbsoluteSize is
		-- zero until it renders, and IgnoreGuiInset changes it underneath you.
		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera and camera.ViewportSize and camera.ViewportSize.Y > 0 then
			width, height = camera.ViewportSize.X, camera.ViewportSize.Y
		elseif M.screen and M.screen.AbsoluteSize and M.screen.AbsoluteSize.Y > 0 then
			width, height = M.screen.AbsoluteSize.X, M.screen.AbsoluteSize.Y
		end

		M.viewport = Vector2.new(width, height)
		M.orientation = (height > width) and "portrait" or "landscape"

		local okInput = pcall(function()
			M.touch = env.uis.TouchEnabled == true
			M.pointer = env.uis.MouseEnabled == true
			M.gamepad = env.uis.GamepadEnabled == true
		end)
		if not okInput then M.touch, M.pointer = false, true end
		-- Mobile GUI coordinates can differ from the camera's render resolution.
		-- Use the same measured space for breakpoints, placement and keyboard bounds.
		if M.touch and not M.pointer and M.screenFrame then
			local size = M.screenFrame.AbsoluteSize
			if size.X > 0 and size.Y > 0 then
				width, height = size.X, size.Y
				M.viewport = Vector2.new(width, height)
				M.orientation = height > width and "portrait" or "landscape"
			end
		end

		pcall(function()
			M.console = env.guisvc:IsTenFootInterface() == true
		end)
		pcall(function()
			M.reduceMotion = env.guisvc.ReducedMotionEnabled == true
		end)
		-- The platform preference is the default, not the last word: someone who wants
		-- the motion off in this client and on everywhere else has to be able to say so,
		-- and someone whose platform reports it wrongly has to be able to say the
		-- opposite. "auto" is the setting that defers.
		do
			local wanted = tostring(env.require("runtime/config").get("ui.reduceMotion", "auto"))
			if wanted == "on" then
				M.reduceMotion = true
			elseif wanted == "off" then
				M.reduceMotion = false
			end
		end
		pcall(function()
			local value = tonumber(env.guisvc.PreferredTransparency)
			M.transparency = value and util.clamp(value, 0, 1) or 1
		end)

		-- The topbar overlaps the top of the screen; GetGuiInset reports by how much.
		local platformBottom = 0
		pcall(function()
			local top, bottom = env.guisvc:GetGuiInset()
			if top then M.inset = Vector2.new(top.X, top.Y) end
			if bottom then platformBottom = math.max(0, bottom.Y) end
		end)

		-- Mobile chat and the jump button sit at the bottom on a touch device.
		M.bottomInset = math.max(platformBottom, M.touch and 24 or 0)

		M.keyboardHeight, M.keyboardTop = 0, nil
		pcall(function()
			if env.uis.OnScreenKeyboardVisible then
				local size = env.uis.OnScreenKeyboardSize
				M.keyboardHeight = math.max(0, math.min(height, size and size.Y or 0))
				-- A keyboard can sit above the bottom edge (floating keyboards and
				-- accessory bars). Its reported top is the actual obstruction.
				if M.touch then
					local position = env.uis.OnScreenKeyboardPosition
					if position and position.Y > 0 and size and size.Y > 0 then
						M.keyboardTop = position.Y
					end
				end
			end
		end)

		local config = env.require("runtime/config")
		local previousBreakpoint, previousMode = M.breakpoint, M.mode
		M.breakpoint = breakpointFor(width)
		M.mode = modeFor(M.breakpoint, config.get("ui.layout", "auto"))

		return previousBreakpoint ~= M.breakpoint or previousMode ~= M.mode
	end

	-- Continuous changes fire `changed`; a real mode switch also fires
	-- `modeChanged`, which is the only one that triggers a rebuild.
	local function refresh(reason)
		local wasMobile = M.isMobile()
		local switched = sample()
		switched = switched or wasMobile ~= M.isMobile()
		M.changed:fire({ reason = reason, mode = M.mode, breakpoint = M.breakpoint, viewport = M.viewport })
		if switched then
			log.debug("responsive", string.format("%s -> %s at %dx%d (%s)",
				M.breakpoint, M.mode, M.viewport.X, M.viewport.Y, tostring(reason)))
			M.modeChanged:fire({ mode = M.mode, breakpoint = M.breakpoint })
		end
		if M.isMobile() and M.keyboardHeight > 0 then
			clock.delay(0.05, function() if M.ready then M.revealFocused() end end)
		end
	end

	local debouncedRefresh
	local releases = {}
	local cameraRelease
	local generation = 0

	function M.destroy()
		generation = generation + 1
		for _, release in ipairs(releases) do release() end
		releases = {}
		if cameraRelease then cameraRelease(); cameraRelease = nil end
		if M.screenFrame then M.screenFrame:Destroy(); M.screenFrame = nil end
		M.ready = false
		M.screen = nil
	end

	function M.init(screenGui)
		M.destroy()
		M.screen = screenGui
		-- Measure the coordinate space children actually occupy. ScreenGui's own
		-- origin is not a reliable stand-in for its device-safe content origin.
		local frame = Instance.new("Frame")
		frame.Name = "Viewport"
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.Size = UDim2.fromScale(1, 1)
		frame.Active = false
		frame.Parent = screenGui
		M.screenFrame = frame
		sample()
		M.ready = true

		local mine = generation
		debouncedRefresh = clock.debounce(function()
			if mine == generation then refresh("viewport") end
		end, 0.12)
		local function watch(connection)
			releases[#releases + 1] = dispose.connection(connection, "responsive")
		end
		local function bindCamera()
			if cameraRelease then cameraRelease(); cameraRelease = nil end
			local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
			if okCamera and camera then
				cameraRelease = dispose.connection(camera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh), "viewport")
			end
		end

		bindCamera()
		for _, property in ipairs({ "AbsoluteSize", "AbsolutePosition" }) do
			watch(frame:GetPropertyChangedSignal(property):Connect(debouncedRefresh))
		end
		-- The camera instance itself is replaced on respawn in some games, so the
		-- workspace is watched too.
		pcall(function()
			watch(env.services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
				bindCamera()
				refresh("camera")
			end))
		end)

		-- The on-screen keyboard is not a resize: the viewport does not change, so
		-- it has to be watched separately or the composer ends up behind it.
		for _, property in ipairs({ "OnScreenKeyboardVisible", "OnScreenKeyboardSize", "OnScreenKeyboardPosition" }) do
			pcall(function()
				watch(env.uis:GetPropertyChangedSignal(property):Connect(function() refresh("keyboard") end))
			end)
		end
		pcall(function()
			watch(env.uis.TextBoxFocused:Connect(function()
				if M.isMobile() then clock.delay(0.05, function() if M.ready then M.revealFocused() end end) end
			end))
		end)

		for _, property in ipairs({ "ReducedMotionEnabled", "PreferredTransparency" }) do
			pcall(function()
				watch(env.guisvc:GetPropertyChangedSignal(property):Connect(function() refresh(property) end))
			end)
		end

		pcall(function()
			watch(env.uis.LastInputTypeChanged:Connect(function(inputType)
				local name = tostring(inputType and inputType.Name or "")
				local wasGamepad = M.gamepad
				if name:find("Gamepad") then M.gamepad = true end
				if wasGamepad ~= M.gamepad then refresh("input") end
			end))
		end)

		local config = env.require("runtime/config")
		releases[#releases + 1] = dispose.add(config.changed:connect(function(path)
			if path == "ui.layout" or path == "ui.reduceMotion" then refresh("setting") end
		end), "responsive settings")
		watch(screenGui.Destroying:Connect(function()
			if M.screen == screenGui then M.destroy() end
		end))
		releases[#releases + 1] = dispose.add(function()
			generation = generation + 1
			M.ready = false
			M.screen = nil
			M.screenFrame = nil
		end, "responsive lifetime")

		log.info("responsive", string.format("%s / %s at %dx%d, touch %s, gamepad %s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "yes" or "no", M.gamepad and "yes" or "no"))
		return M
	end

	function M.refresh(reason)
		refresh(reason or "manual")
	end

	-- Hit targets. Apple and Google both land on ~44pt for touch; a pointer can be
	-- served by much less, and cramming a mouse interface to 44px wastes the space
	-- a desktop is buying us.
	function M.minTarget()
		if M.console then return 48 end
		return M.touch and 44 or 28
	end

	function M.isNarrow()
		return M.mode == "sheet"
	end

	function M.isMobile()
		return M.touch and not M.console
			and (not M.pointer or M.mode == "sheet" or M.mode == "panel")
	end

	function M.isCompactHeight()
		return M.viewport.Y < 520 or M.keyboardHeight > 0
	end

	-- Default geometry per mode, in pixels, clamped to the viewport so the window
	-- can never open larger than the screen it is on.
	function M.geometry()
		local width, height = M.viewport.X, M.viewport.Y
		if M.isMobile() then
			-- Keep game space around the panel, with enough reading room on a
			-- phone. Expand remains an explicit, reversible action.
			local portrait = M.orientation == "portrait"
			return {
				width = math.floor(math.min(width * (portrait and 0.96 or 0.6), portrait and 600 or 560)),
				height = math.floor(math.min(height * (portrait and 0.78 or 0.82), 700)),
				anchored = portrait and "bottom" or "right",
			}
		end
		if M.mode == "sheet" then
			return {
				width = width,
				height = math.floor(height * (M.isMobile() and 0.64 or (M.orientation == "portrait" and 0.72 or 0.9))),
				anchored = "bottom",
			}
		end
		if M.mode == "panel" then
			return {
				width = math.floor(util.clamp(width * 0.52, 320, 460)),
				height = M.isMobile() and math.floor(util.clamp(height * 0.74, 220, 560))
					or math.floor(height - M.inset.Y - 24),
				anchored = "right",
			}
		end
		if M.mode == "tv" then
			return {
				width = math.floor(util.clamp(width * 0.62, 720, 1200)),
				height = math.floor(util.clamp(height * 0.7, 420, 760)),
				anchored = "center",
			}
		end
		return {
			width = math.floor(util.clamp(width * 0.44, 460, 780)),
			height = math.floor(util.clamp(height * 0.68, 360, 620)),
			anchored = "center",
		}
	end

	-- How much of the bottom of the screen is unusable: the on-screen keyboard when
	-- it is up, otherwise the platform's own bottom furniture.
	function M.bottomObstruction()
		return math.max(M.keyboardHeight, M.bottomInset)
	end

	function M.parentGeometry(relative)
		if relative == M.screen and M.screenFrame then relative = M.screenFrame end
		local origin = relative and relative.AbsolutePosition or Vector2.new(0, 0)
		local size = relative and relative.AbsoluteSize or M.viewport
		if size.X <= 0 or size.Y <= 0 then size = M.viewport end
		return origin, size
	end

	-- Default placement avoids the top bar. Moving a surface can use the entire
	-- device-safe parent: GetGuiInset describes CoreGui's reserved band, not a
	-- physical obstruction across the whole screen. Treating it as a drag limit
	-- strands both the window and launcher far below the top on some clients.
	function M.usableRect(relative, margin, avoidTopbar)
		margin = margin or 0
		if avoidTopbar == nil and M.isMobile() then avoidTopbar = false end
		local origin, size = M.parentGeometry(relative)
		margin = math.max(0, math.min(margin, (math.min(size.X, size.Y) - 1) / 2))
		local left = (avoidTopbar == false and 0 or math.max(0, M.inset.X - origin.X)) + margin
		local top = (avoidTopbar == false and 0 or math.max(0, M.inset.Y - origin.Y)) + margin
		-- Camera.ViewportSize and GUI pixels can differ under client/display scaling.
		-- Mixing them caps movement at a fraction of the visible screen. Use the
		-- measured GUI extent for both axes, keeping the camera as a boot fallback.
		local screenOrigin, screenSize = M.parentGeometry(M.screen)
		local right = math.min(size.X, screenOrigin.X + screenSize.X - origin.X) - margin
		local bottom = math.min(size.Y, screenOrigin.Y + screenSize.Y - M.bottomObstruction() - origin.Y) - margin
		if M.isMobile() and M.keyboardTop then
			bottom = math.min(size.Y - margin, screenOrigin.Y + screenSize.Y - M.bottomInset - origin.Y - margin,
				M.keyboardTop - origin.Y - margin)
		end
		return { x = left, y = top, width = math.max(1, right - left), height = math.max(1, bottom - top) }
	end

	function M.describe()
		return string.format("%s / %s  %dx%d  %s%s%s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "touch " or "",
			M.gamepad and "gamepad " or "",
			M.reduceMotion and "reduced-motion" or "")
	end

	-- Reveal the active mobile field after the keyboard and its ancestors finish
	-- resizing. Only its scrolling ancestors move; reading another panel stays put.
	function M.revealFocused()
		if not M.isMobile() then return end
		local ok, field = pcall(function() return env.uis:GetFocusedTextBox() end)
		if not ok or not field or not field.Parent or not M.screen or not field:IsDescendantOf(M.screen) then return end
		local node = field.Parent
		while node and node ~= M.screen do
			if node:IsA("ScrollingFrame") and node.ScrollingEnabled and node.Visible then
				local visible = node.AbsoluteWindowSize.Y
				if visible <= 0 then visible = node.AbsoluteSize.Y end
				local margin = M.minTarget() / 4
				local top = node.AbsolutePosition.Y + margin
				local bottom = node.AbsolutePosition.Y + visible - margin
				local y, height = field.AbsolutePosition.Y, field.AbsoluteSize.Y
				local delta = y < top and y - top or (y + height > bottom and math.min(y - top, y + height - bottom) or 0)
				local maximum = math.max(0, node.AbsoluteCanvasSize.Y - visible)
				if visible > 0 and delta ~= 0 then
					node.CanvasPosition = Vector2.new(node.CanvasPosition.X, util.clamp(node.CanvasPosition.Y + delta, 0, maximum))
				end
			end
			node = node.Parent
		end
	end

	return M
end
end)()

-- ==========================================================================
-- ui/settingspanes
-- ==========================================================================
__UAI_MODULES["ui/settingspanes"] = (function()
-- What is in the settings, as a list of panes.
--
-- Two surfaces render these: the Settings panel stacks every pane in one scroll, and
-- the settings dialog the sidebar opens shows one at a time behind a category list.
-- Declaring them once is what keeps the two from drifting -- the dialog used to hold
-- its own copy of three appearance rows, none of which were wired to anything, while
-- the panel held the real ones.
--
-- A pane is `{ id, section, label, icon, build(container) }`. `build` is handed a
-- column to fill and returns nothing; everything it puts there reads and writes
-- config, so nothing has to be re-read when it is shown again.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local configTransfer = env.require("runtime/config_transfer")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local fsx = env.require("runtime/fsx")
	local place = env.require("runtime/place")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local quickchat = env.require("ui/quickchat")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local R = env.require("ui/settingsrows")
	local permissions = env.require("agent/permissions")
	local state = env.require("agent/state")
	local usage = env.require("agent/usage")
	local stats = env.require("agent/stats")
	local registry = env.require("agent/registry")
	local sessions = env.require("agent/session")
	local providers = env.require("provider/registry")
	local ua = env.require("net/ua")
	local http = env.require("net/http")
	local bridgeModule = env.require("net/bridge")

	local M = {}

	-- The token budgets. They stop where the widest models of the moment do -- a
	-- million in, a hundred and twenty-eight thousand out -- rather than where a
	-- default conversation needs, because a ceiling that cannot reach the model is
	-- indistinguishable from the model not having it.
	local BUDGET_STOPS = {
		4000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000,
		128000, 160000, 200000, 256000, 320000, 400000, 512000, 750000, 1000000,
	}
	local REPLY_STOPS = { 256, 512, 1024, 2048, 4096, 8192, 16000, 24000, 32000, 64000, 96000, 128000 }
	local RESULT_STOPS = { 1000, 2000, 4000, 6000, 8000, 12000, 16000, 24000, 32000, 48000, 64000, 96000, 128000 }

	-- The request timeout. The top stop is the default and is the highest of any
	-- clock in this client: no other deadline can rescue a model call that times out,
	-- so it has to sit above every other budget by default. The stops are the
	-- plausible lowerings rather than a linear scale -- the difference between sixty
	-- seconds and ninety is a setting someone might want, and the difference between
	-- eight hours and nine is not.
	local REQUEST_STOPS = { 30, 60, 120, 180, 300, 600, 900, 1800, 3600, 7200, 21600, 43200, 86400 }

	-- Each pane builds into a fresh column, so the layout order it needs is just a
	-- running count. This is the only bookkeeping a pane does.
	local function builder(container)
		local order = 0
		local api = {}
		function api.order()
			order = order + 1
			return order
		end
		-- A heading and its card go in one wrapper with a tight gap.
		--
		-- They used to be two siblings of the pane's own column, which means the distance
		-- from a heading to the card it labels was the pane's uniform gap -- exactly the
		-- distance from that heading to the card *above* it. Nothing in the layout said
		-- which block a heading belonged to, and a pane of six sections read as twelve
		-- unrelated things.
		function api.section(title, description)
			local group = P.column(container, {
				name = "Group",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = api.order(),
			})
			P.sectionHeader(group, { title = title, description = description, layoutOrder = 1 })
			return P.card(group, { layoutOrder = 2, gap = theme.space.md })
		end
		function api.note(text, colour)
			return R.paragraph(container, text, { color = colour, layoutOrder = api.order() })
		end
		return api
	end

	local function accentOptions()
		local out = {}
		for key, entry in pairs(theme.ACCENTS) do
			out[#out + 1] = { value = key, label = entry.label }
		end
		table.sort(out, function(a, b) return a.label < b.label end)
		return out
	end

	-- General -----------------------------------------------------------------

	local function paneGeneral(container)
		local build = builder(container)

		local appearance = build.section("Appearance",
			"Layout follows the viewport by default. Pin it if you would rather it did not.")

		P.text(appearance, { text = "Accent", role = "small" })
		C.segmented(appearance, {
			options = accentOptions(),
			value = config.get("ui.accent", "claude"),
			onChange = function(value) config.set("ui.accent", value) end,
		})

		P.text(appearance, { text = "Density", role = "small" })
		C.segmented(appearance, {
			options = {
				{ value = "comfortable", label = "Comfortable" },
				{ value = "compact", label = "Compact" },
			},
			value = config.get("ui.density", "comfortable"),
			onChange = function(value) config.set("ui.density", value) end,
		})

		P.text(appearance, { text = "Layout", role = "small" })
		C.segmented(appearance, {
			options = {
				{ value = "auto", label = "Auto" },
				{ value = "sheet", label = "Sheet" },
				{ value = "panel", label = "Panel" },
				{ value = "window", label = "Window" },
			},
			value = config.get("ui.layout", "auto"),
			onChange = function(value) config.set("ui.layout", value) end,
		})

		R.number(appearance, "Text scale", "Multiplies every type size.", "ui.fontScale", 0.85, 1.4, 0.05)
		R.segmented(appearance, {
			name = "ReduceMotion",
			label = "Reduce motion",
			hint = "Auto follows the platform's own accessibility preference.",
			path = "ui.reduceMotion",
			options = {
				{ value = "auto", label = "Auto" },
				{ value = "on", label = "On" },
				{ value = "off", label = "Off" },
			},
		})
		R.toggle(appearance, {
			label = "Show reasoning",
			hint = "Display the model's chain of thought when it sends one. Applies to the conversation already on screen.",
			path = "ui.showReasoning",
		})
		R.toggle(appearance, {
			label = "Show the code a tool was given",
			hint = "Draws the Luau, the file body or the property map a tool call carries under its "
				.. "row, outside the fold. Off, it is still there behind the row's own caret.",
			path = "ui.showToolCode",
		})
		R.toggle(appearance, {
			label = "Expand tool detail",
			hint = "Open the remaining arguments and the result by default, rather than on the first click.",
			path = "ui.showToolDetail",
		})
		R.toggle(appearance, {
			label = "Show token counts",
			hint = "Token and cost details in the composer's options menu.",
			path = "ui.showUsage",
		})
		R.toggle(appearance, {
			label = "Show the activity card",
			hint = "The greeting and the counters an empty conversation opens with.",
			path = "ui.showActivity",
		})
		R.toggle(appearance, {
			label = "Notify while minimized",
			hint = "A toast when a turn finishes, fails or is stopped with the window closed -- from any conversation. The count on the launcher appears either way.",
			path = "ui.notifications",
		})

		-- Built here rather than after the section below it, because nothing in this
		-- card sets a layout order: the rows appear in the order they are created, and a
		-- note constructed later landed wherever the tie-break put it.
		local viewportNote = P.text(appearance, {
			text = "Now: " .. responsive.describe(),
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		viewportNote.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = responsive.changed:connect(function()
			if not viewportNote.Parent then return end
			viewportNote.Text = "Now: " .. responsive.describe()
		end)
		viewportNote.Destroying:Connect(function() pcall(unsubscribe) end)

		local shortcuts = build.section("Shortcuts",
			"Quick chat opens in the middle of the screen, takes one message to the conversation the Chat panel shows, and closes itself.")
		local row = P.row(shortcuts, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm })
		local text = P.column(row, {
			size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
		})
		P.text(text, { text = "Quick chat key", role = "small" })
		local keyHint = P.text(text, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local keyButton
		local function describeKey()
			keyHint.Text = "Currently " .. quickchat.keyName()
				.. ". Press the button, then the key you want it to be."
		end
		keyButton = P.button(row, {
			name = "QuickKey",
			text = quickchat.keyName(),
			variant = "secondary",
			size = "sm",
			width = theme.size.keyColumn + theme.space.xxl,
			layoutOrder = 2,
			onClick = function()
				keyButton.setText("press a key")
				-- Captured rather than typed: a user thinks "this key", and a character
				-- would not survive a different keyboard layout.
				quickchat.captureNext(function(name)
					if not keyButton.instance.Parent then return end
					keyButton.setText(name)
					describeKey()
				end)
			end,
		})
		keyButton.instance.LayoutOrder = 2
		describeKey()
	end

	-- Privacy -----------------------------------------------------------------

	local function paneprivacy(container)
		local build = builder(container)

		local where = build.section("Where your data goes",
			"This client has no telemetry and no home to call. The only outbound requests it "
			.. "makes are the ones listed here, and every one of them is somewhere you added.")

		local list = {}
		for _, record in ipairs(providers.list()) do
			if record.enabled ~= false then
				list[#list + 1] = {
					key = record.label,
					value = record.baseUrl,
					tone = record.id == (providers.active() or {}).id and "good" or nil,
				}
			end
		end
		if config.get("bridge.enabled", false) == true then
			list[#list + 1] = { key = "Web bridge", value = bridgeModule.status().url }
		end
		if #list == 0 then
			build.note("Nothing is configured, so nothing leaves this machine at all.")
		else
			R.facts(container, list, { name = "Endpoints", layoutOrder = build.order() })
		end

		local secrets = build.section("Keys and logs",
			"An API key is stored in the settings file so a request can be signed with it. "
			.. "Request logs and diagnostic exports reduce API keys to their last four characters. "
			.. "Full configuration export keeps all credentials so you can transfer settings; keep that copy private.")
		R.toggle(secrets, {
			label = "Mirror the log to the console",
			hint = "Also print every entry with print/warn, which a developer console can read.",
			path = "logs.mirror",
			onChange = function(value) log.mirror = value == true end,
		})
		P.text(secrets, { text = "Level", role = "small" })
		C.segmented(secrets, {
			options = {
				{ value = "debug", label = "Debug" },
				{ value = "info", label = "Info" },
				{ value = "warn", label = "Warn" },
				{ value = "error", label = "Error" },
			},
			value = config.get("logs.level", "info"),
			onChange = function(value)
				config.set("logs.level", value)
				log.setLevel(value)
			end,
		})

		local clear = build.section("Clear what is stored",
			"Each of these is immediate and cannot be undone.")
		R.actions(clear, {
			{
				name = "ClearRequests",
				text = "Request history",
				variant = "ghost",
				onClick = function()
					http.clearHistory()
					overlay.toast("Request history cleared", "good", 2)
				end,
			},
			{
				name = "ClearLog",
				text = "Log",
				variant = "ghost",
				onClick = function()
					log.clear()
					overlay.toast("Log cleared", "good", 2)
				end,
			},
			{
				name = "ClearConversations",
				text = "All conversations",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Delete every conversation?",
						description = "Every transcript on disk is removed. The activity counters are kept.",
						confirmText = "Delete",
						danger = true,
						onConfirm = function()
							for _, session in ipairs(sessions.list()) do
								sessions.remove(session.id)
							end
							overlay.toast("Conversations deleted", "good", 2)
						end,
					})
				end,
			},
			{
				name = "ClearActivity",
				text = "Activity history",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset the activity history?",
						description = "Every day, model and token count this client has recorded is discarded. "
							.. "The conversations themselves are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							stats.reset()
							overlay.toast("Activity history reset", "good", 2)
						end,
					})
				end,
			},
		})
	end

	-- Usage -------------------------------------------------------------------

	local function paneUsage(container)
		local build = builder(container)

		local live = build.section("This session",
			"What the client has spent since it started, as the provider reported it.")
		local liveText = P.text(live, {
			name = "UsageLine",
			text = usage.line(),
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		liveText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = usage.changed:connect(function()
			if not liveText.Parent then return end
			liveText.Text = usage.line()
		end)
		liveText.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(live, { {
			name = "ResetCounters",
			text = "Reset counters",
			variant = "ghost",
			onClick = function() usage.reset() end,
		} })

		local window = stats.window("all")
		local totals = build.section("Everything recorded",
			"Counted from what this client observed and kept on disk, so it survives a restart.")
		local facts = {
			{ key = "Conversations", value = util.formatNumber(window.sessions) },
			{ key = "Messages", value = util.formatNumber(window.messages) },
			{ key = "Requests", value = util.formatNumber(window.requests) },
			{ key = "Tokens in", value = util.formatNumber(window.tokensIn) },
			{ key = "Tokens out", value = util.formatNumber(window.tokensOut) },
			{ key = "Tool calls", value = util.formatNumber(window.toolCalls) },
			{ key = "Active days", value = util.formatNumber(window.activeDays) },
		}
		local cost = usage.formatCost(window.cost)
		if cost ~= "" then
			facts[#facts + 1] = { key = "Cost", value = cost .. (window.estimated and " (some estimated)" or "") }
		end
		if window.tokensFrom then
			facts[#facts + 1] = { key = "Tokens since", value = clock.describeDay(clock.dayKey(window.tokensFrom)) }
		end
		R.facts(totals, facts, { name = "Totals" })
		if not window.tokensFrom then
			R.paragraph(totals,
				"No request has been recorded yet, so there are no token counts. Messages and "
				.. "conversations from before counting began were read back out of the transcripts "
				.. "already on disk; tokens could not be, because nothing recorded them.")
		end

		if #window.models > 0 then
			local models = build.section("By model", "Which model spent what.")
			for index, row in ipairs(window.models) do
				C.keyValue(models, {
					key = row.id,
					value = string.format("%s tokens  %s  %d%%",
						util.formatCompact(row.tokens), util.pluralise(row.requests, "request"),
						math.floor((row.share or 0) * 100 + 0.5)),
					layoutOrder = index,
				})
			end
		end

		local tools = stats.topTools(8)
		if #tools > 0 then
			local toolCard = build.section("Most used tools", "Across every conversation.")
			for index, entry in ipairs(tools) do
				C.keyValue(toolCard, {
					key = entry.name,
					value = util.formatNumber(entry.count),
					layoutOrder = index,
				})
			end
		end
	end

	-- Claude Code -------------------------------------------------------------

	-- A live sample of one code palette, drawn in that palette's own colours rather
	-- than the active one -- which is what lets both be shown side by side and picked
	-- by pressing the one you want, the way the reference client does it.
	local function codePreview(parent, name, order, onPick)
		local palette = theme.CODE_THEMES[name] or theme.CODE_THEMES.dark
		local selected = theme.codeThemeName == name
		local lineHeight = theme.text.monoSmall.height + theme.space.hair
		-- Four sample lines, a bar, and the two hair-thin paddings around them. Stated
		-- once and passed as the card's own size: P.rowButton takes `size` when it is
		-- given one and ignores `height` unless the button is auto-sizing, so passing
		-- both -- with a zero height in the size -- gave the card no height at all and
		-- spilled a hundred pixels of preview over the control below it.
		local cardHeight = lineHeight * 4 + theme.size.rowTight + theme.space.hair * 2
		local card = P.rowButton(parent, {
			name = "CodePreview_" .. name,
			vertical = true,
			size = UDim2.new(0.5, -theme.space.sm, 0, cardHeight),
			height = cardHeight,
			bg = palette.surface,
			radius = theme.radius.md,
			gap = 0,
			padding = theme.space.hair,
			alignY = "Top",
			clip = true,
			stroke = true,
			strokeColor = selected and theme.color.accent or palette.border,
			bgHover = palette.surface,
			bgPress = palette.surface,
			bgSelected = palette.surface,
			selected = selected,
			layoutOrder = order,
			onClick = function()
				config.set("ui.codeTheme", name)
				if onPick then pcall(onPick, name) end
			end,
		})

		local head = P.row(card.row, {
			name = "PreviewBar",
			size = UDim2.new(1, 0, 0, theme.size.rowTight),
			bg = palette.bar,
			padding = { x = theme.space.xs },
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.text(head, {
			text = palette.label,
			role = "caption",
			color = palette.gutter,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		if selected then
			local mark = P.frame(head, {
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 2,
			})
			icons.check(mark, theme.size.icon, theme.color.accent)
		end

		local lines = {
			{ number = 1, prefix = " ", text = "local function greet(name)" },
			{ number = 2, prefix = "-", text = 'return "Hello, " .. name', tone = "remove" },
			{ number = 2, prefix = "+", text = 'return string.format("Hi %s!", name)', tone = "add" },
			{ number = 3, prefix = " ", text = "end" },
		}
		for index, line in ipairs(lines) do
			local fill, ink = nil, palette.text
			if line.tone == "add" then
				fill, ink = palette.addSurface, palette.addText
			elseif line.tone == "remove" then
				fill, ink = palette.removeSurface, palette.removeText
			end
			local row = P.row(card.row, {
				name = "Line" .. tostring(index),
				size = UDim2.new(1, 0, 0, lineHeight),
				bg = fill,
				gap = theme.space.xs,
				padding = { x = theme.space.xs },
				layoutOrder = index + 1,
			})
			P.text(row, {
				text = tostring(line.number),
				role = "monoSmall",
				color = palette.gutter,
				align = "Right",
				size = UDim2.fromOffset(theme.space.md, theme.text.monoSmall.height),
				layoutOrder = 1,
			})
			P.text(row, {
				text = line.prefix,
				role = "monoSmall",
				color = ink,
				size = UDim2.fromOffset(theme.space.sm, theme.text.monoSmall.height),
				layoutOrder = 2,
			})
			P.text(row, {
				text = line.text,
				role = "monoSmall",
				color = ink,
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				truncate = true,
				layoutOrder = 3,
			})
		end
		return card
	end

	local function paneClaudeCode(container)
		local build = builder(container)

		local appearance = build.section("Code appearance",
			"How a fenced code block is drawn, in the transcript and everywhere else. "
			.. "Press one to use it.")
		local row = P.row(appearance, {
			name = "CodeThemes",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			alignY = "Top",
		})
		for index, key in ipairs(theme.CODE_THEME_ORDER) do
			codePreview(row, key, index)
		end

		local fontOptions = {}
		for _, key in ipairs(theme.CODE_ORDER) do
			fontOptions[#fontOptions + 1] = { value = key, label = theme.CODE_FONTS[key].label }
		end
		R.segmented(appearance, {
			name = "CodeFont",
			label = "Code font",
			hint = "The monospace family for code and diagnostics. Roblox renders from a fixed "
				.. "set of families, so this offers the ones that exist rather than a box to type "
				.. "a font name into that could not be loaded.",
			path = "ui.codeFont",
			options = fontOptions,
		})

		local interface = build.section("Appearance",
			"The type the interface itself is set in.")
		local interfaceOptions = {}
		for _, key in ipairs(theme.INTERFACE_ORDER) do
			interfaceOptions[#interfaceOptions + 1] = { value = key, label = theme.INTERFACE_FONTS[key].label }
		end
		R.select(interface, {
			name = "InterfaceFont",
			label = "Interface font",
			hint = "Menus, the sidebar and the transcript. Only the families this client can "
				.. "actually load are listed -- the list is probed against the engine rather than "
				.. "declared, so it is shorter on an older client than a longer one.",
			path = "ui.interfaceFont",
			options = interfaceOptions,
		})
		-- What is being rendered, as opposed to what is selected. Two clients can resolve
		-- the same setting differently: the weight axis needs the modern type stack, and
		-- without it every "medium" role falls back to whichever legacy member pairs that
		-- family with a heavier weight. Saying so is cheaper than someone wondering why
		-- their headings look the same as their body text.
		R.paragraph(interface, string.format("Now: %s, %s.",
			theme.interfaceFontName,
			theme.hasFontFace and "with the regular/medium/semibold weight axis"
				or "weights from the legacy font set on this client"))

		-- Text size is the same setting as the scale slider under General, expressed the
		-- way the reference client expresses it. One value, two controls: the segmented
		-- one reads the scale back rather than keeping a second copy of it.
		local scale = tonumber(config.get("ui.fontScale", 1)) or 1
		local currentSize = "medium"
		if scale < 0.95 then currentSize = "small" end
		if scale > 1.08 then currentSize = "large" end
		R.segmented(interface, {
			name = "TranscriptSize",
			label = "Transcript text size",
			hint = "The same value as the text scale under General.",
			value = currentSize,
			options = {
				{ value = "small", label = "Small" },
				{ value = "medium", label = "Medium" },
				{ value = "large", label = "Large" },
			},
			onChange = function(value)
				local scales = { small = 0.9, medium = 1, large = 1.15 }
				config.set("ui.fontScale", scales[value] or 1)
			end,
		})

		R.segmented(interface, {
			name = "TranscriptWidth",
			label = "Transcript width",
			hint = "The widest the transcript and the composer will grow on a large screen.",
			path = "ui.transcriptWidth",
			options = {
				{ value = "narrow", label = "Narrow" },
				{ value = "medium", label = "Medium" },
				{ value = "wide", label = "Wide" },
			},
		})
	end

	-- Cowork ------------------------------------------------------------------

	local function paneCowork(container)
		local build = builder(container)
		build.section("Cowork",
			"A browser on this machine can join the conversation that is open here. Both sides "
			.. "dial out to a small local process, because a Roblox client cannot accept a "
			.. "connection.")
		env.require("ui/panels/cowork").rows(container, { layoutOrder = build.order() })
		build.order()
	end

	-- Import and export -------------------------------------------------------

	local EXPORT_DIR = "export"

	-- What an export contains, and what it deliberately does not.
	local function exportPayload()
		local settings = util.deepCopy(config.data)
		-- The keys are the one thing that must not be copied into a second file. Kept as
		-- their last four characters so an exported provider list is still readable as a
		-- list of providers.
		for _, record in ipairs(util.get(settings, "providers.list", {}) or {}) do
			local key = tostring(record.apiKey or "")
			if key ~= "" then record.apiKey = "..." .. key:sub(-4) end
		end
		settings.bridge = settings.bridge or {}
		if util.trim(tostring(settings.bridge.token or "")) ~= "" then
			settings.bridge.token = "(removed)"
		end
		return {
			exportedAt = clock.ms(),
			version = env.info and env.info.version or "",
			place = place.facts(),
			settings = settings,
			activity = stats.data,
		}
	end

	local function fullConfigImport()
		local modal = overlay.modal({
			title = "Import full configuration",
			description = "Paste the private JSON copied by Full configuration export. Review it before replacing your settings.",
			width = theme.size.modalWide,
			height = theme.size.dialogTall,
			scroll = true,
		})
		if not modal then return end
		local candidate, applyButton
		local status = P.text(modal.content, {
			name = "ConfigImportStatus",
			text = "Paste your JSON below, then select Review.",
			role = "small",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 1,
		})
		local field = P.field(modal.content, {
			name = "ConfigImportJSON",
			placeholder = '{"format":"project-uai-config","version":1,...}',
			role = "monoSmall",
			multiline = true,
			height = theme.text.monoSmall.height * 8 + theme.space.md * 2,
			layoutOrder = 2,
			onChange = function()
				candidate = nil
				if applyButton then applyButton.setEnabled(false) end
				status.Text = "Select Review to validate this configuration."
				status.TextColor3 = theme.color.textSecondary
			end,
		})
		P.text(modal.content, {
			text = "Applying replaces providers, credentials, permissions, and all saved preferences. Conversations, activity history, workspace files, and skill files stay on this device.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
		})
		P.button(modal.footer, {
			text = "Cancel", variant = "ghost", size = "sm", layoutOrder = 1,
			onClick = function() modal.close() end,
		})
		P.button(modal.footer, {
			name = "ReviewConfigImport", text = "Review", size = "sm", layoutOrder = 2,
			onClick = function()
				local preview, err = configTransfer.preview(field.get())
				candidate = preview
				applyButton.setEnabled(preview ~= nil)
				if not preview then
					status.Text = tostring(err)
					status.TextColor3 = theme.color.warn
					return
				end
				local summary = preview.summary
				status.Text = string.format("Ready to import\n%s · %s\nActive provider: %s\nPermission mode: %s · %s\n%s · Bridge %s",
					util.pluralise(summary.providers, "provider"), util.pluralise(summary.keys, "API key"),
					util.ellipsis(summary.active, 64), permissions.MODE_LABELS[summary.permissionMode] or summary.permissionMode,
					util.pluralise(summary.rules, "rule"), util.pluralise(summary.memory, "memory entry"),
					summary.bridgeEnabled and "enabled" or "disabled")
				status.TextColor3 = theme.color.text
			end,
		})
		applyButton = P.button(modal.footer, {
			name = "ApplyConfigImport", text = "Apply", variant = "primary", size = "sm", layoutOrder = 3,
			enabled = false,
			onClick = function()
				if not candidate then return end
				local ok, persisted = configTransfer.apply(candidate)
				if not ok then
					status.Text = tostring(persisted)
					status.TextColor3 = theme.color.warn
					return
				end
				log.setLevel(config.get("logs.level", "info"))
				log.mirror = config.get("logs.mirror", false) == true
				providers.changed:fire("import")
				permissions.changed:fire("import")
				state.memoryChanged:fire(config.get("memory.entries", {}))
				env.require("runtime/skills").changed:fire(nil, nil)
				modal.close(true)
				-- The Settings dialog survives app rebuilds, so close its stale controls.
				for index = #overlay.open, 1, -1 do
					local entry = overlay.open[index]
					if entry.card and entry.card.Name == "SettingsDialog" then entry.close() end
				end
				overlay.toast(persisted and "Full configuration imported and saved" or "Configuration imported for this session", "good", 4)
			end,
		})
		clock.delay(theme.duration("fast"), function()
			if not modal.closed then field.focus() end
		end)
	end

	local function paneImportExport(container)
		local build = builder(container)

		local transfer = build.section("Full configuration",
			"Copy every saved setting to another device, including provider records, API keys and key pools, custom headers and parameters, permissions, and preferences. This JSON includes credentials; keep it private.")
		R.paragraph(transfer,
			"Conversations, activity history, workspace files, and skill files are not included. Saved memory and skill preferences are included.")
		local copyButton = P.button(transfer, {
			name = "CopyFullConfig",
			text = "Copy config · includes API keys",
			variant = "secondary",
			fill = true,
			enabled = caps.clipboard,
			onClick = function()
				local copied, err = configTransfer.copyToClipboard(caps.fn.clipboard)
				overlay.toast(copied and "Full configuration copied, including API keys" or tostring(err), copied and "good" or "warn", 4)
			end,
		})
		copyButton.setEnabled(caps.clipboard)
		if not caps.clipboard then
			R.paragraph(transfer, "This host cannot write to the clipboard. You can still paste an export to import it.")
		end
		P.button(transfer, {
			name = "PasteFullConfig", text = "Paste configuration to import", fill = true,
			onClick = fullConfigImport,
		})

		local out = build.section("Diagnostic export",
			"Writes a copy of your settings and the activity history into the client's own "
			.. "folder. API keys are reduced to their last four characters and the bridge token "
			.. "is dropped. Custom fields may still contain credentials, so review before sharing.")
		local outPath = EXPORT_DIR .. "/uai-export.json"
		local result = P.text(out, {
			name = "ExportResult",
			text = fsx.enabled and ("Will write " .. fsx.root .. "/" .. outPath)
				or "This host has no filesystem, so an export can only go to the clipboard.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		result.Size = UDim2.new(1, 0, 0, 0)

		local actions = {}
		if fsx.enabled then
			actions[#actions + 1] = {
				name = "ExportFile",
				text = "Export to a file",
				variant = "secondary",
				onClick = function()
					local ok, err = fsx.writeJson(outPath, exportPayload())
					result.Text = ok and ("Written to " .. fsx.root .. "/" .. outPath)
						or ("Could not write it: " .. tostring(err))
					overlay.toast(ok and "Exported" or "Export failed", ok and "good" or "warn", 2)
				end,
			}
		end
		if caps.clipboard then
			actions[#actions + 1] = {
				name = "ExportClipboard",
				text = "Copy to clipboard",
				variant = "ghost",
				onClick = function()
					local okEncode, body = pcall(util.encode, exportPayload())
					if not okEncode then
						overlay.toast("Could not encode the export", "warn", 2)
						return
					end
					local ok = pcall(caps.fn.clipboard, body)
					overlay.toast(ok and "Copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			}
		end
		if #actions > 0 then R.actions(out, actions) end

		local inbound = build.section("Import",
			"Reads a file from the client's folder and applies the settings in it. Providers, "
			-- Being explicit about this: an import that silently replaced a working key
			-- with "...abcd" from an export would break the client in a way that looks
			-- like the provider rejecting you.
			.. "keys and the bridge token are never imported, because an export does not "
			.. "contain them.")
		local importResult = P.text(inbound, {
			name = "ImportResult",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		importResult.Size = UDim2.new(1, 0, 0, 0)
		R.actions(inbound, { {
			name = "ImportFile",
			text = "Import from a file",
			variant = "secondary",
			onClick = function()
				overlay.prompt({
					title = "Import settings",
					description = "A path inside " .. fsx.root .. ", as it appears in the folder.",
					placeholder = EXPORT_DIR .. "/uai-export.json",
					value = outPath,
					confirmText = "Import",
					onConfirm = function(path)
						local data = fsx.readJson(path, nil)
						local incoming = type(data) == "table" and (data.settings or data) or nil
						if type(incoming) ~= "table" then
							importResult.Text = "Nothing readable at " .. tostring(path)
							return
						end
						local applied = 0
						for _, section in ipairs({ "ui", "agent", "logs", "identity" }) do
							if type(incoming[section]) == "table" then
								config.set(section, util.merge(config.get(section, {}), incoming[section]))
								applied = applied + 1
							end
						end
						importResult.Text = applied > 0
							and (util.pluralise(applied, "section") .. " imported")
							or "That file had no settings in it"
						overlay.toast(importResult.Text, applied > 0 and "good" or "warn", 2)
					end,
				})
			end,
		} })
	end

	-- Desktop app -------------------------------------------------------------

	local function paneDesktop(container)
		local build = builder(container)

		local shell = build.section("Window",
			"Where the interface opens and how much of the screen it takes.")
		R.segmented(shell, {
			name = "OpenPanel",
			label = "Open on",
			hint = "Which surface the interface shows when it is opened.",
			path = "ui.panel",
			options = {
				{ value = "chat", label = "Chat" },
				{ value = "cowork", label = "Cowork" },
				{ value = "providers", label = "Providers" },
				{ value = "tools", label = "Tools" },
				{ value = "logs", label = "Logs" },
			},
		})
		R.toggle(shell, {
			label = "Start with the sidebar collapsed",
			hint = "The conversation list can always be brought back with the toggle in the header.",
			path = "ui.sidebarCollapsed",
		})
		R.toggle(shell, {
			label = "Keep the panel list open",
			hint = "Whether the sidebar's More section starts expanded.",
			path = "ui.sidebarExpanded",
		})
		R.actions(shell, {
			{
				name = "ResetWindow",
				text = "Reset window position",
				variant = "ghost",
				onClick = function()
					config.set("ui.window", util.deepCopy(util.get(config.defaults, "ui.window")))
					overlay.toast("Window position reset", "good", 2)
				end,
			},
			{
				name = "ResetLauncher",
				text = "Reset the launcher",
				variant = "ghost",
				onClick = function()
					config.set("ui.launcher", util.deepCopy(util.get(config.defaults, "ui.launcher")))
					overlay.toast("Launcher reset", "good", 2)
				end,
			},
		})

		local host = build.section("This host",
			"What the client found when it started. None of it is configurable; all of it "
			.. "decides what works.")
		local facts = {
			{ key = "Client", value = tostring(env.info and env.info.version or "") },
			{ key = "Transport", value = caps.http .. (caps.requestName and (" (" .. caps.requestName .. ")") or "") },
			{ key = "Identity", value = caps.uaSupported and "can be sent" or "cannot be sent here", tone = caps.uaSupported and "good" or "warn" },
			{ key = "Filesystem", value = caps.fs and "yes" or "no", tone = caps.fs and "good" or "warn" },
			{ key = "Executor", value = caps.executor },
			{ key = "Viewport", value = responsive.describe() },
		}
		if caps.studio then facts[#facts + 1] = { key = "Studio", value = "yes" } end
		for _, entry in ipairs(place.facts()) do facts[#facts + 1] = entry end
		R.facts(host, facts, { name = "HostFacts" })
	end

	-- Developer ---------------------------------------------------------------

	local function paneDeveloper(container)
		local build = builder(container)

		local logs = build.section("Diagnostics",
			"Every request and every log line the client has kept, and what it keeps them for.")
		local counts = P.text(logs, {
			name = "LogCounts",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		counts.Size = UDim2.new(1, 0, 0, 0)
		local function describeCounts()
			counts.Text = string.format("%s in the request history\n%s in the log\n%s registered for cleanup",
				util.pluralise(#http.history, "entry"),
				util.pluralise(#log.entries, "line"),
				util.pluralise(env.require("runtime/dispose").count(), "handle"))
		end
		describeCounts()
		R.actions(logs, {
			{
				name = "OpenLogs",
				text = "Open the log",
				variant = "secondary",
				onClick = function()
					env.require("ui/app").show("logs")
				end,
			},
			{
				name = "RefreshCounts",
				text = "Refresh",
				variant = "ghost",
				onClick = describeCounts,
			},
			{
				name = "CopyDiagnostics",
				text = "Copy diagnostics",
				variant = "ghost",
				onClick = function()
					local report = table.concat({
						"UAI " .. tostring(env.info and env.info.version or ""),
						caps.summary(),
						responsive.describe(),
						place.describe(),
						ua.describe(),
						usage.line(),
						log.export(),
					}, "\n")
					if caps.clipboard then
						local ok = pcall(caps.fn.clipboard, report)
						overlay.toast(ok and "Diagnostics copied" or "Could not reach the clipboard",
							ok and "good" or "warn", 2)
					else
						log.info("diagnostics", report)
						overlay.toast("No clipboard here, so it went to the log", "info", 3)
					end
				end,
			},
		})

		local identity = build.section("Client identity",
			"Requests are sent as the Claude Code CLI. Gateways that gate on it accept them; "
			.. "others ignore the extra headers.")
		R.toggle(identity, {
			label = "Send the Claude Code identity",
			hint = "Applies to every inference request.",
			path = "identity.claudeUa",
		})
		R.field(identity, {
			name = "IdentityVersion",
			path = "identity.version",
			placeholder = ua.DEFAULT_VERSION,
			transform = function(text)
				if util.trim(text) == "" then return ua.DEFAULT_VERSION end
				return util.trim(text)
			end,
		})
		local identityBox = P.frame(identity, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			padding = theme.space.sm,
		})
		P.stroke(identityBox, theme.color.codeBorder)
		local identityText = P.text(identityBox, {
			text = ua.describe(),
			role = "monoSmall",
			color = theme.color.codeText,
			wrap = true,
			auto = "Y",
		})
		identityText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = config.changed:connect(function(path)
			if not identityText.Parent then return end
			if path == nil or util.startsWith(tostring(path), "identity.") then
				identityText.Text = ua.describe()
			end
		end)
		identityText.Destroying:Connect(function() pcall(unsubscribe) end)
		if not caps.uaSupported then
			R.paragraph(identity,
				"This host has no executor HTTP function, so Roblox sends its own User-Agent and "
				.. "drops ours. Everything else still works.", { color = theme.color.warn })
		end

		local danger = build.section("Reset",
			"Providers, permission rules and memory are kept unless you say otherwise.")
		R.actions(danger, {
			{
				name = "ResetSettings",
				text = "Reset all settings",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset every setting?",
						description = "Appearance and agent settings go back to defaults. Providers, rules and memory are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							config.reset("ui")
							config.reset("agent")
							overlay.toast("Settings reset", "good")
						end,
					})
				end,
			},
			{
				name = "UnloadUai",
				text = "Unload UAI",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Unload UAI?",
						description = "Stops the current turn, drains every timer and input handler, saves your settings and removes the interface. Run the loader again to come back.",
						confirmText = "Unload",
						danger = true,
						onConfirm = function()
							-- The handle the bootstrap published, which is the only thing
							-- holding the disposer registry and the ScreenGui together.
							local globals = (type(getgenv) == "function") and getgenv() or nil
							local live = globals and globals.UAI
							if live and live.destroy then
								live.destroy()
							else
								env.require("runtime/dispose").drain()
								pcall(function() env.require("ui/app").screen:Destroy() end)
							end
						end,
					})
				end,
			},
		})
	end

	-- Agent -------------------------------------------------------------------

	local function paneAgent(container)
		local build = builder(container)

		local agent = build.section("Agent", "How hard it works before it stops and answers.")
		R.number(agent, "Step limit", "Tool rounds allowed in one turn, unless the switch below removes it.",
			"agent.maxTurns", 4, 60, 1)
		R.toggle(agent, {
			label = "Unlimited tool calls",
			hint = "Ignore the step limit and the fifteen-minute turn deadline, and keep calling tools until the answer is written. The repeat breaker, each tool's own timeout and Stop still apply, and subagents keep their own budgets.",
			path = "agent.unlimitedTurns",
		})
		R.number(agent, "Parallel tools", "Tool calls run at once within one step.",
			"agent.toolConcurrency", 1, 8, 1)
		R.number(agent, "Tool timeout",
			"Seconds before a tool is abandoned. Subagents are exempt: they run to their own budget below.",
			"agent.toolTimeout", 5, 60, 1)
		R.number(agent, "Request timeout",
			"How long one model call may run before the transport gives up. The default is a day, the highest of any clock here: replies cannot stream incrementally in this client, so a reasoning model can think for a long time before the first byte. Lower it only for a quick model; the top stop is the default.",
			"agent.requestTimeout", REQUEST_STOPS)
		R.toggle(agent, {
			label = "Unlimited requests",
			hint = "Ignore the timeout above and wait as long as the model takes, up to a day. The same wall as the default, spelled as a switch instead of a number: the slider can be lowered for a quick model without losing the day the heavy one needs. Stop still applies, and each attempt still ends at its own deadline.",
			path = "agent.requestUnlimited",
		})
		R.number(agent, "Subagent budget",
			"Seconds one subagent may work for before it wraps up. The call that dispatched it waits this long plus a minute, so a finished report is never thrown away. Ignored while the switch below is on.",
			"agent.subagentBudget", 30, 900, 30)
		-- The switch the step-limit message asks for. A subagent that stops mid-job and
		-- says "I reached this session's step limit" has spent the whole dispatch and
		-- answered nothing, and until this existed the only way past it was to edit
		-- config.json -- `Unlimited tool calls` deliberately stops at the conversation the
		-- user is watching.
		R.toggle(agent, {
			label = "Unlimited subagents",
			hint = "Let a dispatched subagent run with no step limit and no clock, and make the call that dispatched it wait as long as the child takes. The repeat breaker, each tool's own timeout, the two ceilings below and Stop still apply -- and the Subagents panel can stop one on its own without ending the turn.",
			path = "agent.subagentUnlimited",
		})
		R.number(agent, "Parallel subagents",
			"Subagents alive at once across the whole tree. Several dispatched in one step run together; this is the ceiling on how many, including the ones a subagent starts itself. Anything over it waits for a slot.",
			"agent.subagentConcurrency", 1, 12, 1)
		-- Two ceilings that had no control anywhere: the only way to change either was
		-- to edit config.json, which for the depth cap means the only switch that can
		-- turn delegation off entirely was unreachable.
		R.number(agent, "Subagent steps",
			"Tool rounds one subagent may take before it has to answer the parent with what it has. Ignored while Unlimited subagents is on.",
			"agent.subagentTurns", 1, 30, 1)
		R.number(agent, "Delegation depth",
			"How many levels of subagent are allowed. A subagent given the full tool set can dispatch its own; at 0 the agent cannot dispatch at all and does the work in the conversation instead. The Subagents panel lists what is running under these limits.",
			"agent.subagentDepth", 0, 4, 1)
		R.number(agent, "Context budget",
			"Hard ceiling on tokens kept before older turns are summarised. When the model's context window is known, compaction begins at the Compact-at fraction of it, so this mainly caps models with very large or unknown windows.",
			"agent.contextTokens", BUDGET_STOPS)
		R.number(agent, "Compact at",
			"Share of the model's context window at which older turns are summarised, when the window is known. Lower compacts sooner and cheaper; higher keeps more history in view. The Context budget above is still a hard ceiling.",
			"agent.contextFraction", 0.5, 0.95, 0.05)
		R.number(agent, "Reply ceiling",
			"max_tokens sent with each request. A value above the model's own limit is lowered to whatever the provider names in its refusal, once, and remembered.",
			"agent.maxTokens", REPLY_STOPS)
		R.number(agent, "Tool result cap",
			"Characters kept from one tool result, roughly four per token. This is the floor on how much a file read or a page fetch can actually return, whatever the tool's own limit says.",
			"agent.resultCap", RESULT_STOPS)
		R.choice(agent, "Effort",
			"How hard a reasoning model works before it answers. Sent as the provider's "
			.. "effort level and clamped to what the chosen model offers; models without one ignore it.",
			"agent.effort",
			{ "low", "medium", "high", "xhigh", "max" },
			{ "Low", "Medium", "High", "Very high", "Max" },
			{ "Faster", "Smarter" })
		R.number(agent, "Temperature",
			"Lower is steadier; 0 is as deterministic as the provider allows. The current Claude models reject it, and it is not sent to them.",
			"agent.temperature", 0, 1.5, 0.05)
		R.number(agent, "Retries", "Attempts per provider before moving to the next.",
			"agent.retries", 1, 6, 1)
		R.toggle(agent, {
			label = "Ask for streams",
			hint = "Streamed replies carry reasoning text and usage counts.",
			path = "agent.stream",
		})
		R.toggle(agent, {
			label = "Summarise old turns",
			hint = "Keeps a long conversation inside the context budget.",
			path = "agent.compaction",
		})
		R.toggle(agent, {
			label = "Provider fallback",
			hint = "Try the next enabled provider when one fails.",
			path = "agent.fallback",
		})
		-- One field, and the only half of the old language picker that was ever wired to
		-- anything. That control was a grid of eleven tiles behind a modal behind a menu
		-- entry, and it advertised two effects: the language the agent answers in, which
		-- src/agent/prompt.lua does read, and the locale dates are formatted with, which
		-- nothing reads at all. What survives is the effect that exists.
		R.field(agent, {
			name = "ReplyLanguage",
			label = "Reply language",
			hint = "Added to the system prompt as one line: answer in this language, leaving code "
				.. "and identifiers alone. Empty means whatever the conversation is already in, "
				.. "which is what a model does by default.",
			path = "agent.replyLanguage",
			placeholder = "Japanese",
		})

		-- The user's own standing instructions. This is the personal half of the prompt;
		-- the built-in half is fixed on purpose, and the copy action below is how it is
		-- inspected -- read-only, on the record, diffable between versions.
		local custom = build.section("Custom instructions",
			"Added to the system prompt every turn, after the built-in rules, so they win "
			.. "when the two disagree. The rest of the prompt is not editable: it is this "
			.. "client's own behaviour, and what is yours is kept separate from it so you "
			.. "can always tell which is which.")
		R.textarea(custom, {
			name = "CustomInstructions",
			path = "agent.customInstructions",
			height = 108,
			placeholder = "e.g. Reply short. I build obby games. My alt account is DaveAlt99 -- ignore it when counting players.",
			hint = "Written when the box loses focus. Applies from the next turn, including "
				.. "subagents, which inherit it with the rest of the brief.",
		})
		R.actions(custom, { {
			name = "CopySystemPrompt",
			text = "Copy system prompt",
			variant = "ghost",
			onClick = function()
				-- The assembled thing rather than the module's constants, so what is on
				-- the clipboard is what the next request will carry: the environment
				-- block, the permission line, this pane's own instructions included.
				local providers = env.require("provider/registry")
				local prompt = env.require("agent/prompt")
				local record = providers.active()
				local body = prompt.build({
					model = record and record.model or nil,
					provider = record and record.label or nil,
				})
				if caps.clipboard then
					local ok = pcall(caps.fn.clipboard, body)
					overlay.toast(ok and "System prompt copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				else
					log.info("prompt", body)
					overlay.toast("No clipboard here, so it went to the log", "info", 3)
				end
			end,
		} })
	end

	-- Permissions -------------------------------------------------------------

	local function panePermissions(container)
		local build = builder(container)
		local card = build.section("Permissions", permissions.MODE_HINTS[permissions.mode()])

		local modeOptions = {}
		for _, mode in ipairs(permissions.MODES) do
			modeOptions[#modeOptions + 1] = { value = mode, label = permissions.MODE_LABELS[mode] or mode }
		end
		local modeHint
		C.segmented(card, {
			options = modeOptions,
			value = permissions.mode(),
			onChange = function(value)
				permissions.setMode(value)
				if modeHint then modeHint.Text = permissions.MODE_HINTS[value] or "" end
			end,
		})
		modeHint = P.text(card, {
			text = permissions.MODE_HINTS[permissions.mode()] or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		modeHint.Size = UDim2.new(1, 0, 0, 0)

		R.toggle(card, {
			label = "Offer to remember",
			hint = "Show the remember switch on each prompt.",
			path = "permissions.remember",
		})

		local rulesLabel = P.text(card, {
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		rulesLabel.Size = UDim2.new(1, 0, 0, 0)
		local function refreshRules()
			local rules = permissions.listRules()
			if #rules == 0 then
				rulesLabel.Text = "No per-tool rules saved."
				return
			end
			local parts = {}
			for _, rule in ipairs(rules) do
				parts[#parts + 1] = rule.pattern .. " = " .. rule.verdict
			end
			rulesLabel.Text = util.pluralise(#rules, "saved rule") .. ": " .. table.concat(parts, ", ")
		end
		refreshRules()
		local unsubscribe = permissions.changed:connect(function()
			if not rulesLabel.Parent then return end
			refreshRules()
		end)
		rulesLabel.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(card, { {
			name = "ClearRules",
			text = "Clear saved rules",
			variant = "ghost",
			onClick = function()
				permissions.clearRules()
				refreshRules()
			end,
		} })
	end

	-- Skills ------------------------------------------------------------------

	local function paneSkills(container)
		local build = builder(container)

		-- Skills (playbooks) ------------------------------------------------
		--
		-- .md files under skills/, each a frontmatter description and a body of
		-- instructions. The list is files on disk rather than config state, so
		-- the honest subtitle is where they come from: dropped in by hand,
		-- written by the agent, or installed from GitHub. The toggle is the one
		-- bit of state kept, and it is stored per filename.
		local skillsCard = build.section("Playbooks",
			"The agent is instructed to read every enabled skill before replying in each "
			.. "new or resumed conversation, including subagents. Drop a .md playbook into "
			.. "skills/, or ask the agent to install one from GitHub. Turn off a skill to "
			.. "exclude it from those reads.")
		local skillsEngine = env.require("runtime/skills")

		local skillsList = P.column(skillsCard, {
			name = "SkillsList",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
		})
		local function refreshSkills()
			-- Keep the layout: clearing it stacked every installed skill at (0, 0).
			for _, child in ipairs(skillsList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local list = skillsEngine.list()
			if #list == 0 then
				R.paragraph(skillsList, "No skills installed yet.",
					{ layoutOrder = 1 })
				return
			end
			for index, skill in ipairs(list) do
				local row = P.row(skillsList, {
					name = "Skill_" .. skill.file,
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.sm,
					layoutOrder = index,
				})
				local text = P.column(row, {
					size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
				})
				P.text(text, { text = skill.name, role = "small", wrap = true, auto = "Y" })
				local detail = skill.description ~= "" and util.ellipsis(skill.description, 140)
					or (skill.unreadable and "could not be read") or "no description"
				P.text(text, {
					text = detail,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				local switch = C.switch(row, {
					value = skill.enabled,
					onChange = function(value)
						skillsEngine.setEnabled(skill.file, value)
					end,
				})
				switch.instance.LayoutOrder = 2
			end
		end
		refreshSkills()
		local unsubscribeSkills = skillsEngine.changed:connect(function()
			if not skillsList.Parent then return end
			refreshSkills()
		end)
		skillsList.Destroying:Connect(function() pcall(unsubscribeSkills) end)

		local memory = build.section("Memory",
			"Facts the agent has chosen to keep between sessions. It writes these itself, with "
			.. "the memory tool; this is where they can be read and removed.")
		R.toggle(memory, {
			label = "Enabled",
			hint = "When off, nothing new is stored and nothing is injected.",
			path = "memory.enabled",
		})
		local memoryList = P.column(memory, {
			name = "MemoryEntries", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs,
		})
		local function refreshMemory()
			for _, child in ipairs(memoryList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local list = state.memoryList()
			if #list == 0 then
				P.text(memoryList, { text = "Nothing stored.", role = "caption", color = theme.color.textTertiary,
					auto = "Y", wrap = true })
				return
			end
			for index, entry in ipairs(list) do
				local row = P.row(memoryList, {
					name = "MemoryEntry_" .. entry.key, size = UDim2.new(1, 0, 0, 0), auto = "Y",
					gap = theme.space.sm, alignY = "Top", layoutOrder = index,
				})
				P.text(row, {
					text = entry.key .. ": " .. util.ellipsis(entry.value, 120),
					role = "caption", color = theme.color.textSecondary, wrap = true, auto = "Y",
					size = UDim2.new(0, 0, 0, 0), flex = "Fill", layoutOrder = 1,
				})
				local key = entry.key
				P.iconButton(row, {
					name = "ForgetOne", icon = "trash", variant = "ghost", diameter = theme.size.controlSmall,
					layoutOrder = 2,
					onClick = function() state.forget(key) end,
				})
			end
		end
		refreshMemory()
		local unsubscribe = state.memoryChanged:connect(function()
			if not memoryList.Parent then return end
			refreshMemory()
		end)
		memoryList.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(memory, { {
			name = "ForgetEverything",
			text = "Forget everything",
			variant = "ghost",
			onClick = function()
				overlay.confirm({
					title = "Clear memory?",
					description = "Every stored fact is deleted.",
					confirmText = "Clear",
					danger = true,
					onConfirm = function()
						state.clearMemory()
						refreshMemory()
					end,
				})
			end,
		} })

		local host = build.section("Host instructions",
			"A script that embeds this client can add its own instructions and hooks. This is "
			.. "what the current host provided.")
		local hostPrompt = env.context and env.context.prompt
		local hooks = env.require("agent/hooks")
		local hookCounts = {}
		for kind in pairs(hooks.KINDS) do
			local count = hooks.count(kind)
			if count > 0 then hookCounts[#hookCounts + 1] = { key = kind, value = tostring(count) } end
		end
		if type(hostPrompt) == "string" and util.trim(hostPrompt) ~= "" then
			R.paragraph(host, util.ellipsis(hostPrompt, 600), { role = "small", color = theme.color.text })
		else
			R.paragraph(host, "No host instructions: this client was loaded on its own.")
		end
		if #hookCounts > 0 then
			table.sort(hookCounts, function(a, b) return a.key < b.key end)
			R.facts(host, hookCounts, { name = "Hooks" })
		end
	end

	-- Connectors --------------------------------------------------------------

	local function paneConnectors(container)
		local build = builder(container)

		local card = build.section("Inference",
			"Where requests go. A provider is a base URL, an auth style, a key and a model.")
		local list = providers.list()
		if #list == 0 then
			R.paragraph(card, "Nothing configured yet.")
		else
			local facts = {}
			for _, record in ipairs(list) do
				local detail = record.baseUrl
				if util.trim(tostring(record.model or "")) ~= "" then
					detail = record.model .. "  " .. record.baseUrl
				end
				facts[#facts + 1] = {
					key = record.label,
					value = detail,
					tone = (providers.active() or {}).id == record.id and "good" or nil,
				}
			end
			R.facts(card, facts, { name = "Providers" })
		end
		R.actions(card, { {
			name = "OpenInference",
			text = "Configure third-party inference",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("providers")
			end,
		} })

		local bridgeCard = build.section("Web bridge",
			"The one connector that is not a model: a browser on this machine sharing the "
			.. "conversation.")
		local status = bridgeModule.status()
		R.facts(bridgeCard, {
			{ key = "State", value = status.running and (status.online and "connected" or "polling") or "off",
				tone = status.running and (status.online and "good" or "warn") or nil },
			{ key = "Address", value = status.url },
		}, { name = "BridgeFacts" })
		R.actions(bridgeCard, { {
			name = "OpenCowork",
			text = "Open Cowork",
			variant = "ghost",
			onClick = function()
				env.require("ui/app").show("cowork")
			end,
		} })
	end

	-- Infinite Yield ------------------------------------------------------------

	-- The mode picker is a segmented control rather than a toggle because there
	-- are three honest states, not two: off, hidden (IY's engine, no IY pixels)
	-- and visible (IY exactly as it draws itself). A toggle would have to fold
	-- "off" and "hidden" into one position, and they are different decisions --
	-- one withholds the commands from the agent, the other only the interface.
	--
	-- Changing the mode does not load anything here. Loading is a megabyte
	-- fetch, a compile and a GUI; a settings row is not where that should spend
	-- itself. The next iy_cmd call picks the new mode up, and the status lines
	-- below say which state it will find.
	local function paneInfiniteYield(container)
		local build = builder(container)
		local card = build.section("Infinite Yield",
			"Run Infinite Yield inside this client and give the agent every one of its "
			.. "commands through the iy tools.")

		local iy = env.require("runtime/iy")
		local facts = P.column(card, {
			name = "IyStatus",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
		})
		local function refresh()
			for _, child in ipairs(facts:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local status = iy.status()
			for index, row in ipairs(status) do
				P.text(facts, {
					text = row[1] .. ": " .. tostring(row[2]),
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				}).Size = UDim2.new(1, 0, 0, 0)
			end
		end
		refresh()

		C.segmented(card, {
			options = {
				{ value = "off", label = "Off" },
				{ value = "hidden", label = "Hidden" },
				{ value = "visible", label = "With GUI" },
			},
			value = config.get("iy.mode", "hidden"),
			onChange = function(value)
				iy.setMode(value)
				refresh()
			end,
		})

		R.paragraph(card,
			"Hidden loads Infinite Yield with its interface parked, so the agent has "
			.. "every command and you keep the screen. With GUI loads it untouched. "
			.. "Either way the agent reaches everything through the same dispatcher, and "
			.. "iy_cmd calls still pass the permission prompt. If Infinite Yield is "
			.. "already running when a command is sent, that copy is used as-is.",
			{ layoutOrder = 4 })

		if not caps.exec then
			R.paragraph(card,
				"This host cannot compile code, so an internal load is unavailable here. "
				.. "An Infinite Yield you start yourself still works.",
				{ color = theme.color.warn })
		end
	end

	-- Plugins -----------------------------------------------------------------

	local function panePlugins(container)
		local build = builder(container)
		local card = build.section("Tool groups",
			"A family of tools can be withheld from the model entirely. That is a different "
			.. "thing from denying a call: a tool that is not offered is one the model will not "
			.. "spend a turn discovering it cannot use.")

		for _, group in ipairs(registry.groups()) do
			local row = P.row(card, {
				name = "Group_" .. group.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
			})
			local text = P.column(row, {
				size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
			})
			P.text(text, { text = group.label, role = "small" })
			local detail = util.pluralise(group.total, "tool")
			if group.unavailable > 0 then
				detail = detail .. ", " .. tostring(group.unavailable) .. " unavailable on this host"
			end
			P.text(text, {
				text = detail,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			local switch = C.switch(row, {
				value = group.enabled,
				onChange = function(value)
					registry.setGroupEnabled(group.id, value)
				end,
			})
			switch.instance.LayoutOrder = 2
		end

		R.actions(card, { {
			name = "OpenTools",
			text = "See every tool",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("tools")
			end,
		} })
	end

	-- The list -----------------------------------------------------------------

	-- Grouped the way the reference client groups them. "Agent" is the one section it
	-- does not have, and it is not optional here: the step limit, the context budget
	-- and the permission mode are the settings this client is actually about, and
	-- filing them under Developer to preserve a menu shape would hide them.
	M.PANES = {
		{ id = "general", section = "Settings", label = "General", icon = "gear", build = paneGeneral },
		{ id = "privacy", section = "Settings", label = "Privacy", icon = "worktree", build = paneprivacy },
		{ id = "usage", section = "Settings", label = "Usage", icon = "sliders", build = paneUsage },
		{ id = "claude_code", section = "Settings", label = "Claude Code", icon = "code", build = paneClaudeCode },
		{ id = "cowork", section = "Settings", label = "Cowork", icon = "terminal", build = paneCowork },
		{ id = "import_export", section = "Settings", label = "Import & export", icon = "document", build = paneImportExport },
		{ id = "agent", section = "Agent", label = "Behaviour", icon = "spark", build = paneAgent },
		{ id = "permissions", section = "Agent", label = "Permissions", icon = "check", build = panePermissions },
		{ id = "desktop_general", section = "Desktop app", label = "General", icon = "windowMaximize", build = paneDesktop },
		{ id = "developer", section = "Desktop app", label = "Developer", icon = "terminal", build = paneDeveloper },
		{ id = "skills", section = "Customize", label = "Skills", icon = "book", build = paneSkills },
		{ id = "connectors", section = "Customize", label = "Connectors", icon = "branch", build = paneConnectors },
		{ id = "infinite_yield", section = "Customize", label = "Infinite Yield", icon = "terminal", build = paneInfiniteYield },
		{ id = "plugins", section = "Customize", label = "Plugins", icon = "worktree", build = panePlugins },
	}

	function M.pane(id)
		for _, entry in ipairs(M.PANES) do
			if entry.id == id then return entry end
		end
		return nil
	end

	-- The dialog's nav, in declaration order, with the section headings kept.
	function M.sections()
		local out, seen = {}, {}
		for _, entry in ipairs(M.PANES) do
			if not seen[entry.section] then
				seen[entry.section] = { title = entry.section, panes = {} }
				out[#out + 1] = seen[entry.section]
			end
			local group = seen[entry.section]
			group.panes[#group.panes + 1] = entry
		end
		return out
	end

	-- One pane into a container of its own. Used by the dialog when a category is
	-- chosen, and by the Settings panel for every pane in turn.
	function M.render(id, container)
		local entry = M.pane(id)
		if not entry then return false end
		local ok, err = pcall(entry.build, container)
		if not ok then
			log.warn("settings", "the " .. tostring(id) .. " pane failed to build", err)
			R.paragraph(container, "This pane could not be built: " .. tostring(err),
				{ color = theme.color.danger })
		end
		return ok
	end

	return M
end
end)()

-- ==========================================================================
-- ui/settingsrows
-- ==========================================================================
__UAI_MODULES["ui/settingsrows"] = (function()
-- The rows a settings surface is made of.
--
-- There are two of those surfaces now -- the Settings panel and the settings dialog
-- the sidebar opens -- and they have to agree about what a toggle looks like, how a
-- token budget is expressed as a track, and which config path a control writes. So
-- the rows live here and both surfaces call them, rather than the dialog growing a
-- second, subtly different set.
--
-- Every builder takes the config path it writes and nothing else about where the
-- value goes: the row reads the current value itself and writes it back itself, which
-- is why none of these return a handle to be wired up afterwards.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")

	local R = {}

	-- A heading with an optional description, followed by the card its rows go in.
	--
	-- Both go inside one wrapper with a tight gap between them, so the heading is
	-- visibly closer to the card it labels than to whatever is above it. As two loose
	-- siblings the two distances were the same number -- the parent's gap -- and a
	-- column of sections read as an alternating stack with no grouping in it.
	function R.section(parent, props)
		props = props or {}
		local group = P.column(parent, {
			name = props.name and (props.name .. "Group") or "Group",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		P.sectionHeader(group, {
			title = props.title,
			description = props.description,
			layoutOrder = 1,
		})
		return P.card(group, {
			name = props.name,
			layoutOrder = 2,
			gap = theme.space.md,
		})
	end

	function R.paragraph(parent, text, props)
		props = props or {}
		local label = P.text(parent, {
			name = props.name,
			text = tostring(text or ""),
			role = props.role or "caption",
			color = props.color or theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = props.layoutOrder,
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		return label
	end

	function R.toggle(parent, props)
		local initial = props.value
		if initial == nil then initial = config.get(props.path, false) == true end
		local row = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		local text = P.column(row, {
			size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = theme.space.xxs, layoutOrder = 1,
		})
		P.text(text, { text = props.label, role = "label", wrap = true, auto = "Y" })
		if props.hint then
			P.text(text, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		local switch = C.switch(row, {
			value = initial,
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		switch.instance.LayoutOrder = 2
		return switch
	end

	-- A million in a 66px monospace field is a wall of zeroes, and the exact digit
	-- is never what the reader is checking at that size.
	local function formatCount(number)
		number = math.floor(number)
		if number >= 1000000 and number % 100000 == 0 then
			local millions = number / 1000000
			return (millions % 1 == 0) and string.format("%dM", millions) or string.format("%.1fM", millions)
		end
		if number >= 1000 and number % 1000 == 0 then return string.format("%dk", number / 1000) end
		return tostring(number)
	end

	R.formatCount = formatCount

	-- `min` may be a list of allowed values rather than a bound. Every row that
	-- counts tokens uses one: the range those rows have to cover is three orders of
	-- magnitude, and a linear track across it cannot resolve the low end where the
	-- useful settings are.
	function R.number(parent, label, hint, path, min, max, step)
		local stops
		if type(min) == "table" then
			stops, min, max, step = min, min[1], min[#min], nil
		end
		local function display(number)
			return (step and step < 1) and string.format("%.2f", number) or formatCount(number)
		end
		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			-- Fills rather than reserving 70 for a 66px value plus a 6px gap, which
			-- overlapped it by two pixels.
			size = UDim2.new(0, 0, 0, 0),
			wrap = true,
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = display(tonumber(config.get(path, min)) or min),
			role = "monoSmall",
			color = theme.color.accent,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		C.slider(column, {
			-- Named after the setting it writes, so the tree says which slider is
			-- which -- eight of them called "Slider" is unreadable from a dump and
			-- unreachable from a test.
			name = "Slider_" .. tostring(path),
			min = min,
			max = max,
			step = step,
			stops = stops,
			value = tonumber(config.get(path, min)) or min,
			onChange = function(number)
				value.Text = display(number)
			end,
			onCommit = function(number)
				config.set(path, (step and step < 1) and util.round(number, 2) or math.floor(number))
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- A row whose stops are words rather than numbers.
	--
	-- A track is still the right control when the values are not numeric: the stops
	-- are ordered and the reader is picking a position on a scale, which a row of
	-- buttons states less clearly. The value reads in the label's own type rather
	-- than numberRow's monospace, because a word set in code font looks like an
	-- identifier, and both ends are named above the track -- what the scale *means*
	-- is the part neither the numbers nor the level names carry.
	function R.choice(parent, label, hint, path, values, labels, ends)
		local index, stored = 1, tostring(config.get(path, values[1]))
		for position, value in ipairs(values) do
			if value == stored then index = position end
		end
		local stops = {}
		for position = 1, #values do stops[position] = position end

		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			size = UDim2.new(0, 0, 0, 0),
			wrap = true,
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = labels[index],
			role = "label",
			color = theme.color.accent,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})

		local feet = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(feet, {
			text = ends[1],
			role = "caption",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		P.text(feet, {
			text = ends[2],
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		C.slider(column, {
			name = "Slider_" .. tostring(path),
			stops = stops,
			value = index,
			onChange = function(number)
				value.Text = labels[math.floor(number)] or value.Text
			end,
			onCommit = function(number)
				local position = math.max(math.min(math.floor(number), #values), 1)
				value.Text = labels[position]
				config.set(path, values[position])
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- Label and description on the left, one control on the right. The dialog's
	-- appearance pane is a column of these.
	--
	-- The right-hand slot states a width. It used to size itself to its contents,
	-- which for a segmented control -- whose own width is a scale when it is not given
	-- one -- resolved to zero: three controls in that pane were invisible and
	-- unclickable, and nothing about the props said so.
	function R.setting(parent, props)
		local row, layout = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignY = "Center",
			gap = theme.space.md,
			layoutOrder = props.layoutOrder,
		})
		local left = P.column(row, {
			size = UDim2.new(1, -(props.width or theme.size.menu) - theme.space.md, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		P.text(left, {
			text = props.label,
			role = "bodyStrong",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
			layoutOrder = 1,
		})
		if props.hint then
			P.text(left, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
		end
		local right = P.frame(row, {
			name = "Control",
			size = UDim2.fromOffset(props.width or theme.size.menu, 0),
			auto = "Y",
			layoutOrder = 2,
		})
		-- Reflow from the actual pane width, including a resized desktop window.
		-- Controls keep their preferred width until the label needs its own line.
		local controlWidth = props.width or theme.size.menu
		local function reflow()
			local width = row.AbsoluteSize.X
			if width <= 0 then return end
			local stacked = width < controlWidth + theme.size.modalMin
			layout.FillDirection = stacked and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
			layout.VerticalAlignment = stacked and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Center
			left.Size = UDim2.new(1, stacked and 0 or -(controlWidth + theme.space.md), 0, 0)
			right.Size = UDim2.fromOffset(math.min(controlWidth, width), 0)
		end
		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		reflow()
		return right, row
	end

	-- A setting row whose control is a segmented picker over a config path.
	function R.segmented(parent, props)
		local width = C.segmentedWidth(props.options)
		local slot = R.setting(parent, {
			name = props.name,
			label = props.label,
			hint = props.hint,
			width = width,
			layoutOrder = props.layoutOrder,
		})
		local control = C.segmented(slot, {
			name = props.name and ("Segmented_" .. props.name) or nil,
			options = props.options,
			value = (props.value ~= nil) and props.value or config.get(props.path, props.options[1].value),
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		return control
	end

	-- A setting row whose control is a menu rather than a row of segments.
	--
	-- Segments stop working somewhere around four options. The interface font list is
	-- eight families wide, and eight segments in a 530px pane give each label sixty
	-- pixels -- which "Titillium Web" does not fit into, and C.segmented neither
	-- truncates nor clips, so the labels would simply run into each other. Same
	-- decision, a control that does not have to show every option at once.
	function R.select(parent, props)
		local options = props.options or {}
		local current = (props.value ~= nil) and props.value
			or config.get(props.path, options[1] and options[1].value)

		local function labelFor(value)
			for _, option in ipairs(options) do
				if option.value == value then return option.label or tostring(value) end
			end
			return tostring(value)
		end

		local slot = R.setting(parent, {
			name = props.name,
			label = props.label,
			hint = props.hint,
			width = props.width or theme.size.menu,
			layoutOrder = props.layoutOrder,
		})

		local control
		control = P.rowButton(slot, {
			name = props.name and ("Select_" .. props.name) or "Select",
			height = math.max(theme.size.control, responsive.minTarget()),
			radius = theme.radius.md,
			stroke = true,
			strokeColor = theme.color.border,
			padding = { x = theme.space.sm },
			onClick = function(handle)
				local menuOptions = {}
				for _, option in ipairs(options) do
					menuOptions[#menuOptions + 1] = {
						label = option.label or tostring(option.value),
						value = option.value,
						detail = option.detail,
						selected = option.value == current,
					}
				end
				env.require("ui/overlay").menu({
					target = handle.instance,
					width = math.max(props.menuWidth or theme.size.menuWide,
						math.floor(handle.instance.AbsoluteSize.X)),
					options = menuOptions,
					onSelect = function(value)
						current = value
						control.text.Text = labelFor(value)
						if props.path then config.set(props.path, value) end
						if props.onChange then pcall(props.onChange, value) end
					end,
				})
			end,
		})
		control.text = control.label(labelFor(current), 1, theme.color.text, "small")
		local caret = P.frame(control.row, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 2,
		})
		env.require("ui/icons").chevron(caret, theme.size.icon, theme.color.textTertiary, "down")
		return control
	end

	-- A field bound to a config path, written on blur rather than per keystroke: a
	-- port typed one digit at a time would otherwise restart the bridge four times.
	function R.field(parent, props)
		if props.label then
			P.text(parent, { text = props.label, role = "small", layoutOrder = props.layoutOrder })
		end
		local field = P.field(parent, {
			name = props.name,
			text = tostring(props.value ~= nil and props.value or config.get(props.path, "")),
			placeholder = props.placeholder,
			size = props.size,
			layoutOrder = props.layoutOrder and (props.layoutOrder + 1) or nil,
			onBlur = function(text)
				local clean = util.trim(text)
				if props.transform then clean = props.transform(clean) end
				if props.path then config.set(props.path, clean) end
				if props.onChange then pcall(props.onChange, clean) end
			end,
		})
		if props.hint then R.paragraph(parent, props.hint,
			{ layoutOrder = props.layoutOrder and (props.layoutOrder + 2) or nil }) end
		return field
	end

	-- A multiline field bound to a config path, written on blur. Not folded into
	-- R.field behind a `multiline` prop: a textarea is a different control -- taller,
	-- top-aligned, Enter inserts a newline -- and every caller so far wants exactly
	-- one of the two. The custom instructions box is the first textarea in the client.
	function R.textarea(parent, props)
		if props.label then
			P.text(parent, { text = props.label, role = "small", layoutOrder = props.layoutOrder })
		end
		local field = P.field(parent, {
			name = props.name,
			multiline = true,
			height = props.height or theme.size.controlLarge * 2,
			text = tostring(props.value ~= nil and props.value or config.get(props.path, "")),
			placeholder = props.placeholder,
			layoutOrder = props.layoutOrder and (props.layoutOrder + 1) or nil,
			-- Written on blur rather than per keystroke, same as R.field: the value is
			-- read by the next request, not this frame.
			onBlur = function(text)
				if props.path then config.set(props.path, tostring(text or "")) end
				if props.onChange then pcall(props.onChange, tostring(text or "")) end
			end,
		})
		if props.hint then R.paragraph(parent, props.hint,
			{ layoutOrder = props.layoutOrder and (props.layoutOrder + 2) or nil }) end
		return field
	end

	-- A row of buttons. Actions rather than settings: a reset, a clear, an unload.
	function R.actions(parent, list, props)
		props = props or {}
		local row = P.row(parent, {
			name = props.name or "Actions",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		local limits = {}
		for index, entry in ipairs(list) do
			local button = P.button(row, {
				name = entry.name,
				text = entry.text,
				variant = entry.variant or "secondary",
				size = "sm",
				layoutOrder = index,
				onClick = entry.onClick,
			})
			button.instance.LayoutOrder = index
			-- Wrapping moves a whole button; it cannot make one long action fit.
			-- Bound the intrinsic label itself so its button shrinks with the pane.
			if button.label then
				button.label.TextTruncate = Enum.TextTruncate.AtEnd
				limits[#limits + 1] = Instance.new("UISizeConstraint", button.label)
			end
		end
		local function fit()
			local width = row.AbsoluteSize.X
			if width <= 0 then return end
			for _, limit in ipairs(limits) do
				limit.MaxSize = Vector2.new(math.max(width - theme.space.md * 2, 0), math.huge)
			end
		end
		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
		fit()
		return row
	end

	-- Key/value facts. Read-only by definition: these are things the client observed,
	-- not things it can be told.
	function R.facts(parent, list, props)
		props = props or {}
		local box = P.frame(parent, {
			name = props.name or "Facts",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.canvas,
			radius = theme.radius.md,
			padding = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		P.stroke(box, theme.color.borderSubtle)
		local column = P.column(box, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
		})
		for index, entry in ipairs(list) do
			C.keyValue(column, {
				key = entry.key,
				value = entry.value,
				layoutOrder = index,
				color = entry.tone and theme.toneColor(entry.tone) or theme.color.text,
			})
		end
		return box
	end

	return R
end
end)()

-- ==========================================================================
-- ui/sidebar
-- ==========================================================================
__UAI_MODULES["ui/sidebar"] = (function()
-- The sidebar: navigation, the mode switch, and the real conversation list.
--
-- Everything in here reads from `agent/session`. The list used to be three hardcoded
-- project names with eleven invented titles under them, copied from a screenshot --
-- which looked exactly right and told you nothing, and whose rows typed their own
-- label into the composer instead of opening anything. What is here now is the
-- threads the client actually has, grouped by the place they happened in, and
-- clicking one switches to it.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local profileUI = env.require("ui/profile")
	local C = env.require("ui/controls")
	local sessions = env.require("agent/session")
	local subagent = env.require("agent/subagent")
	local providers = env.require("provider/registry")
	local place = env.require("runtime/place")

	local M = {}

	-- The panels the "More" row reveals. Chat is not in it: the mode switch above is
	-- what selects between the conversation and the shared session.
	local MORE_PANELS = {
		{ id = "agents", label = "Subagents", icon = "spark" },
		{ id = "providers", label = "Providers", icon = "sliders" },
		{ id = "tools", label = "Tools", icon = "worktree" },
		{ id = "logs", label = "Logs & traces", icon = "document" },
		{ id = "settings", label = "Settings", icon = "gear" },
	}

	function M.new(parent, host)
		local handle = {}

		-- One inset and one icon size for every row in here.
		--
		-- There were six of each. Row padding ran xxs, xs and md depending on which row
		-- it was, and the icon slot -- whose width is what decides where the label starts
		-- -- was written three different ways as `icon`, `icon - hair` and `icon - xxs`.
		-- The result was six different left text edges down one 240px column, two of them
		-- two pixels apart on adjacent rows. Both are also dimensionally wrong to
		-- subtract from each other: `space` scales by 0.78 under compact density and
		-- `size` by 0.86, so the gaps drifted rather than holding.
		local ROW_INSET = theme.space.sm
		local ROW_ICON = theme.size.icon

		local sidebar = P.column(parent, {
			name = "Sidebar",
			size = UDim2.fromScale(1, 1),
			-- One step of air between groups rather than the same six pixels used inside
			-- them: the nav strip, the mode switch, the new-conversation button, the action
			-- rows and the history are five separate things, and at a uniform xs they read
			-- as one undifferentiated stack.
			gap = theme.space.sm,
			padding = { x = theme.space.sm, y = theme.space.md },
		})

		-- Top row: the app menu, the collapse toggle, search, and the two history
		-- arrows. Every one of them does something; the pair that used to announce
		-- "Navigated to previous session" in a toast now actually goes there.
		--
		-- It wraps because on a touch device every one of these is forced to 44px by the
		-- hit-target floor, and five of those plus their gaps are wider than the sidebar.
		local topNav = P.row(sidebar, {
			name = "TopNav",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xxs,
			layoutOrder = 1,
		})

		local function navButton(name, icon, order, onClick, enabled)
			local button = P.iconButton(topNav, {
				name = name,
				icon = icon,
				diameter = theme.size.controlSmall,
				layoutOrder = order,
				onClick = onClick,
			})
			button.instance.LayoutOrder = order
			if enabled == false then button.setEnabled(false) end
			return button
		end

		navButton("Nav_menu", "bars", 1, function()
			host.showAppMenu(topNav)
		end)
		navButton("Nav_sidebar", "sidebarToggle", 2, function()
			host.toggleSidebar()
		end)
		navButton("Nav_search", "search", 3, function()
			host.showSearch()
		end)
		handle.back = navButton("Nav_back", "arrowLeft", 4, function()
			host.back()
		end, host.canBack())
		handle.forward = navButton("Nav_forward", "arrowRight", 5, function()
			host.forward()
		end, host.canForward())

		-- Shared conversation and Code workspace destinations.
		local modeRow = P.row(sidebar, {
			name = "ModeSwitcher",
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget(),
				theme.text.caption.height) + theme.space.hair * 2),
			bg = theme.color.surface,
			radius = theme.radius.lg,
			padding = theme.space.hair,
			gap = theme.space.hair,
			layoutOrder = 2,
			stretch = true,
		})

		local modes = {}
		local function modeButton(id, label, icon, order)
			local selected = host.panel == id
			local button = P.rowButton(modeRow, {
				name = "Segment_" .. id,
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				height = theme.size.controlSmall,
				radius = theme.radius.md,
				bgSelected = theme.color.surfaceActive,
				selected = selected,
				alignX = "Center",
				gap = theme.space.xxs,
				padding = theme.space.none,
				layoutOrder = order,
				onClick = function()
					host.show(id)
				end,
			})
			button.icon(icon, 1, selected and theme.color.text or theme.color.textTertiary,
				theme.size.icon - theme.space.xxs)
			local label2 = P.text(button.row, {
				text = label,
				role = "caption",
				color = selected and theme.color.text or theme.color.textTertiary,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				auto = "X",
				flex = "Shrink",
				truncate = true,
				layoutOrder = 2,
			})
			modes[id] = { button = button, label = label2 }
			return button
		end
		modeButton("cowork", "Cowork", "terminal", 1)
		modeButton("chat", "Chat", "spark", 2)
		modeButton("code", "Code", "terminal", 3)

		-- New conversation. A real thread rather than a wipe of the current one: the
		-- list below is what makes the difference visible, and clearing in place is what
		-- the composer's own clear control is for.
		local newButton = P.button(sidebar, {
			name = "NewChat",
			text = "New conversation",
			icon = "plus",
			variant = "secondary",
			size = "md",
			fill = true,
			layoutOrder = 3,
			onClick = function()
				host.openSession(sessions.newThread().id)
			end,
		})
		newButton.instance.LayoutOrder = 3

		local actions = P.column(sidebar, {
			name = "ActionRows",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 4,
		})

		local customize = P.rowButton(actions, {
			name = "Customize",
			bg = nil,
			padding = { x = ROW_INSET },
			layoutOrder = 1,
			onClick = function()
				host.showSettingsDialog("claude_code")
			end,
		})
		customize.icon("sliders", 1, theme.color.textSecondary, ROW_ICON)
		customize.label("Customize", 2, theme.color.textSecondary)

		local expanded = config.get("ui.sidebarExpanded", false) == true
		local more = P.rowButton(actions, {
			name = "More",
			padding = { x = ROW_INSET },
			layoutOrder = 2,
			onClick = function()
				expanded = not expanded
				config.set("ui.sidebarExpanded", expanded, { quiet = true })
				handle.renderMore()
			end,
		})
		local moreIcon = more.icon("chevron", 1, theme.color.textSecondary, ROW_ICON)
		more.label("More", 2, theme.color.textSecondary)

		local moreList = P.column(actions, {
			name = "MorePanels",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 3,
		})

		function handle.renderMore()
			for _, child in ipairs(moreList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The chevron points at what pressing it will do.
			for _, child in ipairs(moreIcon:GetChildren()) do child:Destroy() end
			icons.chevron(moreIcon, ROW_ICON, theme.color.textSecondary,
				expanded and "up" or "down")
			if not expanded then return end
			for index, entry in ipairs(MORE_PANELS) do
				local selected = host.panel == entry.id
				local row = P.rowButton(moreList, {
					name = "NavRow_" .. entry.id,
					padding = { x = ROW_INSET },
					selected = selected,
					layoutOrder = index,
					onClick = function()
						host.show(entry.id)
					end,
				})
				row.icon(entry.icon, 1, selected and theme.color.text or theme.color.textTertiary, ROW_ICON)
				-- How many subagents are working, on the row that leads to them. A
				-- dispatch runs for minutes with nothing on screen once its card has
				-- scrolled away, so the count is the only standing sign of it.
				local label = entry.label
				if entry.id == "agents" then
					local running = #subagent.running()
					if running > 0 then label = label .. "  " .. tostring(running) end
				end
				row.label(label, 2, selected and theme.color.text or theme.color.textSecondary)
			end
		end

		-- Same guard as the history, for the same reason: this rebuilds five rows and it
		-- is called from refresh, which runs on every status event of every turn. The
		-- three things it can show are which panel is selected, whether it is open, and
		-- how many subagents are running.
		local function moreSignature()
			return string.format("%s|%s|%d", tostring(host.panel),
				expanded and "+" or "-", #subagent.running())
		end

		function handle.syncMore(force)
			local signature = moreSignature()
			if not force and signature == handle.moreSignature then return false end
			handle.moreSignature = signature
			handle.renderMore()
			return true
		end

		handle.renderMore()
		handle.moreSignature = moreSignature()

		-- The conversation list, which takes whatever height is left rather than a
		-- hand-summed remainder: the stack above it changes height with density, with
		-- the platform's hit-target floor and with whether More is open, and a fixed
		-- offset was wrong in all three directions at once.
		local historyHolder = P.frame(sidebar, {
			name = "HistoryHolder",
			size = UDim2.new(1, 0, 0, 0),
			layoutOrder = 5,
		})
		local historyFlex = Instance.new("UIFlexItem", historyHolder)
		historyFlex.FlexMode = Enum.UIFlexMode.Fill

		local history = P.scroll(historyHolder, {
			name = "HistoryScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = { top = theme.space.xs, bottom = theme.space.sm },
		})
		-- Expanded navigation can exceed a short window by itself. It shares the
		-- scroll viewport with history so the profile remains reachable below it.
		actions.Parent = history.instance
		actions.LayoutOrder = 1
		local historyList = P.column(history.instance, { name = "HistoryList",
			size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs, layoutOrder = 2 })

		-- Which place groups are folded, by placeId.
		--
		-- Stored rather than kept in a local: the list is rebuilt from scratch on every
		-- new thread, rename, delete, place change and busy transition, so a local would
		-- unfold everything several times a minute. Quiet writes, because this is a
		-- record of what the user folded and not a token anything derives from -- a noisy
		-- one would reach the theme's subscription and rebuild the whole interface.
		local function collapsedKey(placeId)
			return "ui.placeCollapsed." .. tostring(placeId)
		end

		local function isCollapsed(placeId)
			return config.get(collapsedKey(placeId), false) == true
		end

		local function setCollapsed(placeId, value)
			config.set(collapsedKey(placeId), value == true, { quiet = true })
		end

		local function sessionMenu(session, target)
			overlay.menu({
				target = target,
				width = theme.size.menu,
				options = {
					{ isHeader = true, title = session.title, subtitle = session.placeName },
					{ label = "Open", value = "open", icon = "arrowRight" },
					{ label = "Rename", value = "rename", icon = "document" },
					{ label = "Delete", value = "delete", icon = "trash", tone = "bad" },
				},
				onSelect = function(value)
					if value == "open" then
						host.openSession(session.id)
					elseif value == "rename" then
						overlay.prompt({
							title = "Rename this conversation",
							description = "The transcript is untouched; only what the list calls it changes.",
							placeholder = "a short title",
							value = session.title,
							confirmText = "Rename",
							onConfirm = function(text)
								local ok, why = session.rename(text)
								if not ok then overlay.toast(tostring(why), "warn", 2) end
							end,
						})
					elseif value == "delete" then
						overlay.confirm({
							title = "Delete this conversation?",
							description = "The transcript and its file are both removed. This cannot be undone.",
							confirmText = "Delete",
							danger = true,
							onConfirm = function()
								sessions.remove(session.id)
								host.openSession(sessions.current().id)
							end,
						})
					end
				end,
			})
		end

		function handle.renderHistory()
			for _, child in ipairs(historyList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local active = sessions.current()
			local groups = sessions.groups()
			local order = 0

			for _, group in ipairs(groups) do
				order = order + 1
				local column = P.column(historyList, {
					name = "Place_" .. tostring(group.placeId),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = order,
				})

				-- The group header is the fold control, so the whole line answers a click
				-- rather than a chevron nobody can hit. The count rides on it because a
				-- folded group has to say how much it is hiding -- otherwise folding one
				-- loses the only sign those conversations exist.
				local collapsed = isCollapsed(group.placeId)
				local head = P.rowButton(column, {
					name = "PlaceHead",
					height = theme.size.rowTight,
					-- The same inset as the rows it heads. It was xxs against their xs, so
					-- a group's name sat two pixels left of every conversation under it.
					padding = { x = ROW_INSET },
					gap = theme.space.xxs,
					layoutOrder = 1,
					onClick = function()
						setCollapsed(group.placeId, not isCollapsed(group.placeId))
						-- Through the signature, so the fold state it just wrote becomes the
						-- baseline the next change is compared against.
						handle.syncHistory()
					end,
				})
				-- Points at what pressing it will do, like the More row above.
				local caret = P.frame(head.row, {
					name = "PlaceCaret",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				icons.chevron(caret, theme.size.icon, theme.color.textTertiary,
					collapsed and "right" or "down")
				P.text(head.row, {
					name = "PlaceName",
					text = group.label,
					role = "overline",
					color = theme.color.textTertiary,
					size = UDim2.new(0, 0, 0, theme.text.overline.height),
					flex = "Fill",
					truncate = true,
					layoutOrder = 2,
				})
				-- How many are in there, and how many of those are working. The second
				-- number is the reason a fold is safe to leave shut: a group with a turn
				-- running in it still says so from the header.
				local busyCount = 0
				for _, session in ipairs(group.sessions) do
					if session.busy then busyCount = busyCount + 1 end
				end
				if busyCount > 0 then
					local slot = P.frame(head.row, {
						name = "PlaceBusy",
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 3,
					})
					C.spinner(slot, {
						diameter = theme.size.icon,
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
				end
				local countLabel = P.text(head.row, {
					name = "PlaceCount",
					text = tostring(#group.sessions),
					role = "caption",
					color = theme.color.textTertiary,
					align = "Right",
					auto = "X",
					layoutOrder = 4,
				})
				countLabel.Size = UDim2.fromOffset(0, theme.text.caption.height)
				-- The place the client is in now is the only one a new conversation can
				-- be started in, so it is the only one that offers.
				if group.current then
					local plus = P.iconButton(head.row, {
						name = "NewInPlace",
						icon = "plus",
						diameter = theme.size.rowTight,
						layoutOrder = 5,
						onClick = function()
							host.openSession(sessions.newThread().id)
						end,
					})
					plus.instance.LayoutOrder = 5
				end

				-- The rows go in a holder of their own so folding hides one frame rather
				-- than each row: a hidden child still takes its slot in a list layout only
				-- if the layout can see it, and hiding thirty of them one at a time is
				-- thirty writes where one will do.
				local body = P.column(column, {
					name = "PlaceSessions",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = 2,
					visible = not collapsed,
				})

				for index, session in ipairs(group.sessions) do
					local selected = session.id == active.id
					local row = P.rowButton(body, {
						name = "SessionRow",
						height = theme.size.rowSmall,
						padding = { x = ROW_INSET },
						selected = selected,
						layoutOrder = index,
						onClick = function()
							host.openSession(session.id)
						end,
					})
					-- The leading slot is always there and usually empty.
					--
					-- It used to hold a hollow circle per row and a filled dot on the active
					-- one: a column of bullets down a 240px list whose only job was to say
					-- which row was selected, which the row's own highlight already says and
					-- says better. The slot itself stays, at the icon's width, because it is
					-- what puts every title on the same left edge as the group name above it
					-- -- and because a spinner has to be able to appear in a row without
					-- moving that row's text.
					--
					-- The spinner is the one thing here that survived: a conversation you are
					-- not looking at can still be working, leaving one does not stop it, and
					-- that is the one fact a row cannot state any other way. It is also the
					-- reason the list refreshes on every busy transition.
					local slot = P.frame(row.row, {
						name = "IconSlot",
						size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
						layoutOrder = 1,
					})
					if session.busy then
						C.spinner(slot, {
							diameter = ROW_ICON,
							anchor = Vector2.new(0.5, 0.5),
							position = UDim2.fromScale(0.5, 0.5),
						})
					end
					local titleText = session.title
					if session.ephemeral then titleText = titleText .. "  (not saved)" end
					row.label(titleText, 2,
						selected and theme.color.text or theme.color.textSecondary,
						selected and "label" or nil)
					local menuButton = P.iconButton(row.row, {
						name = "SessionMenu",
						icon = "ellipsis",
						diameter = theme.size.rowTight,
						layoutOrder = 3,
						onClick = function(button)
							sessionMenu(session, button.instance)
						end,
					})
					menuButton.instance.LayoutOrder = 3
				end
			end

			if order == 0 then
				local empty = P.text(historyList, {
					name = "NoHistory",
					text = "Your conversations will appear here, organized by place.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = ROW_INSET },
					layoutOrder = 1,
				})
				empty.Size = UDim2.new(1, 0, 0, 0)
			end
		end

		handle.renderHistory()

		P.divider(sidebar, { color = theme.color.borderSubtle, layoutOrder = 6 })

		-- A distinct identity control, with room for a headshot and two readable lines.
		local identity = profileUI.identity()
		local identityHeight = theme.text.heading.height + theme.text.caption.height + theme.space.hair
		local profile, profileMenu, chevron
		profile = P.rowButton(sidebar, {
			name = "ProfileBar",
			-- Matched to the chat composer's *visible* box, not its shell. The composer
			-- shell is taller (control + sm*3 + xxs) but its bordered surface is inset
			-- within it at control + sm*2; the profile bar is a bordered box that fills
			-- its whole height. Sizing to the surface is what makes the two read as the
			-- same height where they dock side by side at the bottom of the window.
			height = math.max(theme.size.control, responsive.minTarget()) + theme.space.sm * 2,
			bg = theme.color.surface,
			radius = theme.radius.lg,
			stroke = true,
			gap = theme.space.md,
			padding = { x = ROW_INSET },
			layoutOrder = 7,
			onClick = function()
				if profileMenu and not profileMenu.closed then profileMenu.close(); return end
				profileMenu = host.showProfileMenu(profile.instance, function()
					if not profile.instance.Parent then return end
					profile.setSelected(false)
					chevron.Rotation = 0
				end)
				if profileMenu and not profileMenu.closed then
					profile.setSelected(true)
					chevron.Rotation = 180
				end
			end,
		})
		profileUI.avatar(profile.row, identity, theme.size.profileAvatar, 1)
		local profileText = P.column(profile.row, {
			name = "ProfileIdentity",
			size = UDim2.new(0, 0, 0, identityHeight),
			flex = "Fill",
			gap = theme.space.hair,
			layoutOrder = 2,
		})
		P.text(profileText, {
			name = "ProfileName",
			text = identity.name,
			role = "heading",
			size = UDim2.new(1, 0, 0, theme.text.heading.height),
			color = theme.color.text,
			truncate = true,
			layoutOrder = 1,
		})
		local profileDetail = P.text(profileText, {
			name = "ProfileProvider",
			text = profileUI.providerLabel(),
			role = "caption",
			size = UDim2.new(1, 0, 0, theme.text.caption.height),
			color = theme.color.textTertiary,
			truncate = true,
			layoutOrder = 2,
		})
		chevron = P.frame(profile.row, {
			name = "ProfileChevron",
			size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
			layoutOrder = 3,
		})
		icons.chevron(chevron, ROW_ICON, theme.color.textTertiary, "up")

		-- What the list currently shows, as a string.
		--
		-- The list is rebuilt from destroyed instances, and everything that can change it
		-- -- a new thread, a rename, a delete, a switch, a busy transition, a place
		-- resolving -- arrives as the same signal with no description of what moved. So
		-- the cheap thing is to ask whether the answer would differ before spending
		-- thirty instances per row finding out that it would not.
		--
		-- This is the stutter. `session.emit` fires listChanged on send, and app.syncNav
		-- runs on every status event -- of which a turn emits one per step plus one per
		-- request -- and each of those was tearing down and rebuilding every row in the
		-- sidebar. A twelve-conversation client spent about 1800 instance constructions
		-- per turn redrawing a list whose contents had not changed since the first one.
		local function listSignature()
			local parts = { tostring(sessions.activeId) }
			for _, group in ipairs(sessions.groups()) do
				parts[#parts + 1] = string.format("%s|%s|%s",
					tostring(group.placeId), tostring(group.label),
					isCollapsed(group.placeId) and "-" or "+")
				for _, session in ipairs(group.sessions) do
					parts[#parts + 1] = string.format("%s\1%s\1%s\1%s",
						tostring(session.id), tostring(session.title),
						session.busy and "b" or "-", session.ephemeral and "e" or "-")
				end
			end
			return table.concat(parts, "\2")
		end

		-- The list, only if it would look different. `force` is for the paths that know
		-- it changed for a reason the signature cannot see -- a fold, a theme rebuild.
		function handle.syncHistory(force)
			local signature = listSignature()
			if not force and signature == handle.signature then return false end
			handle.signature = signature
			handle.renderHistory()
			return true
		end

		function handle.refresh()
			profileDetail.Text = profileUI.providerLabel()
			for id, entry in pairs(modes) do
				local selected = host.panel == id
				entry.button.setSelected(selected)
				entry.label.TextColor3 = selected and theme.color.text or theme.color.textTertiary
			end
			handle.back.setEnabled(host.canBack())
			handle.forward.setEnabled(host.canForward())
			handle.syncMore()
			handle.syncHistory()
		end

		handle.signature = listSignature()

		-- The list is the app's own state: a new thread, a rename, a delete or a switch
		-- all have to show up here without the panel knowing this exists.
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not sidebar.Parent then return end
			handle.syncHistory()
		end)
		local unsubscribeProviders = providers.changed:connect(function()
			if not sidebar.Parent then return end
			profileDetail.Text = profileUI.providerLabel()
		end)
		local unsubscribePlace = place.changed:connect(function()
			if not sidebar.Parent then return end
			-- The place decides a group's label, which the signature covers.
			handle.syncHistory()
		end)
		-- The count on the Subagents row. Debounced, because the register changes on
		-- every tool call a child makes and this rebuilds a list of rows -- and
		-- debounced rather than throttled so the last change in a burst, which is the
		-- one that drops the count back to nothing, is not the one that gets dropped.
		local refreshAgents, cancelAgents = clock.debounce(function()
			if not sidebar.Parent then return end
			handle.syncMore()
		end, 0.3)
		local unsubscribeAgents = subagent.changed:connect(refreshAgents)

		sidebar.Destroying:Connect(function()
			pcall(unsubscribeSessions)
			pcall(unsubscribeProviders)
			pcall(unsubscribePlace)
			pcall(unsubscribeAgents)
			cancelAgents()
		end)

		handle.instance = sidebar
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/theme
-- ==========================================================================
__UAI_MODULES["ui/theme"] = (function()
-- Design tokens.
--
-- Every colour, size, radius, weight and duration in the interface comes from
-- here. No use site writes a literal, which is the only way a project this size
-- stays coherent -- and it is what lets density, accent and text scale change at
-- runtime without hunting through forty files.
--
-- The palette is a warm neutral, not a cool one, and not pure black. Warm because
-- the whole ramp is one hue family with the accent -- a coral -- so a page of prose
-- with two inline code spans in it reads as one material rather than as grey with
-- orange stuck on. Not pure black because on an OLED phone pure black next to a 1px
-- hairline reads as a seam, and a slight lift keeps the surface hierarchy legible at
-- low brightness.
--
-- The lightness steps are deliberately close together at the dark end. The interface
-- it is modelled on separates a sidebar from a canvas from a card by two or three
-- percent of lightness and a hairline, never by a shadow or a heavy fill, and that is
-- what makes it read as flat rather than as a stack of boxes.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local signal = env.require("runtime/signal")

	local M = { changed = signal.new("theme") }

	local function rgb(r, g, b)
		return Color3.fromRGB(r, g, b)
	end

	-- Roblox has no alpha on Color3, so anything that would be a translucent
	-- overlay is pre-blended against the surface it sits on.
	function M.mix(from, to, alpha)
		return from:Lerp(to, util.clamp(alpha, 0, 1))
	end

	local NEUTRAL = {
		[0] = rgb(23, 23, 22),
		[1] = rgb(30, 30, 28),
		[2] = rgb(35, 35, 33),
		[3] = rgb(42, 42, 39),
		[4] = rgb(50, 50, 46),
		[5] = rgb(62, 62, 57),
		[6] = rgb(74, 74, 71),
		[7] = rgb(92, 91, 86),
		[8] = rgb(108, 107, 102),
		[9] = rgb(163, 161, 152),
		[10] = rgb(194, 191, 181),
		[11] = rgb(245, 244, 238),
	}

	-- Accents, all landing in the same lightness band so switching one does not
	-- change how loud the interface feels. The coral is the default and the one the
	-- rest of the palette is tuned around; the others are kept because someone who
	-- picked teal a version ago should not have it silently taken away.
	local ACCENTS = {
		claude = { base = rgb(217, 119, 87), hot = rgb(232, 146, 117), label = "Coral" },
		aurora = { base = rgb(58, 205, 186), hot = rgb(96, 226, 208), label = "Aurora" },
		indigo = { base = rgb(122, 136, 255), hot = rgb(153, 165, 255), label = "Indigo" },
		amber = { base = rgb(226, 160, 74), hot = rgb(243, 184, 108), label = "Amber" },
		rose = { base = rgb(240, 108, 138), hot = rgb(249, 142, 166), label = "Rose" },
	}

	M.ACCENTS = ACCENTS

	-- Type resolution, in two layers.
	--
	-- `Enum.Font` is the legacy pairing of a family with one baked-in weight --
	-- BuilderSansMedium is a member, and there is no way to ask that family for
	-- anything else. `FontFace` is the modern one: a family asset plus an independent
	-- weight axis, so a single family yields Regular, Medium and SemiBold rather than
	-- whichever pairs somebody happened to enumerate. Having the weight axis is most
	-- of the difference between type that reads as an application and type that reads
	-- as a 2016 forum: hierarchy comes from 400/500/600 at one or two sizes, not from
	-- jumping the size every level because only two weights exist.
	--
	-- The family string is never written here. It is read back off the engine with
	-- Font.fromEnum, so a family this client cannot load can never be named. A
	-- hardcoded rbxasset path has the opposite failure mode: it constructs fine and
	-- renders nothing, and there is no way to detect that from Lua.
	local function enumFont(name)
		local ok, item = pcall(function() return Enum.Font[name] end)
		if ok and item then return item end
		return nil
	end

	local function fontOr(name, fallback)
		return enumFont(name) or fallback
	end

	local function familyOf(name)
		local item = enumFont(name)
		if not item then return nil end
		local ok, face = pcall(function() return Font.fromEnum(item) end)
		if ok and face and type(face.Family) == "string" and face.Family ~= "" then
			return face.Family
		end
		return nil
	end

	-- Which point on the weight axis each role asks for. `strong` is SemiBold rather
	-- than Bold: at 15 and 16 pixels Bold on a dark ground blooms and reads as shouting,
	-- and 600 is what the interface this follows uses for a title.
	local WEIGHTS = { regular = "Regular", medium = "Medium", strong = "SemiBold" }

	local function faceFor(family, weight)
		if not family then return nil end
		local ok, face = pcall(function()
			return Font.new(family,
				Enum.FontWeight[WEIGHTS[weight] or "Regular"],
				Enum.FontStyle.Normal)
		end)
		if ok and face then return face end
		return nil
	end

	local SANS = fontOr("BuilderSans", Enum.Font.Gotham)
	local SANS_MEDIUM = fontOr("BuilderSansMedium", Enum.Font.GothamMedium)

	-- The interface and code families a person can actually pick from.
	--
	-- A free-text font field is the one control in the reference client that cannot be
	-- honest here: Roblox renders from a fixed set of families and cannot load a name it
	-- was handed, so naming JetBrains Mono in a box would change nothing. What is
	-- offered instead is the set that exists *on this client*, discovered rather than
	-- declared -- every candidate below is probed against the engine and dropped if it
	-- does not resolve, so an older client shows a shorter list instead of a list with
	-- dead entries in it.
	--
	-- Every name here is a real member of Enum.Font. That is not a stylistic point: an
	-- invented one would be silently dropped by the probe on a real client and silently
	-- *accepted* by the test harness, whose Enum proxy resolves anything asked of it --
	-- so a typo would surface as a font option that exists only in the tests.
	local INTERFACE_CANDIDATES = {
		-- Montserrat leads: a contemporary geometric sans with a full weight axis,
		-- which reads as a modern interface face at the sizes this project uses.
		-- The order below is the fallback chain, so a client missing a family gets
		-- the next most contemporary one rather than the last.
		{ id = "montserrat", label = "Montserrat", regular = "Montserrat", medium = "MontserratMedium" },
		{ id = "builder", label = "Builder Sans", regular = "BuilderSans", medium = "BuilderSansMedium" },
		{ id = "arimo", label = "Arimo", regular = "Arimo", medium = "ArimoBold" },
		{ id = "roboto", label = "Roboto", regular = "Roboto", medium = "Roboto" },
		{ id = "nunito", label = "Nunito", regular = "Nunito", medium = "Nunito" },
		{ id = "titillium", label = "Titillium Web", regular = "TitilliumWeb", medium = "TitilliumWeb" },
		{ id = "ubuntu", label = "Ubuntu", regular = "Ubuntu", medium = "Ubuntu" },
		{ id = "source", label = "Source Sans", regular = "SourceSans", medium = "SourceSansSemibold" },
		{ id = "gotham", label = "Gotham", regular = "Gotham", medium = "GothamMedium" },
	}

	-- Two, because Enum.Font has two monospace families and no more. Anything else a
	-- code editor would reach for -- JetBrains Mono, Inconsolata, Fira -- is not in the
	-- engine, and offering it would be offering nothing.
	local CODE_CANDIDATES = {
		{ id = "code", label = "Source Code Pro", regular = "Code" },
		{ id = "roboto", label = "Roboto Mono", regular = "RobotoMono" },
	}

	-- Resolution happens once, at load. Probing is a dozen pcalls; doing it per rebuild
	-- would repeat them on every accent change.
	local function resolveFamilies(candidates, fallbackEnum)
		local byId, order = {}, {}
		for _, entry in ipairs(candidates) do
			local regular = enumFont(entry.regular)
			local family = familyOf(entry.regular)
			-- Kept when either layer works: the family gives the weight axis, the enum
			-- alone still renders. Dropped only when the client has neither.
			if regular or family then
				byId[entry.id] = {
					id = entry.id,
					label = entry.label,
					family = family,
					enumName = entry.regular,
					regular = regular or fallbackEnum,
					medium = fontOr(entry.medium or entry.regular, regular or fallbackEnum),
					faces = {
						regular = faceFor(family, "regular"),
						medium = faceFor(family, "medium"),
						strong = faceFor(family, "strong"),
					},
				}
				order[#order + 1] = entry.id
			end
		end
		return byId, order
	end

	local INTERFACE_FONTS, INTERFACE_ORDER = resolveFamilies(INTERFACE_CANDIDATES, SANS)
	local CODE_FONTS, CODE_ORDER = resolveFamilies(CODE_CANDIDATES, Enum.Font.Code)

	M.INTERFACE_FONTS = INTERFACE_FONTS
	M.INTERFACE_ORDER = INTERFACE_ORDER
	M.CODE_FONTS = CODE_FONTS
	M.CODE_ORDER = CODE_ORDER

	-- The first candidate that resolved, which is the most contemporary family this
	-- client has. Named rather than assumed: on a client old enough to be missing
	-- Builder Sans the default has to move, and a stored setting naming a family that
	-- is not here has to fall back to something rather than to nil.
	M.defaultInterfaceFont = INTERFACE_ORDER[1] or "gotham"
	M.defaultCodeFont = CODE_ORDER[1] or "code"

	-- The two code palettes the appearance pane previews and the transcript uses.
	--
	-- Light is a real option rather than a swatch: a code block on a light card in a
	-- dark interface is what the reference client does, and the setting has to change
	-- what a fenced block in the transcript looks like or it is decoration.
	local CODE_THEMES = {
		dark = {
			label = "Claude Dark",
			surface = NEUTRAL[0],
			border = NEUTRAL[4],
			bar = NEUTRAL[2],
			text = NEUTRAL[11],
			-- Line numbers and the language label. It has to clear 3:1 on the bar it
			-- sits on: a gutter nobody can read is a column of noise down the left.
			gutter = NEUTRAL[9],
			addSurface = rgb(24, 54, 34),
			addText = rgb(126, 217, 148),
			removeSurface = rgb(64, 28, 32),
			removeText = rgb(240, 138, 132),
			keyword = rgb(201, 171, 235),
			string = rgb(165, 201, 148),
			number = rgb(227, 184, 134),
			comment = NEUTRAL[9],
			call = rgb(149, 193, 225),
		},
		light = {
			label = "Claude Light",
			surface = rgb(250, 249, 245),
			border = rgb(214, 211, 202),
			bar = rgb(237, 235, 228),
			text = rgb(38, 38, 36),
			gutter = rgb(104, 102, 95),
			addSurface = rgb(219, 245, 226),
			addText = rgb(21, 105, 55),
			removeSurface = rgb(252, 226, 226),
			removeText = rgb(163, 32, 32),
			keyword = rgb(116, 63, 156),
			string = rgb(53, 106, 43),
			number = rgb(144, 81, 23),
			comment = rgb(103, 104, 94),
			call = rgb(31, 96, 147),
		},
	}
	local CODE_THEME_ORDER = { "dark", "light" }

	M.CODE_THEMES = CODE_THEMES
	M.CODE_THEME_ORDER = CODE_THEME_ORDER

	-- Line heights, named. Four of them were loose numbers inside the type table and
	-- three more were repeated at use sites that needed a label to sit on a control's
	-- centre line -- a title at the reading measure of 1.6 is 40px of box around 16px
	-- of glyph, which is why the window header's two lines had one pixel of air above
	-- and below them.
	-- `code` is the loosest of them on purpose. A block of output is read one line at
	-- a time, looking for the one that matters, and at the 1.5 the rest of the mono
	-- text uses, eleven lines of `key: value` arrive as a solid slab -- the gaps
	-- between the lines are what the eye scans down.
	M.line = { tight = 1.2, snug = 1.35, normal = 1.5, reading = 1.6, code = 1.65 }

	-- Body text is the one thing in here a person actually reads, so it gets the
	-- room: 15 on a 1.6 line, which is a reading measure rather than a UI measure.
	-- Everything that is not prose is quieter and tighter than it used to be --
	-- headings a step down, labels one weight rather than bold-and-uppercase --
	-- because the interface this follows gets its hierarchy from spacing and colour,
	-- not from size. A 22px bold display over 13px body is a dashboard; this is a
	-- document with controls at the edges.
	--
	-- `weight` names a point on the family's weight axis rather than a font, because
	-- the family is a setting: the interface font and the code font are both pickable,
	-- and a resolved Enum.Font baked in here could not follow them.
	local BASE_TEXT = {
		display = { size = 22, weight = "strong", line = M.line.tight },
		title = { size = 17, weight = "strong", line = M.line.tight },
		heading = { size = 15, weight = "medium", line = M.line.snug },
		body = { size = 15, weight = "regular", line = M.line.reading },
		bodyStrong = { size = 15, weight = "medium", line = M.line.reading },
		small = { size = 13, weight = "regular", line = M.line.normal },
		label = { size = 12, weight = "medium", line = M.line.tight },
		caption = { size = 12, weight = "regular", line = M.line.snug },
		overline = { size = 11, weight = "medium", line = M.line.tight },
		mono = { size = 13, weight = "mono", line = M.line.normal },
		monoSmall = { size = 12, weight = "mono", line = M.line.normal },
	}

	local BASE_SPACE = {
		none = 0, hair = 2, xxs = 4, xs = 6, sm = 8, md = 12, lg = 16, xl = 20, xxl = 28, huge = 40,
	}

	local BASE_SIZE = {
		codeToolbar = 38,
		codeStatus = 22,
		codeWide = 800,
		codeOutput = 170,
		codeGutter = 44,
		codeOverscan = 8,
		control = 34,      -- default button / field height
		controlSmall = 28,
		controlLarge = 42,
		icon = 16,
		iconLarge = 20,
		row = 36,
		-- Tall enough for two lines of chrome plus air. At 42 the window header's title
		-- and subtitle -- 40px of type between them at the reading measure -- had a
		-- single pixel above and below, so the title touched the window's top edge.
		header = 56,
		rail = 52,
		tab = 30,
		launcher = 44,
		scrollbar = 4,
		avatar = 26,
		profileAvatar = 40,
		profileAvatarLarge = 48,
		-- The switch. `switchWide` is the width, kept as a token because it was a
		-- hardcoded 38 that four panels each reserved a hand-summed 46 for -- every one
		-- of which would have gone wrong the moment either number moved. Those rows now
		-- fill instead of reserving, but the size still belongs here.
		switch = 20,
		switchWide = 34,
		-- Slider and progress geometry.
		track = 3,
		knob = 12,
		-- The label column in a key/value list, wide enough for the longest key any
		-- panel in here uses.
		keyColumn = 104,
		-- Status dots, and the right-hand column a transcript row puts a duration or a
		-- progress count in. Both were literals repeated at five and three sites
		-- respectively, with two of the dot sizes disagreeing by a pixel.
		dot = 6,
		dotSmall = 4,
		metaColumn = 52,
		metaColumnWide = 88,
		-- Overlay widths. Twelve independent literals between 160 and 420 used to
		-- decide how wide a menu, a dropdown or a dialog was, which is why no two
		-- dialogs in here were the same width.
		menu = 200,
		menuMin = 160,
		menuWide = 320,
		menuMax = 320,
		modal = 380,
		modalWide = 480,
		modalMin = 260,
		-- The reading column. Past roughly this width a line of prose becomes a single
		-- sentence a foot long, which is unreadable however correct the layout is.
		-- Overridden by the transcript-width setting, which is why the three widths it
		-- offers are tokens too rather than numbers in a panel.
		codeViewport = 380,
		reading = 1000,
		readingNarrow = 720,
		readingMedium = 860,
		sidebar = 248,
		-- Dense list furniture: a session row in the sidebar, a group header above it,
		-- the pinned profile bar at the bottom, a chip in the composer.
		rowSmall = 30,
		rowTight = 22,
		bar = 36,
		chip = 26,
		-- Chat-only geometry: a full-width prompt above an independent toolbar.
		composerPrompt = 44,
		composerExpanded = 144,
		composerModel = 144,
		composerModelMin = 76,
		composerFieldMin = 240,
		promptCard = 88,
		promptColumns = 480,
		modelPicker = 480,
		modelPickerHeight = 500,
		thinkingViewport = 180,
		tableColumnMin = 104,
		tableColumnMax = 320,
		tableViewport = 380,
		-- The home card: its column, one metric tile, and one cell of the activity
		-- grid. All three were literals in the surface that drew them.
		statCard = 560,
		statTile = 56,
		cell = 11,
		-- The settings dialog, which is a window of its own rather than a modal card.
		dialog = 760,
		dialogTall = 520,
		dialogNav = 190,
	}

	-- Corners are tighter than they were. A 16px radius on a card reads as a mobile
	-- widget; 6 to 10 reads as a document panel, which is what this is.
	M.radius = { none = 0, xs = 2, sm = 6, md = 8, lg = 12, xl = 16, pill = 999 }
	M.stroke = { hair = 1, focus = 2 }

	-- The visual constants that are neither a colour nor a size. They were literals
	-- at half a dozen use sites, which is how the modal scrim ended up at 0.45 and the
	-- quick-chat scrim -- the same effect, one layer up -- at 0.5.
	M.opacity = { scrollbar = 0.4, scrim = 0.5, dim = 0.6 }

	-- How far a surface is scaled down as it enters. Small on purpose: a panel that
	-- springs in from 0.9 is a phone app, and three surfaces here were each doing it
	-- by a slightly different amount.
	M.scale = { enter = 0.98 }

	M.motion = {
		-- Durations, in seconds, for a caller that needs a number rather than a tween.
		fast = 0.12,
		base = 0.18,
		slow = 0.3,
		-- Tweens. `instant` is a real TweenInfo rather than a zero, because the thing
		-- callers actually want from it is "apply this now" through the same
		-- TweenService path as every other paint -- a bare 0 is not a TweenInfo and
		-- cannot be passed to Create at all.
		instant = TweenInfo.new(0.01, Enum.EasingStyle.Linear),
		enter = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		exit = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
		hover = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		press = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		slide = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		-- The repeating pair. These are the only tweens here with a negative repeat
		-- count, and they deliberately do not go through M.tween: collapsing the
		-- duration to 0.01s for reduced motion would spin them at a hundred hertz
		-- rather than stop them. Callers check responsive.reduceMotion themselves and
		-- skip the tween entirely.
		spin = TweenInfo.new(0.9, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1),
		pulse = TweenInfo.new(0.85, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut, -1, true),
	}

	-- A dropdown is always opened from something, so it has to sit above whatever
	-- opened it -- including a modal. It used to rank below one, which is why the
	-- preset menu in the Add provider dialog opened behind the dialog.
	M.z = { base = 1, raised = 10, header = 20, overlay = 100, modal = 160, dropdown = 200, quick = 210, toast = 240 }

	-- Recomputed whenever density, accent or text scale changes.
	function M.rebuild()
